INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('5', 'ul', 'Ulangan', 6, 12, 'maka berhati-hatilah, supaya jangan engkau melupakan TUHAN, yang telah membawa kamu keluar dari tanah Mesir, dari rumah perbudakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 13, 'Engkau harus takut akan TUHAN, Allahmu; kepada Dia haruslah engkau beribadah dan demi nama-Nya haruslah engkau bersumpah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 14, 'Janganlah kamu mengikuti allah lain, dari antara allah bangsa-bangsa sekelilingmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 15, 'sebab TUHAN, Allahmu, adalah Allah yang cemburu di tengah-tengahmu, supaya jangan bangkit murka TUHAN, Allahmu, terhadap engkau, sehingga Ia memunahkan engkau dari muka bumi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 16, 'Janganlah kamu mencobai TUHAN, Allahmu, seperti kamu mencobai Dia di Masa.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 17, 'Haruslah kamu berpegang pada perintah, peringatan dan ketetapan TUHAN, Allahmu, yang diperintahkan-Nya kepadamu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 18, 'haruslah engkau melakukan apa yang benar dan baik di mata TUHAN, supaya baik keadaanmu dan engkau memasuki dan menduduki negeri yang baik, yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 19, 'dengan mengusir semua musuhmu dari hadapanmu, seperti yang difirmankan TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 20, 'Apabila di kemudian hari anakmu bertanya kepadamu: Apakah peringatan, ketetapan dan peraturan itu, yang diperintahkan kepadamu oleh TUHAN Allah kita?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 21, 'maka haruslah engkau menjawab anakmu itu: Kita dahulu adalah budak Firaun di Mesir, tetapi TUHAN membawa kita keluar dari Mesir dengan tangan yang kuat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 22, 'TUHAN membuat tanda-tanda dan mujizat-mujizat, yang besar dan yang mencelakakan, terhadap Mesir, terhadap Firaun dan seisi rumahnya, di depan mata kita;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 23, 'tetapi kita dibawa-Nya keluar dari sana, supaya kita dapat dibawa-Nya masuk untuk memberikan kepada kita negeri yang telah dijanjikan-Nya dengan sumpah kepada nenek moyang kita.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 24, 'TUHAN, Allah kita, memerintahkan kepada kita untuk melakukan segala ketetapan itu dan untuk takut akan TUHAN, Allah kita, supaya senantiasa baik keadaan kita dan supaya Ia membiarkan kita hidup, seperti sekarang ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 6, 25, 'Dan kita akan menjadi benar, apabila kita melakukan segenap perintah itu dengan setia di hadapan TUHAN, Allah kita, seperti yang diperintahkan-Nya kepada kita."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 1, '"Apabila TUHAN, Allahmu, telah membawa engkau ke dalam negeri, ke mana engkau masuk untuk mendudukinya, dan Ia telah menghalau banyak bangsa dari depanmu, yakni orang Het, orang Girgasi, orang Amori, orang Kanaan, orang Feris, orang Hewi dan orang Yebus, tujuh bangsa, yang lebih banyak dan lebih kuat dari padamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 2, 'dan TUHAN, Allahmu, telah menyerahkan mereka kepadamu, sehingga engkau memukul mereka kalah, maka haruslah kamu menumpas mereka sama sekali. Janganlah engkau mengadakan perjanjian dengan mereka dan janganlah engkau mengasihani mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 3, 'Janganlah juga engkau kawin-mengawin dengan mereka: anakmu perempuan janganlah kauberikan kepada anak laki-laki mereka, ataupun anak perempuan mereka jangan kauambil bagi anakmu laki-laki;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 4, 'sebab mereka akan membuat anakmu laki-laki menyimpang dari pada-Ku, sehingga mereka beribadah kepada allah lain. Maka murka TUHAN akan bangkit terhadap kamu dan Ia akan memunahkan engkau dengan segera.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 5, 'Tetapi beginilah kamu lakukan terhadap mereka: mezbah-mezbah mereka haruslah kamu robohkan, tugu-tugu berhala mereka kamu remukkan, tiang-tiang berhala mereka kamu hancurkan dan patung-patung mereka kamu bakar habis.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 6, 'Sebab engkaulah umat yang kudus bagi TUHAN, Allahmu; engkaulah yang dipilih oleh TUHAN, Allahmu, dari segala bangsa di atas muka bumi untuk menjadi umat kesayangan-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 7, 'Bukan karena lebih banyak jumlahmu dari bangsa manapun juga, maka hati TUHAN terpikat olehmu dan memilih kamu?bukankah kamu ini yang paling kecil dari segala bangsa? ?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 8, 'tetapi karena TUHAN mengasihi kamu dan memegang sumpah-Nya yang telah diikrarkan-Nya kepada nenek moyangmu, maka TUHAN telah membawa kamu keluar dengan tangan yang kuat dan menebus engkau dari rumah perbudakan, dari tangan Firaun, raja Mesir.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 9, 'Sebab itu haruslah kauketahui, bahwa TUHAN, Allahmu, Dialah Allah, Allah yang setia, yang memegang perjanjian dan kasih setia-Nya terhadap orang yang kasih kepada-Nya dan berpegang pada perintah-Nya, sampai kepada beribu-ribu keturunan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 10, 'tetapi terhadap diri setiap orang dari mereka yang membenci Dia, Ia melakukan pembalasan dengan membinasakan orang itu. Ia tidak bertangguh terhadap orang yang membenci Dia. Ia langsung mengadakan pembalasan terhadap orang itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 11, 'Jadi berpeganglah pada perintah, yakni ketetapan dan peraturan yang kusampaikan kepadamu pada hari ini untuk dilakukan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 12, '"Dan akan terjadi, karena kamu mendengarkan peraturan-peraturan itu serta melakukannya dengan setia, maka terhadap engkau TUHAN, Allahmu, akan memegang perjanjian dan kasih setia-Nya yang diikrarkan-Nya dengan sumpah kepada nenek moyangmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 13, 'Ia akan mengasihi engkau, memberkati engkau dan membuat engkau banyak; Ia akan memberkati buah kandunganmu dan hasil bumimu, gandum dan anggur serta minyakmu, anak lembu sapimu dan anak kambing dombamu, di tanah yang dijanjikan-Nya dengan sumpah kepada nenek moyangmu untuk memberikannya kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 14, 'Engkau akan diberkati lebih dari pada segala bangsa: tidak akan ada laki-laki atau perempuan yang mandul di antaramu, ataupun di antara hewanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 15, 'TUHAN akan menjauhkan segala penyakit dari padamu, dan tidak ada satu dari wabah celaka yang kaukenal di Mesir itu akan ditimpakan-Nya kepadamu, tetapi Ia akan mendatangkannya kepada semua orang yang membenci engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 16, 'Engkau harus melenyapkan segala bangsa yang diserahkan kepadamu oleh TUHAN, Allahmu; janganlah engkau merasa sayang kepada mereka dan janganlah beribadah kepada allah mereka, sebab hal itu akan menjadi jerat bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 17, 'Jika sekiranya engkau berkata dalam hatimu: Bangsa-bangsa ini lebih banyak dari padaku, bagaimanakah aku dapat menghalaukan mereka?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 18, 'maka janganlah engkau takut kepada mereka; ingatlah selalu apa yang dilakukan TUHAN, Allahmu, terhadap Firaun dan seluruh Mesir,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 19, 'yakni cobaan-cobaan besar, yang kaulihat dengan matamu sendiri, tanda-tanda dan mujizat-mujizat, tangan yang kuat dan lengan yang teracung, yang dipakai TUHAN, Allahmu, untuk membawa engkau keluar. Demikianlah juga akan dilakukan TUHAN, Allahmu, terhadap segala bangsa yang engkau takuti.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 20, 'Lagipula TUHAN, Allahmu, akan melepaskan tabuhan menyerbu mereka, sampai habis binasa orang-orang yang masih tinggal dan yang menyembunyikan diri terhadap engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 21, 'Janganlah gemetar karena mereka, sebab TUHAN, Allahmu, ada di tengah-tengahmu, Allah yang besar dan dahsyat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 22, 'TUHAN, Allahmu, akan menghalau bangsa-bangsa ini dari hadapanmu sedikit demi sedikit; engkau tidak boleh membinasakan mereka dengan segera, supaya jangan binatang hutan menjadi terlalu banyak melebihi engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 23, 'Demikianlah TUHAN, Allahmu, akan menyerahkan mereka kepadamu dan akan mengacaukan mereka sama sekali, sampai mereka punah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 24, 'Raja-raja mereka akan diserahkan-Nya ke dalam tanganmu, sehingga engkau menghapuskan nama mereka dari kolong langit; tidak akan ada yang dapat bertahan menghadapi engkau, sampai engkau memunahkan mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 25, 'Patung-patung allah mereka haruslah kamu bakar habis; perak dan emas yang ada pada mereka janganlah kauingini dan kauambil bagi dirimu sendiri, supaya jangan engkau terjerat karenanya, sebab hal itu adalah kekejian bagi TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 7, 26, 'Dan janganlah engkau membawa sesuatu kekejian masuk ke dalam rumahmu, sehingga engkaupun ditumpas seperti itu; haruslah engkau benar-benar merasa jijik dan keji terhadap hal itu, sebab semuanya itu dikhususkan untuk dimusnahkan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 1, '"Segenap perintah, yang kusampaikan kepadamu pada hari ini, haruslah kamu lakukan dengan setia, supaya kamu hidup dan bertambah banyak dan kamu memasuki serta menduduki negeri yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 2, 'Ingatlah kepada seluruh perjalanan yang kaulakukan atas kehendak TUHAN, Allahmu, di padang gurun selama empat puluh tahun ini dengan maksud merendahkan hatimu dan mencobai engkau untuk mengetahui apa yang ada dalam hatimu, yakni, apakah engkau berpegang pada perintah-Nya atau tidak.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 3, 'Jadi Ia merendahkan hatimu, membiarkan engkau lapar dan memberi engkau makan manna, yang tidak kaukenal dan yang juga tidak dikenal oleh nenek moyangmu, untuk membuat engkau mengerti, bahwa manusia hidup bukan dari roti saja, tetapi manusia hidup dari segala yang diucapkan TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 4, 'Pakaianmu tidaklah menjadi buruk di tubuhmu dan kakimu tidaklah menjadi bengkak selama empat puluh tahun ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 5, 'Maka haruslah engkau insaf, bahwa TUHAN, Allahmu, mengajari engkau seperti seseorang mengajari anaknya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 6, 'Oleh sebab itu haruslah engkau berpegang pada perintah TUHAN, Allahmu, dengan hidup menurut jalan yang ditunjukkan-Nya dan dengan takut akan Dia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 7, 'Sebab TUHAN, Allahmu, membawa engkau masuk ke dalam negeri yang baik, suatu negeri dengan sungai, mata air dan danau, yang keluar dari lembah-lembah dan gunung-gunung;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 8, 'suatu negeri dengan gandum dan jelainya, dengan pohon anggur, pohon ara dan pohon delimanya; suatu negeri dengan pohon zaitun dan madunya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 9, 'suatu negeri, di mana engkau akan makan roti dengan tidak usah berhemat, di mana engkau tidak akan kekurangan apapun; suatu negeri, yang batunya mengandung besi dan dari gunungnya akan kaugali tembaga.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 10, 'Dan engkau akan makan dan akan kenyang, maka engkau akan memuji TUHAN, Allahmu, karena negeri yang baik yang diberikan-Nya kepadamu itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 11, 'Hati-hatilah, supaya jangan engkau melupakan TUHAN, Allahmu, dengan tidak berpegang pada perintah, peraturan dan ketetapan-Nya, yang kusampaikan kepadamu pada hari ini;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 12, 'dan supaya, apabila engkau sudah makan dan kenyang, mendirikan rumah-rumah yang baik serta mendiaminya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 13, 'dan apabila lembu sapimu dan kambing dombamu bertambah banyak dan emas serta perakmu bertambah banyak, dan segala yang ada padamu bertambah banyak,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 14, 'jangan engkau tinggi hati, sehingga engkau melupakan TUHAN, Allahmu, yang membawa engkau keluar dari tanah Mesir, dari rumah perbudakan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 15, 'dan yang memimpin engkau melalui padang gurun yang besar dan dahsyat itu, dengan ular-ular yang ganas serta kalajengkingnya dan tanahnya yang gersang, yang tidak ada air. Dia yang membuat air keluar bagimu dari gunung batu yang keras,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 16, 'dan yang di padang gurun memberi engkau makan manna, yang tidak dikenal oleh nenek moyangmu, supaya direndahkan-Nya hatimu dan dicobai-Nya engkau, hanya untuk berbuat baik kepadamu akhirnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 17, 'Maka janganlah kaukatakan dalam hatimu: Kekuasaanku dan kekuatan tangankulah yang membuat aku memperoleh kekayaan ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 18, 'Tetapi haruslah engkau ingat kepada TUHAN, Allahmu, sebab Dialah yang memberikan kepadamu kekuatan untuk memperoleh kekayaan, dengan maksud meneguhkan perjanjian yang diikrarkan-Nya dengan sumpah kepada nenek moyangmu, seperti sekarang ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 19, 'Tetapi jika engkau sama sekali melupakan TUHAN, Allahmu, dan mengikuti allah lain, beribadah kepadanya dan sujud menyembah kepadanya, aku memperingatkan kepadamu hari ini, bahwa kamu pasti binasa;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 8, 20, 'seperti bangsa-bangsa, yang dibinasakan TUHAN di hadapanmu, kamupun akan binasa, sebab kamu tidak mau mendengarkan suara TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 1, '"Dengarlah, hai orang Israel! Engkau akan menyeberangi sungai Yordan pada hari ini untuk memasuki serta menduduki daerah bangsa-bangsa yang lebih besar dan lebih kuat dari padamu, yakni kota-kota besar yang kubu-kubunya sampai ke langit?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 2, 'suatu bangsa yang besar dan tinggi, orang Enak, yang kaukenal dan yang tentangnya kaudengar orang berkata: Siapakah yang dapat bertahan menghadapi orang Enak?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 3, 'Maka ketahuilah pada hari ini, bahwa TUHAN, Allahmu, Dialah yang berjalan di depanmu laksana api yang menghanguskan; Dia akan memunahkan mereka dan Dia akan menundukkan mereka di hadapanmu. Demikianlah engkau akan menghalau dan membinasakan mereka dengan segera, seperti yang dijanjikan kepadamu oleh TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 4, 'Janganlah engkau berkata dalam hatimu, apabila TUHAN, Allahmu, telah mengusir mereka dari hadapanmu: Karena jasa-jasakulah TUHAN membawa aku masuk menduduki negeri ini; padahal karena kefasikan bangsa-bangsa itulah TUHAN menghalau mereka dari hadapanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 5, 'Bukan karena jasa-jasamu atau karena kebenaran hatimu engkau masuk menduduki negeri mereka, tetapi karena kefasikan bangsa-bangsa itulah, TUHAN, Allahmu, menghalau mereka dari hadapanmu, dan supaya TUHAN menepati janji yang diikrarkan-Nya dengan sumpah kepada nenek moyangmu, yakni Abraham, Ishak dan Yakub.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 6, 'Jadi ketahuilah, bahwa bukan karena jasa-jasamu TUHAN, Allahmu, memberikan kepadamu negeri yang baik itu untuk diduduki. Sesungguhnya engkau bangsa yang tegar tengkuk!"', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 7, '"Ingatlah, janganlah lupa, bahwa engkau sudah membuat TUHAN, Allahmu, gusar di padang gurun. Sejak engkau keluar dari tanah Mesir sampai kamu tiba di tempat ini, kamu menentang TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 8, 'Di Horeb kamu sudah membuat TUHAN gusar, bahkan TUHAN begitu murka kepadamu, hingga Ia mau memunahkan kamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 9, 'Setelah aku mendaki gunung untuk menerima loh-loh batu, loh-loh perjanjian yang diikat TUHAN dengan kamu, maka aku tinggal empat puluh hari empat puluh malam lamanya di gunung itu; roti tidak kumakan dan air tidak kuminum.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 10, 'TUHAN memberikan kepadaku kedua loh batu, yang ditulisi jari Allah, di mana ada segala firman yang diucapkan TUHAN kepadamu di gunung itu dari tengah-tengah api, pada hari perkumpulan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 11, 'Sesudah lewat empat puluh hari empat puluh malam itu, maka TUHAN memberikan kepadaku kedua loh batu, loh-loh perjanjian itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 12, 'Lalu berfirmanlah TUHAN kepadaku: Bangunlah, turunlah dengan segera dari sini, sebab bangsamu, yang kaubawa keluar dari Mesir, telah berlaku busuk; mereka segera menyimpang dari jalan yang Kuperintahkan kepada mereka; mereka telah membuat patung tuangan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 13, 'Lagi TUHAN berfirman kepadaku: Telah Kulihat bangsa ini dan sesungguhnya mereka adalah bangsa yang tegar tengkuk.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 14, 'Biarkanlah Aku, maka Aku akan memunahkan mereka dan menghapuskan nama mereka dari kolong langit; tetapi dari padamu akan Kubuat suatu bangsa yang lebih berkuasa dan lebih banyak dari pada bangsa ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 15, 'Setelah itu berpalinglah aku, lalu turun dari gunung yang sedang menyala itu dengan kedua loh perjanjian di kedua tanganku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 16, 'Lalu aku menyaksikan, bahwa sesungguhnya kamu telah berbuat dosa terhadap TUHAN, Allahmu: kamu telah membuat suatu anak lembu tuangan, kamu telah segera menyimpang dari jalan yang diperintahkan TUHAN kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 17, 'Maka kupeganglah kuat-kuat kedua loh itu, kulemparkan dari kedua tanganku, kupecahkan di depan matamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 18, 'Sesudah itu aku sujud di hadapan TUHAN, empat puluh hari empat puluh malam lamanya, seperti yang pertama kali?roti tidak kumakan dan air tidak kuminum?karena segala dosa yang telah kamu perbuat, yakni kamu melakukan apa yang jahat di mata TUHAN, sehingga kamu menimbulkan sakit hati-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 19, 'Sebab aku gentar karena murka dan kepanasan amarah yang ditimpakan TUHAN kepadamu, sampai Ia mau memunahkan kamu. Tetapi sekali inipun TUHAN mendengarkan aku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 20, 'Juga kepada Harun TUHAN begitu murka, hingga Ia mau membinasakannya; maka pada waktu itu aku berdoa untuk Harun juga.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 21, 'Tetapi hasil perbuatanmu yang berdosa, yakni anak lembu itu, kuambil, kubakar, kuhancurkan dan kugiling baik-baik sampai halus, menjadi abu, lalu abunya kulemparkan ke dalam sungai yang mengalir turun dari gunung.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 22, 'Juga di Tabera, di Masa dan di Kibrot-Taawa, kamu selalu membuat TUHAN gusar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 23, 'Dan ketika TUHAN menyuruh kamu pergi dari Kadesh-Barnea dengan berfirman: Majulah dan dudukilah negeri yang Kuberikan kepadamu itu, maka kamu menentang titah TUHAN, Allahmu; kamu tidak percaya kepada-Nya dan tidak mendengarkan suara-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 24, 'Bahkan kamu menentang TUHAN, sejak aku mengenal kamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 25, 'Maka aku sujud di hadapan TUHAN?empat puluh hari empat puluh malam lamanya aku sujud?,karena TUHAN telah berfirman akan memunahkan kamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 26, 'dan aku berdoa kepada TUHAN, kataku: Ya, Tuhan ALLAH, janganlah musnahkan umat milik-Mu sendiri, yang Kautebus dengan kebesaran-Mu, dan yang Kaubawa keluar dari Mesir dengan tangan yang kuat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 27, 'Ingatlah kepada hamba-hamba-Mu, kepada Abraham, Ishak dan Yakub; janganlah perhatikan ketegaran bangsa ini ataupun kefasikannya dan dosanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 28, 'supaya negeri, dari mana Engkau membawa kami keluar, jangan berkata: Sebab TUHAN tidak dapat membawa mereka masuk ke negeri yang dijanjikan-Nya kepada mereka, dan sebab benci-Nya kepada mereka, maka Ia membawa mereka keluar untuk membunuh mereka di padang gurun.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 9, 29, 'Bukankah mereka itu umat milik-Mu sendiri, yang Kaubawa keluar dengan kekuatan-Mu yang besar dan dengan lengan-Mu yang teracung?"', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 1, '"Pada waktu itu berfirmanlah TUHAN kepadaku: Pahatlah dua loh batu yang serupa dengan yang mula-mula, naiklah kepada-Ku ke atas gunung, dan buatlah sebuah tabut dari kayu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 2, 'maka Aku akan menuliskan pada loh itu firman-firman yang ada pada loh yang mula-mula yang telah kaupecahkan itu, kemudian letakkanlah kedua loh ke dalam tabut itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 3, 'Maka aku membuat sebuah tabut dari kayu penaga dan memahat dua loh batu yang serupa dengan yang mula-mula; kemudian aku mendaki gunung dengan kedua loh itu di tanganku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 4, 'Dan pada loh itu Ia menuliskan, sama dengan tulisan yang mula-mula, Kesepuluh Firman yang telah diucapkan TUHAN kepadamu di atas gunung dari tengah-tengah api pada hari kamu berkumpul; sesudah itu TUHAN memberikannya kepadaku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 5, 'Lalu aku turun kembali dari atas gunung, dan aku meletakkan loh-loh itu ke dalam tabut yang telah kubuat; dan di situlah tempatnya, seperti yang diperintahkan TUHAN kepadaku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 6, 'Maka orang Israel berangkat dari Beerot Bene-Yaakan ke Mosera; di sanalah Harun mati dan dikuburkan; lalu Eleazar, anaknya, menjadi imam menggantikan dia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 7, 'Dari sana mereka berangkat ke Gudgod, dan dari Gudgod ke Yotbata, suatu daerah yang banyak sungainya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 8, 'Pada waktu itu TUHAN menunjuk suku Lewi untuk mengangkut tabut perjanjian TUHAN, untuk bertugas melayani TUHAN dan untuk memberi berkat demi nama-Nya, sampai sekarang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 9, 'Sebab itu suku Lewi tidak mempunyai bagian milik pusaka bersama-sama dengan saudara-saudaranya; Tuhanlah milik pusakanya, seperti yang difirmankan kepadanya oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 10, 'Maka aku ini berdiri di atas gunung seperti yang pertama kali, empat puluh hari empat puluh malam lamanya, dan sekali inipun TUHAN mendengarkan aku: TUHAN tidak mau memusnahkan engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 11, 'Lalu berfirmanlah TUHAN kepadaku: Bersiaplah, pergilah berjalan di depan bangsa itu, supaya mereka memasuki dan menduduki negeri yang Kujanjikan dengan sumpah kepada nenek moyang mereka untuk memberikannya kepada mereka."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 12, '"Maka sekarang, hai orang Israel, apakah yang dimintakan dari padamu oleh TUHAN, Allahmu, selain dari takut akan TUHAN, Allahmu, hidup menurut segala jalan yang ditunjukkan-Nya, mengasihi Dia, beribadah kepada TUHAN, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 13, 'berpegang pada perintah dan ketetapan TUHAN yang kusampaikan kepadamu pada hari ini, supaya baik keadaanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 14, 'Sesungguhnya, TUHAN, Allahmulah yang empunya langit, bahkan langit yang mengatasi segala langit, dan bumi dengan segala isinya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 15, 'tetapi hanya oleh nenek moyangmulah hati TUHAN terpikat sehingga Ia mengasihi mereka, dan keturunan merekalah, yakni kamu, yang dipilih-Nya dari segala bangsa, seperti sekarang ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 16, 'Sebab itu sunatlah hatimu dan janganlah lagi kamu tegar tengkuk.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 17, 'Sebab TUHAN, Allahmulah Allah segala allah dan Tuhan segala tuhan, Allah yang besar, kuat dan dahsyat, yang tidak memandang bulu ataupun menerima suap;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 18, 'yang membela hak anak yatim dan janda dan menunjukkan kasih-Nya kepada orang asing dengan memberikan kepadanya makanan dan pakaian.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 19, 'Sebab itu haruslah kamu menunjukkan kasihmu kepada orang asing, sebab kamupun dahulu adalah orang asing di tanah Mesir.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 20, 'Engkau harus takut akan TUHAN, Allahmu, kepada-Nya haruslah engkau beribadah dan berpaut, dan demi nama-Nya haruslah engkau bersumpah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 21, 'Dialah pokok puji-pujianmu dan Dialah Allahmu, yang telah melakukan di antaramu perbuatan-perbuatan yang besar dan dahsyat, yang telah kaulihat dengan matamu sendiri.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 10, 22, 'Dengan tujuh puluh orang nenek moyangmu pergi ke Mesir, tetapi sekarang ini TUHAN, Allahmu, telah membuat engkau banyak seperti bintang-bintang di langit."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 1, '"Haruslah engkau mengasihi TUHAN, Allahmu, dan melakukan dengan setia kewajibanmu terhadap Dia dengan senantiasa berpegang pada segala ketetapan-Nya, peraturan-Nya dan perintah-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 2, 'Kamu tahu sekarang?kukatakan bukan kepada anak-anakmu, yang tidak mengenal dan tidak melihat hajaran TUHAN, Allahmu?kebesaran-Nya, tangan-Nya yang kuat dan lengan-Nya yang teracung,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 3, 'tanda-tanda dan perbuatan-perbuatan yang dilakukan-Nya di Mesir terhadap Firaun, raja Mesir, dan terhadap seluruh negerinya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 4, 'juga apa yang dilakukan-Nya terhadap pasukan Mesir, dengan kuda-kudanya dan kereta-keretanya, yakni bagaimana Ia membuat air Laut Teberau meluap meliputi mereka, ketika mereka mengejar kamu, sehingga TUHAN membinasakan mereka untuk selamanya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 5, 'dan apa yang dilakukan-Nya terhadapmu di padang gurun, sampai kamu tiba di tempat ini;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 6, 'pula apa yang dilakukan-Nya terhadap Datan dan Abiram, anak-anak Eliab, anak Ruben, yakni ketika tanah mengangakan mulutnya dan menelan mereka dengan seisi rumahnya, kemah-kemah dan segala yang mengikuti mereka, di tengah-tengah seluruh orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 7, 'Sebab matamu sendirilah yang telah melihat segala perbuatan besar yang dilakukan TUHAN."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 8, '"Jadi kamu harus berpegang pada seluruh perintah yang kusampaikan kepadamu pada hari ini, supaya kamu kuat untuk memasuki serta menduduki negeri, ke mana kamu pergi mendudukinya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 9, 'dan supaya lanjut umurmu di tanah yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu untuk memberikannya kepada mereka dan kepada keturunan mereka, suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 10, 'Sebab negeri, ke mana engkau masuk untuk mendudukinya, bukanlah negeri seperti tanah Mesir, dari mana kamu keluar, yang setelah ditabur dengan benih harus kauairi dengan jerih payah, seakan-akan kebun sayur.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 11, 'Tetapi negeri, ke mana kamu pergi untuk mendudukinya, ialah negeri yang bergunung-gunung dan berlembah-lembah, yang mendapat air sebanyak hujan yang turun dari langit;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 12, 'suatu negeri yang dipelihara oleh TUHAN, Allahmu: mata TUHAN, Allahmu, tetap mengawasinya dari awal sampai akhir tahun.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 13, 'Jika kamu dengan sungguh-sungguh mendengarkan perintah yang kusampaikan kepadamu pada hari ini, sehingga kamu mengasihi TUHAN, Allahmu, dan beribadah kepada-Nya dengan segenap hatimu dan dengan segenap jiwamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 14, 'maka Ia akan memberikan hujan untuk tanahmu pada masanya, hujan awal dan hujan akhir, sehingga engkau dapat mengumpulkan gandummu, anggurmu dan minyakmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 15, 'dan Dia akan memberi rumput di padangmu untuk hewanmu, sehingga engkau dapat makan dan menjadi kenyang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 16, 'Hati-hatilah, supaya jangan hatimu terbujuk, sehingga kamu menyimpang dengan beribadah kepada allah lain dan sujud menyembah kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 17, 'Jika demikian, maka akan bangkitlah murka TUHAN terhadap kamu dan Ia akan menutup langit, sehingga tidak ada hujan dan tanah tidak mengeluarkan hasil, lalu kamu lenyap dengan cepat dari negeri yang baik yang diberikan TUHAN kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 18, 'Tetapi kamu harus menaruh perkataanku ini dalam hatimu dan dalam jiwamu; kamu harus mengikatkannya sebagai tanda pada tanganmu dan haruslah itu menjadi lambang di dahimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 19, 'Kamu harus mengajarkannya kepada anak-anakmu dengan membicarakannya, apabila engkau duduk di rumahmu dan apabila engkau sedang dalam perjalanan, apabila engkau berbaring dan apabila engkau bangun;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 20, 'engkau harus menuliskannya pada tiang pintu rumahmu dan pada pintu gerbangmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 21, 'supaya panjang umurmu dan umur anak-anakmu di tanah yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu untuk memberikannya kepada mereka, selama ada langit di atas bumi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 22, 'Sebab jika kamu sungguh-sungguh berpegang pada perintah yang kusampaikan kepadamu untuk dilakukan, dengan mengasihi TUHAN, Allahmu, dengan hidup menurut segala jalan yang ditunjukkan-Nya dan dengan berpaut pada-Nya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 23, 'maka TUHAN akan menghalau segala bangsa ini dari hadapanmu, sehingga kamu menduduki daerah bangsa-bangsa yang lebih besar dan lebih kuat dari padamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 24, 'Setiap tempat yang diinjak oleh telapak kakimu, kamulah yang akan memilikinya: mulai dari padang gurun sampai gunung Libanon, dan dari sungai itu, yakni sungai Efrat, sampai laut sebelah barat, akan menjadi daerahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 25, 'Tidak ada yang akan dapat bertahan menghadapi kamu: TUHAN, Allahmu, akan membuat seluruh negeri yang kauinjak itu menjadi gemetar dan takut kepadamu, seperti yang dijanjikan TUHAN kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 26, 'Lihatlah, aku memperhadapkan kepadamu pada hari ini berkat dan kutuk:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 27, 'berkat, apabila kamu mendengarkan perintah TUHAN, Allahmu, yang kusampaikan kepadamu pada hari ini;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 28, 'dan kutuk, jika kamu tidak mendengarkan perintah TUHAN, Allahmu, dan menyimpang dari jalan yang kuperintahkan kepadamu pada hari ini, dengan mengikuti allah lain yang tidak kamu kenal.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 29, 'Jadi apabila TUHAN, Allahmu, telah membawa engkau ke negeri, yang engkau masuki untuk mendudukinya, maka haruslah engkau mengucapkan berkat di atas gunung Gerizim dan kutuk di atas gunung Ebal.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 30, 'Bukankah keduanya terletak di sebelah barat sungai Yordan, di belakang jalan raya sebelah matahari terbenam, di negeri orang Kanaan yang diam di Araba-Yordan, di tentangan Gilgal dekat pohon-pohon tarbantin di More?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 31, 'Sebab kamu ini sebentar lagi hendak menyeberangi sungai Yordan untuk memasuki dan menduduki negeri yang diberikan kepadamu oleh TUHAN, Allahmu; dan bila kamu akan menduduki dan mendiaminya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 11, 32, 'maka haruslah kamu melakukan dengan setia segala ketetapan dan peraturan yang kupaparkan kepadamu pada hari ini."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 1, '"Inilah ketetapan dan peraturan yang harus kamu lakukan dengan setia di negeri yang diberikan TUHAN, Allah nenek moyangmu, kepadamu untuk memilikinya, selama kamu hidup di muka bumi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 2, 'Kamu harus memusnahkan sama sekali segala tempat, di mana bangsa-bangsa yang daerahnya kamu duduki itu beribadah kepada allah mereka, yakni di gunung-gunung yang tinggi, di bukit-bukit dan di bawah setiap pohon yang rimbun.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 3, 'Mezbah mereka kamu harus robohkan, tugu-tugu berhala mereka kamu remukkan, tiang-tiang berhala mereka kamu bakar habis, patung-patung allah mereka kamu hancurkan, dan nama mereka kamu hapuskan dari tempat itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 4, 'Jangan kamu berbuat seperti itu terhadap TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 5, 'Tetapi tempat yang akan dipilih TUHAN, Allahmu, dari segala sukumu sebagai kediaman-Nya untuk menegakkan nama-Nya di sana, tempat itulah harus kamu cari dan ke sanalah harus kamu pergi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 6, 'Ke sanalah harus kamu bawa korban bakaran dan korban sembelihanmu, persembahan persepuluhanmu dan persembahan khususmu, korban nazarmu dan korban sukarelamu, anak-anak sulung lembu sapimu dan kambing dombamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 7, 'Di sanalah kamu makan di hadapan TUHAN, Allahmu, dan bersukaria, kamu dan seisi rumahmu, karena dalam segala usahamu engkau diberkati oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 8, 'Jangan kamu melakukan apapun yang kita lakukan di sini sekarang, yakni masing-masing berbuat segala sesuatu yang dipandangnya benar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 9, 'Sebab hingga sekarang kamu belum sampai ke tempat perhentian dan ke milik pusaka yang diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 10, 'Tetapi apabila nanti sudah kamu seberangi sungai Yordan dan kamu diam di negeri yang diberikan TUHAN, Allahmu, kepadamu untuk dimiliki, dan apabila Ia mengaruniakan kepadamu keamanan dari segala musuhmu di sekelilingmu, dan kamu diam dengan tenteram,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 11, 'maka ke tempat yang dipilih TUHAN, Allahmu, untuk membuat nama-Nya diam di sana, haruslah kamu bawa semuanya yang kuperintahkan kepadamu, yakni korban bakaran dan korban sembelihanmu, persembahan persepuluhanmu dan persembahan khususmu dan segala korban nazarmu yang terpilih, yang kamu nazarkan kepada TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 12, 'Kamu harus bersukaria di hadapan TUHAN, Allahmu, kamu ini, anakmu laki-laki dan anakmu perempuan, hambamu laki-laki dan hambamu perempuan, dan orang Lewi yang di dalam tempatmu, sebab orang Lewi tidak mendapat bagian milik pusaka bersama-sama kamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 13, 'Hati-hatilah, supaya jangan engkau mempersembahkan korban-korban bakaranmu di sembarang tempat yang kaulihat;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 14, 'tetapi di tempat yang akan dipilih TUHAN di daerah salah satu sukumu, di sanalah harus kaupersembahkan korban bakaranmu, dan di sanalah harus kaulakukan segala yang kuperintahkan kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 15, 'Tetapi engkau boleh menyembelih dan memakan daging sesuka hatimu, sesuai dengan berkat TUHAN, Allahmu, yang diberikan-Nya kepadamu di segala tempatmu. Orang najis ataupun orang tahir boleh memakannya, seperti juga daging kijang atau daging rusa;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 16, 'hanya darahnya janganlah kaumakan, tetapi harus kaucurahkan ke bumi seperti air.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 17, 'Di dalam tempatmu tidak boleh kaumakan persembahan persepuluhan dari gandummu, dari anggurmu dan minyakmu, ataupun dari anak-anak sulung lembu sapimu dan kambing dombamu, ataupun sesuatu dari korban yang akan kaunazarkan, ataupun dari korban sukarelamu, ataupun persembahan khususmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 18, 'Tetapi di hadapan TUHAN, Allahmu, haruslah engkau memakannya, di tempat yang akan dipilih TUHAN, Allahmu, engkau ini, anakmu laki-laki dan anakmu perempuan, hambamu laki-laki dan hambamu perempuan, dan orang Lewi yang di dalam tempatmu, dan haruslah engkau bersukaria di hadapan TUHAN, Allahmu, karena segala usahamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 19, 'Hati-hatilah, supaya jangan engkau melalaikan orang Lewi, selama engkau ada di tanahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 20, 'Apabila TUHAN, Allahmu, telah meluaskan daerahmu nanti, seperti yang dijanjikan-Nya kepadamu dan engkau berpikir: Aku mau makan daging, karena engkau ingin makan daging, maka bolehlah engkau makan daging sesuka hatimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 21, 'Apabila tempat yang akan dipilih TUHAN, Allahmu, untuk menegakkan nama-Nya di sana, terlalu jauh dari tempatmu, maka engkau boleh menyembelih dari lembu sapimu dan kambing dombamu yang diberikan TUHAN kepadamu, seperti yang kuperintahkan kepadamu, dan memakan dagingnya di tempatmu sesuka hatimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 22, 'Tetapi engkau harus memakan dagingnya, seperti memakan daging kijang atau daging rusa; baik orang najis maupun orang tahir boleh memakannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 23, 'Tetapi jagalah baik-baik, supaya jangan engkau memakan darahnya, sebab darah ialah nyawa, maka janganlah engkau memakan nyawa bersama-sama dengan daging.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 24, 'Janganlah engkau memakannya; engkau harus mencurahkannya ke bumi seperti air.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 25, 'Janganlah engkau memakannya, supaya baik keadaanmu dan keadaan anak-anakmu yang kemudian, apabila engkau melakukan apa yang benar di mata TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 26, 'Tetapi persembahan kudusmu yang ada padamu dan korban nazarmu haruslah kaubawa ke tempat yang akan dipilih TUHAN;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 27, 'engkau harus mengolah korban bakaranmu, daging dan darahnya, di atas mezbah TUHAN, Allahmu, dan darah korban sembelihanmu haruslah dicurahkan ke atas mezbah TUHAN, Allahmu, tetapi dagingnya boleh kaumakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 28, 'Dengarkanlah baik-baik segala yang kuperintahkan kepadamu, supaya baik keadaanmu dan keadaan anak-anakmu yang kemudian untuk selama-lamanya, apabila engkau melakukan apa yang baik dan benar di mata TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 29, '"Apabila TUHAN, Allahmu, telah melenyapkan dari hadapanmu bangsa-bangsa yang daerahnya kaumasuki untuk mendudukinya, dan apabila engkau sudah menduduki daerahnya dan diam di negerinya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 30, 'maka hati-hatilah, supaya jangan engkau kena jerat dan mengikuti mereka, setelah mereka dipunahkan dari hadapanmu, dan supaya jangan engkau menanya-nanya tentang allah mereka dengan berkata: Bagaimana bangsa-bangsa ini beribadah kepada allah mereka? Akupun mau berlaku begitu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 31, 'Jangan engkau berbuat seperti itu terhadap TUHAN, Allahmu; sebab segala yang menjadi kekejian bagi TUHAN, apa yang dibenci-Nya, itulah yang dilakukan mereka bagi allah mereka; bahkan anak-anaknya lelaki dan anak-anaknya perempuan dibakar mereka dengan api bagi allah mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 12, 32, 'Segala yang kuperintahkan kepadamu haruslah kamu lakukan dengan setia, janganlah engkau menambahinya ataupun menguranginya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 1, 'Apabila di tengah-tengahmu muncul seorang nabi atau seorang pemimpi, dan ia memberitahukan kepadamu suatu tanda atau mujizat,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 2, 'dan apabila tanda atau mujizat yang dikatakannya kepadamu itu terjadi, dan ia membujuk: Mari kita mengikuti allah lain, yang tidak kaukenal, dan mari kita berbakti kepadanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 3, 'maka janganlah engkau mendengarkan perkataan nabi atau pemimpi itu; sebab TUHAN, Allahmu, mencoba kamu untuk mengetahui, apakah kamu sungguh-sungguh mengasihi TUHAN, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 4, 'TUHAN, Allahmu, harus kamu ikuti, kamu harus takut akan Dia, kamu harus berpegang pada perintah-Nya, suara-Nya harus kamu dengarkan, kepada-Nya harus kamu berbakti dan berpaut.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 5, 'Nabi atau pemimpi itu haruslah dihukum mati, karena ia telah mengajak murtad terhadap TUHAN, Allahmu, yang telah membawa kamu keluar dari tanah Mesir dan yang menebus engkau dari rumah perbudakan?dengan maksud untuk menyesatkan engkau dari jalan yang diperintahkan TUHAN, Allahmu, kepadamu untuk dijalani. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 6, 'Apabila saudaramu laki-laki, anak ibumu, atau anakmu laki-laki atau anakmu perempuan atau isterimu sendiri atau sahabat karibmu membujuk engkau diam-diam, katanya: Mari kita berbakti kepada allah lain yang tidak dikenal olehmu ataupun oleh nenek moyangmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 7, 'salah satu allah bangsa-bangsa sekelilingmu, baik yang dekat kepadamu maupun yang jauh dari padamu, dari ujung bumi ke ujung bumi,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 8, 'maka janganlah engkau mengalah kepadanya dan janganlah mendengarkan dia. Janganlah engkau merasa sayang kepadanya, janganlah mengasihani dia dan janganlah menutupi salahnya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 9, 'tetapi bunuhlah dia! Pertama-tama tanganmu sendirilah yang bergerak untuk membunuh dia, kemudian seluruh rakyat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 10, 'Engkau harus melempari dia dengan batu, sehingga mati, karena ia telah berikhtiar menyesatkan engkau dari pada TUHAN, Allahmu, yang telah membawa engkau keluar dari tanah Mesir, dari rumah perbudakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 11, 'Maka seluruh orang Israel akan mendengar dan menjadi takut, sehingga mereka tidak akan melakukan lagi perbuatan jahat seperti itu di tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 12, 'Apabila di salah satu kota yang diberikan TUHAN, Allahmu, kepadamu untuk diam di sana, kaudengar orang berkata:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 13, 'Ada orang-orang dursila tampil dari tengah-tengahmu, yang telah menyesatkan penduduk kota mereka dengan berkata: Mari kita berbakti kepada allah lain yang tidak kamu kenal,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 14, 'maka haruslah engkau memeriksa, menyelidiki dan menanyakan baik-baik. Jikalau ternyata benar dan sudah pasti, bahwa kekejian itu dilakukan di tengah-tengahmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 15, 'maka bunuhlah dengan mata pedang penduduk kota itu, dan tumpaslah dengan mata pedang kota itu serta segala isinya dan hewannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 16, 'Seluruh jarahan harus kaukumpulkan di tengah-tengah lapangan dan harus kaubakar habis kota dengan seluruh jarahan itu sebagai korban bakaran yang lengkap bagi TUHAN, Allahmu. Semuanya itu akan tetap menjadi timbunan puing untuk selamanya dan tidak akan dibangun kembali.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 17, 'Dari barang-barang yang dikhususkan itu janganlah apapun melekat pada tanganmu, supaya TUHAN berhenti dari murka-Nya yang bernyala-nyala itu, menunjukkan belas kasihan-Nya kepadamu, mengasihani engkau dan membuat jumlahmu banyak, seperti yang dijanjikan-Nya dengan sumpah kepada nenek moyangmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 13, 18, 'Sebab dengan demikian engkau mendengarkan suara TUHAN, Allahmu, untuk berpegang pada segala perintah-Nya, yang kusampaikan kepadamu pada hari ini, dengan melakukan apa yang benar di mata TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 1, '"Kamulah anak-anak TUHAN, Allahmu; janganlah kamu menoreh-noreh dirimu ataupun menggundul rambut di atas dahimu karena kematian seseorang;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 2, 'sebab engkaulah umat yang kudus bagi TUHAN, Allahmu, dan engkau dipilih TUHAN untuk menjadi umat kesayangan-Nya dari antara segala bangsa yang di atas muka bumi."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 3, '"Janganlah engkau memakan sesuatu yang merupakan kekejian.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 4, 'Inilah binatang-binatang berkaki empat yang boleh kamu makan: lembu, domba dan kambing;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 5, 'rusa, kijang, rusa dandi, kambing hutan, kijang gunung, lembu hutan dan domba hutan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 6, 'Setiap binatang berkaki empat yang berkuku belah?yaitu yang kukunya bersela panjang menjadi dua?dan yang memamah biak di antara binatang-binatang berkaki empat, itu boleh kamu makan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 7, 'Tetapi inilah yang tidak boleh kamu makan dari antara yang memamah biak atau dari antara yang berbelah dan bersela kukunya: unta, kelinci hutan dan marmot, karena semuanya itu memang memamah biak, tetapi tidak berkuku belah; haram semuanya itu bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 8, 'Juga babi hutan, karena memang berkuku belah, tetapi tidak memamah biak; haram itu bagimu. Daging binatang-binatang itu janganlah kamu makan dan janganlah kamu terkena bangkainya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 9, 'Inilah yang boleh kamu makan dari segala yang hidup di dalam air; segala yang bersirip dan bersisik boleh kamu makan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 10, 'tetapi segala yang tidak bersirip atau bersisik janganlah kamu makan; haram semuanya itu bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 11, 'Setiap burung yang tidak haram boleh kamu makan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 12, 'Tetapi yang berikut janganlah kamu makan: burung rajawali, ering janggut dan elang laut;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 13, 'elang merah, elang hitam dan burung dendang menurut jenisnya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 14, 'setiap burung gagak menurut jenisnya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 15, 'burung unta, burung hantu, camar dan elang sikap menurut jenisnya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 16, 'burung pungguk, burung hantu besar, burung hantu putih;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 17, 'burung undan, burung ering dan burung dendang air;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 18, 'burung ranggung, dan bangau menurut jenisnya, meragai dan kelelawar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 19, 'Juga segala binatang mengeriap yang bersayap, itupun haram bagimu, jangan dimakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 20, 'Segala burung yang tidak haram boleh kamu makan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 21, 'Janganlah kamu memakan bangkai apapun, tetapi boleh kauberikan kepada pendatang yang di dalam tempatmu untuk dimakan, atau boleh kaujual kepada orang asing; sebab engkaulah umat yang kudus bagi TUHAN, Allahmu. Janganlah kaumasak anak kambing dalam air susu induknya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 22, '"Haruslah engkau benar-benar mempersembahkan sepersepuluh dari seluruh hasil benih yang tumbuh di ladangmu, tahun demi tahun.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 23, 'Di hadapan TUHAN, Allahmu, di tempat yang akan dipilih-Nya untuk membuat nama-Nya diam di sana, haruslah engkau memakan persembahan persepuluhan dari gandummu, dari anggurmu dan minyakmu, ataupun dari anak-anak sulung lembu sapimu dan kambing dombamu, supaya engkau belajar untuk selalu takut akan TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 24, 'Apabila, dalam hal engkau diberkati TUHAN, Allahmu, jalan itu terlalu jauh bagimu, sehingga engkau tidak dapat mengangkutnya, karena tempat yang akan dipilih TUHAN untuk menegakkan nama-Nya di sana terlalu jauh dari tempatmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 25, 'maka haruslah engkau menguangkannya dan membawa uang itu dalam bungkusan dan pergi ke tempat yang akan dipilih TUHAN, Allahmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 26, 'dan haruslah engkau membelanjakan uang itu untuk segala yang disukai hatimu, untuk lembu sapi atau kambing domba, untuk anggur atau minuman yang memabukkan, atau apapun yang diingini hatimu, dan haruslah engkau makan di sana di hadapan TUHAN, Allahmu dan bersukaria, engkau dan seisi rumahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 27, 'Juga orang Lewi yang diam di dalam tempatmu janganlah kauabaikan, sebab ia tidak mendapat bagian milik pusaka bersama-sama engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 28, 'Pada akhir tiga tahun engkau harus mengeluarkan segala persembahan persepuluhan dari hasil tanahmu dalam tahun itu dan menaruhnya di dalam kotamu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 14, 29, 'maka orang Lewi, karena ia tidak mendapat bagian milik pusaka bersama-sama engkau, dan orang asing, anak yatim dan janda yang di dalam tempatmu, akan datang makan dan menjadi kenyang, supaya TUHAN, Allahmu, memberkati engkau di dalam segala usaha yang dikerjakan tanganmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 1, '"Pada akhir tujuh tahun engkau harus mengadakan penghapusan hutang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 2, 'Inilah cara penghapusan itu: setiap orang yang berpiutang harus menghapuskan apa yang dipinjamkannya kepada sesamanya; janganlah ia menagih dari sesamanya atau saudaranya, karena telah dimaklumkan penghapusan hutang demi TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 3, 'Dari seorang asing boleh kautagih, tetapi piutangmu kepada saudaramu haruslah kauhapuskan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 4, 'Maka tidak akan ada orang miskin di antaramu, sebab sungguh TUHAN akan memberkati engkau di negeri yang diberikan TUHAN, Allahmu, kepadamu untuk menjadi milik pusaka,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 5, 'asal saja engkau mendengarkan baik-baik suara TUHAN, Allahmu, dan melakukan dengan setia segenap perintah yang kusampaikan kepadamu pada hari ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 6, 'Apabila TUHAN, Allahmu, memberkati engkau, seperti yang dijanjikan-Nya kepadamu, maka engkau akan memberi pinjaman kepada banyak bangsa, tetapi engkau sendiri tidak akan meminta pinjaman; engkau akan menguasai banyak bangsa, tetapi mereka tidak akan menguasai engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 7, 'Jika sekiranya ada di antaramu seorang miskin, salah seorang saudaramu di dalam salah satu tempatmu, di negeri yang diberikan kepadamu oleh TUHAN, Allahmu, maka janganlah engkau menegarkan hati ataupun menggenggam tangan terhadap saudaramu yang miskin itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 8, 'tetapi engkau harus membuka tangan lebar-lebar baginya dan memberi pinjaman kepadanya dengan limpahnya, cukup untuk keperluannya, seberapa ia perlukan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 9, 'Hati-hatilah, supaya jangan timbul di dalam hatimu pikiran dursila, demikian: Sudah dekat tahun ketujuh, tahun penghapusan hutang, dan engkau menjadi kesal terhadap saudaramu yang miskin itu dan engkau tidak memberikan apa-apa kepadanya, maka ia berseru kepada TUHAN tentang engkau, dan hal itu menjadi dosa bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 10, 'Engkau harus memberi kepadanya dengan limpahnya dan janganlah hatimu berdukacita, apabila engkau memberi kepadanya, sebab oleh karena hal itulah TUHAN, Allahmu, akan memberkati engkau dalam segala pekerjaanmu dan dalam segala usahamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 11, 'Sebab orang-orang miskin tidak hentinya akan ada di dalam negeri itu; itulah sebabnya aku memberi perintah kepadamu, demikian: Haruslah engkau membuka tangan lebar-lebar bagi saudaramu, yang tertindas dan yang miskin di negerimu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 12, '"Apabila seorang saudaramu menjual dirinya kepadamu, baik seorang laki-laki Ibrani ataupun seorang perempuan Ibrani, maka ia akan bekerja padamu enam tahun lamanya, tetapi pada tahun yang ketujuh engkau harus melepaskan dia sebagai orang merdeka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 13, 'Dan apabila engkau melepaskan dia sebagai orang merdeka, maka janganlah engkau melepaskan dia dengan tangan hampa,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 14, 'engkau harus dengan limpahnya memberi bekal kepadanya dari kambing dombamu, dari tempat pengirikanmu dan dari tempat pemerasanmu, sesuai dengan berkat yang diberikan kepadamu oleh TUHAN, Allahmu, haruslah kauberikan kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 15, 'Haruslah kauingat, bahwa engkaupun dahulu budak di tanah Mesir dan engkau ditebus TUHAN, Allahmu; itulah sebabnya aku memberi perintah itu kepadamu pada hari ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 16, 'Tetapi apabila dia berkata kepadamu: Aku tidak mau keluar meninggalkan engkau, karena ia mengasihi engkau dan keluargamu, sebab baik keadaannya padamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 17, 'maka engkau harus mengambil sebuah penusuk dan menindik telinganya pada pintu, sehingga ia menjadi budakmu untuk selama-lamanya. Demikian juga kauperbuat kepada budakmu perempuan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 18, 'Janganlah merasa susah, apabila engkau melepaskan dia sebagai orang merdeka, sebab enam tahun lamanya ia telah bekerja padamu dengan jasa dua kali upah seorang pekerja harian. Maka TUHAN, Allahmu, akan memberkati engkau dalam segala sesuatu yang kaukerjakan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 19, '"Segala anak sulung jantan yang lahir di antara lembu sapimu dan kambing dombamu, haruslah kaukuduskan bagi TUHAN, Allahmu; janganlah engkau memakai anak sulung lembumu, dan janganlah engkau menggunting bulu anak sulung dombamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 20, 'Di hadapan TUHAN, Allahmu, engkau harus memakan dagingnya tahun demi tahun di tempat yang akan dipilih TUHAN, engkau ini dan seisi rumahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 21, 'Tetapi apabila ada cacatnya, jika timpang atau buta, bahkan cacat apapun yang buruk, maka janganlah engkau menyembelihnya bagi TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 22, 'Di dalam tempatmu boleh engkau, baik orang najis maupun orang tahir, memakan dagingnya, seperti daging kijang atau daging rusa.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 15, 23, 'Hanya darahnya janganlah kaumakan; haruslah kaucurahkan ke tanah seperti air."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 1, '"Ingatlah akan bulan Abib dan rayakanlah Paskah bagi TUHAN, Allahmu, sebab dalam bulan Abib itulah TUHAN, Allahmu, membawa engkau keluar dari Mesir pada waktu malam.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 2, 'Maka engkau harus menyembelih kambing domba dan lembu sapi sebagai korban Paskah bagi TUHAN, Allahmu, di tempat yang akan dipilih TUHAN untuk membuat nama-Nya diam di sana.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 3, 'Janganlah engkau makan sesuatu yang beragi besertanya; tujuh hari lamanya engkau harus makan roti yang tidak beragi besertanya, yakni roti penderitaan, sebab dengan buru-buru engkau keluar dari tanah Mesir. Maksudnya supaya seumur hidupmu engkau teringat akan hari engkau keluar dari tanah Mesir.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 4, 'Janganlah terdapat padamu ragi di seluruh daerahmu, tujuh hari lamanya; dan dari daging hewan yang kausembelih pada waktu petang pada hari pertama, janganlah ada yang bermalam sampai pagi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 5, 'Engkau tidak boleh mempersembahkan korban Paskah di salah satu tempat yang diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 6, 'Tetapi di tempat yang akan dipilih TUHAN, Allahmu, untuk membuat nama-Nya diam di sana, engkau harus mempersembahkan korban Paskah itu pada waktu senja, ketika matahari terbenam, bertepatan dengan saat engkau keluar dari Mesir.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 7, 'Engkau harus memasaknya dan memakannya di tempat yang akan dipilih TUHAN, Allahmu; kemudian paginya engkau harus pulang kembali ke kemahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 8, 'Enam hari lamanya engkau harus makan roti yang tidak beragi dan pada hari yang ketujuh harus ada perkumpulan raya bagi TUHAN, Allahmu; maka janganlah engkau melakukan pekerjaan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 9, 'Tujuh minggu harus kauhitung: pada waktu orang mulai menyabit gandum yang belum dituai, haruslah engkau mulai menghitung tujuh minggu itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 10, 'Kemudian haruslah engkau merayakan hari raya Tujuh Minggu bagi TUHAN, Allahmu, sekedar persembahan sukarela yang akan kauberikan, sesuai dengan berkat yang diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 11, 'Haruslah engkau bersukaria di hadapan TUHAN, Allahmu, engkau ini dan anakmu laki-laki serta anakmu perempuan, hambamu laki-laki dan hambamu perempuan, dan orang Lewi yang di dalam tempatmu, dan orang asing, anak yatim dan janda, yang di tengah-tengahmu, di tempat yang akan dipilih TUHAN, Allahmu, untuk membuat nama-Nya diam di sana.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 12, 'Haruslah kauingat, bahwa engkaupun dahulu budak di Mesir, dan haruslah engkau melakukan ketetapan ini dengan setia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 13, 'Hari raya Pondok Daun haruslah kaurayakan tujuh hari lamanya, apabila engkau selesai mengumpulkan hasil tempat pengirikanmu dan tempat pemerasanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 14, 'Haruslah engkau bersukaria pada hari rayamu itu, engkau ini dan anakmu laki-laki serta anakmu perempuan, hambamu laki-laki dan hambamu perempuan, dan orang Lewi, orang asing, anak yatim dan janda yang di dalam tempatmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 15, 'Tujuh hari lamanya harus engkau mengadakan perayaan bagi TUHAN, Allahmu, di tempat yang akan dipilih TUHAN; sebab TUHAN, Allahmu, akan memberkati engkau dalam segala hasil tanahmu dan dalam segala usahamu, sehingga engkau dapat bersukaria dengan sungguh-sungguh.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 16, 'Tiga kali setahun setiap orang laki-laki di antaramu harus menghadap hadirat TUHAN, Allahmu, ke tempat yang akan dipilih-Nya, yakni pada hari raya Roti Tidak Beragi, pada hari raya Tujuh Minggu dan pada hari raya Pondok Daun. Janganlah ia menghadap hadirat TUHAN dengan tangan hampa,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 17, 'tetapi masing-masing dengan sekedar persembahan, sesuai dengan berkat yang diberikan kepadamu oleh TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 18, '"Hakim-hakim dan petugas-petugas haruslah kauangkat di segala tempat yang diberikan TUHAN, Allahmu, kepadamu, menurut suku-sukumu; mereka harus menghakimi bangsa itu dengan pengadilan yang adil.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 19, 'Janganlah memutarbalikkan keadilan, janganlah memandang bulu dan janganlah menerima suap, sebab suap membuat buta mata orang-orang bijaksana dan memutarbalikkan perkataan orang-orang yang benar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 20, 'Semata-mata keadilan, itulah yang harus kaukejar, supaya engkau hidup dan memiliki negeri yang diberikan kepadamu oleh TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 21, '"Janganlah engkau menanam sesuatu pohon sebagai tiang berhala di samping mezbah TUHAN, Allahmu, mezbah yang akan kaubuat bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 16, 22, 'Janganlah juga kaudirikan bagimu tugu berhala, yang dibenci oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 1, 'Janganlah engkau mempersembahkan bagi TUHAN, Allahmu, lembu atau domba, yang ada cacatnya, atau sesuatu yang buruk; sebab yang demikian adalah kekejian bagi TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 2, '"Apabila di tengah-tengahmu di salah satu tempatmu yang diberikan kepadamu oleh TUHAN, Allahmu, ada terdapat seorang laki-laki atau perempuan yang melakukan apa yang jahat di mata TUHAN, Allahmu, dengan melangkahi perjanjian-Nya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 3, 'dan yang pergi beribadah kepada allah lain dan sujud menyembah kepadanya, atau kepada matahari atau bulan atau segenap tentara langit, hal yang telah Kularang itu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 4, 'dan apabila hal itu diberitahukan atau terdengar kepadamu, maka engkau harus memeriksanya baik-baik. Jikalau ternyata benar dan sudah pasti, bahwa kekejian itu dilakukan di antara orang Israel,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 5, 'maka engkau harus membawa laki-laki atau perempuan yang telah melakukan perbuatan jahat itu ke luar ke pintu gerbang, kemudian laki-laki atau perempuan itu harus kaulempari dengan batu sampai mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 6, 'Atas keterangan dua atau tiga orang saksi haruslah mati dibunuh orang yang dihukum mati; atas keterangan satu orang saksi saja janganlah ia dihukum mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 7, 'Saksi-saksi itulah yang pertama-tama menggerakkan tangan mereka untuk membunuh dia, kemudian seluruh rakyat. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 8, '"Apabila sesuatu perkara terlalu sukar bagimu untuk diputuskan, misalnya bunuh-membunuh, tuntut-menuntut, atau luka-melukai?perkara pendakwaan di dalam tempatmu?maka haruslah engkau pergi menghadap ke tempat yang akan dipilih TUHAN, Allahmu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 9, 'haruslah engkau pergi kepada imam-imam orang Lewi dan kepada hakim yang ada pada waktu itu, dan meminta putusan. Mereka akan memberitahukan kepadamu keputusan hakim.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 10, 'Dan engkau harus berbuat menurut keputusan yang diberitahukan mereka kepadamu dari tempat yang akan dipilih TUHAN; engkau harus melakukan dengan setia segala yang ditunjukkan mereka kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 11, 'Menurut petunjuk yang diberikan mereka kepadamu dan menurut keputusan yang dikatakan mereka kepadamu haruslah engkau berbuat; janganlah engkau menyimpang ke kanan atau ke kiri dari keputusan yang diberitahukan mereka kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 12, 'Orang yang berlaku terlalu berani dengan tidak mendengarkan perkataan imam yang berdiri di sana sebagai pelayan TUHAN, Allahmu, ataupun perkataan hakim, maka orang itu harus mati. Demikianlah harus kauhapuskan yang jahat itu dari antara orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 13, 'Maka seluruh bangsa itu akan mendengar dan menjadi takut dan tidak lagi berlaku terlalu berani."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 14, '"Apabila engkau telah masuk ke negeri yang diberikan kepadamu oleh TUHAN, Allahmu, dan telah mendudukinya dan diam di sana, kemudian engkau berkata: Aku mau mengangkat raja atasku, seperti segala bangsa yang di sekelilingku,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 15, 'maka hanyalah raja yang dipilih TUHAN, Allahmu, yang harus kauangkat atasmu. Dari tengah-tengah saudara-saudaramu haruslah engkau mengangkat seorang raja atasmu; seorang asing yang bukan saudaramu tidaklah boleh kauangkat atasmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 16, 'Hanya, janganlah ia memelihara banyak kuda dan janganlah ia mengembalikan bangsa ini ke Mesir untuk mendapat banyak kuda, sebab TUHAN telah berfirman kepadamu: Janganlah sekali-kali kamu kembali melalui jalan ini lagi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 17, 'Juga janganlah ia mempunyai banyak isteri, supaya hatinya jangan menyimpang; emas dan perakpun janganlah ia kumpulkan terlalu banyak.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 18, 'Apabila ia duduk di atas takhta kerajaan, maka haruslah ia menyuruh menulis baginya salinan hukum ini menurut kitab yang ada pada imam-imam orang Lewi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 19, 'Itulah yang harus ada di sampingnya dan haruslah ia membacanya seumur hidupnya untuk belajar takut akan TUHAN, Allahnya, dengan berpegang pada segala isi hukum dan ketetapan ini untuk dilakukannya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 17, 20, 'supaya jangan ia tinggi hati terhadap saudara-saudaranya, supaya jangan ia menyimpang dari perintah itu ke kanan atau ke kiri, agar lama ia memerintah, ia dan anak-anaknya di tengah-tengah orang Israel."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 1, '"Imam-imam orang Lewi, seluruh suku Lewi, janganlah mendapat bagian milik pusaka bersama-sama orang Israel; dari korban api-apian kepada TUHAN dan apa yang menjadi milik-Nya harus mereka mendapat rezeki.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 2, 'Janganlah ia mempunyai milik pusaka di tengah-tengah saudara-saudaranya; Tuhanlah milik pusakanya, seperti yang dijanjikan-Nya kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 3, 'Inilah hak imam terhadap kaum awam, terhadap mereka yang mempersembahkan korban sembelihan, baik lembu maupun domba: kepada imam haruslah diberikan paha depan, kedua rahang dan perut besar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 4, 'Hasil pertama dari gandummu, dari anggurmu dan minyakmu, dan bulu guntingan pertama dari dombamu haruslah kauberikan kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 5, 'Sebab dialah yang dipilih oleh TUHAN, Allahmu, dari segala sukumu, supaya ia senantiasa melayani TUHAN dan menyelenggarakan kebaktian demi nama-Nya, ia dan anak-anaknya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 6, 'Apabila seorang Lewi datang dari tempat manapun di Israel, di mana ia tinggal sebagai pendatang, dan dengan sepenuh hati masuk ke tempat yang akan dipilih TUHAN,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 7, 'dan menyelenggarakan kebaktian demi nama TUHAN, Allahnya, sama seperti semua saudaranya, orang-orang Lewi, yang melayani TUHAN di sana,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 8, 'maka haruslah mereka mendapat rezeki yang sama, dengan tidak terhitung apa yang ia peroleh dengan menjual harta nenek moyangnya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 9, '"Apabila engkau sudah masuk ke negeri yang diberikan kepadamu oleh TUHAN, Allahmu, maka janganlah engkau belajar berlaku sesuai dengan kekejian yang dilakukan bangsa-bangsa itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 10, 'Di antaramu janganlah didapati seorangpun yang mempersembahkan anaknya laki-laki atau anaknya perempuan sebagai korban dalam api, ataupun seorang yang menjadi petenung, seorang peramal, seorang penelaah, seorang penyihir,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 11, 'seorang pemantera, ataupun seorang yang bertanya kepada arwah atau kepada roh peramal atau yang meminta petunjuk kepada orang-orang mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 12, 'Sebab setiap orang yang melakukan hal-hal ini adalah kekejian bagi TUHAN, dan oleh karena kekejian-kekejian inilah TUHAN, Allahmu, menghalau mereka dari hadapanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 13, 'Haruslah engkau hidup dengan tidak bercela di hadapan TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 14, 'Sebab bangsa-bangsa yang daerahnya akan kaududuki ini mendengarkan kepada peramal atau petenung, tetapi engkau ini tidak diizinkan TUHAN, Allahmu, melakukan yang demikian.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 15, 'Seorang nabi dari tengah-tengahmu, dari antara saudara-saudaramu, sama seperti aku, akan dibangkitkan bagimu oleh TUHAN, Allahmu; dialah yang harus kamu dengarkan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 16, 'Tepat seperti yang kamu minta dahulu kepada TUHAN, Allahmu, di gunung Horeb, pada hari perkumpulan, dengan berkata: Tidak mau aku mendengar lagi suara TUHAN, Allahku, dan api yang besar ini tidak mau aku melihatnya lagi, supaya jangan aku mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 17, 'Lalu berkatalah TUHAN kepadaku: Apa yang dikatakan mereka itu baik;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 18, 'seorang nabi akan Kubangkitkan bagi mereka dari antara saudara mereka, seperti engkau ini; Aku akan menaruh firman-Ku dalam mulutnya, dan ia akan mengatakan kepada mereka segala yang Kuperintahkan kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 19, 'Orang yang tidak mendengarkan segala firman-Ku yang akan diucapkan nabi itu demi nama-Ku, dari padanya akan Kutuntut pertanggungjawaban.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 20, 'Tetapi seorang nabi, yang terlalu berani untuk mengucapkan demi nama-Ku perkataan yang tidak Kuperintahkan untuk dikatakan olehnya, atau yang berkata demi nama allah lain, nabi itu harus mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 21, 'Jika sekiranya kamu berkata dalam hatimu: Bagaimanakah kami mengetahui perkataan yang tidak difirmankan TUHAN? ?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 18, 22, 'apabila seorang nabi berkata demi nama TUHAN dan perkataannya itu tidak terjadi dan tidak sampai, maka itulah perkataan yang tidak difirmankan TUHAN; dengan terlalu berani nabi itu telah mengatakannya, maka janganlah gentar kepadanya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 1, '"Apabila TUHAN, Allahmu, sudah melenyapkan bangsa-bangsa yang negerinya diberikan kepadamu oleh TUHAN, Allahmu, dan engkau sudah menduduki daerah mereka dan diam di kota-kota dan rumah-rumah mereka,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 2, 'maka engkau harus mengkhususkan tiga kota di dalam negeri yang diberikan TUHAN, Allahmu, kepadamu untuk diduduki.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 3, 'Engkau harus menetapkan jauhnya jalan, dan membagi dalam tiga bagian wilayah negeri yang diberikan TUHAN, Allahmu, untuk dimiliki olehmu, supaya setiap pembunuh dapat melarikan diri ke sana.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 4, 'Inilah ketentuan mengenai pembunuh yang melarikan diri ke sana dan boleh tinggal hidup: apabila ia membunuh sesamanya manusia dengan tidak sengaja dan dengan tidak membenci dia sebelumnya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 5, 'misalnya apabila seseorang pergi ke hutan dengan temannya untuk membelah kayu, ketika tangannya mengayunkan kapak untuk menebang pohon kayu, mata kapak terlucut dari gagangnya, lalu mengenai temannya sehingga mati, maka ia boleh melarikan diri ke salah satu kota itu dan tinggal hidup.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 6, 'Maksudnya supaya jangan penuntut tebusan darah sementara hatinya panas dapat mengejar pembunuh itu, karena jauhnya perjalanan, menangkapnya dan membunuhnya, padahal pembunuh itu tidak patut mendapat hukuman mati, karena ia tidak membenci dia sebelumnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 7, 'Itulah sebabnya aku memberi perintah kepadamu, demikian: tiga kota haruslah kaukhususkan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 8, 'Dan jika TUHAN, Allahmu, sudah meluaskan daerahmu nanti, seperti yang dijanjikan-Nya dengan sumpah kepada nenek moyangmu, dan sudah memberikan kepadamu seluruh negeri yang dikatakan-Nya akan diberikan kepada nenek moyangmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 9, '?apabila engkau melakukan dengan setia perintah ini, yang kusampaikan kepadamu pada hari ini, dengan mengasihi TUHAN, Allahmu, dan dengan senantiasa hidup menurut jalan yang ditunjukkan-Nya?maka haruslah engkau menambah tiga kota lagi kepada yang tiga itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 10, 'supaya jangan tercurah darah orang yang tidak bersalah di negeri yang diberikan TUHAN, Allahmu, kepadamu menjadi milikmu dan hutang darah melekat kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 11, 'Tetapi apabila seseorang membenci sesamanya manusia, dan dengan bersembunyi menantikan dia, lalu bangun menyerang dan memukul dia, sehingga mati, kemudian melarikan diri ke salah satu kota itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 12, 'maka haruslah para tua-tua kotanya menyuruh mengambil dia dari sana dan menyerahkan dia kepada penuntut tebusan darah, supaya ia mati dibunuh.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 13, 'Janganlah engkau merasa sayang kepadanya. Demikianlah harus kauhapuskan darah orang yang tidak bersalah dari antara orang Israel, supaya baik keadaanmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 14, '"Janganlah menggeser batas tanah sesamamu yang telah ditetapkan oleh orang-orang dahulu di dalam milik pusaka yang akan kaumiliki di negeri yang diberikan TUHAN, Allahmu, kepadamu untuk menjadi milikmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 15, '"Satu orang saksi saja tidak dapat menggugat seseorang mengenai perkara kesalahan apapun atau dosa apapun yang mungkin dilakukannya; baru atas keterangan dua atau tiga orang saksi perkara itu tidak disangsikan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 16, 'Apabila seorang saksi jahat menggugat seseorang untuk menuduh dia mengenai suatu pelanggaran,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 17, 'maka kedua orang yang mempunyai perkara itu haruslah berdiri di hadapan TUHAN, di hadapan imam-imam dan hakim-hakim yang ada pada waktu itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 18, 'Maka hakim-hakim itu harus memeriksanya baik-baik, dan apabila ternyata, bahwa saksi itu seorang saksi dusta dan bahwa ia telah memberi tuduhan dusta terhadap saudaranya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 19, 'maka kamu harus memperlakukannya sebagaimana ia bermaksud memperlakukan saudaranya. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 20, 'Maka orang-orang lain akan mendengar dan menjadi takut, sehingga mereka tidak akan melakukan lagi perbuatan jahat seperti itu di tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 19, 21, 'Janganlah engkau merasa sayang kepadanya, sebab berlaku: nyawa ganti nyawa, mata ganti mata, gigi ganti gigi, tangan ganti tangan, kaki ganti kaki."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 1, '"Apabila engkau keluar berperang melawan musuhmu, dan engkau melihat kuda dan kereta, yakni tentara yang lebih banyak dari padamu, maka janganlah engkau takut kepadanya, sebab TUHAN, Allahmu, yang telah menuntun engkau keluar dari tanah Mesir, menyertai engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 2, 'Apabila kamu menghadapi pertempuran, maka seorang imam harus tampil ke depan dan berbicara kepada rakyat,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 3, 'dengan berkata kepada mereka: Dengarlah, hai orang Israel! Kamu sekarang menghadapi pertempuran melawan musuhmu; janganlah lemah hatimu, janganlah takut, janganlah gentar dan janganlah gemetar karena mereka,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 4, 'sebab TUHAN, Allahmu, Dialah yang berjalan menyertai kamu untuk berperang bagimu melawan musuhmu, dengan maksud memberikan kemenangan kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 5, 'Para pengatur pasukan haruslah berbicara kepada tentara, demikian: Siapakah orang yang telah mendirikan rumah baru, tetapi belum menempatinya? Ia boleh pergi dan pulang ke rumahnya, supaya jangan ia mati dalam pertempuran dan orang lain yang menempatinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 6, 'Dan siapa telah membuat kebun anggur, tetapi belum mengecap hasilnya? Ia boleh pergi dan pulang ke rumahnya, supaya jangan ia mati dalam pertempuran dan orang lain yang mengecap hasilnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 7, 'Dan siapa telah bertunangan dengan seorang perempuan, tetapi belum mengawininya? Ia boleh pergi dan pulang ke rumahnya, supaya jangan ia mati dalam pertempuran dan orang lain yang mengawininya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 8, 'Lagi para pengatur pasukan itu harus berbicara kepada tentara demikian: Siapa takut dan lemah hati? Ia boleh pergi dan pulang ke rumahnya, supaya hati saudara-saudaranya jangan tawar seperti hatinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 9, 'Apabila para pengatur pasukan selesai berbicara kepada tentara, maka haruslah ditunjuk kepala-kepala pasukan untuk mengepalai tentara.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 10, 'Apabila engkau mendekati suatu kota untuk berperang melawannya, maka haruslah engkau menawarkan perdamaian kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 11, 'Apabila kota itu menerima tawaran perdamaian itu dan dibukanya pintu gerbang bagimu, maka haruslah semua orang yang terdapat di situ melakukan pekerjaan rodi bagimu dan menjadi hamba kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 12, 'Tetapi apabila kota itu tidak mau berdamai dengan engkau, melainkan mengadakan pertempuran melawan engkau, maka haruslah engkau mengepungnya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 13, 'dan setelah TUHAN, Allahmu, menyerahkannya ke dalam tanganmu, maka haruslah engkau membunuh seluruh penduduknya yang laki-laki dengan mata pedang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 14, 'Hanya perempuan, anak-anak, hewan dan segala yang ada di kota itu, yakni seluruh jarahan itu, boleh kaurampas bagimu sendiri, dan jarahan yang dari musuhmu ini, yang diberikan kepadamu oleh TUHAN, Allahmu, boleh kaupergunakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 15, 'Demikianlah harus kaulakukan terhadap segala kota yang sangat jauh letaknya dari tempatmu, yang tidak termasuk kota-kota bangsa-bangsa di sini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 16, 'Tetapi dari kota-kota bangsa-bangsa itu yang diberikan TUHAN, Allahmu, kepadamu menjadi milik pusakamu, janganlah kaubiarkan hidup apapun yang bernafas,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 17, 'melainkan kautumpas sama sekali, yakni orang Het, orang Amori, orang Kanaan, orang Feris, orang Hewi, dan orang Yebus, seperti yang diperintahkan kepadamu oleh TUHAN, Allahmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 18, 'supaya mereka jangan mengajar kamu berbuat sesuai dengan segala kekejian, yang dilakukan mereka bagi allah mereka, sehingga kamu berbuat dosa kepada TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 19, 'Apabila dalam memerangi suatu kota, engkau lama mengepungnya untuk direbut, maka tidak boleh engkau merusakkan pohon-pohon sekelilingnya dengan mengayunkan kapak kepadanya; buahnya boleh kaumakan, tetapi batangnya janganlah kautebang; sebab, pohon yang di padang itu bukan manusia, jadi tidak patut ikut kaukepung.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 20, 20, 'Hanya pohon-pohon, yang engkau tahu tidak menghasilkan makanan, boleh kaurusakkan dan kautebang untuk mendirikan pagar pengepungan terhadap kota yang berperang melawan engkau, sampai kota itu jatuh."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 1, '"Apabila di tanah yang diberikan TUHAN, Allahmu, kepadamu untuk menjadi milikmu, terdapat seorang yang mati terbunuh di padang, dengan tidak diketahui siapa yang membunuhnya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 2, 'maka haruslah para tua-tuamu dan para hakimmu keluar mengukur jarak ke kota-kota yang di sekeliling orang yang terbunuh itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 3, 'Kota yang ternyata paling dekat dengan tempat orang yang terbunuh itu, para tua-tua kota itulah harus mengambil seekor lembu betina yang muda, yang belum pernah dipakai, yang belum pernah menghela dengan kuk.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 4, 'Para tua-tua kota itu haruslah membawa lembu muda itu ke suatu lembah yang selalu berair dan yang belum pernah dikerjakan atau ditaburi, dan di sana di lembah itu haruslah mereka mematahkan batang leher lembu muda itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 5, 'Imam-imam bani Lewi haruslah tampil ke depan, sebab merekalah yang dipilih TUHAN, Allahmu, untuk melayani Dia dan untuk memberi berkat demi nama TUHAN; menurut putusan merekalah setiap perkara dan setiap hal luka-melukai harus diselesaikan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 6, 'Dan semua tua-tua dari kota yang paling dekat dengan tempat orang yang terbunuh itu, haruslah membasuh tangannya di atas lembu muda yang batang lehernya dipatahkan di lembah itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 7, 'dan mereka harus memberi pernyataan dengan mengatakan: Tangan kami tidak mencurahkan darah ini dan mata kami tidak melihatnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 8, 'Adakanlah pendamaian bagi umat-Mu Israel yang telah Kautebus itu, TUHAN, dan janganlah timpakan darah orang yang tidak bersalah ke tengah-tengah umat-Mu Israel. Maka karena darah itu telah diadakan pendamaian bagi mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 9, 'Demikianlah engkau harus menghapuskan darah orang yang tidak bersalah itu dari tengah-tengahmu, sebab dengan demikian engkau melakukan apa yang benar di mata TUHAN."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 10, '"Apabila engkau keluar berperang melawan musuhmu, dan TUHAN, Allahmu, menyerahkan mereka ke dalam tanganmu dan engkau menjadikan mereka tawanan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 11, 'dan engkau melihat di antara tawanan itu seorang perempuan yang elok, sehingga hatimu mengingini dia dan engkau mau mengambil dia menjadi isterimu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 12, 'maka haruslah engkau membawa dia ke dalam rumahmu. Perempuan itu harus mencukur rambutnya, memotong kukunya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 13, 'menanggalkan pakaian yang dipakainya pada waktu ditawan, dan tinggal di rumahmu untuk menangisi ibu bapanya sebulan lamanya. Sesudah demikian, bolehlah engkau menghampiri dia dan menjadi suaminya, sehingga ia menjadi isterimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 14, 'Apabila engkau tidak suka lagi kepadanya, maka haruslah engkau membiarkan dia pergi sesuka hatinya; tidak boleh sekali-kali engkau menjual dia dengan bayaran uang; tidak boleh engkau memperlakukan dia sebagai budak, sebab engkau telah memaksa dia."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 15, '"Apabila seorang mempunyai dua orang isteri, yang seorang dicintai dan yang lain tidak dicintainya, dan mereka melahirkan anak-anak lelaki baginya, baik isteri yang dicintai maupun isteri yang tidak dicintai, dan anak sulung adalah dari isteri yang tidak dicintai,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 16, 'maka pada waktu ia membagi warisan harta kepunyaannya kepada anak-anaknya itu, tidaklah boleh ia memberikan bagian anak sulung kepada anak dari isteri yang dicintai merugikan anak dari isteri yang tidak dicintai, yang adalah anak sulung.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 17, 'Tetapi ia harus mengakui anak yang sulung, anak dari isteri yang tidak dicintai itu, dengan memberikan kepadanya dua bagian dari segala kepunyaannya, sebab dialah kegagahannya yang pertama-tama: dialah yang empunya hak kesulungan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 18, '"Apabila seseorang mempunyai anak laki-laki yang degil dan membangkang, yang tidak mau mendengarkan perkataan ayahnya dan ibunya, dan walaupun mereka menghajar dia, tidak juga ia mendengarkan mereka,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 19, 'maka haruslah ayahnya dan ibunya memegang dia dan membawa dia keluar kepada para tua-tua kotanya di pintu gerbang tempat kediamannya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 20, 'dan harus berkata kepada para tua-tua kotanya: Anak kami ini degil dan membangkang, ia tidak mau mendengarkan perkataan kami, ia seorang pelahap dan peminum.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 21, 'Maka haruslah semua orang sekotanya melempari anak itu dengan batu, sehingga ia mati. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu; dan seluruh orang Israel akan mendengar dan menjadi takut."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 22, '"Apabila seseorang berbuat dosa yang sepadan dengan hukuman mati, lalu ia dihukum mati, kemudian kaugantung dia pada sebuah tiang,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 21, 23, 'maka janganlah mayatnya dibiarkan semalam-malaman pada tiang itu, tetapi haruslah engkau menguburkan dia pada hari itu juga, sebab seorang yang digantung terkutuk oleh Allah; janganlah engkau menajiskan tanah yang diberikan TUHAN, Allahmu, kepadamu menjadi milik pusakamu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 1, '"Apabila engkau melihat, bahwa lembu atau domba saudaramu tersesat, janganlah engkau pura-pura tidak tahu; haruslah engkau benar-benar mengembalikannya kepada saudaramu itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 2, 'Dan apabila saudaramu itu tidak tinggal dekat denganmu dan engkau tidak mengenalnya, maka haruslah engkau membawa hewan itu ke dalam rumahmu dan haruslah itu tinggal padamu, sampai saudaramu itu datang mencarinya; engkau harus mengembalikannya kepadanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 3, 'Demikianlah harus kauperbuat dengan keledainya, demikianlah kauperbuat dengan pakaiannya, demikianlah kauperbuat dengan setiap barang yang hilang dari saudaramu dan yang kautemui; tidak boleh engkau pura-pura tidak tahu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 4, 'Apabila engkau melihat keledai saudaramu atau lembunya rebah di jalan, janganlah engkau pura-pura tidak tahu; engkau harus benar-benar menolong membangunkannya bersama-sama dengan saudaramu itu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 5, '"Seorang perempuan janganlah memakai pakaian laki-laki dan seorang laki-laki janganlah mengenakan pakaian perempuan, sebab setiap orang yang melakukan hal ini adalah kekejian bagi TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 6, 'Apabila engkau menemui di jalan sarang burung di salah satu pohon atau di tanah dengan anak-anak burung atau telur-telur di dalamnya, dan induknya sedang duduk mendekap anak-anak atau telur-telur itu, maka janganlah engkau mengambil induk itu bersama-sama dengan anak-anaknya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 7, 'Setidak-tidaknya induk itu haruslah kaulepaskan, tetapi anak-anaknya boleh kauambil. Maksudnya supaya baik keadaanmu dan lanjut umurmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 8, 'Apabila engkau mendirikan rumah yang baru, maka haruslah engkau memagari sotoh rumahmu, supaya jangan kaudatangkan hutang darah kepada rumahmu itu, apabila ada seorang jatuh dari atasnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 9, 'Janganlah kautaburi kebun anggurmu dengan dua jenis benih, supaya seluruh hasil benih yang kautaburkan dan hasil kebun anggurmu jangan menjadi milik tempat kudus.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 10, 'Janganlah engkau membajak dengan lembu dan keledai bersama-sama.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 11, 'Janganlah engkau memakai pakaian yang dua jenis bahannya, yakni bulu domba dan lenan bersama-sama.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 12, 'Haruslah engkau membuat tali yang terpilin pada keempat punca kain penutup tubuhmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 13, '"Apabila seseorang mengambil isteri dan setelah menghampiri perempuan itu, menjadi benci kepadanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 14, 'menuduhkan kepadanya perbuatan yang kurang senonoh dan membusukkan namanya dengan berkata: Perempuan ini kuambil menjadi isteriku, tetapi ketika ia kuhampiri, tidak ada kudapati padanya tanda-tanda keperawanan?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 15, 'maka haruslah ayah dan ibu gadis itu memperlihatkan tanda-tanda keperawanan gadis itu kepada para tua-tua kota di pintu gerbang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 16, 'Dan ayah si gadis haruslah berkata kepada para tua-tua itu: Aku telah memberikan anakku kepada laki-laki ini menjadi isterinya, lalu ia menjadi benci kepadanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 17, 'dan ketahuilah, ia menuduhkan perbuatan yang kurang senonoh dengan berkata: Tidak ada kudapati tanda-tanda keperawanan pada anakmu. Tetapi inilah tanda-tanda keperawanan anakku itu. Lalu haruslah mereka membentangkan kain itu di depan para tua-tua kota.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 18, 'Maka haruslah para tua-tua kota itu mengambil laki-laki itu, menghajar dia,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 19, 'mendenda dia seratus syikal perak dan memberikan perak itu kepada ayah si gadis?karena laki-laki itu telah membusukkan nama seorang perawan Israel. Perempuan itu haruslah tetap menjadi isterinya; selama hidupnya tidak boleh laki-laki itu menyuruh dia pergi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 20, 'Tetapi jika tuduhan itu benar dan tidak didapati tanda-tanda keperawanan pada si gadis,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 21, 'maka haruslah si gadis dibawa ke luar ke depan pintu rumah ayahnya, dan orang-orang sekotanya haruslah melempari dia dengan batu, sehingga mati?sebab dia telah menodai orang Israel dengan bersundal di rumah ayahnya. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 22, 'Apabila seseorang kedapatan tidur dengan seorang perempuan yang bersuami, maka haruslah keduanya dibunuh mati: laki-laki yang telah tidur dengan perempuan itu dan perempuan itu juga. Demikianlah harus kauhapuskan yang jahat itu dari antara orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 23, 'Apabila ada seorang gadis yang masih perawan dan yang sudah bertunangan?jika seorang laki-laki bertemu dengan dia di kota dan tidur dengan dia,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 24, 'maka haruslah mereka keduanya kamu bawa ke luar ke pintu gerbang kota dan kamu lempari dengan batu, sehingga mati: gadis itu, karena walaupun di kota, ia tidak berteriak-teriak, dan laki-laki itu, karena ia telah memperkosa isteri sesamanya manusia. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 25, 'Tetapi jikalau di padang laki-laki itu bertemu dengan gadis yang telah bertunangan itu, memaksa gadis itu tidur dengan dia, maka hanyalah laki-laki yang tidur dengan gadis itu yang harus mati,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 26, 'tetapi gadis itu janganlah kauapa-apakan. Gadis itu tidak ada dosanya yang sepadan dengan hukuman mati, sebab perkara ini sama dengan perkara seseorang yang menyerang sesamanya manusia dan membunuhnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 27, 'Sebab laki-laki itu bertemu dengan dia di padang; walaupun gadis yang bertunangan itu berteriak-teriak, tetapi tidak ada yang datang menolongnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 28, 'Apabila seseorang bertemu dengan seorang gadis, yang masih perawan dan belum bertunangan, memaksa gadis itu tidur dengan dia, dan keduanya kedapatan?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 29, 'maka haruslah laki-laki yang sudah tidur dengan gadis itu memberikan lima puluh syikal perak kepada ayah gadis itu, dan gadis itu haruslah menjadi isterinya, sebab laki-laki itu telah memperkosa dia; selama hidupnya tidak boleh laki-laki itu menyuruh dia pergi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 22, 30, 'Seorang laki-laki janganlah mengambil isteri ayahnya dan jangan menyingkapkan punca kain ayahnya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 1, '"Orang yang hancur buah pelirnya atau yang terpotong kemaluannya, janganlah masuk jemaah TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 2, 'Seorang anak haram janganlah masuk jemaah TUHAN, bahkan keturunannya yang kesepuluhpun tidak boleh masuk jemaah TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 3, 'Seorang Amon atau seorang Moab janganlah masuk jemaah TUHAN, bahkan keturunannya yang kesepuluhpun tidak boleh masuk jemaah TUHAN sampai selama-lamanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 4, 'karena mereka tidak menyongsong kamu dengan roti dan air pada waktu perjalananmu keluar dari Mesir, dan karena mereka mengupah Bileam bin Beor dari Petor di Aram-Mesopotamia melawan engkau, supaya dikutukinya engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 5, 'Tetapi TUHAN, Allahmu, tidak mau mendengarkan Bileam dan TUHAN, Allahmu, telah mengubah kutuk itu menjadi berkat bagimu, karena TUHAN, Allahmu, mengasihi engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 6, 'Selama engkau hidup, janganlah engkau mengikhtiarkan kesejahteraan dan kebahagiaan mereka sampai selama-lamanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 7, 'Janganlah engkau menganggap keji orang Edom, sebab dia saudaramu. Janganlah engkau menganggap keji orang Mesir, sebab engkaupun dahulu adalah orang asing di negerinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 8, 'Anak-anak yang lahir bagi mereka dalam keturunan yang ketiga, boleh masuk jemaah TUHAN."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 9, '"Apabila engkau maju dengan tentaramu melawan musuhmu, maka haruslah engkau menjaga diri terhadap segala yang jahat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 10, 'Apabila ada di antaramu seorang laki-laki yang tidak tahir disebabkan oleh sesuatu yang terjadi atasnya pada malam hari, maka haruslah ia pergi ke luar perkemahan, janganlah ia masuk ke dalam perkemahan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 11, 'Kemudian menjelang senja haruslah ia mandi dengan air, dan pada waktu matahari terbenam, ia boleh masuk kembali ke dalam perkemahan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 12, 'Di luar perkemahan itu haruslah ada bagimu suatu tempat ke mana engkau pergi untuk kada hajat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 13, 'Di antara perlengkapanmu haruslah ada padamu sekop kecil dan apabila engkau jongkok kada hajat, haruslah engkau menggali lobang dengan itu dan menimbuni kotoranmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 14, 'Sebab TUHAN, Allahmu, berjalan dari tengah-tengah perkemahanmu untuk melepaskan engkau dan menyerahkan musuhmu kepadamu; sebab itu haruslah perkemahanmu itu kudus, supaya jangan Ia melihat sesuatu yang tidak senonoh di antaramu, lalu berbalik dari padamu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 15, '"Janganlah kauserahkan kepada tuannya seorang budak yang melarikan diri dari tuannya kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 16, 'Bersama-sama engkau ia boleh tinggal, di tengah-tengahmu, di tempat yang dipilihnya di salah satu tempatmu, yang dirasanya baik; janganlah engkau menindas dia."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 17, '"Di antara anak-anak perempuan Israel janganlah ada pelacur bakti, dan di antara anak-anak lelaki Israel janganlah ada semburit bakti.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 18, 'Janganlah kaubawa upah sundal atau uang semburit ke dalam rumah TUHAN, Allahmu, untuk menepati salah satu nazar, sebab keduanya itu adalah kekejian bagi TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 19, '"Janganlah engkau membungakan kepada saudaramu, baik uang maupun bahan makanan atau apapun yang dapat dibungakan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 20, 'Dari orang asing boleh engkau memungut bunga, tetapi dari saudaramu janganlah engkau memungut bunga?supaya TUHAN, Allahmu, memberkati engkau dalam segala usahamu di negeri yang engkau masuki untuk mendudukinya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 21, '"Apabila engkau bernazar kepada TUHAN, Allahmu, janganlah engkau menunda-nunda memenuhinya, sebab tentulah TUHAN, Allahmu, akan menuntutnya dari padamu, sehingga hal itu menjadi dosa bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 22, 'Tetapi apabila engkau tidak bernazar, maka hal itu bukan menjadi dosa bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 23, 'Apa yang keluar dari bibirmu haruslah kaulakukan dengan setia, sebab dengan sukarela kaunazarkan kepada TUHAN, Allahmu, sesuatu yang kaukatakan dengan mulutmu sendiri."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 24, '"Apabila engkau melalui kebun anggur sesamamu, engkau boleh makan buah anggur sepuas-puas hatimu, tetapi tidak boleh kaumasukkan ke dalam bungkusanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 23, 25, 'Apabila engkau melalui ladang gandum sesamamu yang belum dituai, engkau boleh memetik bulir-bulirnya dengan tanganmu, tetapi sabit tidak boleh kauayunkan kepada gandum sesamamu itu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 1, '"Apabila seseorang mengambil seorang perempuan dan menjadi suaminya, dan jika kemudian ia tidak menyukai lagi perempuan itu, sebab didapatinya yang tidak senonoh padanya, lalu ia menulis surat cerai dan menyerahkannya ke tangan perempuan itu, sesudah itu menyuruh dia pergi dari rumahnya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 2, 'dan jika perempuan itu keluar dari rumahnya dan pergi dari sana, lalu menjadi isteri orang lain,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 3, 'dan jika laki-laki yang kemudian ini tidak cinta lagi kepadanya, lalu menulis surat cerai dan menyerahkannya ke tangan perempuan itu serta menyuruh dia pergi dari rumahnya, atau jika laki-laki yang kemudian mengambil dia menjadi isterinya itu mati,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 4, 'maka suaminya yang pertama, yang telah menyuruh dia pergi itu, tidak boleh mengambil dia kembali menjadi isterinya, setelah perempuan itu dicemari; sebab hal itu adalah kekejian di hadapan TUHAN. Janganlah engkau mendatangkan dosa atas negeri yang diberikan TUHAN, Allahmu, kepadamu menjadi milik pusakamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 5, 'Apabila baru saja seseorang mengambil isteri, janganlah ia keluar bersama-sama dengan tentara maju berperang atau dibebankan sesuatu pekerjaan; satu tahun lamanya ia harus dibebaskan untuk keperluan rumah tangganya dan menyukakan hati perempuan yang telah diambilnya menjadi isterinya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 6, '"Janganlah mengambil kilangan atau batu kilangan atas sebagai gadai, karena yang demikian itu mengambil nyawa orang sebagai gadai.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 7, 'Apabila seseorang kedapatan sedang menculik orang, salah seorang saudaranya, dari antara orang Israel, lalu memperlakukan dia sebagai budak dan menjual dia, maka haruslah penculik itu mati. Demikianlah harus kauhapuskan yang jahat itu dari tengah-tengahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 8, 'Hati-hatilah dalam hal penyakit kusta dan lakukanlah dengan tepat segala yang diajarkan imam-imam orang Lewi kepadamu; apa yang kuperintahkan kepada mereka haruslah kamu lakukan dengan setia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 9, 'Ingatlah apa yang dilakukan TUHAN, Allahmu, kepada Miryam pada waktu perjalananmu keluar dari Mesir.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 10, 'Apabila engkau meminjamkan sesuatu kepada sesamamu, janganlah engkau masuk ke rumahnya untuk mengambil gadai dari padanya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 11, 'Haruslah engkau tinggal berdiri di luar, dan orang yang kauberi pinjaman itu haruslah membawa gadai itu ke luar kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 12, 'Jika ia seorang miskin, janganlah engkau tidur dengan barang gadaiannya;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 13, 'kembalikanlah gadaian itu kepadanya pada waktu matahari terbenam, supaya ia dapat tidur dengan memakai kainnya sendiri dan memberkati engkau. Maka engkau akan menjadi benar di hadapan TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 14, 'Janganlah engkau memeras pekerja harian yang miskin dan menderita, baik ia saudaramu maupun seorang asing yang ada di negerimu, di dalam tempatmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 15, 'Pada hari itu juga haruslah engkau membayar upahnya sebelum matahari terbenam; ia mengharapkannya, karena ia orang miskin; supaya ia jangan berseru kepada TUHAN mengenai engkau dan hal itu menjadi dosa bagimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 16, 'Janganlah ayah dihukum mati karena anaknya, janganlah juga anak dihukum mati karena ayahnya; setiap orang harus dihukum mati karena dosanya sendiri.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 17, 'Janganlah engkau memperkosa hak orang asing dan anak yatim; juga janganlah engkau mengambil pakaian seorang janda menjadi gadai.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 18, 'Haruslah kauingat, bahwa engkaupun dahulu budak di Mesir dan engkau ditebus TUHAN, Allahmu, dari sana; itulah sebabnya aku memerintahkan engkau melakukan hal ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 19, 'Apabila engkau menuai di ladangmu, lalu terlupa seberkas di ladang, maka janganlah engkau kembali untuk mengambilnya; itulah bagian orang asing, anak yatim dan janda?supaya TUHAN, Allahmu, memberkati engkau dalam segala pekerjaanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 20, 'Apabila engkau memetik hasil pohon zaitunmu dengan memukul-mukulnya, janganlah engkau memeriksa dahan-dahannya sekali lagi; itulah bagian orang asing, anak yatim dan janda.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 21, 'Apabila engkau mengumpulkan hasil kebun anggurmu, janganlah engkau mengadakan pemetikan sekali lagi; itulah bagian orang asing, anak yatim dan janda.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 24, 22, 'Haruslah kauingat, bahwa engkaupun dahulu budak di tanah Mesir; itulah sebabnya aku memerintahkan engkau melakukan hal ini."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 1, '"Apabila ada perselisihan di antara beberapa orang, lalu mereka pergi ke pengadilan, dan mereka diadili dengan dinyatakannya siapa yang benar dan siapa yang salah,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 2, 'maka jika orang yang bersalah itu layak dipukul, haruslah hakim menyuruh dia meniarap dan menyuruh orang memukuli dia di depannya dengan sejumlah dera setimpal dengan kesalahannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 3, 'Empat puluh kali harus orang itu dipukuli, jangan lebih; supaya jangan saudaramu menjadi rendah di matamu, apabila ia dipukul lebih banyak lagi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 4, 'Janganlah engkau memberangus mulut lembu yang sedang mengirik."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 5, '"Apabila orang-orang yang bersaudara tinggal bersama-sama dan seorang dari pada mereka mati dengan tidak meninggalkan anak laki-laki, maka janganlah isteri orang yang mati itu kawin dengan orang di luar lingkungan keluarganya; saudara suaminya haruslah menghampiri dia dan mengambil dia menjadi isterinya dan dengan demikian melakukan kewajiban perkawinan ipar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 6, 'Maka anak sulung yang nanti dilahirkan perempuan itu haruslah dianggap sebagai anak saudara yang sudah mati itu, supaya nama itu jangan terhapus dari antara orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 7, 'Tetapi jika orang itu tidak suka mengambil isteri saudaranya, maka haruslah isteri saudaranya itu pergi ke pintu gerbang menghadap para tua-tua serta berkata: Iparku menolak menegakkan nama saudaranya di antara orang Israel, ia tidak mau melakukan kewajiban perkawinan ipar dengan aku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 8, 'Kemudian para tua-tua kotanya haruslah memanggil orang itu dan berbicara dengan dia. Jika ia tetap berpendirian dengan mengatakan: Aku tidak suka mengambil dia sebagai isteri?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 9, 'maka haruslah isteri saudaranya itu datang kepadanya di hadapan para tua-tua, menanggalkan kasut orang itu dari kakinya, meludahi mukanya sambil menyatakan: Beginilah harus dilakukan kepada orang yang tidak mau membangun keturunan saudaranya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 10, 'Dan di antara orang Israel namanya haruslah disebut: Kaum yang kasutnya ditanggalkan orang."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 11, '"Apabila dua orang berkelahi dan isteri yang seorang datang mendekat untuk menolong suaminya dari tangan orang yang memukulnya, dan perempuan itu mengulurkan tangannya dan menangkap kemaluan orang itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 12, 'maka haruslah kaupotong tangan perempuan itu; janganlah engkau merasa sayang kepadanya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 13, '"Janganlah ada di dalam pundi-pundimu dua macam batu timbangan, yang besar dan yang kecil.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 14, 'Janganlah ada di dalam rumahmu dua macam efa, yang besar dan yang kecil.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 15, 'Haruslah ada padamu batu timbangan yang utuh dan tepat; haruslah ada padamu efa yang utuh dan tepat?supaya lanjut umurmu di tanah yang diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 16, 'Sebab setiap orang yang melakukan hal yang demikian, setiap orang yang berbuat curang, adalah kekejian bagi TUHAN, Allahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 17, '"Ingatlah apa yang dilakukan orang Amalek kepadamu pada waktu perjalananmu keluar dari Mesir;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 18, 'bahwa engkau didatangi mereka di jalan dan semua orang lemah pada barisan belakangmu dihantam mereka, sedang engkau lelah dan lesu. Mereka tidak takut akan Allah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 25, 19, 'Maka apabila TUHAN, Allahmu, sudah mengaruniakan keamanan kepadamu dari pada segala musuhmu di sekeliling, di negeri yang diberikan TUHAN, Allahmu, kepadamu untuk dimiliki sebagai milik pusaka, maka haruslah engkau menghapuskan ingatan kepada Amalek dari kolong langit. Janganlah lupa!"', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 1, '"Apabila engkau telah masuk ke negeri yang diberikan TUHAN, Allahmu, kepadamu menjadi milik pusakamu, dan engkau telah mendudukinya dan diam di sana,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 2, 'maka haruslah engkau membawa hasil pertama dari bumi yang telah kaukumpulkan dari tanahmu yang diberikan kepadamu oleh TUHAN, Allahmu, dan haruslah engkau menaruhnya dalam bakul, kemudian pergi ke tempat yang akan dipilih TUHAN, Allahmu, untuk membuat nama-Nya diam di sana.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 3, 'Dan sesampainya kepada imam yang ada pada waktu itu, haruslah engkau berkata kepadanya: Aku memberitahukan pada hari ini kepada TUHAN, Allahmu, bahwa aku telah masuk ke negeri yang dijanjikan TUHAN dengan sumpah kepada nenek moyang kita untuk memberikannya kepada kita.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 4, 'Maka imam harus menerima bakul itu dari tanganmu dan meletakkannya di depan mezbah TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 5, 'Kemudian engkau harus menyatakan di hadapan TUHAN, Allahmu, demikian: Bapaku dahulu seorang Aram, seorang pengembara. Ia pergi ke Mesir dengan sedikit orang saja dan tinggal di sana sebagai orang asing, tetapi di sana ia menjadi suatu bangsa yang besar, kuat dan banyak jumlahnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 6, 'Ketika orang Mesir menganiaya dan menindas kami dan menyuruh kami melakukan pekerjaan yang berat,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 7, 'maka kami berseru kepada TUHAN, Allah nenek moyang kami, lalu TUHAN mendengar suara kami dan melihat kesengsaraan dan kesukaran kami dan penindasan terhadap kami.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 8, 'Lalu TUHAN membawa kami keluar dari Mesir dengan tangan yang kuat dan lengan yang teracung, dengan kedahsyatan yang besar dan dengan tanda-tanda serta mujizat-mujizat.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 9, 'Ia membawa kami ke tempat ini, dan memberikan kepada kami negeri ini, suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 10, 'Oleh sebab itu, di sini aku membawa hasil pertama dari bumi yang telah Kauberikan kepadaku, ya TUHAN. Kemudian engkau harus meletakkannya di hadapan TUHAN, Allahmu; engkau harus sujud di hadapan TUHAN, Allahmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 11, 'dan haruslah engkau, orang Lewi dan orang asing yang ada di tengah-tengahmu bersukaria karena segala yang baik yang diberikan TUHAN, Allahmu, kepadamu dan kepada seisi rumahmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 12, '"Apabila dalam tahun yang ketiga, tahun persembahan persepuluhan, engkau sudah selesai mengambil segala persembahan persepuluhan dari hasil tanahmu, maka haruslah engkau memberikannya kepada orang Lewi, orang asing, anak yatim dan kepada janda, supaya mereka dapat makan di dalam tempatmu dan menjadi kenyang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 13, 'Dan haruslah engkau berkata di hadapan TUHAN, Allahmu: Telah kupindahkan persembahan kudus itu dari rumahku, juga telah kuberikan kepada orang Lewi, dan kepada orang asing, anak yatim dan kepada janda, tepat seperti perintah yang telah Kauberikan kepadaku. Tidak kulangkahi atau kulupakan sesuatu dari perintah-Mu itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 14, 'Pada waktu aku berkabung sesuatu tidak kumakan dari persembahan kudus itu, pada waktu aku najis sesuatu tidak kujauhkan dari padanya, juga sesuatu tidak kupersembahkan dari padanya kepada orang mati, tetapi aku mendengarkan suara TUHAN, Allahku, aku berbuat sesuai dengan segala yang Kauperintahkan kepadaku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 15, 'Jenguklah dari tempat kediaman-Mu yang kudus, dari dalam sorga, dan berkatilah umat-Mu Israel, dan tanah yang telah Kauberikan kepada kami, seperti yang telah Kaujanjikan dengan sumpah kepada nenek moyang kami?suatu negeri yang berlimpah-limpah susu dan madunya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 16, '"Pada hari ini TUHAN, Allahmu, memerintahkan engkau melakukan ketetapan dan peraturan ini; lakukanlah semuanya itu dengan setia, dengan segenap hatimu dan segenap jiwamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 17, 'Engkau telah menerima janji dari pada TUHAN pada hari ini, bahwa Ia akan menjadi Allahmu, dan engkaupun akan hidup menurut jalan yang ditunjukkan-Nya dan berpegang pada ketetapan, perintah serta peraturan-Nya, dan mendengarkan suara-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 18, 'Dan TUHAN telah menerima janji dari padamu pada hari ini, bahwa engkau akan menjadi umat kesayangan-Nya, seperti yang dijanjikan-Nya kepadamu, dan bahwa engkau akan berpegang pada segala perintah-Nya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 26, 19, 'dan Iapun akan mengangkat engkau di atas segala bangsa yang telah dijadikan-Nya, untuk menjadi terpuji, ternama dan terhormat. Maka engkau akan menjadi umat yang kudus bagi TUHAN, Allahmu, seperti yang dijanjikan-Nya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 1, 'Lagi Musa dan para tua-tua Israel memerintahkan kepada bangsa itu: "Berpeganglah pada segenap perintah yang kusampaikan kepadamu pada hari ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 2, 'Dan pada hari kamu menyeberangi sungai Yordan ke negeri yang diberikan kepadamu oleh TUHAN, Allahmu, maka haruslah engkau menegakkan batu-batu besar, dan mengapurnya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 3, 'lalu pada batu itu haruslah kautuliskan segala perkataan hukum Taurat ini, sesudah engkau menyeberang, supaya engkau masuk ke negeri yang diberikan kepadamu oleh TUHAN, Allahmu, suatu negeri yang berlimpah-limpah susu dan madunya, seperti yang dijanjikan kepadamu oleh TUHAN, Allah nenek moyangmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 4, 'Dan sesudah kamu menyeberangi sungai Yordan, maka haruslah batu-batu itu, yang telah kuperintahkan kepadamu pada hari ini, kamu tegakkan di gunung Ebal dan kaukapuri.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 5, 'Juga haruslah kaudirikan di sana mezbah bagi TUHAN, Allahmu, suatu mezbah dari batu yang tidak boleh kauolah dengan perkakas besi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 6, 'Dari batu yang tidak dipahat haruslah kaudirikan mezbah TUHAN, Allahmu, itu dan di atasnya haruslah kaupersembahkan korban bakaran kepada TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 7, 'Juga haruslah engkau mempersembahkan korban keselamatan, memakannya di sana dan bersukaria di hadapan TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 8, 'Selanjutnya haruslah engkau menuliskan pada batu-batu itu segala perkataan hukum Taurat ini dengan jelas dan terang."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 9, 'Juga berbicaralah Musa dan imam-imam orang Lewi kepada seluruh orang Israel: "Diamlah dan dengarlah, hai orang Israel. Pada hari ini engkau telah menjadi umat TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 10, 'Sebab itu engkau harus mendengarkan suara TUHAN, Allahmu, dan melakukan perintah dan ketetapan-Nya, yang kusampaikan kepadamu pada hari ini."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 11, 'Pada hari itu Musa memberi perintah kepada bangsa itu:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 12, '"Sesudah kamu menyeberangi sungai Yordan, maka mereka inilah yang harus berdiri di gunung Gerizim untuk memberkati bangsa itu, yakni suku Simeon, Lewi, Yehuda, Isakhar, Yusuf dan Benyamin.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 13, 'Dan mereka inilah yang harus berdiri di gunung Ebal untuk mengutuki, yakni suku Ruben, Gad, Asyer, Zebulon, Dan serta Naftali.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 14, 'Maka haruslah orang-orang Lewi mulai bicara dan mengatakan kepada seluruh orang Israel dengan suara nyaring:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 15, 'Terkutuklah orang yang membuat patung pahatan atau patung tuangan, suatu kekejian bagi TUHAN, buatan tangan seorang tukang, dan yang mendirikannya dengan tersembunyi. Dan seluruh bangsa itu haruslah menjawab: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 16, 'Terkutuklah orang yang memandang rendah ibu dan bapanya. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 17, 'Terkutuklah orang yang menggeser batas tanah sesamanya manusia. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 18, 'Terkutuklah orang yang membawa seorang buta ke jalan yang sesat. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 19, 'Terkutuklah orang yang memperkosa hak orang asing, anak yatim dan janda. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 20, 'Terkutuklah orang yang tidur dengan isteri ayahnya, sebab ia telah menyingkapkan punca kain ayahnya. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 21, 'Terkutuklah orang yang tidur dengan binatang apapun. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 22, 'Terkutuklah orang yang tidur dengan saudaranya perempuan, anak ayah atau anak ibunya. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 23, 'Terkutuklah orang yang tidur dengan mertuanya perempuan. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 24, 'Terkutuklah orang yang membunuh sesamanya manusia dengan tersembunyi. Dan seluruh bangsa itu haruslah berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 25, 'Terkutuklah orang yang menerima suap untuk membunuh seseorang yang tidak bersalah. Dan seluruh bangsa itu harus berkata: Amin!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 27, 26, 'Terkutuklah orang yang tidak menepati perkataan hukum Taurat ini dengan perbuatan. Dan seluruh bangsa itu haruslah berkata: Amin!"', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 1, '"Jika engkau baik-baik mendengarkan suara TUHAN, Allahmu, dan melakukan dengan setia segala perintah-Nya yang kusampaikan kepadamu pada hari ini, maka TUHAN, Allahmu, akan mengangkat engkau di atas segala bangsa di bumi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 2, 'Segala berkat ini akan datang kepadamu dan menjadi bagianmu, jika engkau mendengarkan suara TUHAN, Allahmu:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 3, 'Diberkatilah engkau di kota dan diberkatilah engkau di ladang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 4, 'Diberkatilah buah kandunganmu, hasil bumimu dan hasil ternakmu, yakni anak lembu sapimu dan kandungan kambing dombamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 5, 'Diberkatilah bakulmu dan tempat adonanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 6, 'Diberkatilah engkau pada waktu masuk dan diberkatilah engkau pada waktu keluar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 7, 'TUHAN akan membiarkan musuhmu yang maju berperang melawan engkau, terpukul kalah olehmu. Bersatu jalan mereka akan menyerangi engkau, tetapi bertujuh jalan mereka akan lari dari depanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 8, 'TUHAN akan memerintahkan berkat ke atasmu di dalam lumbungmu dan di dalam segala usahamu; Ia akan memberkati engkau di negeri yang diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 9, 'TUHAN akan menetapkan engkau sebagai umat-Nya yang kudus, seperti yang dijanjikan-Nya dengan sumpah kepadamu, jika engkau berpegang pada perintah TUHAN, Allahmu, dan hidup menurut jalan yang ditunjukkan-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 10, 'Maka segala bangsa di bumi akan melihat, bahwa nama TUHAN telah disebut atasmu, dan mereka akan takut kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 11, 'Juga TUHAN akan melimpahi engkau dengan kebaikan dalam buah kandunganmu, dalam hasil ternakmu dan dalam hasil bumimu?di tanah yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu untuk memberikannya kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 12, 'TUHAN akan membuka bagimu perbendaharaan-Nya yang melimpah, yakni langit, untuk memberi hujan bagi tanahmu pada masanya dan memberkati segala pekerjaanmu, sehingga engkau memberi pinjaman kepada banyak bangsa, tetapi engkau sendiri tidak meminta pinjaman.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 13, 'TUHAN akan mengangkat engkau menjadi kepala dan bukan menjadi ekor, engkau akan tetap naik dan bukan turun, apabila engkau mendengarkan perintah TUHAN, Allahmu, yang kusampaikan pada hari ini kaulakukan dengan setia,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 14, 'dan apabila engkau tidak menyimpang ke kanan atau ke kiri dari segala perintah yang kuberikan kepadamu pada hari ini, dengan mengikuti allah lain dan beribadah kepadanya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 15, '"Tetapi jika engkau tidak mendengarkan suara TUHAN, Allahmu, dan tidak melakukan dengan setia segala perintah dan ketetapan-Nya, yang kusampaikan kepadamu pada hari ini, maka segala kutuk ini akan datang kepadamu dan mencapai engkau:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 16, 'Terkutuklah engkau di kota dan terkutuklah engkau di ladang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 17, 'Terkutuklah bakulmu dan tempat adonanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 18, 'Terkutuklah buah kandunganmu, hasil bumimu, anak lembu sapimu dan kandungan kambing dombamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 19, 'Terkutuklah engkau pada waktu masuk dan terkutuklah engkau pada waktu keluar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 20, 'TUHAN akan mendatangkan kutuk, huru-hara dan penghajaran ke antaramu dalam segala usaha yang kaukerjakan, sampai engkau punah dan binasa dengan segera karena jahat perbuatanmu, sebab engkau telah meninggalkan Aku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 21, 'TUHAN akan melekatkan penyakit sampar kepadamu, sampai dihabiskannya engkau dari tanah, ke mana engkau pergi untuk mendudukinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 22, 'TUHAN akan menghajar engkau dengan batuk kering, demam, demam kepialu, sakit radang, kekeringan, hama dan penyakit gandum; semuanya itu akan memburu engkau sampai engkau binasa.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 23, 'Juga langit yang di atas kepalamu akan menjadi tembaga dan tanah yang di bawahpun menjadi besi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 24, 'TUHAN akan menurunkan hujan abu dan debu ke atas negerimu; dari langit akan turun semuanya itu ke atasmu, sampai engkau punah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 25, 'TUHAN akan membiarkan engkau terpukul kalah oleh musuhmu. Bersatu jalan engkau akan keluar menyerang mereka, tetapi bertujuh jalan engkau akan lari dari depan mereka, sehingga engkau menjadi kengerian bagi segala kerajaan di bumi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 26, 'Mayatmu akan menjadi makanan segala burung di udara serta binatang-binatang di bumi, dengan tidak ada yang mengganggunya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 27, 'TUHAN akan menghajar engkau dengan barah Mesir, dengan borok, dengan kedal dan kudis, yang dari padanya engkau tidak dapat sembuh.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 28, 'TUHAN akan menghajar engkau dengan kegilaan, kebutaan dan kehilangan akal,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 29, 'sehingga engkau meraba-raba pada waktu tengah hari, seperti seorang buta meraba-raba di dalam gelap; perjalananmu tidak akan beruntung, tetapi engkau selalu diperas dan dirampasi, dengan tidak ada seorang yang datang menolong.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 30, 'Engkau akan bertunangan dengan seorang perempuan, tetapi orang lain akan menidurinya. Engkau akan mendirikan rumah, tetapi tidak akan mendiaminya. Engkau akan membuat kebun anggur, tetapi tidak akan mengecap hasilnya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 31, 'Lembumu akan disembelih orang di depan matamu, tetapi engkau tidak akan memakan dagingnya. Keledaimu akan dirampas dari depanmu, dan tidak akan dikembalikan kepadamu. Kambing dombamu akan diberikan kepada musuhmu dengan tidak ada orang yang datang menolong engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 32, 'Anak-anakmu lelaki dan anak-anakmu perempuan akan diserahkan kepada bangsa lain, sedang engkau melihatnya dengan matamu sendiri, dan sehari-harian engkau rindu kepada mereka, dengan tidak dapat berbuat apa-apa.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 33, 'Suatu bangsa yang tidak kaukenal akan memakan hasil bumimu dan segala hasil jerih payahmu; engkau akan selalu ditindas dan diinjak.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 34, 'Engkau akan menjadi gila karena apa yang dilihat matamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 35, 'TUHAN akan menghajar engkau dengan barah jahat, yang dari padanya engkau tidak dapat sembuh, pada lutut dan pahamu, bahkan dari telapak kakimu sampai kepada batu kepalamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 36, 'TUHAN akan membawa engkau dengan raja yang kauangkat atasmu itu kepada suatu bangsa yang tidak dikenal olehmu ataupun oleh nenek moyangmu; di sanalah engkau akan beribadah kepada allah lain, kepada kayu dan batu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 37, 'Engkau akan menjadi kedahsyatan, kiasan dan sindiran di antara segala bangsa, ke mana TUHAN akan menyingkirkan engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 38, 'Banyak benih yang akan kaubawa ke ladang, tetapi sedikit hasil yang akan kaukumpulkan, sebab belalang akan menghabiskannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 39, 'Kebun-kebun anggur akan kaubuat dan kauusahakan, tetapi engkau tidak akan meminum atau menyimpan anggur, sebab ulat akan memakannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 40, 'Pohon-pohon zaitun akan kaupunyai di seluruh daerahmu, tetapi engkau tidak akan berurap dengan minyaknya; sebab buah zaitunmu akan gugur.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 41, 'Engkau akan mendapat anak-anak lelaki dan anak-anak perempuan, tetapi mereka bukan bagi dirimu, sebab mereka akan menjadi tawanan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 42, 'Segala pohon-pohonmu dan hasil bumimu akan diduduki oleh kawanan belalang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 43, 'Orang asing yang ada di tengah-tengahmu akan menjadi makin tinggi mengatasi engkau, tetapi engkau menjadi makin rendah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 44, 'Ia akan memberi pinjaman kepadamu, tetapi engkau tidak akan memberi pinjaman kepadanya; ia akan menjadi kepala, tetapi engkau akan menjadi ekor.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 45, 'Segala kutuk itu akan datang ke atasmu, memburu engkau dan mencapai engkau, sampai engkau punah, karena engkau tidak mendengarkan suara TUHAN, Allahmu dan tidak berpegang pada perintah dan ketetapan yang diperintahkan-Nya kepadamu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 46, 'semuanya itu akan menjadi tanda dan mujizat di antaramu dan di antara keturunanmu untuk selamanya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 47, '"Karena engkau tidak mau menjadi hamba kepada TUHAN, Allahmu, dengan sukacita dan gembira hati walaupun kelimpahan akan segala-galanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 48, 'maka dengan menanggung lapar dan haus, dengan telanjang dan kekurangan akan segala-galanya engkau akan menjadi hamba kepada musuh yang akan disuruh TUHAN melawan engkau. Ia akan membebankan kuk besi ke atas tengkukmu, sampai engkau dipunahkan-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 49, 'TUHAN akan mendatangkan kepadamu suatu bangsa dari jauh, dari ujung bumi, seperti rajawali yang datang menyambar; suatu bangsa yang bahasanya engkau tidak mengerti,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 50, 'suatu bangsa yang garang mukanya, yang tidak menghiraukan orang tua-tua dan tidak merasa kasihan kepada anak-anak;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 51, 'yang akan memakan habis hasil ternakmu dan hasil bumimu, sampai engkau punah; yang tidak akan meninggalkan bagimu gandum, air anggur atau minyak, ataupun anak lembu sapimu atau anak kambing dombamu, sampai engkau dibinasakannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 52, 'Engkau akan ditekannya di segala tempatmu, sampai runtuh tembok-tembokmu yang tinggi dan berkubu, yang kaupercayai itu di seluruh negerimu, bahkan engkau akan ditekan di dalam segala tempatmu, di seluruh negeri yang telah diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 53, 'Dan engkau akan memakan buah kandunganmu, yakni daging anak-anakmu lelaki dan anak-anakmu perempuan yang diberikan kepadamu oleh TUHAN, Allahmu, ?dalam keadaan susah dan sulit yang ditimbulkan musuhmu kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 54, 'Dan orang laki-laki yang paling lemah dan paling manja di antaramu akan kesal terhadap saudaranya atau terhadap isterinya sendiri atau terhadap anak-anaknya yang masih tinggal padanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 55, 'sehingga kepada salah seorang dari mereka itu ia tidak mau memberikan sedikitpun dari daging anak-anaknya yang dimakannya, karena tidak ada lagi sesuatu yang ditinggalkan baginya, dalam keadaan susah dan sulit yang ditimbulkan musuhmu kepadamu di segala tempatmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 56, 'Perempuan yang lemah dan manja di antaramu, yang tidak pernah mencoba menjejakkan telapak kakinya ke tanah karena sifatnya yang manja dan lemah itu, akan kesal terhadap suaminya sendiri atau terhadap anaknya laki-laki atau anaknya perempuan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 57, 'karena uri yang keluar dari kandungannya ataupun karena anak-anak yang dilahirkannya; sebab karena kekurangan segala-galanya ia akan memakannya dengan sembunyi-sembunyi, dalam keadaan susah dan sulit yang ditimbulkan musuhmu kepadamu di dalam tempatmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 58, 'Jika engkau tidak melakukan dengan setia segala perkataan hukum Taurat yang tertulis dalam kitab ini, dan engkau tidak takut akan Nama yang mulia dan dahsyat ini, yakni akan TUHAN, Allahmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 59, 'maka TUHAN akan menimpakan pukulan-pukulan yang ajaib kepadamu, dan kepada keturunanmu, yakni pukulan-pukulan yang keras lagi lama dan penyakit-penyakit yang jahat lagi lama.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 28, 60, 'Ia akan mendatangkan pula segala wabah Mesir yang kautakuti itu kepadamu, sehingga semuanya itu melekat padamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 1, 'Inilah perkataan perjanjian yang diikat Musa dengan orang Israel di tanah Moab sesuai dengan perintah TUHAN, selain perjanjian yang telah diikat-Nya dengan mereka di gunung Horeb.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 2, 'Musa memanggil seluruh orang Israel berkumpul, lalu berkata kepada mereka: "Sudah kamu lihat segala yang dilakukan TUHAN di tanah Mesir di depan matamu terhadap Firaun dan terhadap semua pegawainya dan terhadap seluruh negerinya:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 3, 'cobaan-cobaan yang besar yang telah dilihat oleh matamu sendiri, tanda-tanda dan mujizat-mujizat yang besar itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 4, 'Tetapi sampai sekarang ini TUHAN tidak memberi kamu akal budi untuk mengerti atau mata untuk melihat atau telinga untuk mendengar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 5, 'Empat puluh tahun lamanya Aku memimpin kamu berjalan melalui padang gurun; pakaianmu tidak menjadi rusak di tubuhmu, dan kasutmu tidak menjadi rusak di kakimu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 6, 'Roti tidak kamu makan, anggur atau minuman yang memabukkan tidak kamu minum?supaya kamu tahu bahwa Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 7, 'Ketika kamu sudah sampai ke tempat ini, maka keluarlah Sihon, raja Hesybon, dan Og, raja Basan, mendatangi kita untuk berperang, dan kita memukul mereka kalah,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 8, 'merebut negeri mereka dan memberikannya kepada orang Ruben, kepada orang Gad, dan kepada suku Manasye yang setengah itu menjadi milik pusaka mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 9, 'Sebab itu lakukanlah perkataan perjanjian ini dengan setia, supaya kamu beruntung dalam segala yang kamu lakukan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 10, 'Kamu sekalian pada hari ini berdiri di hadapan TUHAN, Allahmu: para kepala sukumu, para tua-tuamu dan para pengatur pasukanmu, semua laki-laki Israel,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 11, 'anak-anakmu, perempuan-perempuanmu dan orang-orang asing dalam perkemahanmu, bahkan tukang-tukang belah kayu dan tukang-tukang timba air di antaramu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 12, 'untuk masuk ke dalam perjanjian TUHAN, Allahmu, yakni sumpah janji-Nya, yang diikat TUHAN, Allahmu, dengan engkau pada hari ini,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 13, 'supaya Ia mengangkat engkau sebagai umat-Nya pada hari ini dan supaya Ia menjadi Allahmu, seperti yang difirmankan-Nya kepadamu dan seperti yang dijanjikan-Nya dengan sumpah kepada nenek moyangmu, yakni kepada Abraham, Ishak dan Yakub.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 14, 'Bukan hanya dengan kamu saja aku mengikat perjanjian dan sumpah janji ini,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 15, 'tetapi dengan setiap orang yang ada di sini pada hari ini bersama-sama dengan kita, yang berdiri di hadapan TUHAN, Allah kita, dan juga dengan setiap orang yang tidak ada di sini pada hari ini bersama-sama dengan kita.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 16, 'Sebab kamu ini tahu, bagaimana kita diam di tanah Mesir dan bagaimana kita berjalan dari tengah-tengah segala bangsa yang negerinya kamu lalui,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 17, 'dan kamu sudah melihat dewa kejijikan dan berhala mereka, yakni kayu dan batu, emas dan perak itu, yang ada terdapat pada mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 18, 'Sebab itu janganlah di antaramu ada laki-laki atau perempuan, kaum keluarga atau suku yang hatinya pada hari ini berpaling meninggalkan TUHAN, Allah kita, untuk pergi berbakti kepada allah bangsa-bangsa itu; janganlah di antaramu ada akar yang menghasilkan racun atau ipuh.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 19, 'Tetapi apabila seseorang pada waktu mendengar perkataan sumpah serapah ini menyangka dirinya tetap diberkati, dengan berkata: Aku akan selamat, walaupun aku berlaku degil?dengan demikian dilenyapkannya baik tanah yang kegenangan maupun yang kekeringan?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 20, 'maka TUHAN tidak akan mau mengampuni orang itu, tetapi murka dan cemburu TUHAN akan menyala atasnya pada waktu itu; segenap sumpah serapah yang tertulis dalam kitab ini akan menghinggapi dia, dan TUHAN akan menghapuskan namanya dari kolong langit.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 21, 'TUHAN akan memisahkan orang itu dari segala suku Israel supaya dia mendapat celaka, sesuai dengan segala sumpah serapah perjanjian yang tertulis dalam kitab hukum Taurat ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 22, 'Maka keturunan yang akan datang, yakni anak-anakmu yang bangkit sesudah kamu, dan orang asing yang datang dari negeri jauh akan berkata?apabila mereka melihat hajaran dan penyakit yang dijatuhkan TUHAN ke negeri itu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 23, 'seluruh tanahnya yang telah hangus oleh belerang dan garam, yang tidak ditaburi, tidak menumbuhkan apa-apa dan tidak ada tumbuh-tumbuhan apapun yang timbul dari padanya, seperti pada waktu ditunggangbalikkan-Nya Sodom, Gomora, Adma dan Zeboim, yakni yang ditunggangbalikkan TUHAN dalam murka dan kepanasan amarah-Nya?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 24, 'bahkan segala bangsa akan berkata: Apakah sebabnya TUHAN berbuat demikian kepada negeri ini? Apakah artinya murka yang hebat bernyala-nyala ini?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 25, 'Maka orang akan menjawab: Sebab mereka itu telah melalaikan perjanjian TUHAN, Allah nenek moyang mereka, yakni perjanjian yang diikat-Nya dengan mereka ketika mereka dibawa-Nya keluar dari tanah Mesir,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 26, 'dan sebab mereka itu sudah pergi berbakti kepada allah lain dan sujud menyembah kepadanya, yakni allah yang tidak dikenal mereka dan yang tidak diberikan TUHAN kepada mereka sebagai bagiannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 27, 'Itulah sebabnya murka TUHAN bangkit terhadap negeri ini, sehingga didatangkan ke atasnya segala kutuk yang tertulis dalam kitab ini:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 28, 'TUHAN telah menyentakkan mereka dari tanah mereka dalam murka dan kepanasan amarah dan gusar-Nya yang hebat, lalu melemparkan mereka ke negeri lain, seperti yang terjadi sekarang ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 29, 29, 'Hal-hal yang tersembunyi ialah bagi TUHAN, Allah kita, tetapi hal-hal yang dinyatakan ialah bagi kita dan bagi anak-anak kita sampai selama-lamanya, supaya kita melakukan segala perkataan hukum Taurat ini."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 1, '"Maka apabila segala hal ini berlaku atasmu, yakni berkat dan kutuk yang telah kuperhadapkan kepadamu itu, dan engkau menjadi sadar dalam hatimu di tengah-tengah segala bangsa, ke mana TUHAN, Allahmu, menghalau engkau,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 2, 'dan apabila engkau berbalik kepada TUHAN, Allahmu, dan mendengarkan suara-Nya sesuai dengan segala yang kuperintahkan kepadamu pada hari ini, baik engkau maupun anak-anakmu, dengan segenap hatimu dan dengan segenap jiwamu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 3, 'maka TUHAN, Allahmu, akan memulihkan keadaanmu dan akan menyayangi engkau. Ia akan mengumpulkan engkau kembali dari segala bangsa, ke mana TUHAN, Allahmu, telah menyerakkan engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 4, 'Sekalipun orang-orang yang terhalau dari padamu ada di ujung langit, dari sanapun TUHAN, Allahmu, akan mengumpulkan engkau kembali dan dari sanapun Ia akan mengambil engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 5, 'TUHAN, Allahmu, akan membawa engkau masuk ke negeri yang sudah dimiliki nenek moyangmu, dan engkaupun akan memilikinya pula. Ia akan berbuat baik kepadamu dan membuat engkau banyak melebihi nenek moyangmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 6, 'Dan TUHAN, Allahmu, akan menyunat hatimu dan hati keturunanmu, sehingga engkau mengasihi TUHAN, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu, supaya engkau hidup.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 7, 'TUHAN, Allahmu, akan menjatuhkan segala sumpah serapah itu kepada musuhmu dan pembencimu, yang telah mengejar engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 8, 'Engkau akan mendengarkan kembali suara TUHAN dan melakukan segala perintah-Nya yang kusampaikan kepadamu pada hari ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 9, 'TUHAN, Allahmu, akan melimpahi engkau dengan kebaikan dalam segala pekerjaanmu, dalam buah kandunganmu, dalam hasil ternakmu dan dalam hasil bumimu, sebab TUHAN, Allahmu, akan bergirang kembali karena engkau dalam keberuntunganmu, seperti Ia bergirang karena nenek moyangmu dahulu?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 10, 'apabila engkau mendengarkan suara TUHAN, Allahmu, dengan berpegang pada perintah dan ketetapan-Nya, yang tertulis dalam kitab Taurat ini dan apabila engkau berbalik kepada TUHAN, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 11, '"Sebab perintah ini, yang kusampaikan kepadamu pada hari ini, tidaklah terlalu sukar bagimu dan tidak pula terlalu jauh.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 12, 'Tidak di langit tempatnya, sehingga engkau berkata: Siapakah yang akan naik ke langit untuk mengambilnya bagi kita dan memperdengarkannya kepada kita, supaya kita melakukannya?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 13, 'Juga tidak di seberang laut tempatnya, sehingga engkau berkata: Siapakah yang akan menyeberang ke seberang laut untuk mengambilnya bagi kita dan memperdengarkannya kepada kita, supaya kita melakukannya?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 14, 'Tetapi firman ini sangat dekat kepadamu, yakni di dalam mulutmu dan di dalam hatimu, untuk dilakukan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 15, 'Ingatlah, aku menghadapkan kepadamu pada hari ini kehidupan dan keberuntungan, kematian dan kecelakaan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 16, 'karena pada hari ini aku memerintahkan kepadamu untuk mengasihi TUHAN, Allahmu, dengan hidup menurut jalan yang ditunjukkan-Nya dan berpegang pada perintah, ketetapan dan peraturan-Nya, supaya engkau hidup dan bertambah banyak dan diberkati oleh TUHAN, Allahmu, di negeri ke mana engkau masuk untuk mendudukinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 17, 'Tetapi jika hatimu berpaling dan engkau tidak mau mendengar, bahkan engkau mau disesatkan untuk sujud menyembah kepada allah lain dan beribadah kepadanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 18, 'maka aku memberitahukan kepadamu pada hari ini, bahwa pastilah kamu akan binasa; tidak akan lanjut umurmu di tanah, ke mana engkau pergi, menyeberangi sungai Yordan untuk mendudukinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 19, 'Aku memanggil langit dan bumi menjadi saksi terhadap kamu pada hari ini: kepadamu kuperhadapkan kehidupan dan kematian, berkat dan kutuk. Pilihlah kehidupan, supaya engkau hidup, baik engkau maupun keturunanmu,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 30, 20, 'dengan mengasihi TUHAN, Allahmu, mendengarkan suara-Nya dan berpaut pada-Nya, sebab hal itu berarti hidupmu dan lanjut umurmu untuk tinggal di tanah yang dijanjikan TUHAN dengan sumpah kepada nenek moyangmu, yakni kepada Abraham, Ishak dan Yakub, untuk memberikannya kepada mereka."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 1, 'Kemudian pergilah Musa, lalu mengatakan segala perkataan ini kepada seluruh orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 2, 'Berkatalah ia kepada mereka: "Aku sekarang berumur seratus dua puluh tahun; aku tidak dapat giat lagi, dan TUHAN telah berfirman kepadaku: Sungai Yordan ini tidak akan kauseberangi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 3, 'TUHAN, Allahmu, Dialah yang akan menyeberang di depanmu; Dialah yang akan memunahkan bangsa-bangsa itu dari hadapanmu, sehingga engkau dapat memiliki negeri mereka; Yosua, dialah yang akan menyeberang di depanmu, seperti yang difirmankan TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 4, 'Dan TUHAN akan melakukan terhadap mereka seperti yang dilakukan-Nya terhadap Sihon dan Og, raja-raja orang Amori, yang telah dipunahkan-Nya itu, dan terhadap negeri mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 5, 'TUHAN akan menyerahkan mereka kepadamu dan haruslah kamu melakukan kepada mereka tepat seperti perintah yang kusampaikan kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 6, 'Kuatkan dan teguhkanlah hatimu, janganlah takut dan jangan gemetar karena mereka, sebab TUHAN, Allahmu, Dialah yang berjalan menyertai engkau; Ia tidak akan membiarkan engkau dan tidak akan meninggalkan engkau."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 7, 'Lalu Musa memanggil Yosua dan berkata kepadanya di depan seluruh orang Israel: "Kuatkan dan teguhkanlah hatimu, sebab engkau akan masuk bersama-sama dengan bangsa ini ke negeri yang dijanjikan TUHAN dengan sumpah kepada nenek moyang mereka untuk memberikannya kepada mereka, dan engkau akan memimpin mereka sampai mereka memilikinya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 8, 'Sebab TUHAN, Dia sendiri akan berjalan di depanmu, Dia sendiri akan menyertai engkau, Dia tidak akan membiarkan engkau dan tidak akan meninggalkan engkau; janganlah takut dan janganlah patah hati."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 9, 'Setelah hukum Taurat itu dituliskan Musa, maka diberikannyalah kepada imam-imam bani Lewi, yang mengangkut tabut perjanjian TUHAN, dan kepada segala tua-tua Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 10, 'Dan Musa memerintahkan kepada mereka, demikian: "Pada akhir tujuh tahun, pada waktu yang telah ditetapkan dalam tahun penghapusan hutang, yakni hari raya Pondok Daun,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 11, 'apabila seluruh orang Israel datang menghadap hadirat TUHAN, Allahmu, di tempat yang akan dipilih-Nya, maka haruslah engkau membacakan hukum Taurat ini di depan seluruh orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 12, 'Seluruh bangsa itu berkumpul, laki-laki, perempuan dan anak-anak, dan orang asing yang diam di dalam tempatmu, supaya mereka mendengarnya dan belajar takut akan TUHAN, Allahmu, dan mereka melakukan dengan setia segala perkataan hukum Taurat ini,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 13, 'dan supaya anak-anak mereka, yang tidak mengetahuinya, dapat mendengarnya dan belajar takut akan TUHAN, Allahmu, ?selama kamu hidup di tanah, ke mana kamu pergi, menyeberangi sungai Yordan untuk mendudukinya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 14, 'Kemudian berfirmanlah TUHAN kepada Musa: "Sesungguhnya sudah dekat waktunya bahwa engkau akan mati; maka panggillah Yosua dan berdirilah bersama-sama dengan dia dalam Kemah Pertemuan, supaya Aku memberi perintah kepadanya." Lalu pergilah Musa dan Yosua berdiri dalam Kemah Pertemuan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 15, 'Dan TUHAN menampakkan diri di kemah itu dalam tiang awan, dan tiang awan itu berdiri pada pintu kemah.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 16, 'TUHAN berfirman kepada Musa: "Ketahuilah, engkau akan mendapat perhentian bersama-sama dengan nenek moyangmu dan bangsa ini akan bangkit dan berzinah dengan mengikuti allah asing yang ada di negeri, ke mana mereka akan masuk; mereka akan meninggalkan Aku dan mengingkari perjanjian-Ku yang Kuikat dengan mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 17, 'Pada waktu itu murka-Ku akan bernyala-nyala terhadap mereka, Aku akan meninggalkan mereka dan menyembunyikan wajah-Ku terhadap mereka, sehingga mereka termakan habis dan banyak kali ditimpa malapetaka serta kesusahan. Maka pada waktu itu mereka akan berkata: Bukankah malapetaka itu menimpa kita, oleh sebab Allah kita tidak ada di tengah-tengah kita?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 18, 'Tetapi Aku akan menyembunyikan wajah-Ku sama sekali pada waktu itu, karena segala kejahatan yang telah dilakukan mereka: yakni mereka telah berpaling kepada allah lain.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 19, 'Oleh sebab itu tuliskanlah nyanyian ini dan ajarkanlah kepada orang Israel, letakkanlah di dalam mulut mereka, supaya nyanyian ini menjadi saksi bagi-Ku terhadap orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 20, 'Sebab Aku akan membawa mereka ke tanah yang Kujanjikan dengan sumpah kepada nenek moyang mereka, yakni tanah yang berlimpah-limpah susu dan madunya; mereka akan makan dan kenyang dan menjadi gemuk, tetapi mereka akan berpaling kepada allah lain dan beribadah kepadanya. Aku ini akan dinista mereka dan perjanjian-Ku akan diingkari mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 21, 'Maka apabila banyak kali mereka ditimpa malapetaka serta kesusahan, maka nyanyian ini akan menjadi kesaksian terhadap mereka, sebab nyanyian ini akan tetap melekat pada bibir keturunan mereka. Sebab Aku tahu niat yang dikandung mereka pada hari ini, sebelum Aku membawa mereka ke negeri yang Kujanjikan dengan sumpah kepada mereka."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 22, 'Maka Musa menuliskan nyanyian ini dan mengajarkannya kepada orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 23, 'Kepada Yosua bin Nun diberi-Nya perintah, firman-Nya: "Kuatkan dan teguhkanlah hatimu, sebab engkau akan membawa orang Israel ke negeri yang Kujanjikan dengan sumpah kepada mereka, dan Aku akan menyertai engkau."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 24, 'Ketika Musa selesai menuliskan perkataan hukum Taurat itu dalam sebuah kitab sampai perkataan yang penghabisan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 25, 'maka Musa memerintahkan kepada orang-orang Lewi pengangkut tabut perjanjian TUHAN, demikian:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 26, '"Ambillah kitab Taurat ini dan letakkanlah di samping tabut perjanjian TUHAN, Allahmu, supaya menjadi saksi di situ terhadap engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 27, 'Sebab aku mengenal kedegilan dan tegar tengkukmu. Sedangkan sekarang, selagi aku hidup bersama-sama dengan kamu, kamu sudah menunjukkan kedegilanmu terhadap TUHAN, terlebih lagi nanti sesudah aku mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 28, 'Suruhlah berkumpul kepadaku segala tua-tua sukumu dan para pengatur pasukanmu, maka aku akan mengatakan hal yang berikut kepada mereka dan memanggil langit dan bumi menjadi saksi terhadap mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 29, 'Sebab aku tahu, bahwa sesudah aku mati, kamu akan berlaku sangat busuk dan akan menyimpang dari jalan yang telah kuperintahkan kepadamu. Sebab itu di kemudian hari malapetaka akan menimpa kamu, apabila kamu berbuat yang jahat di mata TUHAN, dan menimbulkan sakit hati-Nya dengan perbuatan tanganmu."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 31, 30, 'Lalu Musa menyampaikan ke telinga seluruh jemaah Israel nyanyian ini sampai perkataan yang penghabisan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 1, '"Pasanglah telingamu, hai langit, aku mau berbicara, dan baiklah bumi mendengarkan ucapan mulutku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 2, 'Mudah-mudahan pengajaranku menitik laksana hujan, perkataanku menetes laksana embun, laksana hujan renai ke atas tunas muda, dan laksana dirus hujan ke atas tumbuh-tumbuhan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 3, 'Sebab nama TUHAN akan kuserukan: Berilah hormat kepada Allah kita,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 4, 'Gunung Batu, yang pekerjaan-Nya sempurna, karena segala jalan-Nya adil, Allah yang setia, dengan tiada kecurangan, adil dan benar Dia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 5, 'Berlaku busuk terhadap Dia, mereka yang bukan lagi anak-anak-Nya, yang merupakan noda, suatu angkatan yang bengkok dan belat-belit.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 6, 'Demikianlah engkau mengadakan pembalasan terhadap TUHAN, hai bangsa yang bebal dan tidak bijaksana? Bukankah Ia Bapamu yang mencipta engkau, yang menjadikan dan menegakkan engkau?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 7, 'Ingatlah kepada zaman dahulu kala, perhatikanlah tahun-tahun keturunan yang lalu, tanyakanlah kepada ayahmu, maka ia memberitahukannya kepadamu, kepada para tua-tuamu, maka mereka mengatakannya kepadamu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 8, 'Ketika Sang Mahatinggi membagi-bagikan milik pusaka kepada bangsa-bangsa, ketika Ia memisah-misah anak-anak manusia, maka Ia menetapkan wilayah bangsa-bangsa menurut bilangan anak-anak Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 9, 'Tetapi bagian TUHAN ialah umat-Nya, Yakub ialah milik yang ditetapkan bagi-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 10, 'Didapati-Nya dia di suatu negeri, di padang gurun, di tengah-tengah ketandusan dan auman padang belantara. Dikelilingi-Nya dia dan diawasi-Nya, dijaga-Nya sebagai biji mata-Nya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 11, 'Laksana rajawali menggoyangbangkitkan isi sarangnya, melayang-layang di atas anak-anaknya, mengembangkan sayapnya, menampung seekor, dan mendukungnya di atas kepaknya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 12, 'demikianlah TUHAN sendiri menuntun dia, dan tidak ada allah asing menyertai dia.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 13, 'Dibuat-Nya dia berkendaraan mengatasi bukit-bukit di bumi, dan memakan hasil dari ladang; dibuat-Nya dia mengisap madu dari bukit batu, dan minyak dari gunung batu yang keras,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 14, 'dadih dari lembu sapi dan susu kambing domba, dengan lemak anak-anak domba; dan domba-domba jantan dari Basan dan kambing-kambing jantan, dengan gandum yang terbaik; juga darah buah anggur yang berbuih engkau minum.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 15, 'Lalu menjadi gemuklah Yesyurun, dan menendang ke belakang, ?bertambah gemuk engkau, gendut dan tambun?dan ia meninggalkan Allah yang telah menjadikan dia, ia memandang rendah gunung batu keselamatannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 16, 'Mereka membangkitkan cemburu-Nya dengan allah asing, mereka menimbulkan sakit hati-Nya dengan dewa kekejian,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 17, 'mereka mempersembahkan korban kepada roh-roh jahat yang bukan Allah, kepada allah yang tidak mereka kenal, allah baru yang belum lama timbul, yang kepadanya nenek moyangmu tidak gentar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 18, 'Gunung batu yang memperanakkan engkau, telah kaulalaikan, dan telah kaulupakan Allah yang melahirkan engkau.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 19, 'Ketika TUHAN melihat hal itu, maka Ia menolak mereka, karena Ia sakit hati oleh anak-anaknya lelaki dan perempuan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 20, 'Ia berfirman: Aku hendak menyembunyikan wajah-Ku terhadap mereka, dan melihat bagaimana kesudahan mereka, sebab mereka itu suatu angkatan yang bengkok, anak-anak yang tidak mempunyai kesetiaan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 21, 'Mereka membangkitkan cemburu-Ku dengan yang bukan Allah, mereka menimbulkan sakit hati-Ku dengan berhala mereka. Sebab itu Aku akan membangkitkan cemburu mereka dengan yang bukan umat, dan akan menyakiti hati mereka dengan bangsa yang bebal.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 22, 'Sebab api telah dinyalakan oleh murka-Ku, dan bernyala-nyala sampai ke bagian dunia orang mati yang paling bawah; api itu memakan bumi dengan hasilnya, dan menghanguskan dasar gunung-gunung.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 23, 'Aku akan menimbun malapetaka ke atas mereka, seluruh anak panah-Ku akan Kutembakkan kepada mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 24, 'Apabila mereka sudah lemas karena lapar dan merana oleh demam yang membara, dan oleh penyakit sampar, maka Aku akan melepaskan taring binatang buas kepada mereka, dengan racun binatang yang menjalar di dalam debu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 25, 'Pedang di luar rumah dan kengerian di dalam kamar akan melenyapkan teruna maupun dara, anak menyusu serta orang ubanan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 26, 'Seharusnya Aku berfirman: Aku meniupkan mereka, melenyapkan ingatan kepada mereka dari antara manusia,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 27, 'tetapi Aku kuatir disakiti hati-Ku oleh musuh, jangan-jangan lawan mereka salah mengerti, jangan-jangan mereka berkata: Tangan kami jaya, bukanlah TUHAN yang melakukan semuanya ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 28, 'Sebab mereka itu suatu bangsa yang tidak punya pertimbangan, dan tidak ada pengertian pada mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 29, 'Sekiranya mereka bijaksana, tentulah mereka mengerti hal ini, dan memperhatikan kesudahan mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 30, 'Bagaimana mungkin satu orang dapat mengejar seribu orang, dan dua orang dapat membuat lari sepuluh ribu orang, kalau tidak gunung batu mereka telah menjual mereka, dan TUHAN telah menyerahkan mereka!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 31, 'Sebab bukanlah seperti gunung batu kita gunung batu orang-orang itu; musuh kita boleh menjadi hakim!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 32, 'Sesungguhnya, pohon anggur mereka berasal dari pohon anggur Sodom, dan dari kebun-kebun Gomora; buah anggur mereka adalah buah anggur yang beracun, pahit gugusan-gugusannya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 33, 'Air anggur mereka adalah racun ular, dan bisa ular tedung yang keras ganas.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 34, 'Bukankah hal itu tersimpan pada-Ku, termeterai dalam perbendaharaan-Ku?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 35, 'Hak-Kulah dendam dan pembalasan, pada waktu kaki mereka goyang, sebab hari bencana bagi mereka telah dekat, akan segera datang apa yang telah disediakan bagi mereka.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 36, 'Sebab TUHAN akan memberi keadilan kepada umat-Nya, dan akan merasa sayang kepada hamba-hamba-Nya; apabila dilihat-Nya, bahwa kekuatan mereka sudah lenyap, dan baik hamba maupun orang merdeka sudah tiada.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 37, 'Maka Ia akan berfirman: Di manakah allah mereka, ?gunung batu tempat mereka berlindung?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 38, 'yang memakan lemak dari korban sembelihan mereka, meminum anggur dari korban curahan mereka? Biarlah mereka bangkit untuk menolong kamu, sehingga kamu mendapat perlindungan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 39, 'Lihatlah sekarang, bahwa Aku, Akulah Dia. Tidak ada Allah kecuali Aku. Akulah yang mematikan dan yang menghidupkan, Aku telah meremukkan, tetapi Akulah yang menyembuhkan, dan seorangpun tidak ada yang dapat melepaskan dari tangan-Ku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 40, 'Sesungguhnya, Aku mengangkat tangan-Ku ke langit, dan berfirman: Demi Aku yang hidup selama-lamanya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 41, 'apabila Aku mengasah pedang-Ku yang berkilat-kilat, dan tangan-Ku memegang penghukuman, maka Aku membalas dendam kepada lawan-Ku, dan mengadakan pembalasan kepada yang membenci Aku.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 42, 'Aku akan memabukkan anak panah-Ku dengan darah, dan pedang-Ku akan memakan daging: darah orang-orang yang mati tertikam dan orang-orang yang tertawan, dari kepala-kepala musuh yang berambut panjang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 43, 'Bersorak-sorailah, hai bangsa-bangsa karena umat-Nya, sebab Ia membalaskan darah hamba-hamba-Nya, Ia membalas dendam kepada lawan-Nya, dan mengadakan pendamaian bagi tanah umat-Nya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 44, 'Lalu datanglah Musa bersama-sama dengan Yosua bin Nun dan menyampaikan ke telinga bangsa itu segala perkataan nyanyian tadi.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 45, 'Setelah Musa selesai menyampaikan segala perkataan itu kepada seluruh orang Israel,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 46, 'berkatalah ia kepada mereka: "Perhatikanlah segala perkataan yang kuperingatkan kepadamu pada hari ini, supaya kamu memerintahkannya kepada anak-anakmu untuk melakukan dengan setia segala perkataan hukum Taurat ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 47, 'Sebab perkataan ini bukanlah perkataan hampa bagimu, tetapi itulah hidupmu, dan dengan perkataan ini akan lanjut umurmu di tanah, ke mana kamu pergi, menyeberangi sungai Yordan untuk mendudukinya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 48, 'Pada hari itulah juga TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 49, '"Naiklah ke atas pegunungan Abarim, ke atas gunung Nebo, yang di tanah Moab, di tentangan Yerikho, dan pandanglah tanah Kanaan yang Kuberikan kepada orang Israel menjadi miliknya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 50, 'kemudian engkau akan mati di atas gunung yang akan kaunaiki itu, supaya engkau dikumpulkan kepada kaum leluhurmu, sama seperti Harun, kakakmu, sudah meninggal di gunung Hor dan dikumpulkan kepada kaum leluhurnya?', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 51, 'oleh sebab kamu telah berubah setia terhadap Aku di tengah-tengah orang Israel, dekat mata air Meriba di Kadesh di padang gurun Zin, dan oleh sebab kamu tidak menghormati kekudusan-Ku di tengah-tengah orang Israel.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 32, 52, 'Engkau boleh melihat negeri itu terbentang di depanmu, tetapi tidak boleh masuk ke sana, ke negeri yang Kuberikan kepada orang Israel."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 1, 'Inilah berkat yang diberikan Musa, abdi Allah itu, kepada orang Israel sebelum ia mati.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 2, 'Berkatalah ia: "TUHAN datang dari Sinai dan terbit kepada mereka dari Seir; Ia tampak bersinar dari pegunungan Paran dan datang dari tengah-tengah puluhan ribu orang yang kudus; di sebelah kanan-Nya tampak kepada mereka api yang menyala.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 3, 'Sungguh Ia mengasihi umat-Nya; semua orang-Nya yang kudus?di dalam tangan-Mulah mereka, pada kaki-Mulah mereka duduk, menangkap sesuatu dari firman-Mu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 4, 'Musa telah memerintahkan hukum Taurat kepada kita, suatu milik bagi jemaah Yakub.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 5, 'Ia menjadi raja di Yesyurun, ketika kepala-kepala bangsa datang berkumpul, yakni segala suku Israel bersama-sama.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 6, 'Biarlah Ruben hidup dan jangan mati, tetapi biarlah orang-orangnya sedikit jumlahnya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 7, 'Dan inilah tentang Yehuda. Katanya: "Dengarlah, ya TUHAN, suara Yehuda dan bawalah dia kepada bangsanya. Berjuanglah baginya dengan tangan-Mu, dan jadilah Engkau penolongnya melawan musuhnya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 8, 'Tentang Lewi ia berkata: "Biarlah Tumim dan Urim-Mu menjadi kepunyaan orang yang Kaukasihi, yang telah Kaucoba di Masa, dengan siapa Engkau berbantah dekat mata air Meriba;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 9, 'yang berkata tentang ayahnya dan tentang ibunya: aku tidak mengindahkan mereka; ia yang tidak mau kenal saudara-saudaranya dan acuh tak acuh terhadap anak-anaknya. Sebab orang-orang Lewi itu berpegang pada firman-Mu dan menjaga perjanjian-Mu;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 10, 'mereka mengajarkan peraturan-peraturan-Mu kepada Yakub, hukum-Mu kepada Israel; mereka menaruh ukupan wangi-wangian di depan-Mu dan korban yang terbakar seluruhnya di atas mezbah-Mu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 11, 'Berkatilah, ya TUHAN, kekuatannya dan berkenanlah kepada pekerjaannya. Remukkanlah pinggang orang yang melawan dia dan yang membenci dia, sehingga mereka tidak dapat bangkit."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 12, 'Tentang Benyamin ia berkata: "Kekasih TUHAN yang diam pada-Nya dengan tenteram! TUHAN melindungi dia setiap waktu dan diam di antara lereng-lereng gunungnya."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 13, 'Tentang Yusuf ia berkata: "Kiranya negerinya diberkati oleh TUHAN dengan yang terbaik dari langit, dengan air embun, dan dengan air samudera raya yang ada di bawah;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 14, 'dengan yang terbaik dari yang dihasilkan matahari, dan dengan yang terbaik dari yang ditumbuhkan bulan;', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 15, 'dengan yang terutama dari gunung-gunung yang sejak dahulu, dan dengan yang terbaik dari bukit-bukit yang berabad-abad,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 16, 'dan dengan yang terbaik dari bumi serta segala isinya; dengan perkenanan Dia yang diam dalam semak duri. Biarlah itu semuanya turun ke atas kepala Yusuf, ke atas batu kepala orang yang teristimewa di antara saudara-saudaranya.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 17, 'Anak sulung lembu sapinya adalah kegemilangannya dan tanduk-tanduknya seperti tanduk-tanduk lembu hutan; dengan itu ia akan menanduk bangsa-bangsa, seluruh bumi, dari ujung ke ujung. Itulah orang Efraim yang puluhan ribu, dan itulah orang Manasye yang ribuan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 18, 'Tentang Zebulon ia berkata: "Bersukacitalah, hai Zebulon, atas perjalanan-perjalananmu, dan engkaupun, hai Isakhar, atas kemah-kemahmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 19, 'Bangsa-bangsa akan dipanggil mereka datang ke gunung; di sanalah mereka akan mempersembahkan korban sembelihan yang benar, sebab mereka akan mengisap kelimpahan laut dan harta yang terpendam di dalam pasir."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 20, 'Tentang Gad ia berkata: "Terpujilah Dia yang memberi kelapangan kepada Gad. Seperti singa betina ia diam dan menerkam lengan, bahkan batu kepala.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 21, 'Ia memilih bagian yang terutama, sebab di sanalah tersimpan bagian panglima; ia datang kepada para kepala bangsa itu; dilakukannya kebenaran TUHAN serta penghukuman-penghukuman-Nya bersama-sama dengan orang Israel."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 22, 'Tentang Dan ia berkata: "Adapun Dan ialah anak singa yang melompat keluar dari Basan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 23, 'Tentang Naftali ia berkata: "Naftali kenyang dengan perkenanan dan penuh dengan berkat TUHAN; milikilah tasik dan wilayah sebelah selatan."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 24, 'Tentang Asyer ia berkata: "Diberkatilah Asyer di antara anak-anak lelaki; biarlah ia disukai oleh saudara-saudaranya, dan biarlah ia mencelupkan kakinya ke dalam minyak.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 25, 'Biarlah dari besi dan dari tembaga palang pintumu, selama umurmu kiranya kekuatanmu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 26, 'Tidak ada yang seperti Allah, hai Yesyurun. Ia berkendaraan melintasi langit sebagai penolongmu dan dalam kejayaan-Nya melintasi awan-awan.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 27, 'Allah yang abadi adalah tempat perlindunganmu, dan di bawahmu ada lengan-lengan yang kekal. Ia mengusir musuh dari depanmu dan berfirman: Punahkanlah!', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 28, 'Maka Israel diam dengan tenteram dan sumber Yakub diam tidak terganggu di dalam suatu negeri yang ada gandum dan anggur; bahkan langitnya menitikkan embun.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 33, 29, 'Berbahagialah engkau, hai Israel; siapakah yang sama dengan engkau? Suatu bangsa yang diselamatkan oleh TUHAN, perisai pertolongan dan pedang kejayaanmu. Sebab itu musuhmu akan tunduk menjilat kepadamu, dan engkau akan berjejak di bukit-bukit mereka."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 1, 'Kemudian naiklah Musa dari dataran Moab ke atas gunung Nebo, yakni ke atas puncak Pisga, yang di tentangan Yerikho, lalu TUHAN memperlihatkan kepadanya seluruh negeri itu: daerah Gilead sampai ke kota Dan,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 2, 'seluruh Naftali, tanah Efraim dan Manasye, seluruh tanah Yehuda sampai laut sebelah barat,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 3, 'Tanah Negeb dan lembah Yordan, lembah Yerikho, kota pohon korma itu, sampai Zoar.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 4, 'Dan berfirmanlah TUHAN kepadanya: "Inilah negeri yang Kujanjikan dengan sumpah kepada Abraham, Ishak dan Yakub; demikian: Kepada keturunanmulah akan Kuberikan negeri itu. Aku mengizinkan engkau melihatnya dengan matamu sendiri, tetapi engkau tidak akan menyeberang ke sana."', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 5, 'Lalu matilah Musa, hamba TUHAN itu, di sana di tanah Moab, sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 6, 'Dan dikuburkan-Nyalah dia di suatu lembah di tanah Moab, di tentangan Bet-Peor, dan tidak ada orang yang tahu kuburnya sampai hari ini.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 7, 'Musa berumur seratus dua puluh tahun, ketika ia mati; matanya belum kabur dan kekuatannya belum hilang.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 8, 'Orang Israel menangisi Musa di dataran Moab tiga puluh hari lamanya. Maka berakhirlah hari-hari tangis perkabungan karena Musa itu.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 9, 'Dan Yosua bin Nun penuh dengan roh kebijaksanaan, sebab Musa telah meletakkan tangannya ke atasnya. Sebab itu orang Israel mendengarkan dia dan melakukan seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 10, 'Seperti Musa yang dikenal TUHAN dengan berhadapan muka, tidak ada lagi nabi yang bangkit di antara orang Israel,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 11, 'dalam hal segala tanda dan mujizat, yang dilakukannya atas perintah TUHAN di tanah Mesir terhadap Firaun dan terhadap semua pegawainya dan seluruh negerinya,', 'id', 'TB'),
  ('5', 'ul', 'Ulangan', 34, 12, 'dan dalam hal segala perbuatan kekuasaan dan segala kedahsyatan yang besar yang dilakukan Musa di depan seluruh orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 1, 'Sesudah Musa hamba TUHAN itu mati, berfirmanlah TUHAN kepada Yosua bin Nun, abdi Musa itu, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 2, '"Hamba-Ku Musa telah mati; sebab itu bersiaplah sekarang, seberangilah sungai Yordan ini, engkau dan seluruh bangsa ini, menuju negeri yang akan Kuberikan kepada mereka, kepada orang Israel itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 3, 'Setiap tempat yang akan diinjak oleh telapak kakimu Kuberikan kepada kamu, seperti yang telah Kujanjikan kepada Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 4, 'Dari padang gurun dan gunung Libanon yang sebelah sana itu sampai ke sungai besar, yakni sungai Efrat, seluruh tanah orang Het, sampai ke Laut Besar di sebelah matahari terbenam, semuanya itu akan menjadi daerahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 5, 'Seorangpun tidak akan dapat bertahan menghadapi engkau seumur hidupmu; seperti Aku menyertai Musa, demikianlah Aku akan menyertai engkau; Aku tidak akan membiarkan engkau dan tidak akan meninggalkan engkau.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 6, 'Kuatkan dan teguhkanlah hatimu, sebab engkaulah yang akan memimpin bangsa ini memiliki negeri yang Kujanjikan dengan bersumpah kepada nenek moyang mereka untuk diberikan kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 7, 'Hanya, kuatkan dan teguhkanlah hatimu dengan sungguh-sungguh, bertindaklah hati-hati sesuai dengan seluruh hukum yang telah diperintahkan kepadamu oleh hamba-Ku Musa; janganlah menyimpang ke kanan atau ke kiri, supaya engkau beruntung, ke manapun engkau pergi.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 8, 'Janganlah engkau lupa memperkatakan kitab Taurat ini, tetapi renungkanlah itu siang dan malam, supaya engkau bertindak hati-hati sesuai dengan segala yang tertulis di dalamnya, sebab dengan demikian perjalananmu akan berhasil dan engkau akan beruntung.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 9, 'Bukankah telah Kuperintahkan kepadamu: kuatkan dan teguhkanlah hatimu? Janganlah kecut dan tawar hati, sebab TUHAN, Allahmu, menyertai engkau, ke manapun engkau pergi."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 10, 'Lalu Yosua memberi perintah kepada pengatur-pengatur pasukan bangsa itu, katanya:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 11, '"Jalanilah seluruh perkemahan dan perintahkanlah kepada bangsa itu, demikian: Sediakanlah bekalmu, sebab dalam tiga hari kamu akan menyeberangi sungai Yordan ini untuk pergi menduduki negeri yang akan diberikan TUHAN, Allahmu, kepadamu untuk diduduki."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 12, 'Kepada orang Ruben, kepada orang Gad dan kepada suku Manasye yang setengah itu berkatalah Yosua, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 13, '"Ingatlah kepada perkataan yang dipesankan Musa, hamba TUHAN itu, kepadamu, yakni: TUHAN, Allahmu, mengaruniakan keamanan kepadamu dan memberikan kepadamu negeri ini;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 14, 'perempuan-perempuan dan anak-anak di antara kamu dan ternakmu boleh tinggal di negeri yang diberikan Musa kepadamu di seberang sungai Yordan, tetapi kamu, semua pahlawan yang gagah perkasa, haruslah menyeberang di depan saudara-saudaramu dengan bersenjata, dan haruslah menolong mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 15, 'sampai TUHAN mengaruniakan keamanan kepada saudara-saudaramu seperti kepada kamu juga, dan mereka juga menduduki negeri yang akan diberikan kepada mereka oleh TUHAN, Allahmu. Kemudian bolehlah kamu pulang kembali ke negerimu sendiri dan menduduki negeri yang diberikan Musa, hamba TUHAN itu, kepadamu di seberang sungai Yordan, di sebelah matahari terbit."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 16, 'Lalu mereka menjawab Yosua, katanya: "Segala yang kauperintahkan kepada kami akan kami lakukan dan ke manapun kami akan kausuruh, kami akan pergi;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 17, 'sama seperti kami mendengarkan perintah Musa, demikianlah kami akan mendengarkan perintahmu. Hanya, TUHAN, Allahmu, kiranya menyertai engkau, seperti Ia menyertai Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 1, 18, 'Setiap orang yang menentang perintahmu dan tidak mendengarkan perkataanmu, apapun yang kauperintahkan kepadanya, dia akan dihukum mati. Hanya, kuatkan dan teguhkanlah hatimu!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 1, 'Yosua bin Nun dengan diam-diam melepas dari Sitim dua orang pengintai, katanya: "Pergilah, amat-amatilah negeri itu dan kota Yerikho." Maka pergilah mereka dan sampailah mereka ke rumah seorang perempuan sundal, yang bernama Rahab, lalu tidur di situ.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 2, 'Kemudian diberitahukanlah kepada raja Yerikho, demikian: "Tadi malam ada orang datang ke mari dari orang Israel untuk menyelidik negeri ini."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 3, 'Maka raja Yerikho menyuruh orang kepada Rahab, mengatakan: "Bawalah ke luar orang-orang yang datang kepadamu itu, yang telah masuk ke dalam rumahmu, sebab mereka datang untuk menyelidik seluruh negeri ini."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 4, 'Tetapi perempuan itu telah membawa dan menyembunyikan kedua orang itu. Berkatalah ia: "Memang, orang-orang itu telah datang kepadaku, tetapi aku tidak tahu dari mana mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 5, 'dan ketika pintu gerbang hendak ditutup menjelang malam, maka keluarlah orang-orang itu; aku tidak tahu, ke mana orang-orang itu pergi. Segeralah kejar mereka, tentulah kamu dapat menyusul mereka."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 6, 'Tetapi perempuan itu telah menyuruh keduanya naik ke sotoh rumah dan menyembunyikan mereka di bawah timbunan batang rami, yang ditebarkan di atas sotoh itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 7, 'Maka pergilah orang-orang itu, mengejar mereka ke arah sungai Yordan, ke tempat-tempat penyeberangan, dan ditutuplah pintu gerbang, segera sesudah pengejar-pengejar itu keluar.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 8, 'Tetapi sebelum kedua orang itu tidur, naiklah perempuan itu mendapatkan mereka di atas sotoh', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 9, 'dan berkata kepada orang-orang itu: "Aku tahu, bahwa TUHAN telah memberikan negeri ini kepada kamu dan bahwa kengerian terhadap kamu telah menghinggapi kami dan segala penduduk negeri ini gemetar menghadapi kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 10, 'Sebab kami mendengar, bahwa TUHAN telah mengeringkan air Laut Teberau di depan kamu, ketika kamu berjalan keluar dari Mesir, dan apa yang kamu lakukan kepada kedua raja orang Amori yang di seberang sungai Yordan itu, yakni kepada Sihon dan Og, yang telah kamu tumpas.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 11, 'Ketika kami mendengar itu, tawarlah hati kami dan jatuhlah semangat setiap orang menghadapi kamu, sebab TUHAN, Allahmu, ialah Allah di langit di atas dan di bumi di bawah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 12, 'Maka sekarang, bersumpahlah kiranya demi TUHAN, bahwa karena aku telah berlaku ramah terhadapmu, kamu juga akan berlaku ramah terhadap kaum keluargaku; dan berikanlah kepadaku suatu tanda yang dapat dipercaya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 13, 'bahwa kamu akan membiarkan hidup ayah dan ibuku, saudara-saudaraku yang laki-laki dan yang perempuan dan semua orang-orang mereka dan bahwa kamu akan menyelamatkan nyawa kami dari maut."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 14, 'Lalu jawab kedua orang itu kepadanya: "Nyawa kamilah jaminan bagi kamu, asal jangan kaukabarkan perkara kami ini; apabila TUHAN nanti memberikan negeri ini kepada kami, maka kami akan menunjukkan terima kasih dan setia kami kepadamu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 15, 'Kemudian perempuan itu menurunkan mereka dengan tali melalui jendela, sebab rumahnya itu letaknya pada tembok kota, jadi pada tembok itulah ia diam.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 16, 'Berkatalah ia kepada mereka: "Pergilah ke pegunungan, supaya pengejar-pengejar itu jangan menemui kamu, dan bersembunyilah di sana tiga hari lamanya, sampai pengejar-pengejar itu pulang; kemudian bolehlah kamu melanjutkan perjalananmu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 17, 'Kedua orang itu berkata kepadanya: "Kami akan bebas dari sumpah kami ini kepadamu, yang telah kausuruh kami ikrarkan?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 18, 'sesungguhnya, apabila kami memasuki negeri ini, haruslah tali dari benang kirmizi ini kauikatkan pada jendela tempat engkau menurunkan kami, dan ayahmu serta ibumu, saudara-saudaramu serta seluruh kaum keluargamu kaukumpulkan di rumahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 19, 'Setiap orang yang keluar nanti dari pintu rumahmu, harus sendiri menanggung akibatnya, kalau darahnya tertumpah, dan kami tidak bersalah; tetapi siapapun juga yang ada di dalam rumahmu, jika ada orang yang menciderainya, kamilah yang menanggung akibat pertumpahan darahnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 20, 'Tetapi jika engkau mengabarkan perkara kami ini, maka bebaslah kami dari sumpah kepadamu itu, yang telah kausuruh kami ikrarkan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 21, 'Perempuan itupun berkata: "Seperti yang telah kamu katakan, demikianlah akan terjadi." Sesudah itu dilepasnyalah orang-orang itu pergi, maka berangkatlah mereka. Kemudian perempuan itu mengikatkan tali kirmizi itu pada jendela.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 22, 'Merekapun pergilah dan tiba di pegunungan. Mereka tinggal di sana tiga hari lamanya, sampai pengejar-pengejar itu pulang. Pengejar-pengejar itu telah mencari di mana-mana sepanjang jalan tanpa menemukan mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 23, 'Maka pulanglah kedua orang itu, mereka turun dari pegunungan, lalu menyeberang dan sampai kepada Yosua bin Nun, kemudian mereka ceritakan segala pengalaman mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 2, 24, 'Kata mereka kepada Yosua: "TUHAN telah menyerahkan seluruh negeri ini ke dalam tangan kita, bahkan seluruh penduduk negeri itu gemetar menghadapi kita."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 1, 'Yosua bangun pagi-pagi, lalu ia dan semua orang Israel berangkat dari Sitim, dan sampailah mereka ke sungai Yordan, maka bermalamlah mereka di sana, sebelum menyeberang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 2, 'Setelah lewat tiga hari, para pengatur pasukan menjalani seluruh perkemahan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 3, 'dan memberi perintah kepada bangsa itu, katanya: "Segera sesudah kamu melihat tabut perjanjian TUHAN, Allahmu, yang diangkat para imam, yang memang suku Lewi, maka kamu harus juga berangkat dari tempatmu dan mengikutinya?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 4, 'hanya antara kamu dan tabut itu harus ada jarak kira-kira dua ribu hasta panjangnya, janganlah mendekatinya?maksudnya supaya kamu mengetahui jalan yang harus kamu tempuh, sebab jalan itu belum pernah kamu lalui dahulu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 5, 'Berkatalah Yosua kepada bangsa itu: "Kuduskanlah dirimu, sebab besok TUHAN akan melakukan perbuatan yang ajaib di antara kamu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 6, 'Dan kepada para imam itu Yosua berkata, demikian: "Angkatlah tabut perjanjian dan menyeberanglah di depan bangsa itu." Maka mereka mengangkat tabut perjanjian dan berjalan di depan bangsa itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 7, 'Dan TUHAN berfirman kepada Yosua: "Pada hari inilah Aku mulai membesarkan namamu di mata seluruh orang Israel, supaya mereka tahu, bahwa seperti dahulu Aku menyertai Musa, demikianlah Aku akan menyertai engkau.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 8, 'Maka kauperintahkanlah kepada para imam pengangkat tabut perjanjian itu, demikian: Setelah kamu sampai ke tepi air sungai Yordan, haruslah kamu tetap berdiri di sungai Yordan itu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 9, 'Lalu berkatalah Yosua kepada orang Israel: "Datanglah dekat dan dengarkanlah firman TUHAN, Allahmu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 10, 'Lagi kata Yosua: "Dari hal inilah akan kamu ketahui, bahwa Allah yang hidup ada di tengah-tengah kamu dan bahwa sungguh-sungguh akan dihalau-Nya orang Kanaan, orang Het, orang Hewi, orang Feris, orang Girgasi, orang Amori dan orang Yebus itu dari depan kamu:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 11, 'sesungguhnya, tabut perjanjian Tuhan semesta bumi berjalan menyeberang di depan kamu, masuk ke sungai Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 12, 'Maka sekarang, pilihlah dua belas orang dari suku-suku Israel, seorang dari tiap-tiap suku.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 13, 'Segera sesudah kaki para imam pengangkat tabut TUHAN, Tuhan semesta bumi, berhenti di dalam air sungai Yordan, maka air sungai Yordan itu akan terputus; air yang turun dari hulu akan berhenti mengalir menjadi bendungan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 14, 'Ketika bangsa itu berangkat dari tempat perkemahan mereka untuk menyeberangi sungai Yordan, para imam pengangkat tabut perjanjian itu berjalan di depan bangsa itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 15, 'Segera sesudah para pengangkat tabut itu sampai ke sungai Yordan, dan para imam pengangkat tabut itu mencelupkan kakinya ke dalam air di tepi sungai itu?sungai Yordan itu sebak sampai meluap sepanjang tepinya selama musim menuai?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 16, 'maka berhentilah air itu mengalir. Air yang turun dari hulu melonjak menjadi bendungan, jauh sekali, di dekat Adam, kota yang terletak di sebelah Sartan, sedang air yang turun ke Laut Araba itu, yakni Laut Asin, terputus sama sekali. Lalu menyeberanglah bangsa itu, di tentangan Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 3, 17, 'Tetapi para imam pengangkat tabut perjanjian TUHAN itu tetap berdiri di tanah yang kering, di tengah-tengah sungai Yordan, sedang seluruh bangsa Israel menyeberang di tanah yang kering, sampai seluruh bangsa itu selesai menyeberangi sungai Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 1, 'Setelah seluruh bangsa itu selesai menyeberangi sungai Yordan, berfirmanlah TUHAN kepada Yosua, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 2, '"Pilihlah dari bangsa itu dua belas orang, seorang dari tiap-tiap suku,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 3, 'dan perintahkanlah kepada mereka, demikian: Angkatlah dua belas batu dari sini, dari tengah-tengah sungai Yordan ini, dari tempat berjejak kaki para imam itu, bawalah semuanya itu ke seberang dan letakkanlah di tempat kamu akan bermalam nanti malam."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 4, 'Lalu Yosua memanggil kedua belas orang yang ditetapkannya dari orang Israel itu, seorang dari tiap-tiap suku,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 5, 'dan Yosua berkata kepada mereka: "Menyeberanglah di depan tabut TUHAN, Allahmu, ke tengah-tengah sungai Yordan, dan angkatlah masing-masing sebuah batu ke atas bahumu, menurut bilangan suku orang Israel,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 6, 'supaya ini menjadi tanda di tengah-tengah kamu. Jika anak-anakmu bertanya di kemudian hari: Apakah artinya batu-batu ini bagi kamu?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 7, 'maka haruslah kamu katakan kepada mereka: Bahwa air sungai Yordan terputus di depan tabut perjanjian TUHAN; ketika tabut itu menyeberangi sungai Yordan, air sungai Yordan itu terputus. Sebab itu batu-batu ini akan menjadi tanda peringatan bagi orang Israel untuk selama-lamanya."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 8, 'Maka orang Israel itu melakukan seperti yang diperintahkan Yosua. Mereka mengangkat dua belas batu dari tengah-tengah sungai Yordan, seperti yang difirmankan TUHAN kepada Yosua, menurut jumlah suku Israel. Semuanya itu dibawa merekalah ke seberang, ke tempat bermalam, dan diletakkan di situ.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 9, 'Pula Yosua menegakkan dua belas batu di tengah-tengah sungai Yordan itu, di tempat bekas berjejak kaki para imam pengangkat tabut perjanjian itu. Batu-batu itu masih ada di sana sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 10, 'Para imam pengangkat tabut itu tinggal berdiri di tengah-tengah sungai Yordan, sampai selesai dilakukan segala yang diperintahkan TUHAN kepada Yosua untuk disampaikan kepada bangsa itu, sesuai dengan segala yang diperintahkan Musa kepada Yosua. Maka menyeberanglah bangsa itu dengan cepat-cepat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 11, 'Ketika seluruh bangsa itu selesai menyeberang, maka menyeberanglah tabut TUHAN itu serta para imam di depan mata bangsa itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 12, 'Juga bani Ruben, bani Gad dan suku Manasye yang setengah itu menyeberang, dengan bersenjata, di depan orang Israel itu, seperti yang dikatakan Musa kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 13, 'Kira-kira empat puluh ribu orang yang siap untuk berperang menyeberang di hadapan TUHAN ke dataran Yerikho untuk berperang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 14, 'Pada waktu itulah TUHAN membesarkan nama Yosua di mata seluruh orang Israel, sehingga mereka takut kepadanya, seperti mereka takut kepada Musa seumur hidupnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 15, 'Berfirmanlah TUHAN kepada Yosua, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 16, '"Perintahkanlah para imam pengangkat tabut hukum Allah itu supaya naik dari sungai Yordan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 17, 'Maka Yosua memerintahkan kepada para imam itu, demikian: "Keluarlah dari sungai Yordan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 18, 'Ketika para imam, pengangkat tabut perjanjian TUHAN itu, keluar dari tengah-tengah sungai Yordan, dan baru saja kaki para imam itu dijejakkan di tanah yang kering, maka berbaliklah air sungai Yordan itu ke tempatnya dan mengalir seperti dahulu dengan meluap sepanjang tepinya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 19, 'Bangsa itu telah keluar dari sungai Yordan pada tanggal sepuluh bulan pertama dan mereka berkemah di Gilgal, di batas timur Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 20, 'Kedua belas batu yang diambil dari sungai Yordan itu ditegakkan oleh Yosua di Gilgal.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 21, 'Dan berkatalah ia kepada orang Israel, demikian: "Apabila di kemudian hari anak-anakmu bertanya kepada ayahnya: Apakah arti batu-batu ini?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 22, 'maka haruslah kamu beritahukan kepada anak-anakmu, begini: Israel telah menyeberangi sungai Yordan ini di tanah yang kering! ?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 23, 'sebab TUHAN, Allahmu, telah mengeringkan di depan kamu air sungai Yordan, sampai kamu dapat menyeberang seperti yang telah dilakukan TUHAN, Allahmu, dengan Laut Teberau, yang telah dikeringkan-Nya di depan kita, sampai kita dapat menyeberang,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 4, 24, 'supaya semua bangsa di bumi tahu, bahwa kuat tangan TUHAN, dan supaya mereka selalu takut kepada TUHAN, Allahmu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 1, 'Ketika semua raja orang Amori di sebelah barat sungai Yordan dan semua raja orang Kanaan di tepi laut mendengar, bahwa TUHAN telah mengeringkan air sungai Yordan di depan orang Israel, sampai mereka dapat menyeberang, tawarlah hati mereka dan hilanglah semangat mereka menghadapi orang Israel itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 2, 'Pada waktu itu berfirmanlah TUHAN kepada Yosua: "Buatlah pisau dari batu dan sunatlah lagi orang Israel itu, untuk kedua kalinya."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 3, 'Lalu Yosua membuat pisau dari batu dan disunatnyalah orang Israel itu di Bukit Kulit Khatan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 4, 'Inilah sebabnya Yosua menyunat mereka: semua orang yang keluar dari Mesir, yakni yang laki-laki, semua prajurit, telah mati di padang gurun di tengah jalan, setelah mereka keluar dari Mesir.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 5, 'Sebab, semua orang yang keluar dari Mesir itu telah bersunat, tetapi semua orang yang lahir di padang gurun dalam perjalanan sejak keluar dari Mesir, belum disunat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 6, 'Sebab empat puluh tahun lamanya orang Israel itu berjalan melalui padang gurun, sampai habis mati seluruh bangsa itu, yakni prajurit yang keluar dari Mesir, yang tidak mendengarkan firman TUHAN. Kepada mereka itu TUHAN telah bersumpah, bahwa Ia tidak akan mengizinkan mereka melihat negeri yang dijanjikan TUHAN dengan bersumpah kepada nenek moyang mereka akan memberikannya kepada kita, suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 7, 'Tetapi anak-anak mereka yang telah dijadikan-Nya ganti mereka, mereka itulah yang disunat Yosua, sebab mereka belum bersunat, karena mereka tidak disunat dalam perjalanan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 8, 'Setelah seluruh bangsa itu selesai disunat, maka tinggallah mereka di tempatnya masing-masing di perkemahan itu, sampai mereka sembuh.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 9, 'Dan berfirmanlah TUHAN kepada Yosua: "Hari ini telah Kuhapuskan cela Mesir itu dari padamu." Itulah sebabnya nama tempat itu disebut Gilgal sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 10, 'Sementara berkemah di Gilgal, orang Israel itu merayakan Paskah pada hari yang keempat belas bulan itu, pada waktu petang, di dataran Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 11, 'Lalu pada hari sesudah Paskah mereka makan hasil negeri itu, yakni roti yang tidak beragi dan bertih gandum, pada hari itu juga.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 12, 'Lalu berhentilah manna itu, pada keesokan harinya setelah mereka makan hasil negeri itu. Jadi orang Israel tidak beroleh manna lagi, tetapi dalam tahun itu mereka makan yang dihasilkan tanah Kanaan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 13, 'Ketika Yosua dekat Yerikho, ia melayangkan pandangnya, dilihatnya seorang laki-laki berdiri di depannya dengan pedang terhunus di tangannya. Yosua mendekatinya dan bertanya kepadanya: "Kawankah engkau atau lawan?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 14, 'Jawabnya: "Bukan, tetapi akulah Panglima Balatentara TUHAN. Sekarang aku datang." Lalu sujudlah Yosua dengan mukanya ke tanah, menyembah dan berkata kepadanya: "Apakah yang akan dikatakan tuanku kepada hambanya ini?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 5, 15, 'Dan Panglima Balatentara TUHAN itu berkata kepada Yosua: "Tanggalkanlah kasutmu dari kakimu, sebab tempat engkau berdiri itu kudus." Dan Yosua berbuat demikian.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 1, 'Dalam pada itu Yerikho telah menutup pintu gerbangnya; telah tertutup kota itu karena orang Israel; tidak ada orang keluar atau masuk.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 2, 'Berfirmanlah TUHAN kepada Yosua: "Ketahuilah, Aku serahkan ke tanganmu Yerikho ini beserta rajanya dan pahlawan-pahlawannya yang gagah perkasa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 3, 'Haruslah kamu mengelilingi kota itu, yakni semua prajurit harus mengedari kota itu sekali saja; demikianlah harus engkau perbuat enam hari lamanya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 4, 'dan tujuh orang imam harus membawa tujuh sangkakala tanduk domba di depan tabut. Tetapi pada hari yang ketujuh, tujuh kali kamu harus mengelilingi kota itu sedang para imam meniup sangkakala.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 5, 'Apabila sangkakala tanduk domba itu panjang bunyinya dan kamu mendengar bunyi sangkakala itu, maka haruslah seluruh bangsa bersorak dengan sorak yang nyaring, maka tembok kota itu akan runtuh, lalu bangsa itu harus memanjatnya, masing-masing langsung ke depan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 6, 'Kemudian Yosua bin Nun memanggil para imam dan berkata kepada mereka: "Angkatlah tabut perjanjian itu dan tujuh orang imam harus membawa tujuh sangkakala tanduk domba di depan tabut TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 7, 'Dan kepada bangsa itu dikatakannya: "Majulah, kelilingilah kota itu, dan orang-orang bersenjata harus berjalan di depan tabut TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 8, 'Segera sesudah Yosua berkata kepada bangsa itu, maka berjalanlah maju ketujuh orang imam, yang membawa ketujuh sangkakala tanduk domba itu di hadapan TUHAN, lalu mereka meniup sangkakala, sedang tabut perjanjian TUHAN mengikut mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 9, 'Dan orang-orang bersenjata berjalan di depan para imam yang meniup sangkakala dan barisan penutup mengikut tabut itu, sedang sangkakala terus-menerus ditiup.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 10, 'Tetapi Yosua telah memerintahkan kepada bangsa itu, demikian: "Janganlah bersorak dan janganlah perdengarkan suaramu, sepatah katapun janganlah keluar dari mulutmu sampai pada hari aku mengatakan kepadamu: Bersoraklah! ?maka kamu harus bersorak."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 11, 'Demikianlah tabut TUHAN mengelilingi kota itu, mengedarinya sekali saja. Kemudian kembalilah mereka ke tempat perkemahan dan bermalam di tempat perkemahan itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 12, 'Keesokan harinya Yosua bangun pagi-pagi, lalu para imam mengangkat tabut TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 13, 'Maka berjalanlah juga ketujuh orang imam, yang membawa ketujuh sangkakala tanduk domba itu di depan tabut TUHAN, sambil berjalan mereka meniup sangkakala, sedang orang-orang bersenjata berjalan di depan mereka dan barisan penutup mengikut tabut TUHAN, sementara sangkakala terus-menerus ditiup.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 14, 'Demikianlah pada hari kedua mereka mengelilingi kota itu sekali saja, lalu pulang ke tempat perkemahan. Dan begitulah dilakukan mereka enam hari lamanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 15, 'Tetapi pada hari yang ketujuh mereka bangun pagi-pagi, ketika fajar menyingsing, dan mengelilingi kota tujuh kali dengan cara yang sama; hanya pada hari itu mereka mengelilingi kota itu tujuh kali.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 16, 'Lalu pada ketujuh kalinya, ketika para imam meniup sangkakala, berkatalah Yosua kepada bangsa itu: "Bersoraklah, sebab TUHAN telah menyerahkan kota ini kepadamu!', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 17, 'Dan kota itu dengan segala isinya akan dikhususkan bagi TUHAN untuk dimusnahkan; hanya Rahab, perempuan sundal itu, akan tetap hidup, ia dengan semua orang yang bersama-sama dengan dia dalam rumah itu, karena ia telah menyembunyikan orang suruhan yang kita suruh.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 18, 'Tetapi kamu ini, jagalah dirimu terhadap barang-barang yang dikhususkan untuk dimusnahkan, supaya jangan kamu mengambil sesuatu dari barang-barang yang dikhususkan itu setelah mengkhususkannya dan dengan demikian membawa kemusnahan atas perkemahan orang Israel dan mencelakakannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 19, 'Segala emas dan perak serta barang-barang tembaga dan besi adalah kudus bagi TUHAN; semuanya itu akan dimasukkan ke dalam perbendaharaan TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 20, 'Lalu bersoraklah bangsa itu, sedang sangkakala ditiup; segera sesudah bangsa itu mendengar bunyi sangkakala, bersoraklah mereka dengan sorak yang nyaring. Maka runtuhlah tembok itu, lalu mereka memanjat masuk ke dalam kota, masing-masing langsung ke depan, dan merebut kota itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 21, 'Mereka menumpas dengan mata pedang segala sesuatu yang di dalam kota itu, baik laki-laki maupun perempuan, baik tua maupun muda, sampai kepada lembu, domba dan keledai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 22, 'Tetapi kepada kedua orang pengintai negeri itu Yosua berkata: "Masuklah ke dalam rumah perempuan sundal itu dan bawalah ke luar perempuan itu dan semua orang yang bersama-sama dengan dia, seperti yang telah kamu janjikan dengan bersumpah kepadanya."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 23, 'Lalu masuklah kedua pengintai muda itu dan membawa ke luar Rahab dan ayahnya, ibunya, saudara-saudaranya dan semua orang yang bersama-sama dengan dia, bahkan seluruh kaumnya dibawa mereka ke luar, lalu mereka menunjukkan kepadanya tempat tinggal di luar perkemahan orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 24, 'Tetapi kota itu dan segala sesuatu yang ada di dalamnya dibakar mereka dengan api; hanya emas dan perak, barang-barang tembaga dan besi ditaruh mereka di dalam perbendaharaan rumah TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 25, 'Demikianlah Rahab, perempuan sundal itu dan keluarganya serta semua orang yang bersama-sama dengan dia dibiarkan hidup oleh Yosua. Maka diamlah perempuan itu di tengah-tengah orang Israel sampai sekarang, karena ia telah menyembunyikan orang suruhan yang disuruh Yosua mengintai Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 26, 'Pada waktu itu bersumpahlah Yosua, katanya: "Terkutuklah di hadapan TUHAN orang yang bangkit untuk membangun kembali kota Yerikho ini; dengan membayarkan nyawa anaknya yang sulung ia akan meletakkan dasar kota itu dan dengan membayarkan nyawa anaknya yang bungsu ia akan memasang pintu gerbangnya!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 6, 27, 'Dan TUHAN menyertai Yosua dan terdengarlah kabar tentang dia di seluruh negeri itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 1, 'Tetapi orang Israel berubah setia dengan mengambil barang-barang yang dikhususkan itu, karena Akhan bin Karmi bin Zabdi bin Zerah, dari suku Yehuda, mengambil sesuatu dari barang-barang yang dikhususkan itu. Lalu bangkitlah murka TUHAN terhadap orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 2, 'Yosua menyuruh orang dari Yerikho ke Ai, yang letaknya dekat Bet-Awen, di sebelah timur Betel, dan berkata kepada mereka, demikian: "Pergilah ke sana dan intailah negeri itu." Maka pergilah orang-orang itu ke sana dan mengintai kota Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 3, 'Kemudian kembalilah mereka kepada Yosua dan berkata kepadanya: "Tidak usah seluruh bangsa itu pergi, biarlah hanya kira-kira dua atau tiga ribu orang pergi untuk menggempur Ai itu; janganlah kaususahkan seluruh bangsa itu dengan berjalan ke sana, sebab orang-orang di sana sedikit saja."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 4, 'Maka berangkatlah kira-kira tiga ribu orang dari bangsa itu ke sana; tetapi mereka melarikan diri di depan orang-orang Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 5, 'Sebab orang-orang Ai menewaskan kira-kira tiga puluh enam orang dari mereka; orang-orang Israel itu dikejar dari depan pintu gerbang kota itu sampai ke Syebarim dan dipukul kalah di lereng. Lalu tawarlah hati bangsa itu amat sangat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 6, 'Yosuapun mengoyakkan jubahnya dan sujudlah ia dengan mukanya sampai ke tanah di depan tabut TUHAN hingga petang, bersama dengan para tua-tua orang Israel, sambil menaburkan debu di atas kepalanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 7, 'Dan berkatalah Yosua: "Ah, Tuhanku ALLAH, mengapa Engkau menyuruh bangsa ini menyeberangi sungai Yordan? supaya kami diserahkan kepada orang Amori untuk dibinasakan? Lebih baik kalau kami putuskan tadinya untuk tinggal di seberang sungai Yordan itu!', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 8, 'O Tuhan, apakah yang akan kukatakan, setelah orang Israel lari membelakangi musuhnya?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 9, 'Apabila hal itu terdengar oleh orang Kanaan dan seluruh penduduk negeri ini, maka mereka akan mengepung kami dan melenyapkan nama kami dari bumi ini. Dan apakah yang akan Kaulakukan untuk memulihkan nama-Mu yang besar itu?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 10, 'Lalu berfirmanlah TUHAN kepada Yosua: "Bangunlah! Mengapa engkau sujud demikian?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 11, 'Orang Israel telah berbuat dosa, mereka melanggar perjanjian-Ku yang Kuperintahkan kepada mereka, mereka mengambil sesuatu dari barang-barang yang dikhususkan itu, mereka mencurinya, mereka menyembunyikannya dan mereka menaruhnya di antara barang-barangnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 12, 'Sebab itu orang Israel tidak dapat bertahan menghadapi musuhnya. Mereka membelakangi musuhnya, sebab mereka itupun dikhususkan untuk ditumpas. Aku tidak akan menyertai kamu lagi jika barang-barang yang dikhususkan itu tidak kamu punahkan dari tengah-tengahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 13, 'Bangunlah, kuduskanlah bangsa itu dan katakan: Kuduskanlah dirimu untuk esok hari, sebab, demikianlah firman TUHAN, Allah Israel: Hai, orang Israel ada barang-barang yang dikhususkan di tengah-tengahmu; kamu tidak akan dapat bertahan menghadapi musuhmu, sebelum barang-barang yang dikhususkan itu kamu jauhkan dari tengah-tengah kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 14, 'Besok pagi kamu harus tampil ke muka suku demi suku dan suku yang ditunjuk oleh TUHAN harus tampil ke muka kaum demi kaum, dan kaum yang ditunjuk oleh TUHAN harus tampil ke muka keluarga demi keluarga dan keluarga yang ditunjuk oleh TUHAN harus tampil ke muka seorang demi seorang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 15, 'Dan siapa yang didapati menyimpan barang-barang yang dikhususkan itu, akan dibakar dengan api, ia dan segala sesuatu yang ada padanya, sebab ia telah melanggar perjanjian TUHAN dan berbuat noda di antara orang Israel."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 16, 'Keesokan harinya bangunlah Yosua pagi-pagi, lalu menyuruh orang Israel tampil ke muka suku demi suku, maka didapatilah suku Yehuda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 17, 'Ketika disuruhnya tampil ke muka kaum-kaum Yehuda, maka didapatinya kaum Zerah. Ketika disuruhnya tampil ke muka kaum Zerah, seorang demi seorang, maka didapatilah Zabdi.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 18, 'Ketika disuruhnya keluarga orang itu tampil ke muka, seorang demi seorang, maka didapatilah Akhan bin Karmi bin Zabdi bin Zerah, dari suku Yehuda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 19, 'Berkatalah Yosua kepada Akhan: "Anakku, hormatilah TUHAN, Allah Israel, dan mengakulah di hadapan-Nya; katakanlah kepadaku apa yang kauperbuat, jangan sembunyikan kepadaku."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 20, 'Lalu Akhan menjawab Yosua, katanya: "Benar, akulah yang berbuat dosa terhadap TUHAN, Allah Israel, sebab beginilah perbuatanku:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 21, 'aku melihat di antara barang-barang jarahan itu jubah yang indah, buatan Sinear, dan dua ratus syikal perak dan sebatang emas yang lima puluh syikal beratnya; aku mengingininya, maka kuambil; semuanya itu disembunyikan di dalam kemahku dalam tanah, dan perak itu di bawah sekali."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 22, 'Lalu Yosua menyuruh orang segera pergi ke kemah itu, dan sesungguhnya, semuanya itu disembunyikan dalam kemah Akhan, dan perak itu ada di bawah sekali.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 23, 'Maka mereka mengambil semuanya itu dari dalam kemah, lalu membawanya kepada Yosua dan kepada semua orang Israel, dan mencurahkannya di hadapan TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 24, 'Kemudian Yosua, beserta seluruh Israel mengambil Akhan bin Zerah, dan perak, jubah dan emas sebatang itu, anak-anaknya yang laki-laki dan perempuan, lembunya, keledainya dan kambing dombanya, kemahnya dan segala kepunyaannya, lalu semuanya itu dibawa ke lembah Akhor.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 25, 'Berkatalah Yosua: "Seperti engkau mencelakakan kami, maka TUHAN pun mencelakakan engkau pada hari ini." Lalu seluruh Israel melontari dia dengan batu, semuanya itu dibakar dengan api dan dilempari dengan batu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 7, 26, 'Sesudah itu didirikanlah di atasnya suatu timbunan batu yang besar, yang masih ada sampai sekarang. Lalu surutlah murka TUHAN yang bernyala-nyala itu. Oleh sebab itu nama tempat itu sampai sekarang disebutkan lembah Akhor.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 1, 'Kemudian berfirmanlah TUHAN kepada Yosua: "Janganlah takut dan janganlah tawar hati; bawalah seluruh tentara dan bersiaplah, majulah ke Ai. Ketahuilah, Aku serahkan kepadamu raja negeri Ai, rakyatnya, kotanya dan negerinya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 2, 'dan haruslah kaulakukan kepada Ai dan rajanya, seperti yang kaulakukan kepada Yerikho dan rajanya; hanya barang-barangnya dan ternaknya boleh kamu jarah. Suruhlah orang bersembunyi di belakang kota itu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 3, 'Lalu bersiaplah Yosua beserta seluruh tentara untuk pergi ke Ai. Yosua memilih tiga puluh ribu orang, pahlawan-pahlawan yang gagah perkasa, mereka disuruhnya pergi pada waktu malam', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 4, 'dan kepada mereka diperintahkannya, katanya: "Ketahuilah, kamu harus bersembunyi di belakang kota itu untuk menyerangnya, janganlah terlalu jauh dari kota itu, dan bersiap-siaplah kamu sekalian.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 5, 'Aku dan semua orang yang bersama-sama dengan aku akan mendekati kota itu; apabila mereka keluar menyerbu kami, seperti yang pertama kali, maka kami akan melarikan diri dari hadapan mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 6, 'Jadi mereka akan keluar menyusul kami, sehingga kami memancing mereka jauh dari kota itu, sebab mereka akan berkata: orang-orang itu melarikan diri dari hadapan kita seperti yang pertama kali. Jika kami melarikan diri dari hadapan mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 7, 'maka kamu harus bangun dari tempat persembunyianmu itu untuk menduduki kota itu, dan TUHAN, Allahmu, akan menyerahkannya ke dalam tanganmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 8, 'Segera setelah kamu merebut kota itu, haruslah kamu membakarnya; sesuai dengan firman TUHAN kamu harus melakukan semuanya itu; ingatlah, itulah perintahku kepadamu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 9, 'Demikianlah Yosua menyuruh mereka pergi, lalu berjalanlah mereka ke tempat persembunyian dan tinggal di antara Betel dan Ai, di sebelah barat Ai. Tetapi Yosua bermalam di tengah-tengah rakyat pada malam itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 10, 'Keesokan harinya Yosua bangun pagi-pagi, lalu diperiksanyalah barisan bangsa itu dan berjalanlah ia maju beserta para tua-tua orang Israel di depan bangsa itu ke Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 11, 'Juga seluruh tentara yang bersama-sama dengan dia berjalan maju; mereka maju mendekat, lalu sampai ke tentangan kota itu, kemudian berkemahlah mereka di sebelah utara Ai, sehingga lembah itu ada di antara mereka dan Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 12, 'Yosua telah mengambil kira-kira lima ribu orang, lalu disuruhnya mereka bersembunyi di antara Betel dan Ai, di sebelah barat kota itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 13, 'Beginilah rakyat itu diatur: seluruh tentara itu di sebelah utara kota dengan barisan belakang di sebelah barat kota. Pada malam itu berjalanlah Yosua melalui lembah itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 14, 'Pagi-pagi, ketika raja negeri Ai melihat hal itu, maka ia dan seluruh rakyatnya, orang-orang kota itu, segera keluar berperang, menyerbu orang Israel, ke lereng di seberang dataran itu; raja itu tidak tahu, bahwa ada orang bersembunyi di belakang kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 15, 'Yosua dan seluruh orang Israel itu berlaku seolah-olah dipukul mundur oleh mereka, lalu melarikan diri ke arah padang gurun.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 16, 'Sebab itu semua orang yang ada di kota dikerahkan untuk mengejar orang Israel. Maka mereka mengejar Yosua, sehingga makin jauhlah mereka terpancing dari kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 17, 'Seorangpun tidak tertinggal lagi di Ai dan Betel yang tidak keluar memburu orang Israel. Mereka meninggalkan kota itu terbuka, karena mereka mengejar orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 18, 'Lalu berfirmanlah TUHAN kepada Yosua: "Acungkanlah lembing yang ada di tanganmu ke arah Ai, sebab Aku menyerahkan kota itu ke dalam tanganmu." Maka Yosua mengacungkan lembing yang di tangannya ke arah kota itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 19, 'Ketika diacungkannya tangannya, maka segeralah bangun orang-orang yang bersembunyi itu dari tempatnya, mereka berlari memasuki kota, merebutnya, lalu segera membakar kota itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 20, 'Ketika orang Ai berpaling menoleh ke belakang, tampaklah asap kota itu naik membubung ke langit; mereka tidak sempat melarikan diri ke manapun juga, sebab rakyat yang tadinya lari ke padang gurun, berbalik melawan pengejar-pengejarnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 21, 'Ketika Yosua dan seluruh Israel melihat, bahwa orang-orang yang bersembunyi itu telah merebut kota dan bahwa asap kota itu naik membubung, berbaliklah mereka, lalu menewaskan orang-orang Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 22, 'Sementara itu juga keluar orang-orang Israel yang lain dari dalam kota menyerbu orang-orang Ai, sehingga terjepit di tengah-tengah orang Israel itu, yang ini dari sini dan yang itu dari sana; orang-orang Ai ditewaskan, sehingga seorangpun dari mereka tidak ada yang dibiarkan terlepas atau luput.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 23, 'Tetapi raja Ai ditangkap mereka hidup-hidup dan dihadapkan kepada Yosua.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 24, 'Segera sesudah orang Israel selesai membunuh seluruh penduduk kota Ai di padang terbuka ke mana orang Israel mengejar mereka, dan orang-orang ini semuanya tewas oleh mata pedang sampai orang yang penghabisan, maka seluruh Israel kembali ke Ai dan memukul kota itu dengan mata pedang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 25, 'Jumlah semua orang yang tewas pada hari itu, baik laki-laki maupun perempuan, ada dua belas ribu orang, semuanya orang Ai.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 26, 'Dan Yosua tidak menarik tangannya yang mengacungkan lembing itu, sebelum seluruh penduduk kota Ai ditumpasnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 27, 'Hanya ternak dan barang-barang kota itu dijarah oleh orang Israel, sesuai dengan firman TUHAN, yang diperintahkan-Nya kepada Yosua.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 28, 'Yosua membakar Ai dan membuatnya menjadi timbunan puing untuk selama-lamanya, menjadi tempat yang tandus sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 29, 'Dan raja Ai digantungnya pada sebuah tiang sampai petang. Ketika matahari terbenam, Yosua memerintahkan orang menurunkan mayat itu dari tiang, lalu dilemparkan di depan pintu gerbang kota, kemudian didirikan oranglah di atasnya suatu timbunan batu yang besar, yang masih ada sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 30, 'Pada waktu itulah Yosua mendirikan mezbah di gunung Ebal bagi TUHAN, Allah Israel,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 31, 'seperti yang diperintahkan Musa, hamba TUHAN, kepada orang Israel, menurut apa yang tertulis dalam kitab hukum Musa: suatu mezbah dari batu-batu yang tidak dipahat, yang tidak diolah dengan perkakas besi apapun. Di atasnyalah mereka mempersembahkan korban bakaran kepada TUHAN dan mengorbankan korban keselamatan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 32, 'Dan di sanalah di atas batu-batu itu, dituliskan Yosua salinan hukum Musa, yang dituliskannya di depan orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 33, 'Seluruh orang Israel, para tua-tuanya, para pengatur pasukannya dan para hakimnya berdiri sebelah-menyebelah tabut, berhadapan dengan para imam yang memang suku Lewi, para pengangkat tabut perjanjian TUHAN itu, baik pendatang maupun anak negeri, setengahnya menghadap ke gunung Gerizim dan setengahnya lagi menghadap ke gunung Ebal, seperti yang dahulu diperintahkan oleh Musa, hamba TUHAN, apabila orang memberkati bangsa Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 34, 'Sesudah itu dibacakannyalah segala perkataan hukum Taurat, berkatnya dan kutuknya, sesuai dengan segala apa yang tertulis dalam kitab hukum.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 8, 35, 'Tidak ada sepatah katapun dari segala apa yang diperintahkan Musa yang tidak dibacakan oleh Yosua kepada seluruh jemaah Israel dan kepada perempuan-perempuan dan anak-anak dan kepada pendatang yang ikut serta.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 1, 'Ketika terdengar oleh raja-raja di sebelah barat sungai Yordan, di Pegunungan, di Daerah Bukit dan sepanjang tepi pantai Laut Besar sampai ke seberang gunung Libanon, yakni raja-raja orang Het, orang Amori, orang Kanaan, orang Feris, orang Hewi dan orang Yebus,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 2, 'bergabunglah mereka dengan seia sekata untuk memerangi Yosua dan orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 3, 'Tetapi ketika terdengar kepada penduduk negeri Gibeon apa yang dilakukan Yosua terhadap Yerikho dan Ai,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 4, 'maka merekapun bertindak dengan memakai akal: mereka pergi menyediakan bekal, mengambil karung yang buruk-buruk untuk dimuatkan ke atas keledai mereka dan kirbat anggur yang buruk-buruk, yang robek dan dijahit kembali,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 5, 'dan kasut yang buruk-buruk dan ditambal untuk dikenakan pada kaki mereka dan pakaian yang buruk-buruk untuk dikenakan oleh mereka, sedang segala roti bekal mereka telah kering, tinggal remah-remah belaka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 6, 'Demikianlah mereka pergi kepada Yosua, ke tempat perkemahan di Gilgal. Berkatalah mereka kepadanya dan kepada orang-orang Israel itu: "Kami ini datang dari negeri jauh; maka sekarang ikatlah perjanjian dengan kami."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 7, 'Tetapi berkatalah orang-orang Israel kepada orang-orang Hewi itu: "Barangkali kamu ini diam di tengah-tengah kami, bagaimana mungkin kami mengikat perjanjian dengan kamu?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 8, 'Lalu kata mereka kepada Yosua: "Kami ini hamba-hambamu." Tanya Yosua: "Siapakah kamu ini dan dari manakah kamu datang?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 9, 'Jawab mereka kepadanya: "Dari negeri yang sangat jauh hamba-hambamu ini datang karena nama TUHAN, Allahmu, sebab kami telah mendengar kabar tentang Dia, yakni segala yang dilakukan-Nya di Mesir,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 10, 'dan segala yang dilakukan-Nya terhadap kedua raja orang Amori itu di seberang sungai Yordan, Sihon, raja Hesybon, dan Og, raja Basan, yang diam di Asytarot.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 11, 'Sebab itu para tua-tua kami dan seluruh penduduk negeri kami berkata kepada kami, demikian: Bawalah bekal untuk di jalan dan pergilah menemui mereka dan berkatalah kepada mereka: Kami ini hamba-hambamu, maka sekarang ikatlah perjanjian dengan kami.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 12, 'Inilah roti kami: masih panas ketika kami bawa sebagai bekal dari rumah pada hari kami berangkat berjalan mendapatkan kamu, tetapi sekarang, lihatlah, telah kering dan tinggal remah-remah belaka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 13, 'Inilah kirbat-kirbat anggur, yang masih baru ketika kami mengisinya, tetapi lihatlah, telah robek; dan inilah pakaian dan kasut kami, semuanya telah buruk-buruk karena perjalanan yang sangat jauh itu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 14, 'Lalu orang-orang Israel mengambil bekal orang-orang itu, tetapi tidak meminta keputusan TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 15, 'Maka Yosua mengadakan persahabatan dengan mereka dan mengikat perjanjian dengan mereka, bahwa ia akan membiarkan mereka hidup; dan para pemimpin umat itu bersumpah kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 16, 'Tetapi setelah lewat tiga hari, sesudah orang Israel mengikat perjanjian dengan orang-orang itu, terdengarlah oleh mereka, bahwa orang-orang itu tinggal dekat mereka, bahkan diam di tengah-tengah mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 17, 'Sebab orang Israel berangkat pergi dan pada hari ketiga sampai ke kota-kota orang-orang itu; adapun kota-kota itu ialah Gibeon, Kefira, Beerot dan Kiryat-Yearim.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 18, 'Orang Israel tidak menewaskan, sebab para pemimpin umat telah bersumpah kepada mereka demi TUHAN, Allah Israel. Lalu bersungut-sungutlah segenap umat kepada para pemimpin.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 19, 'Berkatalah pemimpin-pemimpin itu kepada seluruh umat: "Kami telah bersumpah kepada mereka demi TUHAN, Allah Israel; oleh sebab itu kita tidak dapat mengusik mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 20, 'Beginilah akan kita perlakukan mereka: membiarkan mereka hidup, supaya kita jangan tertimpa murka karena sumpah yang telah kita ikrarkan itu kepada mereka."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 21, 'Lagi kata para pemimpin kepada mereka: "Biarlah mereka hidup." Maka merekapun dijadikan tukang belah kayu dan tukang timba air untuk segenap umat, seperti yang ditetapkan oleh para pemimpin mengenai mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 22, 'Lalu Yosua memanggil mereka dan berkata kepada mereka, demikian: "Mengapa kamu menipu kami dengan berkata: Kami ini tinggal sangat jauh dari pada kamu, padahal kamu diam di tengah-tengah kami?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 23, 'Oleh sebab itu, terkutuklah kamu dan tak putus-putusnya kamu menjadi hamba, tukang belah kayu dan tukang timba air untuk rumah Allahku."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 24, 'Jawab mereka kepada Yosua, katanya: "Sebab telah dikabarkan dengan sungguh-sungguh kepada hamba-hambamu ini, bahwa TUHAN, Allahmu, memerintahkan kepada Musa hamba-Nya, memberikan seluruh negeri itu kepadamu dan memunahkan seluruh penduduk negeri itu dari depan kamu, maka sangatlah kami takut kehilangan nyawa, menghadapi kamu; itulah sebabnya kami melakukan yang demikian.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 25, 'Maka sekarang, kami ini dalam tanganmu; perlakukanlah kami seperti yang kaupandang baik dan benar untuk dilakukan kepada kami."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 26, 'Demikianlah dilakukannya kepada mereka. Dilepaskannyalah mereka dari tangan orang-orang Israel, sehingga mereka tidak dibunuh.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 9, 27, 'Dan pada waktu itu Yosua menjadikan mereka tukang belah kayu dan tukang timba air untuk umat itu dan untuk mezbah TUHAN, sampai sekarang, di tempat yang akan dipilih-Nya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 1, 'Setelah terdengar oleh Adoni-Zedek, raja Yerusalem, bahwa Yosua telah merebut Ai dan telah menumpasnya?seperti yang dilakukannya terhadap Yerikho dan terhadap rajanya, demikianlah juga dilakukannya terhadap Ai dan terhadap rajanya?dan bahwa penduduk kota Gibeon telah mengadakan ikatan persahabatan dengan orang Israel dan diam di tengah-tengah mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 2, 'maka sangat takutlah orang, sebab Gibeon itu kota yang besar, seperti salah satu kota kerajaan, bahkan lebih besar dari Ai, dan semua orangnya adalah pahlawan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 3, 'Sebab itu Adoni-Zedek, raja Yerusalem, menyuruh orang kepada Hoham, raja Hebron, kepada Piream, raja Yarmut, kepada Yafia, raja Lakhis, dan kepada Debir, raja Eglon, mengatakan:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 4, '"Datanglah kepadaku dan bantulah aku, supaya kita menggempur Gibeon, karena telah mengadakan ikatan persahabatan dengan Yosua dan orang Israel."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 5, 'Lalu kelima raja orang Amori itu berkumpul dan bergerak maju: raja Yerusalem, raja Hebron, raja Yarmut, raja Lakhis dan raja Eglon, mereka beserta seluruh tentara mereka. Mereka berkemah mengepung Gibeon dan berperang melawannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 6, 'Lalu orang-orang Gibeon itu menyuruh orang kepada Yosua, ke tempat perkemahan di Gilgal, mengatakan: "Jangan menarik tanganmu dari pada hamba-hambamu ini. Datanglah dengan segera kepada kami, lepaskanlah kami dan bantulah kami, sebab semua raja orang Amori, yang diam di pegunungan, telah bergabung melawan kami."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 7, 'Lalu Yosua bergerak maju dari Gilgal, dia dan seluruh tentara yang bersama-sama dengan dia, semuanya pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 8, 'Berfirmanlah TUHAN kepada Yosua: "Janganlah takut kepada mereka, sebab Aku menyerahkan mereka kepadamu. Tidak seorangpun dari mereka yang akan dapat bertahan menghadapi engkau."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 9, 'Lalu Yosua menyerang mereka dengan tiba-tiba, setelah semalam-malaman bergerak maju dari Gilgal.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 10, 'Dan TUHAN mengacaukan mereka di depan orang Israel, sehingga Yosua menimbulkan kekalahan yang besar di antara mereka dekat Gibeon, mengejar mereka ke arah pendakian Bet-Horon dan memukul mereka mundur sampai dekat Azeka dan Makeda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 11, 'Sedang mereka melarikan diri di depan orang Israel dan baru di lereng Bet-Horon, maka TUHAN melempari mereka dengan batu-batu besar dari langit, sampai ke Azeka, sehingga mereka mati. Yang mati kena hujan batu itu ada lebih banyak dari yang dibunuh oleh orang Israel dengan pedang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 12, 'Lalu Yosua berbicara kepada TUHAN pada hari TUHAN menyerahkan orang Amori itu kepada orang Israel; ia berkata di hadapan orang Israel: "Matahari, berhentilah di atas Gibeon dan engkau, bulan, di atas lembah Ayalon!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 13, 'Maka berhentilah matahari dan bulanpun tidak bergerak, sampai bangsa itu membalaskan dendamnya kepada musuhnya. Bukankah hal itu telah tertulis dalam Kitab Orang Jujur? Matahari tidak bergerak di tengah langit dan lambat-lambat terbenam kira-kira sehari penuh.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 14, 'Belum pernah ada hari seperti itu, baik dahulu maupun kemudian, bahwa TUHAN mendengarkan permohonan seorang manusia secara demikian, sebab yang berperang untuk orang Israel ialah TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 15, 'Kemudian Yosua dan seluruh orang Israel yang menyertainya pulang kembali ke tempat perkemahan di Gilgal.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 16, 'Kelima raja itu melarikan diri dan bersembunyi di dalam gua di Makeda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 17, 'Kepada Yosua dikabarkan, demikian: "Kelima raja itu telah ditemukan bersembunyi di dalam gua di Makeda."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 18, 'Lalu berkatalah Yosua: "Gulingkanlah batu-batu yang besar ke mulut gua itu dan tempatkanlah di sana orang untuk menjaga mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 19, 'Tetapi kamu, janganlah kamu berhenti, kejarlah musuhmu dan hantamlah barisan belakangnya; janganlah biarkan mereka masuk ke dalam kota-kota mereka, sebab TUHAN, Allahmu, menyerahkan mereka kepadamu!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 20, 'Setelah Yosua dan orang Israel selesai menimbulkan kekalahan yang besar sekali di antara mereka, sampai mereka dihancurkan sama sekali?beberapa orang dari mereka dapat lolos dan masuk ke kota-kota yang diperkuat?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 21, 'pulanglah seluruh bangsa itu dengan selamat kepada Yosua ke tempat perkemahan, di Makeda. Tidak ada seorangpun yang berani melemparkan kata-kata ancaman terhadap orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 22, 'Kemudian berkatalah Yosua: "Bukalah mulut gua dan keluarkanlah kelima raja itu dari dalam dan bawa kepadaku."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 23, 'Dilakukan oranglah demikian, kelima raja itu dikeluarkan dari gua itu dan dibawa kepadanya: raja Yerusalem, raja Hebron, raja Yarmut, raja Lakhis dan raja Eglon.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 24, 'Setelah raja-raja itu dikeluarkan dan dibawa kepada Yosua, maka Yosuapun memanggil semua orang Israel berkumpul dan berkata kepada para panglima tentara, yang ikut berperang bersama-sama dengan dia: "Marilah dekat, taruhlah kakimu ke atas tengkuk raja-raja ini." Maka datanglah mereka dekat dan menaruh kakinya ke atas tengkuk raja-raja itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 25, 'Lalu berkatalah Yosua kepada mereka: "Janganlah takut dan janganlah tawar hati, kuatkan dan teguhkanlah hatimu, sebab secara itulah akan dilakukan TUHAN kepada semua musuhmu, yang kamu perangi."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 26, 'Sesudah itu Yosua membunuh raja-raja itu, dan menggantung mereka pada lima tiang, dan mereka tinggal tergantung pada tiang-tiang itu sampai matahari terbenam.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 27, 'Tetapi menjelang matahari terbenam, atas perintah Yosua mayat mereka diturunkan dari tiang-tiang itu, dan dilemparkan ke dalam gua, tempat mereka bersembunyi. Lalu mulut gua itu ditutupi orang dengan batu-batu besar, yang masih ada sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 28, 'Pada hari itu Yosua merebut Makeda dan kota itu dipukulnya dengan mata pedang, juga rajanya; kota itu dan semua makhluk yang ada di dalamnya ditumpasnya, tidak ada seorangpun yang dibiarkannya lolos, dan raja Makeda, diperlakukannya seperti telah diperlakukannya raja Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 29, 'Kemudian Yosua dengan seluruh Israel berjalan terus dari Makeda ke Libna, lalu memerangi Libna.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 30, 'Dan TUHAN menyerahkan kota itu juga kepada orang Israel, beserta rajanya. Yosua memukul kota itu dan semua makhluk yang ada di dalamnya dengan mata pedang, tidak ada seorangpun di dalamnya yang dibiarkannya lolos, dan rajanya itu, diperlakukannya seperti telah diperlakukannya raja Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 31, 'Kemudian Yosua dengan seluruh Israel berjalan terus dari Libna ke Lakhis, lalu berkemah mengepung kota itu dan berperang melawannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 32, 'Dan TUHAN menyerahkan Lakhis kepada orang Israel. Yosua merebut kota itu pada hari yang kedua. Kota itu dan semua makhluk yang ada di dalamnya dipukulnya dengan mata pedang, tepat seperti yang dilakukannya terhadap Libna.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 33, 'Lalu Horam, raja Gezer, maju untuk membantu Lakhis, tetapi Yosua menewaskan dia dan rakyatnya, sehingga tidak ada seorangpun padanya yang dibiarkannya lolos.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 34, 'Kemudian Yosua dengan seluruh Israel berjalan terus dari Lakhis ke Eglon, lalu mereka berkemah mengepung kota itu dan berperang melawannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 35, 'Kota itu direbut mereka pada hari itu juga dan dipukul dengan mata pedang. Semua makhluk yang ada di dalamnya ditumpasnya pada hari itu, tepat seperti yang dilakukan terhadap Lakhis.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 36, 'Kemudian Yosua dengan seluruh Israel bergerak maju dari Eglon ke Hebron, lalu berperang melawannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 37, 'Negeri itu direbut mereka dan dipukul dengan mata pedang, juga rajanya dan segala kotanya dan semua makhluk yang ada di dalamnya, tidak seorangpun yang dibiarkannya lolos, tepat seperti yang dilakukannya terhadap Eglon. Kota itu dan semua makhluk yang ada di dalamnya ditumpasnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 38, 'Kemudian Yosua dengan seluruh Israel kembali ke Debir, lalu berperang melawannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 39, 'Negeri itu beserta rajanya dan segala kotanya direbutnya, dan dipukul dengan mata pedang. Semua makhluk yang ada di dalamnya ditumpas mereka, tidak seorangpun yang dibiarkannya lolos; seperti yang dilakukannya terhadap Hebron, demikianlah dilakukan terhadap Debir beserta rajanya, sama seperti yang dilakukannya terhadap Libna beserta rajanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 40, 'Demikianlah Yosua mengalahkan seluruh negeri itu, Pegunungan, Tanah Negeb, Daerah Bukit dan Lereng Gunung, beserta semua raja mereka. Tidak seorangpun yang dibiarkannya lolos, tetapi ditumpasnya semua yang bernafas, seperti yang diperintahkan TUHAN, Allah Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 41, 'Yosua menewaskan mereka dari Kadesh-Barnea sampai Gaza, juga seluruh tanah Gosyen sampai Gibeon.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 42, 'Semua raja ini dan negeri mereka telah dikalahkan Yosua sekaligus, sebab yang berperang untuk orang Israel ialah TUHAN, Allah Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 10, 43, 'Kemudian Yosua dengan seluruh Israel pulang kembali ke tempat perkemahan di Gilgal.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 1, 'Setelah hal itu terdengar kepada Yabin, raja Hazor, diutusnyalah orang kepada Yobab, raja Madon, dan kepada raja negeri Simron, kepada raja negeri Akhsaf,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 2, 'serta kepada raja-raja yang di sebelah utara, di Pegunungan, di Araba-Yordan di sebelah selatan Kinerot, di Daerah Bukit dan di tanah bukit Dor di sebelah barat,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 3, 'yakni raja-raja orang Kanaan di sebelah timur dan di sebelah barat, orang Amori, orang Het, orang Feris, orang Yebus di pegunungan dan orang Hewi di kaki gunung Hermon, di tanah Mizpa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 4, 'Kemudian keluarlah raja-raja ini bersama-sama semua tentaranya, amat banyak rakyat, seperti pasir di tepi laut banyaknya, beserta sangat banyak kuda dan kereta.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 5, 'Raja-raja ini bersekutu dan datang berkemah bersama-sama dekat mata air Merom untuk memerangi orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 6, 'Lalu TUHAN berkata kepada Yosua: "Janganlah takut menghadapi mereka, sebab besok kira-kira waktu ini Aku menyerahkan mereka mati terbunuh semuanya kepada orang Israel. Kuda mereka haruslah kamu lumpuhkan dan kereta mereka haruslah kamu bakar dengan api."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 7, 'Lalu Yosua dengan seluruh tentaranya mendatangi mereka dengan tiba-tiba dekat mata air Merom, dan menyerbu mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 8, 'Dan TUHAN menyerahkan mereka kepada orang Israel. Mereka dikalahkan dan dikejar sampai Sidon-Besar dan sampai Misrefot-Maim, dan sampai lembah Mizpa yang di sebelah timur. Demikianlah mereka dihancurkan, sehingga tidak seorangpun dari mereka yang dibiarkan lolos.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 9, 'Yosua melakukan terhadap mereka seperti yang difirmankan TUHAN kepadanya: kuda mereka dilumpuhkan dan kereta mereka dibakar dengan api.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 10, 'Pada waktu itu Yosua kembali, direbutnya Hazor, dan rajanya dibunuhnya dengan mata pedang. Sebab Hazor pada waktu dahulu adalah yang terutama di antara segala kerajaan itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 11, 'Semua makhluk yang ada di dalamnya dibunuhnya dengan mata pedang, sambil menumpas orang-orang itu. Tidak ada yang tinggal hidup dari semua yang bernafas dan Hazor dibakarnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 12, 'Selanjutnya segala kota kepunyaan raja-raja itu dan semua rajanya dikalahkan Yosua dan dibunuhnya dengan mata pedang. Mereka ditumpasnya seperti yang diperintahkan Musa, hamba TUHAN itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 13, 'Tetapi kota-kota yang letaknya di atas bukit-bukit puing tidaklah dibakar oleh orang Israel, hanya Hazor saja yang dibakar oleh Yosua.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 14, 'Segala barang dari kota-kota itu serta ternaknya telah dijarah orang Israel. Tetapi manusia semuanya dibunuh mereka dengan mata pedang, sehingga orang-orang itu dipunahkan mereka. Tidak ada yang ditinggalkan hidup dari semua yang bernafas.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 15, 'Seperti yang diperintahkan TUHAN kepada Musa, hamba-Nya itu, demikianlah diperintahkan Musa kepada Yosua dan seperti itulah dilakukan Yosua: tidak ada sesuatu yang diabaikannya dari segala yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 16, 'Demikianlah Yosua merebut seluruh negeri itu, pegunungan, seluruh Tanah Negeb, seluruh tanah Gosyen, Daerah Bukit, serta Araba-Yordan, dan Pegunungan Israel dengan tanah rendahnya;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 17, 'mulai dari Pegunungan Gundul, yang mendaki ke arah Seir, sampai ke Baal-Gad di lembah gunung Libanon, di kaki gunung Hermon. Semua rajanya ditangkapnya, dan dibunuhnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 18, 'Lama Yosua melakukan perang melawan semua raja itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 19, 'Tidak ada satu kotapun yang mengadakan ikatan persahabatan dengan orang Israel, selain dari pada orang Hewi yang diam di Gibeon itu, semuanya telah direbut mereka dengan berperang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 20, 'Karena TUHAN yang menyebabkan hati orang-orang itu menjadi keras, sehingga mereka berperang melawan orang Israel, supaya mereka ditumpas, dan jangan dikasihani, tetapi dipunahkan, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 21, 'Pada waktu itu Yosua datang dan melenyapkan orang Enak dari pegunungan, dari Hebron, Debir dan Anab, dari seluruh pegunungan Yehuda dan dari seluruh pegunungan Israel. Mereka dan kota-kota mereka ditumpas oleh Yosua.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 22, 'Tidak ada lagi orang Enak ditinggalkan hidup di negeri orang Israel; hanya di Gaza, di Gat dan di Asdod masih ada yang tertinggal.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 11, 23, 'Demikianlah Yosua merebut seluruh negeri itu sesuai dengan segala yang difirmankan TUHAN kepada Musa. Dan Yosuapun memberikan negeri itu kepada orang Israel menjadi milik pusaka mereka, menurut pembagian suku mereka. Lalu amanlah negeri itu, berhenti dari berperang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 1, 'Inilah raja-raja negeri yang dikalahkan oleh orang Israel dan yang negerinya diduduki mereka di seberang Yordan ke arah matahari terbit, dari sungai Arnon sampai gunung Hermon, serta seluruh Araba-Yordan ke arah timur:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 2, 'yakni Sihon, raja orang Amori, yang diam di Hesybon, yang memerintah atas suatu daerah dari Aroer, yang letaknya di tepi sungai Arnon, pada pertengahan sungai itu, ditambah setengah Gilead, sampai sungai Yabok, batas daerah bani Amon,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 3, 'dan atas Araba-Yordan sampai sebelah timur danau Kinerot dan sampai sebelah timur Laut Araba, yakni Laut Asin, ke arah Bet-Yesimot dan ke arah selatan sampai kaki lereng-lereng gunung Pisga.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 4, 'Selanjutnya daerah Og, raja Basan, seorang dari sisa-sisa orang Refaim. Raja ini diam di Asytarot dan di Edrei,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 5, 'dan memerintah atas gunung Hermon, atas Salkha dan atas seluruh Basan sampai daerah orang Gesur dan orang Maakha dan atas setengah Gilead, sampai daerah Sihon, raja Hesybon.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 6, 'Musa, hamba TUHAN itu, beserta orang Israel, telah mengalahkan mereka, dan Musa, hamba TUHAN itu, telah memberikan daerah itu kepada orang Ruben, orang Gad dan suku Manasye yang setengah itu, menjadi milik mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 7, 'Inilah raja negeri yang dikalahkan oleh Yosua dan oleh orang Israel di sebelah barat sungai Yordan, dari Baal-Gad di lembah gunung Libanon sampai Pegunungan Gundul, yang mendaki ke arah Seir?negeri ini diberikan Yosua kepada suku-suku Israel menjadi miliknya, menurut pembagiannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 8, 'di Pegunungan, di Daerah Bukit, di Araba-Yordan, di Lereng Gunung, di Padang Gurun dan di Tanah Negeb, yakni di negeri orang Het, orang Amori, orang Kanaan, orang Feris, orang Hewi dan orang Yebus?:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 9, 'Raja negeri Yerikho, satu; raja negeri Ai, di sebelah Betel, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 10, 'raja negeri Yerusalem, satu; raja negeri Hebron, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 11, 'raja negeri Yarmut, satu; raja negeri Lakhis, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 12, 'raja negeri Eglon, satu; raja negeri Gezer, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 13, 'raja negeri Debir, satu; raja negeri Geder, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 14, 'raja negeri Horma, satu; raja negeri Arad, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 15, 'raja negeri Libna, satu; raja negeri Adulam, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 16, 'raja negeri Makeda, satu; raja negeri Betel, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 17, 'raja negeri Tapuah, satu; raja negeri Hefer, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 18, 'raja negeri Afek, satu; raja negeri Lasaron, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 19, 'raja negeri Madon, satu; raja negeri Hazor, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 20, 'raja negeri Simron Meron, satu; raja negeri Akhsaf, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 21, 'raja negeri Taanakh, satu; raja negeri Megido, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 22, 'raja negeri Kedesh, satu; raja negeri Yokneam di dekat gunung Karmel, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 23, 'raja negeri Dor di tanah bukit Dor, satu; raja negeri Goyim di Galilea, satu;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 12, 24, 'raja negeri Tirza, satu; jadi jumlah semua raja itu, tiga puluh satu orang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 1, 'Setelah Yosua menjadi tua dan lanjut umurnya, berfirmanlah TUHAN kepadanya: "Engkau telah tua dan lanjut umur, dan dari negeri ini masih amat banyak yang belum diduduki.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 2, 'Inilah negeri yang tertinggal: segenap wilayah orang Filistin dan seluruh negeri orang Gesur,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 3, 'mulai dari sungai Sikhor di sebelah timur Mesir sampai ke daerah Ekron ke arah utara?semuanya itu terhitung tanah orang Kanaan?;ada lima raja kota orang Filistin, yakni di Gaza, di Asdod, di Askelon, di Gat dan di Ekron?;dan orang Awi', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 4, 'di sebelah selatan; seluruh negeri orang Kanaan dan Meara, kepunyaan orang Sidon, sampai ke Afek, sampai ke daerah orang Amori;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 5, 'selanjutnya negeri orang Gebal dan seluruh gunung Libanon di sebelah matahari terbit, mulai dari Baal-Gad di kaki gunung Hermon sampai ke jalan yang menuju ke Hamat;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 6, 'semua orang yang diam di pegunungan, mulai dari gunung Libanon sampai ke Misrefot-Maim; semua orang Sidon. Aku sendiri akan menghalau mereka dari depan orang Israel; hanya undikanlah dahulu negeri itu di antara orang Israel menjadi milik pusaka mereka, seperti yang Kuperintahkan kepadamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 7, 'Oleh sebab itu, bagikanlah negeri ini kepada suku yang sembilan itu dan kepada suku Manasye yang setengah itu menjadi milik pusaka mereka."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 8, 'Bersama-sama dengan suku Manasye yang setengah lagi, orang Ruben dan orang Gad telah menerima milik pusaka mereka, yang telah diberikan Musa kepada mereka di sebelah timur sungai Yordan, seperti yang ditentukan Musa, hamba TUHAN itu, kepada mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 9, 'yakni mulai dari Aroer, yang di tepi sungai Arnon, kota pada pertengahan sungai itu, dan seluruh dataran tinggi, dari Medeba sampai ke Dibon;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 10, 'dan segala kota Sihon, raja orang Amori, yang berkerajaan di Hesybon, sampai ke daerah orang Amon;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 11, 'selanjutnya Gilead dan daerah orang Gesur dan orang Maakha, serta seluruh gunung Hermon dan seluruh tanah Basan sampai ke Salkha,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 12, 'seluruh kerajaan Og di Basan, yang memerintah di Asytarot dan Edrei, dialah yang tinggal hidup dari sisa-sisa orang Refaim yang telah dikalahkan dan dihalau oleh Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 13, 'Tetapi orang Israel tidak menghalau orang Gesur dan orang Maakha itu, sehingga Gesur dan Maakha masih tetap diam di tengah-tengah Israel sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 14, 'Hanya kepada suku Lewi tidak diberikan milik pusaka: yang menjadi milik pusakanya ialah TUHAN, Allah Israel, seperti yang dijanjikan-Nya kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 15, 'Kepada suku bani Ruben, menurut kaum-kaum mereka, telah diberikan Musa bagian ini:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 16, 'daerah kepunyaan mereka mulai dari Aroer yang di tepi sungai Arnon, kota pada pertengahan sungai itu, dan seluruh dataran tinggi dekat Medeba;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 17, 'Hesybon dan segala kotanya, yang di dataran tinggi, yakni Dibon, Bamot-Baal, Bet-Baal-Meon,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 18, 'Yahas, Kedemot, Mefaat,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 19, 'Kiryataim, Sibma, Zeret-Hasahar di atas gunung di lembah itu,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 20, 'Bet-Peor, lereng-lereng gunung Pisga, Bet-Yesimot,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 21, 'selanjutnya segala kota di dataran tinggi itu dan seluruh kerajaan Sihon, raja orang Amori, yang memerintah di Hesybon, yang dikalahkan oleh Musa; bersama-sama dia juga dikalahkannya raja-raja Midian, yakni Ewi, Rekem, Zur, Hur dan Reba, raja-raja bawahan Sihon, penduduk negeri itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 22, 'Juga Bileam bin Beor, juru tenung itu, telah dibunuh oleh orang Israel dengan pedang, beserta orang-orang yang telah mati tertikam oleh mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 23, 'Jadi batas daerah bani Ruben ialah sungai Yordan dengan daerah pinggirnya. Itulah milik pusaka bani Ruben menurut kaum-kaum mereka, yakni kota-kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 24, 'Kepada suku Gad, yakni kepada bani Gad menurut kaum-kaum mereka, telah diberikan Musa bagian ini:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 25, 'daerah kepunyaan mereka ialah Yaezer dan segala kota negeri Gilead, serta setengah negeri orang Amon sampai ke Aroer, yang di sebelah timur Raba,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 26, 'yakni mulai dari Hesybon sampai ke Ramat-Mizpa dan Betonim, dan dari Mahanaim sampai ke daerah Debir;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 27, 'dan di lembah: Bet-Haram, Bet-Nimra, Sukot dan Zafon, sisa kerajaan Sihon, raja Hesybon; sungai Yordan dengan daerah pinggirnya, sampai ke ujung danau Kineret, di sebelah timur sungai Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 28, 'Itulah milik pusaka bani Gad menurut kaum-kaum mereka, yakni kota-kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 29, 'Kepada suku Manasye yang setengah itu, yakni kepada puak bani Manasye yang setengah itu, menurut kaum-kaum mereka, telah diberikan Musa bagian ini:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 30, 'daerah mereka mulai dari Mahanaim: seluruh Basan, seluruh kerajaan Og, raja Basan, dan segenap Hawot-Yair, yang di Basan itu, enam puluh kota banyaknya;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 31, 'selanjutnya setengah Gilead, Asytarot dan Edrei, kota-kota kerajaan Og di Basan, menjadi bagian bani Makhir, anak Manasye, yaitu bagian setengah bani Makhir menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 32, 'Itulah semuanya yang dibagikan Musa sebagai milik pusaka di dataran Moab di sebelah timur sungai Yordan dekat Yerikho.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 13, 33, 'Tetapi kepada suku Lewi Musa tidak memberikan milik pusaka: TUHAN, Allah Israel, Dialah yang menjadi milik pusaka mereka, seperti yang dijanjikan-Nya kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 1, 'Inilah semuanya yang diterima oleh orang Israel sebagai milik pusaka di tanah Kanaan, yang telah dibagikan kepada orang Israel oleh imam Eleazar, dan Yosua bin Nun dan para kepala kaum keluarga dari suku-suku mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 2, 'dengan mengundi milik pusaka itu, seperti yang diperintahkan TUHAN dengan perantaraan Musa mengenai suku-suku yang sembilan setengah itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 3, 'Sebab kepada suku-suku yang dua setengah lagi telah diberikan Musa milik pusaka di seberang sungai Yordan, tetapi kepada orang Lewi tidak diberikannya milik pusaka di tengah-tengah mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 4, 'Sebab bani Yusuf merupakan dua suku, Manasye dan Efraim. Maka kepada orang Lewi tidak diberikan bagiannya di negeri itu, selain dari kota-kota untuk didiami, dengan tanah penggembalaannya untuk ternak dan hewan mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 5, 'Seperti yang diperintahkan TUHAN kepada Musa, demikianlah diperbuat oleh orang Israel dan dibagi-bagi merekalah negeri itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 6, 'Bani Yehuda datang menghadap Yosua di Gilgal. Pada waktu itu berkatalah Kaleb bin Yefune, orang Kenas itu, kepadanya: "Engkau tahu firman yang diucapkan TUHAN kepada Musa, abdi Allah itu, tentang aku dan tentang engkau di Kadesh-Barnea.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 7, 'Aku berumur empat puluh tahun, ketika aku disuruh Musa, hamba TUHAN itu, dari Kadesh-Barnea untuk mengintai negeri ini; dan aku pulang membawa kabar kepadanya yang sejujur-jujurnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 8, 'Sedang saudara-saudaraku, yang bersama-sama pergi ke sana dengan aku, membuat tawar hati bangsa itu, aku tetap mengikuti TUHAN, Allahku, dengan sepenuh hati.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 9, 'Pada waktu itu Musa bersumpah, katanya: Sesungguhnya tanah yang diinjak oleh kakimu itu akan menjadi milik pusakamu dan anak-anakmu sampai selama-lamanya, sebab engkau tetap mengikuti TUHAN, Allahku, dengan sepenuh hati.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 10, 'Jadi sekarang, sesungguhnya TUHAN telah memelihara hidupku, seperti yang dijanjikan-Nya. Kini sudah empat puluh lima tahun lamanya, sejak diucapkan TUHAN firman itu kepada Musa, dan selama itu orang Israel mengembara di padang gurun. Jadi sekarang, telah berumur delapan puluh lima tahun aku hari ini;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 11, 'pada waktu ini aku masih sama kuat seperti pada waktu aku disuruh Musa; seperti kekuatanku pada waktu itu demikianlah kekuatanku sekarang untuk berperang dan untuk keluar masuk.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 12, 'Oleh sebab itu, berikanlah kepadaku pegunungan, yang dijanjikan TUHAN pada waktu itu, sebab engkau sendiri mendengar pada waktu itu, bahwa di sana ada orang Enak dengan kota-kota yang besar dan berkubu. Mungkin TUHAN menyertai aku, sehingga aku menghalau mereka, seperti yang difirmankan TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 13, 'Lalu Yosua memberkati Kaleb bin Yefune, dan diberikannyalah Hebron kepadanya menjadi milik pusakanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 14, 'Itulah sebabnya Hebron menjadi milik pusaka Kaleb bin Yefune, orang Kenas itu, sampai sekarang ini, karena ia tetap mengikuti TUHAN, Allah Israel, dengan sepenuh hati.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 14, 15, 'Nama Hebron dahulu ialah Kiryat-Arba; Arba ialah orang yang paling besar di antara orang Enak. Dan amanlah negeri itu, berhenti berperang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 1, 'Bagian yang diundikan kepada suku bani Yehuda menurut kaum-kaum mereka adalah sampai ke batas tanah Edom, sampai ke padang gurun Zin ke selatan, di ujung selatan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 2, 'Batas selatan bagi mereka mulai dari ujung Laut Asin, dari teluk yang menghadap ke selatan;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 3, 'lalu keluar pada sebelah selatan pendakian Akrabim, terus ke Zin, naik ke sebelah selatan Kadesh-Barnea, terus ke Hezron, naik ke Adar, membelok ke Karka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 4, 'terus ke Azmon dan keluar pada sungai tanah Mesir, sehingga batas itu berakhir ke laut. Itulah bagi kamu batas selatan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 5, 'Batas timur ialah Laut Asin sampai ke muara sungai Yordan. Batas pada sisi utara mulai dari teluk di muara sungai Yordan itu:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 6, 'batas itu naik ke Bet-Hogla, melalui sebelah utara Bet-Araba, kemudian batas itu naik ke batu Bohan bin Ruben;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 7, 'lalu dari lembah Akhor batas itu naik ke Debir, dan menuju ke utara ke Gilgal di seberang pendakian Adumim, yang di sebelah selatan sungai. Kemudian batas itu terus ke mata air En-Semes dan keluar ke En-Rogel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 8, 'Kemudian batas itu naik ke lembah Ben-Hinom, di sebelah selatan sepanjang lereng gunung Yebus, itulah Yerusalem; kemudian batas itu naik ke puncak gunung yang di seberang lembah Hinom, di sebelah barat, di ujung utara lembah orang Refaim.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 9, 'Kemudian batas itu melengkung dari puncak gunung itu ke mata air Me-Neftoah, lalu keluar ke kota-kota pegunungan Efron; selanjutnya batas itu melengkung ke Baala, itulah Kiryat-Yearim.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 10, 'Kemudian batas itu membelok dari Baala ke barat ke pegunungan Seir, terus ke utara ke lereng gunung Yearim, itulah Kesalon, turun ke Bet-Semes dan terus ke Timna.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 11, 'Kemudian batas itu keluar ke utara ke lereng gunung Ekron; kemudian batas itu melengkung ke Sikron, terus ke gunung Baala dan keluar dekat Yabneel, sehingga batas itu berakhir di laut.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 12, 'Batas barat ialah Laut Besar dan pantainya. Itulah, ke segala penjuru, batas-batas daerah bani Yehuda menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 13, 'Tetapi kepada Kaleb bin Yefune diberikan Yosua sebagian di tengah-tengah bani Yehuda itu, yakni Kiryat-Arba, seperti yang dititahkan TUHAN kepadanya; Arba ialah bapa Enak. Itulah Hebron.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 14, 'Dan Kaleb menghalau dari sana ketiga orang Enak, yakni Sesai, Ahiman dan Talmai, anak-anak Enak.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 15, 'Dari sana ia maju menyerang penduduk Debir. Nama Debir itu dahulu ialah Kiryat-Sefer.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 16, 'Lalu berkatalah Kaleb: "Siapa yang menggempur Kiryat-Sefer dan merebutnya, kepadanya akan kuberikan Akhsa, anakku, menjadi isterinya."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 17, 'Dan Otniel, anak Kenas saudara Kaleb, merebut kota itu; lalu Kaleb memberikan kepadanya Akhsa, anaknya, menjadi isterinya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 18, 'Ketika perempuan itu tiba, dibujuknya suaminya untuk meminta ladang kepada ayahnya. Maka turunlah perempuan itu dari keledainya, lalu berkatalah Kaleb kepadanya: "Ada apa?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 19, 'Jawabnya: "Berikanlah kepadaku hadiah; telah kauberikan kepadaku tanah yang gersang, berikanlah juga kepadaku mata air." Lalu diberikannyalah kepadanya mata air yang di hulu dan mata air yang di hilir.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 20, 'Inilah milik pusaka suku bani Yehuda menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 21, 'Kota-kota suku bani Yehuda yang paling ujung, dekat batas tanah Edom di Tanah Negeb, ialah Kabzeel, Eder, Yagur,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 22, 'Kina, Dimona, Adada,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 23, 'Kedesh, Hazor, Yitnan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 24, 'Zif, Telem, Bealot,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 25, 'Hazor-Hadata, Keriot-Hezron, itulah Hazor;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 26, 'Amam, Sema, Molada,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 27, 'Hazar-Gada, Hesmon, Bet-Pelet,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 28, 'Hazar-Sual, Bersyeba dan segala anak kotanya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 29, 'Baala, Iyim, Ezem,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 30, 'Eltolad, Kesil, Horma,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 31, 'Ziklag, Madmana, Sansana,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 32, 'Lebaot, Silhim, Ain dan Rimon; seluruhnya dua puluh sembilan kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 33, 'Di Daerah Bukit: Esytaol, Zora, Asna,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 34, 'Zanoah, En-Ganim, Tapuah, Enam,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 35, 'Yarmut, Adulam, Sokho, Azeka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 36, 'Saaraim, Aditaim, Gedera dan Gederotaim; empat belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 37, 'Zenan, Hadasa, Migdal-Gad,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 38, 'Dilean, Mizpa, Yokteel,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 39, 'Lakhis, Bozkat, Eglon,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 40, 'Kabon, Lahmas, Kitlis,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 41, 'Gederot, Bet-Dagon, Naama dan Makeda; enam belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 42, 'Libna, Eter, Asan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 43, 'Yiftah, Asna, Nezib,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 44, 'Kehila, Akhzib dan Maresa; sembilan kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 45, 'Ekron dengan segala anak kota dan desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 46, 'Mulai dari Ekron sampai ke laut, segala yang di sisi Asdod dan desa-desanya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 47, 'Asdod dengan segala anak kota dan desa-desanya, Gaza dengan segala anak kota dan desa-desanya, sampai ke sungai tanah Mesir, Laut Besar dan pantainya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 48, 'Lagi di Pegunungan: Samir, Yatir, Sokho,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 49, 'Dana, Kiryat-Sana, itulah Debir;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 50, 'Anab, Estemo, Anim,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 51, 'Gosyen, Holon dan Gilo; sebelas kota dengan desa-desanya;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 52, 'Arab, Duma, Esan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 53, 'Yanum, Bet-Tapuah, Afeka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 54, 'Humta, Kiryat-Arba, itulah Hebron, dan Zior; sembilan kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 55, 'Maon, Karmel, Zif, Yuta,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 56, 'Yizreel, Yokdeam, Zanoah,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 57, 'Kain, Gibea dan Timna; sepuluh kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 58, 'Halhul, Bet-Zur, Gedor,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 59, 'Maarat, Bet-Anot dan Eltekon; enam kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 15, 60, 'Kiryat-Baal, itulah Kiryat-Yearim, dan Raba; dua kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 1, 'Kemudian keluarlah undian bagi bani Yusuf. Batas mereka mulai dari sungai Yordan dekat Yerikho, di sebelah timur mata-mata air Yerikho, melalui padang gurun, yang naik dari Yerikho ke pegunungan, ke Betel,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 2, 'keluar dari Betel menuju ke Lus, terus ke daerah orang Arki, ke Atarot,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 3, 'turun ke barat ke daerah orang Yaflet, sampai daerah Bet-Horon Hilir dan selanjutnya sampai Gezer dan berakhir di laut.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 4, 'Demikianlah bani Yusuf, yakni suku Manasye dan suku Efraim, menerima milik pusaka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 5, 'Daerah bani Efraim menurut kaum-kaum mereka ialah demikian: batas milik pusaka mereka ke timur ialah Atarot-Adar sampai Bet-Horon Hulu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 6, 'Ke barat batas itu keluar di sebelah utara Mikhmetat; kemudian batas itu membelok ke timur ke Taanat-Silo, dan dari sana terus sampai ke sebelah timur Yanoah,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 7, 'turun dari Yanoah ke Atarot dan Naharat, menyinggung daerah Yerikho dan keluar ke sungai Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 8, 'Dari Tapuah batas itu terus ke barat ke sungai Kana dan berakhir ke laut. Itulah milik pusaka suku bani Efraim menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 9, 'Selanjutnya bagi bani Efraim ditentukan kota-kota terpisah di tengah-tengah milik pusaka bani Manasye, segala kota itu dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 16, 10, 'Tetapi orang Kanaan yang diam di Gezer tidaklah dihalau mereka. Jadi orang Kanaan itu masih tetap tinggal di tengah-tengah suku Efraim sampai sekarang, tetapi menjadi budak rodi.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 1, 'Bagian undian yang ditentukan bagi suku Manasye, sebab dialah anak sulung Yusuf, ialah demikian: Kepada Makhir, anak sulung Manasye, bapa Gilead, telah diberikan Gilead dan Basan, karena ia seorang tentara.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 2, 'Jadi bagian itulah yang ditentukan bagi anak-anak Manasye yang lain, menurut kaum-kaum mereka, yakni bagi bani Abiezer, bani Helek, bani Asriel, bani Sekhem, bani Hefer dan bani Semida; itulah keturunan yang laki-laki dari Manasye bin Yusuf, menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 3, 'Tetapi Zelafehad bin Hefer bin Gilead bin Makhir bin Manasye tidak mempunyai anak laki-laki, tetapi hanya anak perempuan. Inilah nama anak-anaknya itu: Mahla, Noa, Hogla, Milka dan Tirza.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 4, 'Mereka datang menghadap imam Eleazar, dan menghadap Yosua bin Nun, serta para pemimpin, dan berkata: "TUHAN telah memerintahkan kepada Musa untuk memberikan milik pusaka kepada kami di tengah-tengah saudara-saudara kami." Sebab itu diberikannya kepada mereka, milik pusaka di tengah-tengah saudara-saudara ayah mereka, sesuai dengan titah TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 5, 'Demikianlah kepada suku Manasye jatuh sepuluh bidang tanah, selain dari tanah Gilead dan Basan yang di seberang Yordan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 6, 'sebab anak-anak perempuan Manasye telah menerima milik pusaka di tengah-tengah anak-anaknya lelaki, sedang tanah Gilead ditentukan bagi anak-anak lelaki Manasye yang lain.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 7, 'Jadi batas daerah Manasye ialah dari Asyer ke Mikhmetat yang di sebelah timur Sikhem; kemudian batas itu terus ke selatan ke daerah penduduk En-Tapuah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 8, 'Tanah Tapuah adalah kepunyaan suku Manasye, tetapi kota Tapuah, dekat batas daerah Manasye, adalah kepunyaan bani Efraim.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 9, 'Kemudian batas itu turun ke sungai Kana, ke sebelah selatan sungai itu. Kota-kota di sana adalah kepunyaan suku Efraim, sekalipun di tengah-tengah kota-kota suku Manasye. Selanjutnya batas daerah Manasye itu lewat dari sebelah utara sungai itu dan berakhir ke laut.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 10, 'Ke selatan daerah itu kepunyaan suku Efraim dan ke utara kepunyaan suku Manasye. Batasnya ialah laut; di sebelah utara batas daerah itu menyinggung daerah Asyer, di sebelah timur menyinggung daerah Isakhar.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 11, 'Tetapi di daerah Isakhar dan Asyer ada juga kepunyaan suku Manasye, yakni Bet-Sean dengan segala anak kotanya, Yibleam dengan segala anak kotanya, penduduk Dor dengan segala anak kotanya, penduduk En-Dor dengan segala anak kotanya, penduduk Taanakh dengan segala anak kotanya, dan penduduk Megido dengan segala anak kotanya, yakni ketiga daerah bukit itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 12, 'Tetapi bani Manasye tidak dapat menduduki kota-kota itu, sebab orang Kanaan berhasil untuk tetap diam di negeri itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 13, 'Setelah orang Israel menjadi kuat, orang Kanaan itu dibuatnya menjadi orang rodi, tetapi tidaklah sama sekali mereka itu dihalaunya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 14, 'Berkatalah bani Yusuf kepada Yosua, demikian: "Mengapa engkau memberikan kepadaku hanya satu bagian undian dan satu bidang tanah saja menjadi milik pusaka, padahal aku ini bangsa yang banyak jumlahnya, karena TUHAN sampai sekarang memberkati aku?"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 15, 'Jawab Yosua kepada mereka: "Kalau engkau bangsa yang banyak jumlahnya, pergilah ke hutan dan bukalah tanah bagimu di sana di negeri orang Feris dan orang Refaim, jika pegunungan Efraim terlalu sesak bagimu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 16, 'Kemudian berkatalah bani Yusuf: "Pegunungan itu tidak cukup bagi kami, dan semua orang Kanaan yang diam di dataran itu mempunyai kereta besi, baik yang diam di Bet-Sean dengan segala anak kotanya maupun yang diam di lembah Yizreel."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 17, 'Lalu berkatalah Yosua kepada keturunan Yusuf, kepada suku Efraim dan suku Manasye: "Engkau ini bangsa yang banyak jumlahnya dan mempunyai kekuatan yang besar; tidak hanya satu bagian undian ditentukan bagimu,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 17, 18, 'tetapi pegunungan itu akan ditentukan bagimu juga, dan karena tanah itu hutan, haruslah kamu membukanya; kamu akan memilikinya sampai kepada ujung-ujungnya, sebab kamu akan menghalau orang Kanaan itu, sekalipun mereka mempunyai kereta besi dan sekalipun mereka kuat."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 1, 'Maka berkumpullah segenap umat Israel di Silo, lalu mereka menempatkan Kemah Pertemuan di sana, karena negeri itu telah takluk kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 2, 'Pada waktu itu masih tinggal tujuh suku di antara orang Israel, yang belum mendapat bagian milik pusaka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 3, 'Sebab itu berkatalah Yosua kepada orang Israel: "Berapa lama lagi kamu bermalas-malas, sehingga tidak pergi menduduki negeri yang telah diberikan kepadamu oleh TUHAN, Allah nenek moyangmu?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 4, 'Ajukanlah tiga orang dari tiap-tiap suku; maka aku akan menyuruh mereka, supaya mereka bersiap untuk menjelajahi negeri itu, mencatat keadaannya, sekadar milik pusaka masing-masing, kemudian kembali kepadaku.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 5, 'Sesudah itu mereka akan membaginya di antara mereka menjadi tujuh bagian. Suku Yehuda akan tetap tinggal dalam daerahnya di sebelah selatan dan keturunan Yusuf akan tetap tinggal dalam daerahnya di sebelah utara.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 6, 'Kamu catat keadaan negeri itu dalam tujuh bagian dan kamu bawa ke mari kepadaku; lalu aku akan membuang undi di sini bagi kamu di hadapan TUHAN, Allah kita.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 7, 'Sebab orang Lewi tidak mendapat bagian di tengah-tengah kamu, karena jabatan sebagai imam TUHAN ialah milik pusaka mereka, sedang suku Gad, suku Ruben dan suku Manasye yang setengah itu telah menerima milik pusaka di sebelah timur sungai Yordan, yang diberikan kepada mereka oleh Musa, hamba TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 8, 'Kemudian bersiaplah orang-orang itu, lalu pergi, sedang Yosua memerintahkan kepada mereka, pada waktu mereka berangkat, supaya mereka mencatat keadaan negeri itu, katanya: "Pergilah, jelajahilah negeri itu, catatkanlah keadaannya, kemudian kembalilah kepadaku; maka di sini, di Silo, aku akan membuang undi bagi kamu di hadapan TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 9, 'Orang-orang itu pergi dan berjalan melalui negeri itu; mereka mencatat keadaannya dalam suatu daftar, kota demi kota, dalam tujuh bagian, lalu kembali kepada Yosua ke tempat perkemahan di Silo.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 10, 'Lalu Yosua membuang undi bagi mereka di Silo, di hadapan TUHAN, dan di sanalah Yosua membagikan negeri itu kepada orang Israel, sesuai dengan pembagian mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 11, 'Maka keluarlah undian suku bani Benyamin menurut kaum-kaum mereka, dan daerah yang diundikan kepada mereka terdapat antara daerah bani Yehuda dan daerah bani Yusuf.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 12, 'Batas pada sisi utara bagi mereka mulai dari sungai Yordan; kemudian batas itu naik ke lereng gunung di sebelah utara Yerikho, naik ke barat ke pegunungan, dan menuju ke padang gurun Bet-Awen.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 13, 'Dari sana batas itu terus ke Lus, ke selatan, ke arah lereng gunung dekat Lus, itulah Betel; kemudian batas itu turun ke Atarot-Adar di pegunungan yang di sebelah selatan Bet-Horon Hilir.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 14, 'Kemudian batas itu melengkung, lalu membelok dari pegunungan yang di seberang Bet-Horon di sebelah selatan menuju ke sisi barat daya, dan berakhir di Kiryat-Baal, itulah Kiryat-Yearim, suatu kota bani Yehuda. Itulah sisi barat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 15, 'Sisi selatan mulai dari ujung Kiryat-Yearim, kemudian batas itu menuju ke barat, dan menuju pula ke mata air Me-Neftoah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 16, 'Selanjutnya batas itu turun ke ujung pegunungan yang di tentangan lebak Ben-Hinom, di sebelah utara lembah orang Refaim; kemudian turun ke lebak Hinom, sepanjang lereng gunung Yebus, ke selatan, kemudian turun ke En-Rogel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 17, 'Kemudian melengkung ke utara, menuju ke En-Semes dan menuju pula ke Gelilot di seberang pendakian Adumim, turun ke batu Bohan bin Ruben,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 18, 'terus ke lereng gunung di seberang Bet-Araba ke utara, dan turun ke Araba-Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 19, 'Kemudian batas itu terus ke lereng gunung dekat Bet-Hogla ke utara dan batas itu berakhir ke teluk utara Laut Asin, ke muara sungai Yordan di sebelah selatan. Itulah batas selatan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 20, 'Sungai Yordan ialah batasnya pada sisi timur. Itulah milik pusaka bani Benyamin dengan batas-batasnya ke segala penjuru menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 21, 'Kota-kota suku bani Benyamin menurut kaum-kaum mereka ialah Yerikho, Bet-Hogla, Emek-Kezis,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 22, 'Bet-Araba, Zemaraim, Betel,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 23, 'Haawim, Para, Ofra,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 24, 'Kefar-Haamonai, Ofni dan Geba; dua belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 25, 'Gibeon, Rama, Beerot,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 26, 'Mizpa, Kefira, Moza,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 27, 'Rekem, Yirpeel, Tarala,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 18, 28, 'Zela, Elef dan Yebus, ialah Yerusalem, Gibeat dan Kiryat; empat belas kota dengan desa-desanya. Itulah milik pusaka bani Benyamin menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 1, 'Undian yang keduapun keluarlah bagi suku Simeon, untuk suku bani Simeon menurut kaum-kaum mereka. Milik pusaka mereka ada di tengah-tengah milik pusaka bani Yehuda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 2, 'Sebagai milik warisan mereka menerima: Bersyeba, Syeba, Molada,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 3, 'Hazar-Sual, Bala, Ezem,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 4, 'Eltolad, Betul, Horma,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 5, 'Ziklag, Bet-Hamarkabot, Hazar-Susa,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 6, 'Bet-Lebaot dan Saruhen: tiga belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 7, 'En-Rimon, Eter, dan Asan: empat kota dengan desa-desanya;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 8, 'juga segala desa di sekeliling kota-kota tadi, sampai ke Baalat-Beer, yakni Rama yang di Tanah Selatan. Itulah milik pusaka suku bani Simeon menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 9, 'Milik pusaka bani Simeon diambil dari bagian bani Yehuda. Karena bagian bani Yehuda itu terlalu besar bagi mereka, maka bani Simeon menerima milik pusaka di tengah-tengah mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 10, 'Undian yang ketigapun keluarlah bagi bani Zebulon menurut kaum-kaum mereka. Batas milik pusaka mereka sampai ke Sarid.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 11, 'Ke sebelah barat batas mereka itu naik ke Marala, menyinggung Dabeset, kemudian menyinggung sungai yang mengalir lewat Yokneam.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 12, 'Dari Sarid batas itu berbalik ke timur, ke arah matahari terbit, melalui daerah Kislot-Tabor, menuju Dobrat, naik ke Yafia;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 13, 'dari sana terus ke timur, ke arah matahari terbit, ke Gat-Hefer, ke Et-Kazin, menuju ke Rimon, dan melengkung ke Nea.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 14, 'Kemudian batas itu membelok mengelilinginya di sebelah utara Hanaton, dan berakhir di lembah Yiftah-El.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 15, 'Lagi Katat, Nahalal, Simron, Yidala dan Betlehem; dua belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 16, 'Itulah milik pusaka bani Zebulon menurut kaum-kaum mereka; kota-kota tadi dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 17, 'Bagi suku Isakhar keluarlah undian yang keempat, yakni bagi bani Isakhar menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 18, 'Daerah mereka ialah Yizreel, Kesulot, Sunem,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 19, 'Hafaraim, Sion, Anaharat,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 20, 'Rabit, Kisyon, Ebes,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 21, 'Remet, En-Ganim, En-Hada dan Bet-Pazes.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 22, 'Batas daerah itu menyinggung Tabor, Sahazima dan Bet-Semes; dan batas daerah mereka berakhir di sungai Yordan; enam belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 23, 'Itulah milik pusaka suku bani Isakhar menurut kaum-kaum mereka, kota-kota itu dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 24, 'Undian yang kelimapun keluarlah bagi suku bani Asyer menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 25, 'Daerah mereka ialah Helkat, Hali, Beten, Akhsaf,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 26, 'Alamelekh, Amad dan Misal; dan batasnya menyinggung gunung Karmel dan sungai Libnat di sebelah barat;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 27, 'kemudian berbalik ke arah matahari terbit, ke Bet-Dagon; menyinggung daerah Zebulon dan lembah Yiftah-El di sebelah utara, Bet-Emek dan Nehiel, dan menuju ke Kabul di sebelah utara,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 28, 'dan ke Ebron, Rehob, Hamon dan Kana sampai ke Sidon Besar.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 29, 'Kemudian batas itu berbalik ke Rama dan sampai ke kota yang berkubu Tirus, kemudian batas itu berbalik ke Hosa dan berakhir di laut. Lagipula Mahalab, Akhzib,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 30, 'Uma, Afek dan Rehob; dua puluh dua kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 31, 'Itulah milik pusaka suku bani Asyer menurut kaum-kaum mereka; kota-kota tadi dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 32, 'Bagi bani Naftali keluarlah undian yang keenam, yakni bagi bani Naftali menurut kaum-kaum mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 33, 'Daerah mereka mulai dari Helef, dari pohon tarbantin di Zaananim, Adami-Nekeb dan Yabneel, sampai ke Lakum, dan berakhir di sungai Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 34, 'Kemudian batas itu berbalik ke barat ke Aznot-Tabor, dari sana menuju ke Hukok, menyinggung daerah Zebulon di sebelah selatan, menyinggung daerah Asyer di sebelah barat dan daerah Yehuda pada sungai Yordan, di sebelah matahari terbit.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 35, 'Kota-kota yang berkubu ialah Zidim, Zer, Hamat, Rakat, Kineret,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 36, 'Adama, Rama, Hazor,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 37, 'Kedesh, Edrei, En-Hazor,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 38, 'Yiron, Migdal-El, Horem, Bet-Anat dan Bet-Semes; sembilan belas kota dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 39, 'Itulah milik pusaka suku bani Naftali menurut kaum-kaum mereka; kota-kota itu dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 40, 'Bagi suku bani Dan menurut kaum-kaum mereka keluarlah undian yang ketujuh.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 41, 'Daerah milik pusaka mereka ialah Zora, Esytaol, Ir-Semes,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 42, 'Saalabin, Ayalon, Yitla,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 43, 'Elon, Timna, Ekron,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 44, 'Elteke, Gibeton, Baalat,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 45, 'Yehud, Bene-Berak, Gat-Rimon,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 46, 'Me-Yarkon dan Rakon, bersama-sama dengan daerah di seberang Yafo.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 47, 'Karena daerah bani Dan telah menjadi terlalu sempit untuk mereka, maka berjalanlah bani Dan itu maju dan berperang melawan kota Lesem. Mereka merebutnya, memarang penduduknya dengan mata pedang dan mendudukinya. Lalu menetaplah mereka di sana dan menamai Lesem itu Dan menurut nama Dan, bapa leluhur mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 48, 'Itulah milik pusaka suku bani Dan menurut kaum-kaum mereka; kota-kota tadi dengan desa-desanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 49, 'Setelah orang Israel selesai membagikan negeri itu menjadi milik pusaka mereka menurut daerah-daerahnya, maka kepada Yosua bin Nun diberikanlah milik pusaka di tengah-tengah mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 50, 'Sesuai dengan titah TUHAN, mereka memberikan kepadanya kota yang dimintanya, yakni Timnat-Serah di pegunungan Efraim. Kota itu dibangunnya dan menetaplah ia di sana.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 19, 51, 'Itulah milik pusaka yang diperundikan di antara suku-suku orang Israel di Silo oleh imam Eleazar, oleh Yosua bin Nun dan oleh para kepala kaum keluarga di hadapan TUHAN di depan pintu Kemah Pertemuan. Demikianlah diselesaikan mereka pembagian negeri itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 1, 'Berfirmanlah TUHAN kepada Yosua, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 2, '"Katakanlah kepada orang Israel, begini: Tentukanlah bagimu kota-kota perlindungan, yang telah Kusebutkan kepadamu dengan perantaraan Musa,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 3, 'supaya siapa yang membunuh seseorang dengan tidak sengaja, dengan tidak ada niat lebih dahulu, dapat melarikan diri ke sana, sehingga kota-kota itu menjadi tempat perlindungan bagimu terhadap penuntut tebusan darah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 4, 'Apabila ia melarikan diri ke salah satu kota tadi, maka haruslah ia tinggal berdiri di depan pintu gerbang kota dan memberitahukan perkaranya kepada para tua-tua kota. Mereka harus menerima dia dalam kota itu dan memberikan tempat kepadanya, dan ia akan diam pada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 5, 'Apabila penuntut tebusan darah itu mengejar dia, pembunuh itu tidak akan diserahkan mereka ke dalam tangannya, sebab ia telah membunuh sesamanya manusia dengan tidak ada niat lebih dahulu, dan dengan tidak menaruh benci kepadanya lebih dahulu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 6, 'Ia harus tetap diam di kota itu sampai ia dihadapkan kepada rapat jemaah untuk diadili, sampai imam besar yang ada pada waktu itu mati. Maka barulah pembunuh itu boleh pulang ke kotanya dan ke rumahnya, ke kota dari mana ia melarikan diri."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 7, 'Lalu orang Israel mengkhususkan sebagai kota perlindungan: Kedesh di Galilea, di pegunungan Naftali dan Sikhem, di pegunungan Efraim, dan Kiryat-Arba, itulah Hebron, di pegunungan Yehuda.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 8, 'Dan di seberang sungai Yordan, di sebelah timur Yerikho, mereka menentukan Bezer, di padang gurun, di dataran tinggi, dari suku Ruben; dan Ramot di Gilead dari suku Gad, dan Golan di Basan dari suku Manasye.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 20, 9, 'Itulah kota-kota yang ditetapkan bagi semua orang Israel dan bagi pendatang-pendatang yang ada di tengah-tengah mereka, supaya setiap orang yang membunuh seseorang dengan tidak sengaja dapat melarikan diri ke sana dan jangan mati dibunuh oleh tangan penuntut tebusan darah, sebelum ia dihadapkan kepada rapat jemaah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 1, 'Kemudian datanglah para kepala kaum keluarga orang Lewi menghadap imam Eleazar, menghadap Yosua bin Nun, dan menghadap para kepala kaum keluarga di antara suku-suku orang Israel', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 2, 'dan berkata kepada mereka di Silo di tanah Kanaan, demikian: "TUHAN telah memerintahkan dengan perantaraan Musa, supaya diberikan kepada kami kota-kota untuk didiami dan tanah-tanah penggembalaannya untuk ternak kami."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 3, 'Lalu orang Israel memberikan dari milik pusaka mereka kota-kota yang berikut dengan tanah-tanah penggembalaannya kepada orang Lewi, seperti yang dititahkan TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 4, 'Lalu keluarlah undian bagi kaum-kaum orang Kehat. Maka di antara orang Lewi anak-anak imam Harun, mendapat dengan undian tiga belas kota dari suku Yehuda, dari suku Simeon dan dari suku Benyamin.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 5, 'Kaum-kaum yang lain di antara keturunan Kehat mendapat dengan undian sepuluh kota dari kaum-kaum suku Efraim, dari suku Dan dan dari suku Manasye yang setengah itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 6, 'Keturunan Gerson mendapat dengan undian tiga belas kota dari kaum-kaum suku Isakhar, dari suku Asyer, dari suku Naftali dan dari setengah suku Manasye yang di Basan itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 7, 'Keturunan Merari mendapat dengan undian dua belas kota menurut kaum-kaum mereka, dari suku Ruben, dari suku Gad dan dari suku Zebulon.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 8, 'Demikianlah diberikan orang Israel kota-kota tadi dengan tanah-tanah penggembalaannya kepada orang Lewi dengan undian seperti yang diperintahkan TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 9, 'Dari suku bani Yehuda dan dari suku bani Simeon diberikan mereka kota-kota yang berikut, yang disebutkan namanya di sini:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 10, 'kepada anak-anak Harun yang dari kaum-kaum orang Kehat yang termasuk bani Lewi, karena bagi merekalah undian yang pertama,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 11, 'kepada mereka diberikan Kiryat-Arba, itulah Hebron?Arba inilah bapa suku Enak?di pegunungan Yehuda, dan tanah-tanah penggembalaan di sekelilingnya;', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 12, 'tetapi tanah ladang kota tadi dengan desa-desanya telah diberikan mereka kepada Kaleb bin Yefune menjadi miliknya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 13, 'Kepada anak-anak imam Harun, diberikan mereka Hebron, kota perlindungan untuk pembunuh, dan tanah-tanah penggembalaan kota itu, Libna dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 14, 'Yatir dengan tanah-tanah penggembalaannya, Estemoa dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 15, 'Holon dengan tanah-tanah penggembalaannya, Debir dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 16, 'Ain dengan tanah-tanah penggembalaannya, Yuta dengan tanah-tanah penggembalaannya dan Bet-Semes dengan tanah-tanah penggembalaannya: sembilan kota dari kedua suku itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 17, 'Dan dari suku Benyamin: Gibeon dengan tanah-tanah penggembalaannya, Geba dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 18, 'Anatot dengan tanah-tanah penggembalaannya dan Almon dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 19, 'Seluruhnya kota-kota kepunyaan anak-anak Harun, para imam itu, ada tiga belas kota dengan tanah-tanah penggembalaannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 20, 'Kaum-kaum keturunan Kehat, yakni orang Lewi yang masih tinggal dari antara keturunan Kehat, mendapat kota-kota yang dengan undian kepada mereka dari suku Efraim.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 21, 'Kepada mereka diberikan Sikhem, kota perlindungan untuk pembunuh, dengan tanah-tanah penggembalaannya, di pegunungan Efraim, Gezer dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 22, 'Kibzaim dengan tanah-tanah penggembalaannya dan Bet-Horon dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 23, 'Dan dari suku Dan: Elteke dengan tanah-tanah penggembalaannya, Gibeton dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 24, 'Ayalon dengan tanah-tanah penggembalaannya dan Gat-Rimon dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 25, 'Dan dari suku Manasye yang setengah itu: Taanakh dengan tanah-tanah penggembalaannya dan Gat-Rimon dengan tanah-tanah penggembalaannya: dua kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 26, 'Seluruhnya kota-kota itu ada sepuluh, dengan tanah-tanah penggembalaannya, ditentukan bagi kaum-kaum yang masih tinggal dari antara keturunan Kehat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 27, 'Bani Gerson dari kaum-kaum orang Lewi mendapat dari suku Manasye yang setengah lagi: Golan, kota perlindungan untuk pembunuh, di Basan, dengan tanah-tanah penggembalaannya, dan Beestera dengan tanah-tanah penggembalaannya: dua kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 28, 'Dan dari suku Isakhar: Kisyon dengan tanah-tanah penggembalaannya, Dobrat dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 29, 'Yarmut dengan tanah-tanah penggembalaannya, dan En-Ganim dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 30, 'Dan dari suku Asyer: Misal dengan tanah-tanah penggembalaannya, Abdon dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 31, 'Helkat dengan tanah-tanah penggembalaannya dan Rehob dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 32, 'Dan dari suku Naftali: Kedesh, kota perlindungan untuk pembunuh, di Galilea, dengan tanah-tanah penggembalaannya, Hamot-Dor dengan tanah-tanah penggembalaannya dan Kartan dengan tanah-tanah penggembalaannya: tiga kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 33, 'Seluruhnya kota-kota kepunyaan orang Gerson menurut kaum-kaum mereka ada tiga belas kota dengan tanah-tanah penggembalaannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 34, 'Kaum-kaum keturunan Merari, orang Lewi yang masih tinggal, mendapat dari suku Zebulon: Yokneam dengan tanah-tanah penggembalaannya, Karta dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 35, 'Dimna dengan tanah-tanah penggembalaannya dan Nahalal dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 36, 'Dan dari suku Ruben: Bezer dengan tanah-tanah penggembalaannya, Yahas dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 37, 'Kedemot dengan tanah-tanah penggembalaannya dan Mefaat dengan tanah-tanah penggembalaannya: empat kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 38, 'Dan dari suku Gad: Ramot, kota perlindungan untuk pembunuh, di Gilead, dengan tanah-tanah penggembalaannya, Mahanaim dengan tanah-tanah penggembalaannya,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 39, 'Hesybon dengan tanah-tanah penggembalaannya dan Yaezer dengan tanah-tanah penggembalaannya: seluruhnya kota-kota itu ada empat.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 40, 'Seluruhnya kota-kota itu ditentukan bagi keturunan Merari menurut kaum-kaum mereka, yakni yang masih tinggal dari kaum-kaum orang Lewi. Bagian undian mereka ada dua belas kota.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 41, 'Seluruhnya kota-kota orang Lewi di tengah-tengah milik orang Israel ada empat puluh delapan kota dengan tanah-tanah penggembalaannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 42, 'Kota-kota itu masing-masing ada tanah-tanah penggembalaannya di sekelilingnya, demikianlah kota-kota tadi seluruhnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 43, 'Jadi seluruh negeri itu diberikan TUHAN kepada orang Israel, yakni negeri yang dijanjikan-Nya dengan bersumpah untuk diberikan kepada nenek moyang mereka. Mereka menduduki negeri itu dan menetap di sana.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 44, 'Dan TUHAN mengaruniakan kepada mereka keamanan ke segala penjuru, tepat seperti yang dijanjikan-Nya dengan bersumpah kepada nenek moyang mereka. Tidak ada seorangpun dari semua musuhnya yang tahan berdiri menghadapi mereka; semua musuhnya diserahkan TUHAN kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 21, 45, 'Dari segala yang baik yang dijanjikan TUHAN kepada kaum Israel, tidak ada yang tidak dipenuhi; semuanya terpenuhi.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 1, 'Lalu Yosua memanggil orang Ruben, orang Gad dan suku Manasye yang setengah itu,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 2, 'dan berkata kepada mereka: "Kamu telah memelihara segala yang diperintahkan kepadamu oleh Musa, hamba TUHAN itu, dan telah mendengarkan perkataanku dalam segala yang kuperintahkan kepadamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 3, 'Kamu tidak meninggalkan saudara-saudaramu selama waktu ini, sampai sekarang, tetapi kamu setia memelihara perintah TUHAN, Allahmu, kepadamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 4, 'Tetapi sekarang TUHAN, Allahmu, telah mengaruniakan keamanan kepada saudara-saudaramu, seperti yang dijanjikan-Nya kepada mereka. Oleh sebab itu, pulanglah ke kemahmu, ke tanah milikmu, yang telah diberikan kepadamu oleh Musa, hamba TUHAN itu, di seberang Yordan.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 5, 'Hanya, lakukanlah dengan sangat setia perintah dan hukum, yang diperintahkan kepadamu oleh Musa, hamba TUHAN itu, yakni mengasihi TUHAN, Allahmu, hidup menurut segala jalan yang ditunjukkan-Nya, tetap mengikuti perintah-Nya, berpaut pada-Nya dan berbakti kepada-Nya dengan segenap hatimu dan dengan segenap jiwamu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 6, 'Lalu Yosua memberkati mereka dan melepas mereka pergi. Maka pulanglah mereka ke kemah mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 7, 'Kepada suku Manasye yang setengah telah diberikan Musa bagian mereka di Basan; kepada suku yang setengah lagi telah diberikan Yosua bagian mereka di antara saudara-saudara mereka di sebelah barat sungai Yordan. Lagipun ketika Yosua melepas mereka pergi ke kemah mereka, setelah memberkati mereka,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 8, 'maka ia berkata kepada mereka, demikian: "Pulanglah ke kemahmu dengan kekayaan yang banyak dan dengan sangat banyak ternak, dengan perak, emas, tembaga, besi dan dengan pakaian yang sangat banyak. Bagilah dengan saudara-saudaramu jarahan yang dari musuhmu itu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 9, 'Maka pulanglah bani Ruben, bani Gad dan suku Manasye yang setengah itu dan mereka pergi meninggalkan orang Israel, keluar dari Silo di tanah Kanaan untuk pergi ke tanah Gilead, tanah milik mereka yang didiami mereka sesuai dengan titah TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 10, 'Ketika mereka sampai ke Gelilot pada sungai Yordan, yang di tanah Kanaan, maka bani Ruben, bani Gad dan suku Manasye yang setengah itu mendirikan mezbah di sana di tepi sungai Yordan, mezbah yang besar bangunannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 11, 'Lalu terdengarlah oleh orang Israel itu cakap orang: "Telah didirikan mezbah oleh bani Ruben, bani Gad dan suku Manasye yang setengah itu, mezbah menghadap ke tanah Kanaan, di Gelilot pada sungai Yordan, di sebelah wilayah orang Israel."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 12, 'Ketika hal itu terdengar oleh orang Israel, berkumpullah segenap umat Israel di Silo, untuk maju memerangi mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 13, 'Kemudian orang Israel mengutus kepada bani Ruben, kepada bani Gad dan kepada suku Manasye yang setengah itu, ke tanah Gilead, imam Pinehas bin Eleazar,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 14, 'dan bersama-sama dengan dia sepuluh pemimpin, yakni seorang pemimpin kaum keluarga sebagai wakil tiap-tiap suku Israel. Masing-masing mereka itu kepala kaum keluarganya di antara kaum-kaum orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 15, 'Setelah mereka sampai kepada bani Ruben, kepada bani Gad dan kepada suku Manasye yang setengah itu di tanah Gilead, berkatalah mereka kepada orang-orang itu, demikian:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 16, '"Beginilah kata segenap umat TUHAN: Apa macam perbuatanmu yang tidak setia ini terhadap Allah Israel, dengan sekarang berbalik dari pada TUHAN dan mendirikan mezbah bagimu, dengan demikian memberontak terhadap TUHAN pada hari ini?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 17, 'Belum cukupkah bagi kita noda yang di Peor itu, yang dari padanya kita belum mentahirkan diri sampai hari ini dan yang menyebabkan umat TUHAN kena tulah,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 18, 'sehingga kamu berbalik pula sekarang ini membelakangi TUHAN? Jika kamu hari ini memberontak terhadap TUHAN, maka besok Ia akan murka kepada segenap umat Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 19, 'Akan tetapi, jika sekiranya tanah milikmu itu najis, marilah menyeberang ke tanah milik TUHAN, tempat kedudukan Kemah Suci TUHAN, dan menetaplah di tengah-tengah kami. Tetapi janganlah memberontak terhadap TUHAN dan janganlah memberontak terhadap kami, dengan mendirikan mezbah bagimu sendiri, selain dari mezbah TUHAN, Allah kita.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 20, 'Ketika Akhan bin Zerah berubah setia dengan mengambil barang-barang yang dikhususkan, bukankah segenap umat Israel kena murka? Bukan orang itu saja yang mati karena dosanya."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 21, 'Lalu jawab bani Ruben, bani Gad dan suku Manasye yang setengah itu, katanya kepada para kepala kaum-kaum orang Israel:', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 22, '"Allah segala allah, TUHAN, Allah segala allah, TUHAN, Dialah yang mengetahui, dan patutlah orang Israel mengetahuinya juga! Jika sekiranya hal ini terjadi dengan maksud memberontak atau dengan maksud berubah setia terhadap TUHAN?biarlah jangan TUHAN selamatkan kami pada hari ini.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 23, 'Jika sekiranya kami mendirikan mezbah untuk berbalik dari pada TUHAN, untuk mempersembahkan korban bakaran dan korban sajian di atasnya serta korban keselamatan di atasnya, biarlah TUHAN sendiri yang menuntut balas terhadap kami.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 24, 'Tetapi sesungguhnya, kami telah melakukannya karena cemas. Sebab pikir kami: Di kemudian hari anak-anak kamu mungkin berkata kepada anak-anak kami, demikian: Apakah sangkut pautmu dengan TUHAN, Allah Israel?', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 25, 'Bukankah TUHAN telah menentukan sungai Yordan sebagai batas antara kami dan kamu, hai orang bani Ruben dan bani Gad! Kamu tidak mempunyai bagian akan TUHAN. Demikianlah mungkin anak-anak kamu membuat anak-anak kami berhenti dari pada takut akan TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 26, 'Sebab itu kata kami: Biarlah kita mendirikan mezbah itu bagi kita! Bukanlah untuk korban bakaran dan bukanlah untuk korban sembelihan,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 27, 'tetapi supaya mezbah itu menjadi saksi antara kami dan kamu, dan antara keturunan kita kemudian, bahwa kami tetap beribadah kepada TUHAN di hadapan-Nya dengan korban bakaran, korban sembelihan dan korban keselamatan kami. Jadi tidaklah mungkin anak-anak kamu di kemudian hari berkata kepada anak-anak kami: Kamu tidak mempunyai bagian pada TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 28, 'Lagi kata kami: Apabila di kemudian hari demikian dikatakan mereka kepada kita dan kepada keturunan kita, maka kita akan berkata: Tengoklah bangunan tiruan mezbah TUHAN itu, yang telah dibuat oleh nenek moyang kami. Bukan untuk korban bakaran dan bukan untuk korban sembelihan, tetapi mezbah itu menjadi saksi antara kami dan kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 29, 'Jauhlah dari pada kami untuk memberontak terhadap TUHAN, dan untuk berbalik dari pada TUHAN pada hari ini dengan mendirikan mezbah untuk korban bakaran, korban sajian atau korban sembelihan, mezbah yang bukan mezbah TUHAN, Allah kita, yang ada di depan Kemah Suci-Nya!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 30, 'Setelah imam Pinehas dan para pemimpin umat serta para kepala kaum-kaum orang Israel yang bersama-sama dengan dia, mendengar perkataan yang dikatakan oleh bani Ruben, bani Gad dan bani Manasye itu, maka mereka menganggap hal itu baik.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 31, 'Kemudian berkatalah imam Pinehas bin Eleazar kepada bani Ruben, bani Gad dan bani Manasye: "Sekarang tahulah kami bahwa TUHAN ada di tengah-tengah kita, sebab tidaklah kamu berubah setia terhadap TUHAN. Dengan demikian kamu telah melepaskan orang Israel dari hukuman TUHAN."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 32, 'Sesudah itu imam Pinehas bin Eleazar serta para pemimpin itu meninggalkan bani Ruben dan bani Gad di tanah Gilead, pulang ke Kanaan kepada orang Israel, lalu disampaikanlah berita itu kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 33, 'Hal itu dipandang baik oleh orang Israel, sehingga orang Israel memuji Allah dan tidak lagi berkata hendak maju memerangi mereka untuk memusnahkan negeri yang didiami bani Ruben dan bani Gad itu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 22, 34, 'Dan bani Ruben dan bani Gad menamai mezbah itu: Saksi, karena inilah saksi antara kita, bahwa TUHAN itulah Allah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 1, 'Lama setelah TUHAN mengaruniakan keamanan kepada orang Israel ke segala penjuru terhadap semua musuhnya, dan ketika Yosua telah tua dan lanjut umur,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 2, 'dipanggilnya seluruh orang Israel, para tua-tuanya, para kepalanya, para hakimnya dan para pengatur pasukannya dan berkata kepada mereka: "Aku telah tua dan sangat lanjut umur,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 3, 'dan kamu ini telah melihat segala yang dilakukan TUHAN, Allahmu, kepada semua bangsa di sini demi kamu, sebab TUHAN, Allahmu, Dialah yang telah berperang bagi kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 4, 'Ingatlah, aku telah membagikan dengan membuang undi bangsa-bangsa yang masih tinggal ini kepada suku-sukumu menjadi milik pusakamu, seperti juga semua bangsa yang telah kulenyapkan hari itu, mulai dari sungai Yordan sampai ke Laut Besar di sebelah matahari terbenam.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 5, 'Dan TUHAN, Allahmu, Dialah yang akan mengusir dan menghalau mereka dari depanmu, sehingga kamu menduduki negeri mereka, seperti yang dijanjikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 6, 'Kuatkanlah benar-benar hatimu dalam memelihara dan melakukan segala yang tertulis dalam kitab hukum Musa, supaya kamu jangan menyimpang ke kanan atau ke kiri,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 7, 'dan supaya kamu jangan bergaul dengan bangsa-bangsa yang masih tinggal di antaramu itu, serta mengakui nama allah mereka dan bersumpah demi nama itu, dan beribadah atau sujud menyembah kepada mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 8, 'Tetapi kamu harus berpaut pada TUHAN, Allahmu, seperti yang kamu lakukan sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 9, 'Bukankah TUHAN telah menghalau bangsa-bangsa yang besar dan kuat dari depanmu, dan akan kamu ini, seorangpun tidak ada yang tahan menghadapi kamu sampai sekarang.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 10, 'Satu orang saja dari pada kamu dapat mengejar seribu orang, sebab TUHAN Allahmu, Dialah yang berperang bagi kamu, seperti yang dijanjikan-Nya kepadamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 11, 'Maka demi nyawamu, bertekunlah mengasihi TUHAN, Allahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 12, 'Sebab jika kamu berbalik dan berpaut kepada sisa bangsa-bangsa ini yang masih tinggal di antara kamu, kawin-mengawin dengan mereka serta bergaul dengan mereka dan mereka dengan kamu,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 13, 'maka ketahuilah dengan sesungguhnya, bahwa TUHAN, Allahmu, tidak akan menghalau lagi bangsa-bangsa itu dari depanmu. Tetapi mereka akan menjadi perangkap dan jerat bagimu, menjadi cambuk pada lambungmu dan duri di matamu, sampai kamu binasa dari tanah yang baik ini, yang telah diberikan kepadamu oleh TUHAN, Allahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 14, 'Maka sekarang, sebentar lagi aku akan menempuh jalan segala yang fana. Sebab itu insaflah dengan segenap hatimu dan segenap jiwamu, bahwa satupun dari segala yang baik yang telah dijanjikan kepadamu oleh TUHAN, Allahmu, tidak ada yang tidak dipenuhi. Semuanya telah digenapi bagimu. Tidak ada satupun yang tidak dipenuhi.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 15, 'Tetapi seperti telah datang atas kamu segala yang baik, yang telah dijanjikan kepadamu oleh TUHAN, Allahmu, demikianlah TUHAN akan mendatangkan atas kamu segala yang tidak baik sampai Ia telah memusnahkan kamu dari tanah yang baik ini, yang diberikan kepadamu oleh TUHAN, Allahmu,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 23, 16, 'apabila kamu melangkahi perjanjian, yang telah diperintahkan kepadamu oleh TUHAN, Allahmu, dan pergi beribadah kepada allah lain dan sujud menyembah kepada mereka. Maka murka TUHAN akan bangkit terhadap kamu, sehingga kamu segera binasa dari negeri yang baik, yang telah diberikan-Nya kepadamu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 1, 'Kemudian Yosua mengumpulkan semua suku orang Israel di Sikhem. Dipanggilnya para tua-tua orang Israel, para kepalanya, para hakimnya dan para pengatur pasukannya, lalu mereka berdiri di hadapan Allah.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 2, 'Berkatalah Yosua kepada seluruh bangsa itu: "Beginilah firman TUHAN, Allah Israel: Dahulu kala di seberang sungai Efrat, di situlah diam nenek moyangmu, yakni Terah, ayah Abraham dan ayah Nahor, dan mereka beribadah kepada allah lain.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 3, 'Tetapi Aku mengambil Abraham, bapamu itu, dari seberang sungai Efrat, dan menyuruh dia menjelajahi seluruh tanah Kanaan. Aku membuat banyak keturunannya dan memberikan Ishak kepadanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 4, 'Kepada Ishak Kuberikan Yakub dan Esau. Kepada Esau Kuberikan pegunungan Seir menjadi miliknya, sedang Yakub serta anak-anaknya pergi ke Mesir.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 5, 'Lalu Aku mengutus Musa serta Harun dan menulahi Mesir, seperti yang Kulakukan di tengah-tengah mereka, kemudian Aku membawa kamu keluar.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 6, 'Setelah Aku membawa nenek moyangmu keluar dari Mesir dan kamu sampai ke laut, lalu orang Mesir mengejar nenek moyangmu dengan kereta dan orang berkuda ke Laut Teberau.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 7, 'Sebab itu berteriak-teriaklah mereka kepada TUHAN, maka diadakan-Nya gelap antara kamu dan orang Mesir itu dan didatangkan-Nya air laut atas mereka, sehingga mereka diliputi. Dan matamu sendiri telah melihat, apa yang Kulakukan terhadap Mesir. Sesudah itu lama kamu diam di padang gurun.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 8, 'Aku membawa kamu ke negeri orang Amori yang diam di seberang sungai Yordan, dan ketika mereka berperang melawan kamu, mereka Kuserahkan ke dalam tanganmu, sehingga kamu menduduki negerinya, sedang mereka Kupunahkan dari depan kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 9, 'Ketika itu Balak bin Zipor, raja Moab, bangkit berperang melawan orang Israel. Disuruhnya memanggil Bileam bin Beor untuk mengutuki kamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 10, 'Tetapi Aku tidak mau mendengarkan Bileam, sehingga iapun memberkati kamu. Demikianlah Aku melepaskan kamu dari tangannya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 11, 'Setelah kamu menyeberangi sungai Yordan dan sampai ke Yerikho, berperanglah melawan kamu warga-warga kota Yerikho, orang Amori, orang Feris, orang Kanaan, orang Het, orang Girgasi, orang Hewi dan orang Yebus, tetapi mereka itu Kuserahkan ke dalam tanganmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 12, 'Kemudian Aku melepaskan tabuhan mendahului kamu dan binatang-binatang ini menghalau mereka dari depanmu, seperti kedua raja orang Amori itu. Sesungguhnya, bukan oleh pedangmu dan bukan pula oleh panahmu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 13, 'Demikianlah Kuberikan kepadamu negeri yang kamu peroleh tanpa bersusah-susah dan kota-kota yang tidak kamu dirikan, tetapi kamulah yang diam di dalamnya; juga kebun-kebun anggur dan kebun-kebun zaitun yang tidak kamu tanami, kamulah yang makan hasilnya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 14, 'Oleh sebab itu, takutlah akan TUHAN dan beribadahlah kepada-Nya dengan tulus ikhlas dan setia. Jauhkanlah allah yang kepadanya nenek moyangmu telah beribadah di seberang sungai Efrat dan di Mesir, dan beribadahlah kepada TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 15, 'Tetapi jika kamu anggap tidak baik untuk beribadah kepada TUHAN, pilihlah pada hari ini kepada siapa kamu akan beribadah; allah yang kepadanya nenek moyangmu beribadah di seberang sungai Efrat, atau allah orang Amori yang negerinya kamu diami ini. Tetapi aku dan seisi rumahku, kami akan beribadah kepada TUHAN!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 16, 'Lalu bangsa itu menjawab: "Jauhlah dari pada kami meninggalkan TUHAN untuk beribadah kepada allah lain!', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 17, 'Sebab TUHAN, Allah kita, Dialah yang telah menuntun kita dan nenek moyang kita dari tanah Mesir, dari rumah perbudakan, dan yang telah melakukan tanda-tanda mujizat yang besar ini di depan mata kita sendiri, dan yang telah melindungi kita sepanjang jalan yang kita tempuh, dan di antara semua bangsa yang kita lalui,', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 18, 'TUHAN menghalau semua bangsa dan orang Amori, penduduk negeri ini, dari depan kita. Kamipun akan beribadah kepada TUHAN, sebab Dialah Allah kita."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 19, 'Tetapi Yosua berkata kepada bangsa itu: "Tidaklah kamu sanggup beribadah kepada TUHAN, sebab Dialah Allah yang kudus, Dialah Allah yang cemburu. Ia tidak akan mengampuni kesalahan dan dosamu.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 20, 'Apabila kamu meninggalkan TUHAN dan beribadah kepada allah asing, maka Ia akan berbalik dari padamu dan melakukan yang tidak baik kepada kamu serta membinasakan kamu, setelah Ia melakukan yang baik kepada kamu dahulu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 21, 'Tetapi bangsa itu berkata kepada Yosua: "Tidak, hanya kepada TUHAN saja kami akan beribadah."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 22, 'Kemudian berkatalah Yosua kepada bangsa itu: "Kamulah saksi terhadap kamu sendiri, bahwa kamu telah memilih TUHAN untuk beribadah kepada-Nya." Jawab mereka: "Kamilah saksi!"', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 23, 'Ia berkata: "Maka sekarang, jauhkanlah allah asing yang ada di tengah-tengah kamu dan condongkanlah hatimu kepada TUHAN, Allah Israel."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 24, 'Lalu jawab bangsa itu kepada Yosua: "Kepada TUHAN, Allah kita, kami akan beribadah, dan firman-Nya akan kami dengarkan."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 25, 'Pada hari itu juga Yosua mengikat perjanjian dengan bangsa itu dan membuat ketetapan dan peraturan bagi mereka di Sikhem.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 26, 'Yosua menuliskan semuanya itu dalam kitab hukum Allah, lalu ia mengambil batu yang besar dan mendirikannya di sana, di bawah pohon besar, di tempat kudus TUHAN.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 27, 'Kata Yosua kepada seluruh bangsa itu: "Sesungguhnya batu inilah akan menjadi saksi terhadap kita, sebab telah didengarnya segala firman TUHAN yang diucapkan-Nya kepada kita. Sebab itu batu ini akan menjadi saksi terhadap kamu, supaya kamu jangan menyangkal Allahmu."', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 28, 'Sesudah itu Yosua melepas bangsa itu pergi, masing-masing ke milik pusakanya.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 29, 'Dan sesudah peristiwa-peristiwa ini, maka matilah Yosua bin Nun, hamba TUHAN itu, ketika berumur seratus sepuluh tahun.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 30, 'Lalu ia dikuburkan di daerah milik pusakanya, di Timnat-Serah yang di pegunungan Efraim, di sebelah utara gunung Gaas.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 31, 'Orang Israel beribadah kepada TUHAN sepanjang zaman Yosua dan sepanjang zaman para tua-tua yang hidup lebih lama dari pada Yosua, dan yang mengenal segenap perbuatan yang dilakukan TUHAN bagi orang Israel.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 32, 'Tulang-tulang Yusuf, yang dibawa orang Israel dari Mesir, dikuburkan mereka di Sikhem, di tanah milik yang dibeli Yakub dengan harga seratus kesita dari anak-anak Hemor, bapa Sikhem, dan yang ditentukan bagi bani Yusuf menjadi milik pusaka mereka.', 'id', 'TB'),
  ('6', 'yos', 'Yosua', 24, 33, 'Juga Eleazar bin Harun mati, dan dia dikuburkan di bukit yang diberikan kepada Pinehas, anaknya itu, di pegunungan Efraim.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 1, 'Sesudah Yosua mati, orang Israel bertanya kepada TUHAN: "Siapakah dari pada kami yang harus lebih dahulu maju menghadapi orang Kanaan untuk berperang melawan mereka?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 2, 'Firman TUHAN: "Suku Yehudalah yang harus maju; sesungguhnya telah Kuserahkan negeri itu ke dalam tangannya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 3, 'Lalu berkatalah Yehuda kepada Simeon, saudaranya itu: "Majulah bersama-sama dengan aku ke bagian yang telah diundikan kepadaku dan baiklah kita berperang melawan orang Kanaan, maka akupun akan maju bersama-sama dengan engkau ke bagian yang telah diundikan kepadamu." Lalu Simeon maju bersama-sama dengan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 4, 'Maka majulah suku Yehuda, lalu TUHAN menyerahkan orang Kanaan dan orang Feris ke dalam tangan mereka, dan mereka memukul kalah orang-orang itu dekat Bezek, sepuluh ribu orang banyaknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 5, 'Di Bezek mereka menjumpai Adoni-Bezek dan berperang melawan dia, dan mereka memukul kalah orang Kanaan dan orang Feris.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 6, 'Tetapi Adoni-Bezek melarikan diri, lalu mereka mengejarnya, menangkapnya dan memotong ibu jari dari tangannya dan dari kakinya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 7, 'Kata Adoni-Bezek: "Ada tujuh puluh raja dengan terpotong ibu jari tangan dan kakinya memungut sisa-sisa makanan di bawah mejaku; sesuai dengan yang kulakukan itu, demikianlah dibalaskan Allah kepadaku." Kemudian ia dibawa ke Yerusalem dan mati di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 8, 'Sesudah itu bani Yehuda berperang melawan Yerusalem, merebutnya lalu memukulnya dengan mata pedang dan memusnahkan kota itu dengan api.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 9, 'Kemudian bani Yehuda maju berperang melawan orang Kanaan, yang diam di pegunungan, di Tanah Negeb dan di Daerah Bukit.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 10, 'Lalu suku Yehuda bergerak menyerang orang Kanaan yang diam di Hebron?nama Hebron dahulu adalah Kiryat-Arba?dan memukul kalah Sesai, Ahiman dan Talmai.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 11, 'Dari sana mereka bergerak menyerang penduduk Debir. Nama Debir dahulu adalah Kiryat-Sefer.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 12, 'Berkatalah Kaleb: "Siapa yang mengalahkan dan merebut Kiryat-Sefer, kepadanya akan kuberikan Akhsa, anakku, menjadi isterinya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 13, 'Dan Otniel, anak Kenas adik Kaleb, merebut kota itu; lalu Kaleb memberikan Akhsa, anaknya, kepadanya menjadi isterinya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 14, 'Ketika perempuan itu tiba, dibujuknya suaminya untuk meminta sebidang ladang kepada ayahnya. Maka turunlah perempuan itu dari keledainya, lalu berkatalah Kaleb kepadanya: "Ada apa?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 15, 'Jawabnya kepadanya: "Berikanlah kepadaku suatu hadiah; telah kauberikan kepadaku tanah yang gersang, berikanlah juga kepadaku mata air." Lalu Kaleb memberikan kepadanya mata air yang di hulu dan mata air yang di hilir.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 16, 'Keturunan Hobab, ipar Musa, orang Keni itu, maju bersama-sama dengan bani Yehuda dari kota pohon korma ke padang gurun Yehuda di Tanah Negeb dekat Arad; lalu mereka menetap di antara penduduk di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 17, 'Yehuda maju bersama-sama dengan Simeon, saudaranya itu, lalu mereka memukul kalah orang Kanaan, penduduk Zefat; mereka menumpas kota itu. Sebab itu kota itu dinamai Horma.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 18, 'Selanjutnya suku Yehuda merebut Gaza dengan daerahnya, Askelon dengan daerahnya dan Ekron dengan daerahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 19, 'Dan TUHAN menyertai suku Yehuda, sehingga mereka menduduki pegunungan itu; tetapi mereka tidak dapat menghalau penduduk yang di lembah, sebab orang-orang ini mempunyai kereta-kereta besi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 20, 'Kepada Kaleb telah diberikan Hebron, seperti yang dikatakan Musa dahulu, dan dari sana telah dihalaukannya anak Enak yang tiga itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 21, 'Tetapi orang Yebus, penduduk kota Yerusalem, tidak dihalau oleh bani Benyamin, jadi orang Yebus itu masih diam bersama-sama dengan bani Benyamin di Yerusalem sampai sekarang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 22, 'Keturunan Yusuf juga maju menyerang Betel, dan TUHAN menyertai mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 23, 'Keturunan Yusuf menyuruh orang mengintai Betel itu?nama kota itu dahulu adalah Lus.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 24, 'Ketika pengintai-pengintai itu melihat seorang keluar dari kota itu, maka berkatalah mereka kepadanya: "Tolong tunjukkan bagaimana kami dapat memasuki kota ini, maka kami akan memperlakukan engkau sebagai sahabat."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 25, 'Lalu ditunjukkannyalah kepada mereka bagaimana mereka dapat memasuki kota itu, dan mereka memukul kota itu dengan mata pedang, tetapi orang itu dengan seluruh kaumnya dibiarkan mereka pergi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 26, 'Orang itu pergi ke negeri orang Het dan mendirikan di sana sebuah kota yang dinamainya Lus. Demikianlah nama kota itu sampai sekarang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 27, 'Suku Manasye tidak menghalau penduduk Bet-Sean dan penduduk segala anak kotanya, penduduk Taanakh dengan segala anak kotanya, penduduk Dor dengan segala anak kotanya, penduduk Yibleam dengan segala anak kotanya, dan penduduk Megido dengan segala anak kotanya, sebab orang Kanaan itu berkeras untuk tetap diam di negeri itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 28, 'Setelah orang Israel menjadi kuat, mereka membuat orang Kanaan itu menjadi orang rodi dan tidak menghalau mereka sama sekali.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 29, 'Suku Efraimpun tidak menghalau orang Kanaan yang diam di Gezer, sehingga orang Kanaan itu tetap diam di tengah-tengah mereka di Gezer.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 30, 'Suku Zebulon tidak menghalau penduduk Kitron dan penduduk Nahalol, sehingga orang Kanaan itu tetap diam di tengah-tengah mereka, walaupun sebagai orang rodi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 31, 'Suku Asyer tidak menghalau penduduk Ako, penduduk Sidon serta Ahlab, Akhzib, Helba, Afek dan Rehob,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 32, 'sehingga orang Asyer itu diam di tengah-tengah orang Kanaan, penduduk asli di negeri itu, sebab orang-orang itu tidak dihalaunya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 33, 'Suku Naftali tidak menghalau penduduk Bet-Semes dan penduduk Bet-Anat, sehingga mereka diam di tengah-tengah orang Kanaan, penduduk asli di negeri itu; tetapi penduduk Bet-Semes dan Bet-Anat itu menjadi orang rodi bagi mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 34, 'Orang Amori mendesak bani Dan ke sebelah pegunungan dan tidak membiarkan mereka turun ke lembah,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 35, 'dan orang Amori itu berkeras untuk tetap diam di Har-Heres, di Ayalon dan di Saalbim, walaupun mereka mendapat tekanan berat dari keturunan Yusuf, sebab mereka menjadi orang rodi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 1, 36, 'Daerah orang Amori itu mulai dari pendakian Akrabim, dari Sela, terus ke atas.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 1, 'Lalu Malaikat TUHAN pergi dari Gilgal ke Bokhim dan berfirman: "Telah Kutuntun kamu keluar dari Mesir dan Kubawa ke negeri yang Kujanjikan dengan bersumpah kepada nenek moyangmu, dan Aku telah berfirman: Aku tidak akan membatalkan perjanjian-Ku dengan kamu untuk selama-lamanya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 2, 'tetapi janganlah kamu mengikat perjanjian dengan penduduk negeri ini; mezbah mereka haruslah kamu robohkan. Tetapi kamu tidak mendengarkan firman-Ku. Mengapa kamu perbuat demikian?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 3, 'Lagi Aku telah berfirman: Aku tidak akan menghalau orang-orang itu dari depanmu, tetapi mereka akan menjadi musuhmu dan segala allah mereka akan menjadi jerat bagimu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 4, 'Setelah Malaikat TUHAN mengucapkan firman itu kepada seluruh Israel, menangislah bangsa itu dengan keras.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 5, 'Maka tempat itu dinamai Bokhim. Lalu mereka mempersembahkan korban di sana kepada TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 6, 'Setelah Yosua melepas bangsa itu pergi, maka pergilah orang Israel itu, masing-masing ke milik pusakanya, untuk memiliki negeri itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 7, 'Dan bangsa itu beribadah kepada TUHAN sepanjang zaman Yosua dan sepanjang zaman para tua-tua yang hidup lebih lama dari pada Yosua, dan yang telah melihat segenap perbuatan yang besar, yang dilakukan TUHAN bagi orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 8, 'Dan Yosua bin Nun, hamba TUHAN itu, mati pada umur seratus sepuluh tahun;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 9, 'ia dikuburkan di daerah milik pusakanya di Timnat-Heres, di pegunungan Efraim, di sebelah utara gunung Gaas.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 10, 'Setelah seluruh angkatan itu dikumpulkan kepada nenek moyangnya, bangkitlah sesudah mereka itu angkatan yang lain, yang tidak mengenal TUHAN ataupun perbuatan yang dilakukan-Nya bagi orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 11, 'Lalu orang Israel melakukan apa yang jahat di mata TUHAN dan mereka beribadah kepada para Baal.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 12, 'Mereka meninggalkan TUHAN, Allah nenek moyang mereka yang telah membawa mereka keluar dari tanah Mesir, lalu mengikuti allah lain, dari antara allah bangsa-bangsa di sekeliling mereka, dan sujud menyembah kepadanya, sehingga mereka menyakiti hati TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 13, 'Demikianlah mereka meninggalkan TUHAN dan beribadah kepada Baal dan para Asytoret.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 14, 'Maka bangkitlah murka TUHAN terhadap orang Israel. Ia menyerahkan mereka ke dalam tangan perampok dan menjual mereka kepada musuh di sekeliling mereka, sehingga mereka tidak sanggup lagi menghadapi musuh mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 15, 'Setiap kali mereka maju, tangan TUHAN melawan mereka dan mendatangkan malapetaka kepada mereka, sesuai dengan apa yang telah diperingatkan kepada mereka oleh TUHAN dengan sumpah, sehingga mereka sangat terdesak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 16, 'Maka TUHAN membangkitkan hakim-hakim, yang menyelamatkan mereka dari tangan perampok itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 17, 'Tetapi juga para hakim itu tidak mereka hiraukan, karena mereka berzinah dengan mengikuti allah lain dan sujud menyembah kepadanya. Mereka segera menyimpang dari jalan yang ditempuh oleh nenek moyangnya yang mendengarkan perintah TUHAN; mereka melakukan yang tidak patut.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 18, 'Setiap kali apabila TUHAN membangkitkan seorang hakim bagi mereka, maka TUHAN menyertai hakim itu dan menyelamatkan mereka dari tangan musuh mereka selama hakim itu hidup; sebab TUHAN berbelas kasihan mendengar rintihan mereka karena orang-orang yang mendesak dan menindas mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 19, 'Tetapi apabila hakim itu mati, kembalilah mereka berlaku jahat, lebih jahat dari nenek moyang mereka, dengan mengikuti allah lain, beribadah kepadanya dan sujud menyembah kepadanya; dalam hal apapun mereka tidak berhenti dengan perbuatan dan kelakuan mereka yang tegar itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 20, 'Apabila murka TUHAN bangkit terhadap orang Israel, berfirmanlah Ia: "Karena bangsa ini melanggar perjanjian yang telah Kuperintahkan kepada nenek moyang mereka, dan tidak mendengarkan firman-Ku,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 21, 'maka Akupun tidak mau menghalau lagi dari depan mereka satupun dari bangsa-bangsa yang ditinggalkan Yosua pada waktu matinya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 22, 'supaya dengan perantaraan bangsa-bangsa itu Aku mencobai orang Israel, apakah mereka tetap hidup menurut jalan yang ditunjukkan TUHAN, seperti yang dilakukan oleh nenek moyang mereka, atau tidak."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 2, 23, 'Demikianlah TUHAN membiarkan bangsa-bangsa itu tinggal dengan tidak segera menghalau mereka; mereka tidak diserahkan-Nya ke dalam tangan Yosua.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 1, 'Inilah bangsa-bangsa yang dibiarkan TUHAN tinggal untuk mencobai orang Israel itu dengan perantaraan mereka, yakni semua orang Israel yang tidak mengenal perang Kanaan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 2, '?Maksudnya hanyalah, supaya keturunan-keturunan orang Israel yang tidak mengenal perang yang sudah-sudah, dilatih berperang oleh TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 3, 'Yang tinggal ialah kelima raja kota orang Filistin dan semua orang Kanaan, orang Sidon dan orang Hewi, yang mendiami pegunungan Libanon, dari gunung Baal-Hermon sampai ke jalan yang menuju ke Hamat.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 4, 'Mereka itu ada di sana, supaya Ia mencobai orang Israel dengan perantaraan mereka untuk mengetahui, apakah mereka mendengarkan perintah yang diberikan TUHAN kepada nenek moyang mereka dengan perantaraan Musa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 5, 'Demikianlah orang Israel itu diam di tengah-tengah orang Kanaan, orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 6, 'Mereka mengambil anak-anak perempuan, orang-orang itu menjadi isteri mereka dan memberikan anak-anak perempuan mereka kepada anak-anak lelaki orang-orang itu, serta beribadah kepada allah orang-orang itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 7, 'Orang Israel melakukan apa yang jahat di mata TUHAN, mereka melupakan TUHAN, Allah mereka, dan beribadah kepada para Baal dan para Asyera.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 8, 'Lalu bangkitlah murka TUHAN terhadap orang Israel, sehingga Ia menjual mereka kepada Kusyan-Risyataim, raja Aram-Mesopotamia dan orang Israel menjadi takluk kepada Kusyan-Risyataim delapan tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 9, 'Lalu berserulah orang Israel kepada TUHAN, maka TUHAN membangkitkan seorang penyelamat bagi orang Israel, yakni Otniel, anak Kenas adik Kaleb.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 10, 'Roh TUHAN menghinggapi dia dan ia menghakimi orang Israel. Ia maju berperang, lalu TUHAN menyerahkan Kusyan-Risyataim, raja Aram, ke dalam tangannya, sehingga ia mengalahkan Kusyan-Risyataim.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 11, 'Lalu amanlah negeri itu empat puluh tahun lamanya. Kemudian matilah Otniel anak Kenas.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 12, 'Tetapi orang Israel melakukan pula apa yang jahat di mata TUHAN; lalu Eglon, raja Moab, diberi TUHAN kuasa atas orang Israel, oleh sebab mereka telah melakukan apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 13, 'Raja ini mengajak bani Amon dan bani Amalek menjadi sekutunya. Lalu majulah ia dan memukul orang Israel kalah. Kota pohon korma diduduki mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 14, 'Delapan belas tahun lamanya orang Israel menjadi takluk kepada Eglon, raja Moab.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 15, 'Lalu orang Israel berseru kepada TUHAN, maka TUHAN membangkitkan bagi mereka seorang penyelamat yakni Ehud, anak Gera, orang Benyamin, seorang yang kidal. Dengan perantaraannya orang Israel biasa mengirimkan upeti kepada Eglon, raja Moab.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 16, 'Dan Ehud membuat pedang yang bermata dua, yang panjangnya hampir sehasta, disandangnyalah itu di bawah pakaiannya, pada pangkal paha kanannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 17, 'Kemudian ia menyampaikan upeti kepada Eglon, raja Moab. Adapun Eglon itu seorang yang sangat gendut.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 18, 'Setelah Ehud selesai menyampaikan upeti itu, disuruhnya pembawa-pembawa upeti itu pulang,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 19, 'tetapi ia sendiri berhenti pada batu-batu berpahat yang di dekat Gilgal, dan kembali menghadap raja. Berkatalah ia: "Ada pesan rahasia yang kubawa untuk tuanku, ya raja." Kata Eglon: "Diamlah dahulu!" Maka semua orang yang berdiri di depannya itu pergi ke luar.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 20, 'Lalu Ehud masuk mendapatkan dia, sedang ia duduk sendirian di kamar atas di rumah peranginannya. Berkatalah Ehud: "Ada firman Allah yang kubawa untuk tuanku." Lalu bangunlah ia berdiri dari tempat duduknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 21, 'Kemudian Ehud mengulurkan tangan kirinya, dihunusnya pedang itu dari pangkal paha kanannya dan ditikamkannya ke perut raja,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 22, 'sehingga hulunya beserta mata pedang itu masuk. Lemak menutupi mata pedang itu, sebab pedang itu tidak dicabutnya dari perut raja. Lalu keluarlah ia melalui pintu belakang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 23, 'Demikianlah Ehud sampai ke serambi; pintu kamar atas itu ditutup dan dikuncinya setelah ia keluar.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 24, 'Baru saja ia keluar, datanglah hamba-hamba raja melihat, tetapi pintu kamar atas itu terkunci. Lalu berkatalah mereka: "Tentulah ia membuang air di kamar rumah peranginan itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 25, 'Lalu mereka menunggu-nunggu sampai menjadi bingung, tetapi raja tidak membuka pintu kamar atas itu. Kemudian mereka mengambil kunci, membuka pintu, maka tampaklah tuan mereka mati tergeletak di lantai.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 26, 'Sedang mereka berlambat-lambat, Ehud meloloskan diri; ia lewat dari batu-batu berpahat dan meloloskan diri ke arah Seira.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 27, 'Setelah ia sampai ke sana, ditiupnyalah sangkakala di pegunungan Efraim, lalu turunlah orang Israel bersama-sama dengan dia dari pegunungan itu, dan ia sendiri di depan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 28, 'Berkatalah ia kepada mereka: "Ikutlah aku, sebab TUHAN telah menyerahkan musuhmu, orang-orang Moab itu, ke dalam tanganmu." Maka turunlah mereka mengikuti dia, lalu mereka merebut tempat penyeberangan sungai Yordan ke Moab dan tidak seorangpun dibiarkan mereka menyeberang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 29, 'Pada waktu itu mereka menewaskan kira-kira sepuluh ribu orang dari Moab, semuanya orang yang tegap dan tangkas, seorangpun tidak ada yang lolos.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 30, 'Demikianlah pada hari itu Moab ditundukkan oleh Israel, maka amanlah tanah itu, delapan puluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 3, 31, 'Sesudah dia, bangkitlah Samgar bin Anat; ia menewaskan orang Filistin dengan tongkat penghalau lembu, enam ratus orang banyaknya. Demikianlah ia juga menyelamatkan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 1, 'Setelah Ehud mati, orang Israel melakukan pula apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 2, 'Lalu TUHAN menyerahkan mereka ke dalam tangan Yabin, raja Kanaan, yang memerintah di Hazor. Panglima tentaranya ialah Sisera yang diam di Haroset-Hagoyim.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 3, 'Lalu orang Israel berseru kepada TUHAN, sebab Sisera mempunyai sembilan ratus kereta besi dan dua puluh tahun lamanya ia menindas orang Israel dengan keras.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 4, 'Pada waktu itu Debora, seorang nabiah, isteri Lapidot, memerintah sebagai hakim atas orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 5, 'Ia biasa duduk di bawah pohon korma Debora antara Rama dan Betel di pegunungan Efraim, dan orang Israel menghadap dia untuk berhakim kepadanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 6, 'Ia menyuruh memanggil Barak bin Abinoam dari Kedesh di daerah Naftali, lalu berkata kepadanya: "Bukankah TUHAN, Allah Israel, memerintahkan demikian: Majulah, bergeraklah menuju gunung Tabor dengan membawa sepuluh ribu orang bani Naftali dan bani Zebulon bersama-sama dengan engkau,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 7, 'dan Aku akan menggerakkan Sisera, panglima tentara Yabin, dengan kereta-keretanya dan pasukan-pasukannya menuju engkau ke sungai Kison dan Aku akan menyerahkan dia ke dalam tanganmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 8, 'Jawab Barak kepada Debora: "Jika engkau turut maju akupun maju, tetapi jika engkau tidak turut maju akupun tidak maju."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 9, 'Kata Debora: "Baik, aku turut! Hanya, engkau tidak akan mendapat kehormatan dalam perjalanan yang engkau lakukan ini, sebab TUHAN akan menyerahkan Sisera ke dalam tangan seorang perempuan." Lalu Debora bangun berdiri dan pergi bersama-sama dengan Barak ke Kedesh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 10, 'Barak mengerahkan suku Zebulon dan suku Naftali ke Kedesh, maka sepuluh ribu orang maju mengikuti dia; juga Debora maju bersama-sama dengan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 11, 'Adapun Heber, orang Keni itu, telah memisahkan diri dari suku Keni, dari anak-anak Hobab ipar Musa, dan telah berpindah-pindah memasang kemahnya sampai ke pohon tarbantin di Zaanaim yang dekat Kedesh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 12, 'Setelah dikabarkan kepada Sisera, bahwa Barak bin Abinoam telah maju ke gunung Tabor,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 13, 'dikerahkannyalah segala keretanya, sembilan ratus kereta besi, dan seluruh rakyat yang bersama-sama dengan dia, dari Haroset-Hagoyim ke sungai Kison.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 14, 'Lalu berkatalah Debora kepada Barak: "Bersiaplah, sebab inilah harinya TUHAN menyerahkan Sisera ke dalam tanganmu. Bukankah TUHAN telah maju di depan engkau?" Lalu turunlah Barak dari gunung Tabor dan sepuluh ribu orang mengikuti dia,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 15, 'dan TUHAN mengacaukan Sisera serta segala keretanya dan seluruh tentaranya oleh mata pedang di depan Barak, sehingga Sisera turun dari keretanya dan melarikan diri dengan berjalan kaki.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 16, 'Lalu Barak mengejar kereta-kereta dan tentara itu sampai ke Haroset-Hagoyim, dan seluruh tentara Sisera tewas oleh mata pedang; tidak ada seorangpun yang tinggal hidup.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 17, 'Tetapi Sisera dengan berjalan kaki melarikan diri ke kemah Yael, isteri Heber, orang Keni itu, sebab ada perhubungan baik antara Yabin, raja Hazor, dengan keluarga Heber, orang Keni itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 18, 'Yael itupun keluar mendapatkan Sisera, dan berkata kepadanya: "Singgahlah, tuanku, silakan masuk. Jangan takut." Lalu singgahlah ia ke dalam kemah perempuan itu dan perempuan itu menutupi dia dengan selimut.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 19, 'Kemudian berkatalah ia kepada perempuan itu: "Berilah kiranya aku minum air sedikit, aku haus." Lalu perempuan itu membuka kirbat susu, diberinyalah dia minum dan diselimutinya pula.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 20, 'Lagi katanya kepada perempuan itu: "Berdirilah di depan pintu kemah dan apabila ada orang datang dan bertanya kepadamu: Ada orang di sini?, maka jawablah: Tidak ada."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 21, 'Tetapi Yael, isteri Heber, mengambil patok kemah, diambilnya pula palu, mendekatinya diam-diam, lalu dilantaknyalah patok itu masuk ke dalam pelipisnya sampai tembus ke tanah?sebab ia telah tidur nyenyak karena lelahnya?maka matilah orang itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 22, 'Pada waktu itu muncullah Barak yang mengejar Sisera. Keluarlah Yael mendapatkan dia dan berkata kepadanya: "Mari, aku akan menunjukkan kepadamu orang yang kaucari itu." Lalu masuklah Barak ke dalam dan tampaklah Sisera mati tergeletak dengan patok dalam pelipisnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 23, 'Demikianlah Allah pada hari itu menundukkan Yabin, raja Kanaan, di depan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 4, 24, 'Dan kekuasaan orang Israel kian keras menekan Yabin, raja Kanaan, sampai mereka melenyapkan Yabin, raja Kanaan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 1, 'Pada hari itu bernyanyilah Debora dan Barak bin Abinoam, demikian:', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 2, 'Karena pahlawan-pahlawan di Israel siap berperang, karena bangsa itu menawarkan dirinya dengan sukarela, pujilah TUHAN!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 3, 'Dengarlah, ya raja-raja! Pasanglah telingamu, ya pemuka-pemuka! Kalau aku, aku mau bernyanyi bagi TUHAN, bermazmur bagi TUHAN, Allah Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 4, 'TUHAN, ketika Engkau bergerak dari Seir, ketika Engkau melangkah maju dari daerah Edom, bergoncanglah bumi, tirislah juga langit, juga awan tiris airnya;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 5, 'gunung-gunung?yakni Sinai?bergoyang di hadapan TUHAN, di hadapan TUHAN, Allah Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 6, 'Dalam zaman Samgar bin Anat, dalam zaman Yael, kafilah tidak ada lagi dan orang-orang yang dalam perjalanan terpaksa menempuh jalan yang berbelit-belit.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 7, 'Penduduk pedusunan diam-diam saja di Israel, ya mereka diam-diam, sampai engkau bangkit, Debora, bangkit sebagai ibu di Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 8, 'Ketika orang memilih allah baru, maka terjadilah perang di pintu gerbang. Sesungguhnya, perisai ataupun tombak tidak terlihat di antara empat puluh ribu orang di Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 9, 'Hatiku tertuju kepada para panglima Israel, kepada mereka yang menawarkan dirinya dengan sukarela di antara bangsa itu. Pujilah TUHAN!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 10, 'Kamu, yang menunggang keledai betina putih, kamu, yang duduk di atas permadani, kamu, yang berjalan di jalan, ceriterakanlah hal itu!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 11, 'Di tempat-tempat penimbaan air, menurut suara orang-orang yang berdendang, di sanalah orang menyanyikan perbuatan TUHAN yang adil, perbuatan-Nya yang adil terhadap orang-orang-Nya di pedusunan di Israel. Pada waktu itu turunlah umat TUHAN ke pintu gerbang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 12, 'Bangunlah, bangunlah, Debora! Bangunlah, bangunlah, nyanyikanlah suatu nyanyian! Bangkitlah, Barak! dan giringlah tawananmu, hai anak Abinoam!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 13, 'Lalu turunlah para bangsawan yang terluput, umat TUHAN turun bagi-Nya sebagai pahlawan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 14, 'Dari suku Efraim mereka datang ke lembah, mengikuti engkau, ya suku Benyamin, dengan laskarmu; dari suku Makhir turunlah para panglima dan dari suku Zebulon orang-orang pembawa tongkat pengerah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 15, 'Juga para pemimpin suku Isakhar menyertai Debora, dan seperti Isakhar, demikianlah Naftali menyertai Barak. Mereka menyusul dia dan menyerbu masuk lembah. Tetapi pihak pasukan-pasukan suku Ruben ada banyak pertimbangan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 16, 'Mengapa engkau tinggal duduk di antara kandang-kandang sambil mendengarkan seruling pemanggil kawanan? Di pihak pasukan-pasukan suku Ruben ada banyak pertimbangan!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 17, 'Orang Gilead tinggal diam di seberang sungai Yordan; dan suku Dan, mengapa mereka tinggal dekat kapal-kapal? Suku Asyer duduk di tepi pantai laut, tinggal diam di teluk-teluknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 18, 'Tetapi suku Zebulon ialah bangsa yang berani mempertaruhkan nyawanya, demikian juga suku Naftali, di tempat-tempat tinggi di padang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 19, 'Raja-raja datang dan berperang, pada waktu itu raja-raja Kanaan berperang dekat Taanakh, pada mata air di Megido, tetapi perak sebagai rampasan tidak diperoleh mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 20, 'Dari langit berperang bintang-bintang, dari peredarannya mereka memerangi Sisera.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 21, 'Sungai Kison menghanyutkan musuh, Kison, sungai yang terkenal dari dahulu kala itu. ?Majulah sekuat tenaga, hai jiwaku! ?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 22, 'Ketika itu menderaplah telapak kuda, karena berpacu lari kuda-kudanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 23, '"Kutukilah kota Meros!" firman Malaikat TUHAN, "kutukilah habis-habisan penduduknya, karena mereka tidak datang membantu TUHAN, membantu TUHAN sebagai pahlawan."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 24, 'Diberkatilah Yael, isteri Heber, orang Keni itu, melebihi perempuan-perempuan lain, diberkatilah ia, melebihi perempuan-perempuan yang di dalam kemah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 25, 'Air diminta orang itu, tetapi susu diberikannya; dalam cawan yang indah disuguhkannya dadih.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 26, 'Tangannya diulurkannya mengambil patok, tangan kanannya mengambil tukul tukang, ditukulnya Sisera, dihancurkannya kepalanya, diremukkan dan ditembusnya pelipisnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 27, 'Dekat kakinya orang itu rebah, tewas tergeletak, dekat kakinya orang itu rebah dan tewas, di tempat ia rebah, di sanalah orang itu tewas, digagahi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 28, 'Dari jendela ibu Sisera menjenguk dan berseru dari tingkap: "Mengapa keretanya tak kunjung datang? Mengapa kereta-keretanya belum kedengaran?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 29, 'Yang paling bijak di antara dayang-dayangnya menjawabnya, dan ia sendiri juga membalas perkataannya itu:', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 30, '"Bukankah mereka mendapat jarahan dan membagi-baginya, gadis seorang dua untuk setiap orang jarahan kain berwarna sehelai dua untuk Sisera, jarahan kain sulaman aneka warna sehelai dua untuk leherku?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 5, 31, 'Demikianlah akan binasa segala musuh-Mu, ya TUHAN! Tetapi orang yang mengasihi-Nya bagaikan matahari terbit dalam kemegahannya. Lalu amanlah negeri itu empat puluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 1, 'Tetapi orang Israel melakukan apa yang jahat di mata TUHAN; sebab itu TUHAN menyerahkan mereka ke dalam tangan orang Midian, tujuh tahun lamanya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 2, 'dan selama itu orang Midian berkuasa atas orang Israel. Karena takutnya kepada orang Midian itu, maka orang Israel membuat tempat-tempat perlindungan di pegunungan, yakni gua-gua dan kubu-kubu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 3, 'Setiap kali orang Israel selesai menabur, datanglah orang Midian, orang Amalek dan orang-orang dari sebelah timur, lalu maju mendatangi mereka;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 4, 'berkemahlah orang-orang itu di daerah mereka, dan memusnahkan hasil tanah itu sampai ke dekat Gaza, dan tidak meninggalkan bahan makanan apapun di Israel, juga domba, atau lembu atau keledaipun tidak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 5, 'Sebab orang-orang itu datang maju dengan ternaknya dan kemahnya, dan datangnya itu berbanyak-banyak seperti belalang. Orang-orangnya dan unta-untanya tidak terhitung banyaknya, sekaliannya datang ke negeri itu untuk memusnahkannya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 6, 'sehingga orang Israel menjadi sangat melarat oleh perbuatan orang Midian itu. Lalu berserulah orang Israel kepada TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 7, 'Ketika orang Israel berseru kepada TUHAN karena orang Midian itu,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 8, 'maka TUHAN mengutus seorang nabi kepada orang Israel, yang berkata kepada mereka: "Beginilah firman TUHAN, Allah Israel: Akulah yang menuntun kamu keluar dari Mesir dan yang membawa kamu keluar dari rumah perbudakan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 9, 'Aku melepaskan kamu dari tangan orang Mesir dan dari tangan semua orang yang menindas kamu, bahkan Aku menghalau mereka dari depanmu dan negeri mereka Kuberikan kepadamu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 10, 'Dan Aku telah berfirman kepadamu: Akulah TUHAN, Allahmu, maka janganlah kamu menyembah allah orang Amori, yang negerinya kamu diami ini. Tetapi kamu tidak mendengarkan firman-Ku itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 11, 'Kemudian datanglah Malaikat TUHAN dan duduk di bawah pohon tarbantin di Ofra, kepunyaan Yoas, orang Abiezer itu, sedang Gideon, anaknya, mengirik gandum dalam tempat pemerasan anggur agar tersembunyi bagi orang Midian.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 12, 'Malaikat TUHAN menampakkan diri kepadanya dan berfirman kepadanya, demikian: "TUHAN menyertai engkau, ya pahlawan yang gagah berani."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 13, 'Jawab Gideon kepada-Nya: "Ah, tuanku, jika TUHAN menyertai kami, mengapa semuanya ini menimpa kami? Di manakah segala perbuatan-perbuatan-yang ajaib yang diceritakan oleh nenek moyang kami kepada kami, ketika mereka berkata: Bukankah TUHAN telah menuntun kita keluar dari Mesir? Tetapi sekarang TUHAN membuang kami dan menyerahkan kami ke dalam cengkeraman orang Midian."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 14, 'Lalu berpalinglah TUHAN kepadanya dan berfirman: "Pergilah dengan kekuatanmu ini dan selamatkanlah orang Israel dari cengkeraman orang Midian. Bukankah Aku mengutus engkau!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 15, 'Tetapi jawabnya kepada-Nya: "Ah Tuhanku, dengan apakah akan kuselamatkan orang Israel? Ketahuilah, kaumku adalah yang paling kecil di antara suku Manasye dan akupun seorang yang paling muda di antara kaum keluargaku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 16, 'Berfirmanlah TUHAN kepadanya: "Tetapi Akulah yang menyertai engkau, sebab itu engkau akan memukul kalah orang Midian itu sampai habis."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 17, 'Maka jawabnya kepada-Nya: "Jika sekiranya aku mendapat kasih karunia di mata-Mu, maka berikanlah kepadaku tanda, bahwa Engkau sendirilah yang berfirman kepadaku.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 18, 'Janganlah kiranya pergi dari sini, sampai aku datang kepada-Mu membawa persembahanku dan meletakkannya di hadapan-Mu." Firman-Nya: "Aku akan tinggal, sampai engkau kembali."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 19, 'Masuklah Gideon ke dalam, lalu mengolah seekor anak kambing dan roti yang tidak beragi dari seefa tepung; ditaruhnya daging itu ke dalam bakul dan kuahnya ke dalam periuk, dibawanya itu kepada-Nya ke bawah pohon tarbantin, lalu disuguhkannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 20, 'Berfirmanlah Malaikat Allah kepadanya: "Ambillah daging dan roti yang tidak beragi itu, letakkanlah ke atas batu ini, dan curahkan kuahnya." Maka diperbuatnya demikian.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 21, 'Dan Malaikat TUHAN mengulurkan tongkat yang ada di tangan-Nya; dengan ujungnya disinggung-Nya daging dan roti itu; maka timbullah api dari batu itu dan memakan habis daging dan roti itu. Kemudian hilanglah Malaikat TUHAN dari pandangannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 22, 'Maka tahulah Gideon, bahwa itulah Malaikat TUHAN, lalu katanya: "Celakalah aku, Tuhanku ALLAH! sebab memang telah kulihat Malaikat TUHAN dengan berhadapan muka."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 23, 'Tetapi berfirmanlah TUHAN kepadanya: "Selamatlah engkau! Jangan takut, engkau tidak akan mati."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 24, 'Lalu Gideon mendirikan mezbah di sana bagi TUHAN dan menamainya: TUHAN itu keselamatan. Mezbah itu masih ada sampai sekarang di Ofra, kota orang Abiezer.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 25, 'Pada malam itu juga TUHAN berfirman kepadanya: "Ambillah seekor lembu jantan kepunyaan ayahmu, yakni lembu jantan yang kedua, berumur tujuh tahun, runtuhkanlah mezbah Baal kepunyaan ayahmu dan tebanglah tiang berhala yang di dekatnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 26, 'Kemudian dirikanlah mezbah bagi TUHAN, Allahmu, di atas kubu pertahanan ini dengan disusun baik, lalu ambillah lembu jantan yang kedua dan persembahkanlah korban bakaran dengan kayu tiang berhala yang akan kautebang itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 27, 'Kemudian Gideon membawa sepuluh orang hambanya dan diperbuatnyalah seperti yang difirmankan TUHAN kepadanya. Tetapi karena ia takut kepada kaum keluarganya dan kepada orang-orang kota itu untuk melakukan hal itu pada waktu siang, maka dilakukannyalah pada waktu malam.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 28, 'Ketika orang-orang kota itu bangun pagi-pagi, tampaklah telah dirobohkan mezbah Baal itu, telah ditebang tiang berhala yang di dekatnya dan telah dikorbankan lembu jantan yang kedua di atas mezbah yang didirikan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 29, 'Berkatalah mereka seorang kepada yang lain: "Siapakah yang melakukan hal itu?" Setelah diperiksa dan ditanya-tanya, maka kata orang: "Gideon bin Yoas, dialah yang melakukan hal itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 30, 'Sesudah itu berkatalah orang-orang kota itu kepada Yoas: "Bawalah anakmu itu ke luar; dia harus mati, karena ia telah merobohkan mezbah Baal dan karena ia telah menebang tiang berhala yang di dekatnya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 31, 'Tetapi jawab Yoas kepada semua orang yang mengerumuninya itu: "Kamu mau berjuang membela Baal? Atau kamu mau menolong dia? Siapa yang berjuang membela Baal akan dihukum mati sebelum pagi. Jika Baal itu allah, biarlah ia berjuang membela dirinya sendiri, setelah mezbahnya dirobohkan orang."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 32, 'Dan pada hari itu diberikan oranglah nama Yerubaal kepada Gideon, karena kata orang: "Biarlah Baal berjuang dengan dia, setelah dirobohkannya mezbahnya itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 33, 'Seluruh orang Midian dan orang Amalek dan orang-orang dari sebelah timur telah berkumpul bersama-sama; mereka telah menyeberang dan berkemah di lembah Yizreel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 34, 'Pada waktu itu Roh TUHAN menguasai Gideon; ditiupnyalah sangkakala dan orang-orang Abiezer dikerahkan untuk mengikuti dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 35, 'Juga dikirimnya pesan kepada seluruh suku Manasye dan orang-orang inipun dikerahkan untuk mengikuti dia. Dikirimnya pula pesan kepada suku Asyer, Zebulon dan Naftali, dan orang-orang inipun maju untuk menggabungkan diri dengan mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 36, 'Kemudian berkatalah Gideon kepada Allah: "Jika Engkau mau menyelamatkan orang Israel dengan perantaraanku, seperti yang Kaufirmankan itu,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 37, 'maka aku membentangkan guntingan bulu domba di tempat pengirikan; apabila hanya di atas guntingan bulu itu ada embun, tetapi seluruh tanah di situ tinggal kering, maka tahulah aku, bahwa Engkau mau menyelamatkan orang Israel dengan perantaraanku, seperti yang Kaufirmankan."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 38, 'Dan demikianlah terjadi; sebab keesokan harinya pagi-pagi ia bangun, dipulasnya guntingan bulu itu dan diperasnya air embun dari guntingan bulu itu, secawan penuh air.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 39, 'Lalu berkatalah Gideon kepada Allah: "Janganlah kiranya murka-Mu bangkit terhadap aku, apabila aku berkata lagi, sekali ini saja; biarkanlah aku satu kali lagi saja mengambil percobaan dengan guntingan bulu itu: sekiranya yang kering hanya guntingan bulu itu, dan di atas seluruh tanah itu ada embun."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 6, 40, 'Dan demikianlah diperbuat Allah pada malam itu, sebab hanya guntingan bulu itu yang kering, dan di atas seluruh tanah itu ada embun.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 1, 'Adapun Yerubaal?itulah Gideon?bangun pagi-pagi dengan segala rakyat yang bersama-sama dengan dia, lalu mereka berkemah dekat mata air Harod; perkemahan orang Midian itu ada di sebelah utaranya, dekat bukit More, di lembah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 2, 'Berfirmanlah TUHAN kepada Gideon: "Terlalu banyak rakyat yang bersama-sama dengan engkau itu dari pada yang Kuhendaki untuk menyerahkan orang Midian ke dalam tangan mereka, jangan-jangan orang Israel memegah-megahkan diri terhadap Aku, sambil berkata: Tanganku sendirilah yang menyelamatkan aku.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 3, 'Maka sekarang, serukanlah kepada rakyat itu, demikian: Siapa yang takut dan gentar, biarlah ia pulang, enyah dari pegunungan Gilead." Lalu pulanglah dua puluh dua ribu orang dari rakyat itu dan tinggallah sepuluh ribu orang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 4, 'Tetapi TUHAN berfirman kepada Gideon: "Masih terlalu banyak rakyat; suruhlah mereka turun minum air, maka Aku akan menyaring mereka bagimu di sana. Siapa yang Kufirmankan kepadamu: Inilah orang yang akan pergi bersama-sama dengan engkau, dialah yang akan pergi bersama-sama dengan engkau, tetapi barangsiapa yang Kufirmankan kepadamu: Inilah orang yang tidak akan pergi bersama-sama dengan engkau, dialah yang tidak akan pergi."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 5, 'Lalu Gideon menyuruh rakyat itu turun minum air, dan berfirmanlah TUHAN kepadanya: "Barangsiapa yang menghirup air dengan lidahnya seperti anjing menjilat, haruslah kaukumpulkan tersendiri, demikian juga semua orang yang berlutut untuk minum."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 6, 'Jumlah orang yang menghirup dengan membawa tangannya ke mulutnya, ada tiga ratus orang, tetapi yang lain dari rakyat itu semuanya berlutut minum air.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 7, 'Lalu berfirmanlah TUHAN kepada Gideon: "Dengan ketiga ratus orang yang menghirup itu akan Kuselamatkan kamu: Aku akan menyerahkan orang Midian ke dalam tanganmu; tetapi yang lain dari rakyat itu semuanya boleh pergi, masing-masing ke tempat kediamannya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 8, 'Dari rakyat itu mereka mengambil bekal dan sangkakala; demikianlah seluruh orang Israel disuruhnya pergi, masing-masing ke kemahnya, tetapi ketiga ratus orang itu ditahannya. Adapun perkemahan orang Midian ada di bawahnya, di lembah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 9, 'Pada malam itu berfirmanlah TUHAN kepadanya: "Bangunlah, turunlah menyerbu perkemahan itu, sebab telah Kuserahkan itu ke dalam tanganmu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 10, 'Tetapi jika engkau takut untuk turun menyerbu, turunlah bersama dengan Pura, bujangmu, ke perkemahan itu;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 11, 'maka kaudengarlah apa yang mereka katakan; kemudian engkau akan mendapat keberanian untuk turun menyerbu perkemahan itu." Lalu turunlah ia bersama dengan Pura, bujangnya itu, sampai kepada penjagaan terdepan laskar di perkemahan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 12, 'Adapun orang Midian dan orang Amalek dan semua orang dari sebelah timur itu bergelimpangan di lembah itu, seperti belalang banyaknya, dan unta mereka tidak terhitung, seperti pasir di tepi laut banyaknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 13, 'Ketika Gideon sampai ke situ, kebetulan ada seorang menceritakan mimpinya kepada temannya, katanya: "Aku bermimpi: tampak sekeping roti jelai terguling masuk ke perkemahan orang Midian; setelah sampai ke kemah ini, dilanggarnyalah kemah ini, sehingga roboh, dan dibongkar-bangkirkannya, demikianlah kemah ini habis runtuh."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 14, 'Lalu temannya menjawab: "Ini tidak lain dari pedang Gideon bin Yoas, orang Israel itu; Allah telah menyerahkan orang Midian dan seluruh perkemahan ini ke dalam tangannya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 15, 'Segera sesudah Gideon mendengar mimpi itu diceritakan dengan maknanya, sujudlah ia menyembah. Kemudian pulanglah ia ke perkemahan orang Israel, lalu berkata: "Bangunlah, sebab TUHAN telah menyerahkan perkemahan orang Midian ke dalam tanganmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 16, 'Sesudah itu dibaginyalah ketiga ratus orang itu dalam tiga pasukan dan ke tangan mereka semuanya diberikannya sangkakala dan buyung kosong dengan suluh di dalam buyung itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 17, 'Dan berkatalah ia kepada mereka: "Perhatikanlah aku dan lakukanlah seperti yang kulakukan. Maka apabila aku sampai ke ujung perkemahan itu, haruslah kamu lakukan seperti yang kulakukan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 18, 'Apabila aku dan semua orang yang bersama dengan aku meniup sangkakala, maka haruslah kamu juga meniup sangkakala sekeliling seluruh perkemahan itu, dan berseru: ?Demi TUHAN dan demi Gideon!?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 19, 'Lalu Gideon dan keseratus orang yang bersama-sama dengan dia sampai ke ujung perkemahan itu pada waktu permulaan giliran jaga tengah malam, ketika penjaga-penjaga baru saja ditempatkan. Lalu mereka meniup sangkakala sambil memecahkan buyung yang di tangan mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 20, 'Demikianlah ketiga pasukan itu bersama-sama meniup sangkakala, dan memecahkan buyung dengan memegang obor di tangan kirinya dan sangkakala di tangan kanannya untuk ditiup, serta berseru: "Pedang demi TUHAN dan demi Gideon!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 21, 'Sementara itu tinggallah mereka berdiri, masing-masing di tempatnya, sekeliling perkemahan itu, tetapi seluruh tentara musuh menjadi kacau balau, berteriak-teriak dan melarikan diri.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 22, 'Sedang ketiga ratus orang itu meniup sangkakala, maka di perkemahan itu TUHAN membuat pedang yang seorang diarahkan kepada yang lain, lalu larilah tentara itu sampai ke Bet-Sita ke arah Zerera sampai ke pinggir Abel-Mehola dekat Tabat.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 23, 'Kemudian dikerahkanlah orang-orang Israel dari suku Naftali dan dari suku Asyer dan dari segenap suku Manasye, lalu mereka mengejar orang Midian itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 24, 'Gideon menyuruh juga orang ke seluruh pegunungan Efraim dengan pesan: "Turunlah menghadapi orang Midian, dan dudukilah segala batang air sampai ke Bet-Bara, dan juga sungai Yordan." Maka semua orang Efraim dikerahkan, lalu mereka menduduki segala batang air sampai ke Bet-Bara, juga sungai Yordan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 7, 25, 'Mereka berhasil menawan dua raja Midian, yakni Oreb dan Zeeb. Oreb dibunuh di gunung batu Oreb dan Zeeb dibunuh dalam tempat pemerasan anggur Zeeb. Mereka mengejar orang Midian itu, lalu mereka membawa kepala Oreb dan kepala Zeeb kepada Gideon di seberang sungai Yordan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 1, 'Lalu berkatalah orang-orang Efraim kepada Gideon: "Apa macam perbuatanmu ini terhadap kami! Mengapa engkau tidak memanggil kami, ketika engkau pergi berperang melawan orang Midian?" Lalu mereka menyesali dia dengan sangat.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 2, 'Jawabnya kepada mereka: "Apa perbuatanku dalam hal ini, jika dibandingkan dengan kamu? Bukankah pemetikan susulan oleh suku Efraim lebih baik hasilnya dari panen buah anggur kaum Abiezer?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 3, 'Allah telah menyerahkan kedua raja Midian itu, yakni Oreb dan Zeeb, ke dalam tanganmu; apa yang telah dapat kucapai, jika dibandingkan dengan kamu?" Setelah ia berkata demikian, maka redalah marah mereka terhadap dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 4, 'Ketika Gideon sampai ke sungai Yordan, menyeberanglah ia dan ketiga ratus orang yang bersama-sama dengan dia, meskipun masih lelah, namun mengejar juga.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 5, 'Dan berkatalah ia kepada orang-orang Sukot: "Tolong berikan beberapa roti untuk rakyat yang mengikuti aku ini, sebab mereka telah lelah, dan aku sedang mengejar Zebah dan Salmuna, raja-raja Midian."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 6, 'Tetapi jawab para pemuka di Sukot itu: "Sudahkah Zebah dan Salmuna itu ada dalam tanganmu, sehingga kami harus memberikan roti kepada tentaramu?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 7, 'Lalu kata Gideon: "Kalau begitu, apabila TUHAN menyerahkan Zebah dan Salmuna ke dalam tanganku, aku akan menggaruk tubuhmu dengan duri padang gurun dan onak."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 8, 'Maka berjalanlah ia dari sana ke Pnuel, dan berkata demikian juga kepada orang-orang Pnuel, tetapi orang-orang inipun menjawabnya seperti orang-orang Sukot.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 9, 'Lalu berkatalah ia juga kepada orang-orang Pnuel: "Apabila aku kembali dengan selamat, maka aku akan merobohkan menara ini."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 10, 'Sementara itu Zebah dan Salmuna ada di Karkor bersama-sama dengan tentara mereka, kira-kira lima belas ribu orang banyaknya, yakni semua orang yang masih tinggal hidup dari seluruh tentara orang-orang dari sebelah timur; banyaknya yang tewas ada seratus dua puluh ribu orang yang bersenjatakan pedang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 11, 'Gideon maju melalui jalan orang-orang yang diam di dalam kemah di sebelah timur Nobah dan Yogbeha, lalu memukul kalah tentara itu, ketika tentara itu menyangka dirinya aman.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 12, 'Zebah dan Salmuna melarikan diri, tetapi Gideon mengejar mereka dan menawan kedua raja Midian itu, yakni Zebah dan Salmuna, sedang seluruh tentara itu diceraiberaikannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 13, 'Kemudian kembalilah Gideon bin Yoas dari peperangan dengan melalui pendakian Heres;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 14, 'ditangkapnyalah seorang muda dari penduduk Sukot. Setelah ditanyai, orang itu menuliskan nama para pemuka dan para tua-tua di Sukot untuk Gideon, tujuh puluh tujuh orang banyaknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 15, 'Lalu pergilah Gideon kepada orang-orang Sukot sambil berkata: "Inilah Zebah dan Salmuna yang karenanya kamu telah mencela aku dengan berkata: Sudahkah Zebah dan Salmuna itu ada dalam tanganmu, sehingga kami harus memberikan roti kepada orang-orangmu yang lelah itu?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 16, 'Lalu ia mengumpulkan para tua-tua kota itu, ia mengambil duri padang gurun dan onak, dan menghajar orang-orang Sukot dengan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 17, 'Juga menara Pnuel dirobohkannya dan dibunuhnya orang-orang kota itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 18, 'Kemudian bertanyalah ia kepada Zebah dan Salmuna: "Di manakah orang-orang yang telah kamu bunuh di Tabor itu?" Jawab mereka: "Mereka itu serupa dengan engkau, sikap mereka masing-masing seperti anak raja."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 19, 'Lalu kata Gideon: "Saudara-saudarakulah itu, anak-anak ibuku! Demi TUHAN yang hidup, seandainya kamu membiarkan mereka hidup, aku tidak akan membunuh kamu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 20, 'Katanya kepada Yeter, anak sulungnya: "Bangunlah, bunuhlah mereka." Tetapi orang muda itu tidak menghunus pedangnya, karena ia takut, sebab ia masih muda.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 21, 'Lalu kata Zebah dan Salmuna: "Bangunlah engkau sendiri dan paranglah kami, sebab seperti orangnya, demikian pula kekuatannya." Maka bangunlah Gideon, dibunuhnya Zebah dan Salmuna, kemudian diambilnya bulan-bulanan yang ada pada leher unta mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 22, 'Kemudian berkatalah orang Israel kepada Gideon: "Biarlah engkau memerintah kami, baik engkau baik anakmu maupun cucumu, sebab engkaulah yang telah menyelamatkan kami dari tangan orang Midian."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 23, 'Jawab Gideon kepada mereka: "Aku tidak akan memerintah kamu dan juga anakku tidak akan memerintah kamu tetapi TUHAN yang memerintah kamu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 24, 'Selanjutnya kata Gideon kepada mereka: "Satu hal saja yang kuminta kepadamu: Baiklah kamu masing-masing memberikan anting-anting dari jarahannya." ?Karena musuh itu beranting-anting mas, sebab mereka orang Ismael.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 25, 'Jawab mereka: "Kami mau memberikannya dengan suka hati." Dan setelah dihamparkan sehelai kain, maka masing-masing melemparkan anting-anting dari jarahannya ke atas kain itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 26, 'Adapun berat anting-anting emas yang dimintanya itu ada seribu tujuh ratus syikal emas, belum terhitung bulan-bulanan, perhiasan telinga dan pakaian kain ungu muda yang dipakai oleh raja-raja Midian, dan belum terhitung kalung rantai yang ada pada leher unta mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 27, 'Kemudian Gideon membuat efod dari semuanya itu dan menempatkannya di kotanya, di Ofra. Di sanalah orang Israel berlaku serong dengan menyembah efod itu; inilah yang menjadi jerat bagi Gideon dan seisi rumahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 28, 'Demikianlah orang Midian tunduk kepada orang Israel dan tidak dapat menegakkan kepalanya lagi; maka amanlah negeri itu empat puluh tahun lamanya pada zaman Gideon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 29, 'Lalu Yerubaal bin Yoas pergilah dan diam di rumahnya sendiri.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 30, 'Gideon mempunyai tujuh puluh anak laki-laki, semuanya anak kandungnya, sebab ia beristeri banyak;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 31, 'juga gundiknya yang tinggal di Sikhem melahirkan seorang anak laki-laki baginya, lalu ia memberikan nama Abimelekh kepada anak itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 32, 'Gideon bin Yoas mati pada waktu rambutnya telah putih, lalu dikuburkan dalam kubur Yoas, ayahnya, di Ofra kota orang Abiezer.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 33, 'Setelah Gideon mati, kembalilah orang Israel berjalan serong dengan mengikuti para Baal dan membuat Baal-Berit menjadi allah mereka;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 34, 'orang Israel tidak ingat kepada TUHAN, Allah mereka, yang telah melepaskan mereka dari tangan semua musuhnya di sekelilingnya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 8, 35, 'juga tidak menunjukkan terima kasihnya kepada keturunan Yerubaal-Gideon seimbang dengan segala yang baik yang telah dilakukannya kepada orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 1, 'Adapun Abimelekh bin Yerubaal pergi ke Sikhem kepada saudara-saudara ibunya dan berkata kepada mereka dan kepada seluruh kaum dari pihak keluarga ibunya:', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 2, '"Tolong katakan kepada seluruh warga kota Sikhem: Manakah yang lebih baik bagimu: tujuh puluh orang memerintah kamu, yaitu semua anak Yerubaal, atau satu orang? Dan ingat juga, bahwa aku darah dagingmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 3, 'Lalu saudara-saudara ibunya mengatakan hal ihwalnya kepada seluruh warga kota Sikhem, maka condonglah hati orang-orang itu untuk mengikuti Abimelekh, sebab kata mereka: "Memang ia saudara kita."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 4, 'Sesudah itu mereka memberikan kepadanya tujuh puluh uang perak dari kuil Baal-Berit, lalu Abimelekh memberi perak itu sebagai upah kepada petualang-petualang dan orang-orang nekat supaya mengikuti dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 5, 'Ia pergi ke rumah ayahnya di Ofra, lalu membunuh saudara-saudaranya, anak-anak Yerubaal, tujuh puluh orang, di atas satu batu. Tetapi Yotam, anak bungsu Yerubaal tinggal hidup, karena ia menyembunyikan diri.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 6, 'Kemudian berkumpullah seluruh warga kota Sikhem dan seluruh Bet-Milo; mereka pergi menobatkan Abimelekh menjadi raja dekat pohon tarbantin di tugu peringatan yang di Sikhem.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 7, 'Setelah hal itu dikabarkan kepada Yotam, pergilah ia ke gunung Gerizim dan berdiri di atasnya, lalu berserulah ia dengan suara nyaring kepada mereka: "Dengarkanlah aku, kamu warga kota Sikhem, maka Allah akan mendengarkan kamu juga.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 8, 'Sekali peristiwa pohon-pohon pergi mengurapi yang akan menjadi raja atas mereka. Kata mereka kepada pohon zaitun: Jadilah raja atas kami!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 9, 'Tetapi jawab pohon zaitun itu kepada mereka: Masakan aku meninggalkan minyakku yang dipakai untuk menghormati Allah dan manusia, dan pergi melayang di atas pohon-pohon?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 10, 'Lalu kata pohon-pohon itu kepada pohon ara: Marilah, jadilah raja atas kami!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 11, 'Tetapi jawab pohon ara itu kepada mereka: Masakan aku meninggalkan manisanku dan buah-buahku yang baik, dan pergi melayang di atas pohon-pohon?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 12, 'Lalu kata pohon-pohon itu kepada pohon anggur: Marilah, jadilah raja atas kami!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 13, 'Tetapi jawab pohon anggur itu kepada mereka: Masakan aku meninggalkan air buah anggurku, yang menyukakan hati Allah dan manusia, dan pergi melayang di atas pohon-pohon?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 14, 'Lalu kata segala pohon itu kepada semak duri: Marilah, jadilah raja atas kami!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 15, 'Jawab semak duri itu kepada pohon-pohon itu: Jika kamu sungguh-sungguh mau mengurapi aku menjadi raja atas kamu, datanglah berlindung di bawah naunganku; tetapi jika tidak, biarlah api keluar dari semak duri dan memakan habis pohon-pohon aras yang di gunung Libanon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 16, 'Maka sekarang, jika kamu berlaku setia dan tulus ikhlas dengan membuat Abimelekh menjadi raja, dan jika kamu berbuat yang baik kepada Yerubaal dan kepada keturunannya dan jika kamu membalaskan kepadanya seimbang dengan jasanya?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 17, 'bukankah ayahku telah berperang membela kamu dan menyabung nyawanya, dan telah melepaskan kamu dari tangan orang Midian,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 18, 'padahal kamu sekarang memberontak terhadap keturunan ayahku dan membunuh anak-anaknya, tujuh puluh orang banyaknya, di atas satu batu, serta membuat Abimelekh anak seorang budaknya perempuan menjadi raja atas warga kota Sikhem, karena ia saudaramu?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 19, 'jadi jika kamu pada hari ini berlaku setia dan tulus ikhlas kepada Yerubaal dan keturunannya, maka silakanlah kamu bersukacita atas Abimelekh dan silakanlah ia bersukacita atas kamu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 20, 'Tetapi jika tidak demikian, maka biarlah api keluar dari pada Abimelekh dan memakan habis warga kota Sikhem dan juga Bet-Milo, dan biarlah api keluar dari pada warga kota Sikhem dan juga dari Bet-Milo dan memakan habis Abimelekh."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 21, 'Kemudian larilah Yotam; ia melarikan diri ke Beer, dan tinggal di sana karena takut kepada Abimelekh, saudaranya itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 22, 'Setelah tiga tahun lamanya Abimelekh memerintah atas orang Israel,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 23, 'maka Allah membangkitkan semangat jahat di antara Abimelekh dan warga kota Sikhem, sehingga warga kota Sikhem itu menjadi tidak setia kepada Abimelekh,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 24, 'supaya kekerasan terhadap ketujuh puluh anak Yerubaal dibalaskan dan darah mereka ditimpakan kepada Abimelekh, saudara mereka yang telah membunuh mereka dan kepada warga kota Sikhem yang membantu dia membunuh saudara-saudaranya itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 25, 'Sebab warga kota Sikhem itu menempatkan orang untuk menghadang dia di puncak gunung dan merampas setiap orang yang melewati mereka melalui jalan itu. Hal itu dikabarkan kepada Abimelekh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 26, 'Sementara itu Gaal bin Ebed beserta saudara-saudaranya telah datang dan pindah ke kota Sikhem. Warga kota Sikhem percaya kepadanya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 27, 'jadi pergilah mereka ke ladang; mereka mengumpulkan hasil kebun anggur mereka, dan mengirik memerasnya, lalu mengadakan perayaan. Mereka masuk ke kuil allah mereka dan makan minum sambil mengutuki Abimelekh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 28, 'Berkatalah Gaal bin Ebed: "Siapa itu Abimelekh dan siapa kita orang Sikhem, maka kita menjadi hambanya? Bukankah anak Yerubaal dan Zebul, wakilnya, menjadi hamba orang-orang Hemor, ayah Sikhem, jadi mengapakah kita menjadi hambanya?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 29, 'Sekiranya orang-orang kota ini ada di dalam tanganku, maka tentulah aku mengenyahkan Abimelekh." Lalu berkatalah ia ke arah Abimelekh: "Perkuatlah tentaramu dan majulah!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 30, 'Ketika Zebul, penguasa kota itu mendengar perkataan Gaal bin Ebed, bangkitlah amarahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 31, 'Ia mengirim utusan kepada Abimelekh di Aruma dengan pesan: "Gaal bin Ebed dan saudara-saudaranya telah datang ke Sikhem dan ketahuilah mereka menghasut kota itu melawan engkau.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 32, 'Oleh sebab itu, berangkatlah pada waktu malam, engkau dan rakyat yang bersama-sama dengan engkau itu, dan adakanlah penghadangan di padang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 33, 'Esoknya pagi-pagi, pada waktu matahari terbit, haruslah engkau menyerbu kota itu. Dan jika ia dan orang-orangnya keluar melawan engkau, maka engkau dapat berbuat kepadanya sesuai dengan keadaan yang kaudapati."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 34, 'Sebab itu berangkatlah Abimelekh pada waktu malam beserta segala rakyat yang bersama-sama dengan dia, lalu mereka mengadakan penghadangan dalam empat pasukan untuk melawan Sikhem.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 35, 'Ketika Gaal bin Ebed pergi ke luar dan berdiri di depan pintu gerbang kota itu, Abimelekh kebetulan bangun dari tempat penghadangannya beserta rakyat yang bersama-sama dengan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 36, 'Ketika Gaal melihat rakyat itu, berkatalah ia kepada Zebul: "Lihat, ada orang banyak turun dari puncak gunung." Jawab Zebul kepadanya: "Itu bayang-bayang gunung, yang kausangka manusia."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 37, 'Kata Gaal sekali lagi: "Lihat, ada orang banyak turun dari gunung Pusat Tanah dan satu kelompok datang dari jalan Pohon Tarbantin Peramal."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 38, 'Jawab Zebul kepadanya: "Di manakah mulutmu itu yang mengatakan: Siapa itu Abimelekh, maka kita menjadi hambanya? Bukankah ini orang-orang yang telah kauhina itu? Majulah sekarang untuk memerangi mereka."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 39, 'Maka majulah Gaal dengan dipandangi oleh warga kota Sikhem, lalu berperang melawan Abimelekh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 40, 'Tetapi Abimelekh mengejar dia, dan ia melarikan diri dari depannya, dan banyaklah orang tewas sampai di depan pintu gerbang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 41, 'Adapun Abimelekh tinggal di Aruma, tetapi Zebul mengusir Gaal dan saudara-saudaranya, sehingga mereka ini tidak dapat tinggal di Sikhem.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 42, 'Keesokan harinya orang-orang kota itu pergi ke ladang. Setelah hal ini dikabarkan kepada Abimelekh,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 43, 'dibawanyalah rakyatnya, dibaginya dalam tiga pasukan, lalu mereka mengadakan penghadangan di padang. Ketika dilihatnya, bahwa orang-orang kota itu keluar dari dalam kota, bangunlah ia menyerang mereka serta menewaskan mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 44, 'Abimelekh dan pasukan yang bersama-sama dengan dia menyerbu dan menduduki pintu gerbang kota, sedang kedua pasukan lain itu menyerbu dan menewaskan semua orang yang ada di padang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 45, 'Sehari-harian itu Abimelekh berperang melawan kota itu; ia merebut kota itu dan membunuh orang-orang yang di dalamnya; kemudian dirobohkannya kota itu dan ditaburinya dengan garam.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 46, 'Mendengar itu masuklah seluruh warga kota Menara-Sikhem ke dalam liang di bawah kuil El-Berit.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 47, 'Dikabarkanlah kepada Abimelekh, bahwa seluruh warga kota Menara-Sikhem telah berhimpun di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 48, 'Lalu Abimelekh dan seluruh rakyat yang bersama-sama dengan dia naik ke gunung Zalmon. Abimelekh mengambil kapak, lalu memotong dahan-dahan kayu, mengangkatnya dan meletakkannya ke atas bahunya sambil berkata kepada rakyatnya yang bersama-sama dengan dia: "Turutilah dengan segera perbuatanku yang kamu lihat ini."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 49, 'Kemudian rakyat itu juga masing-masing memotong dahan-dahan, lalu mengikuti Abimelekh, meletakkan dahan-dahan itu di atas liang dan membakar liang itu di atas kepala orang-orang itu. Demikianlah semua penduduk kota Menara-Sikhem juga mati, kira-kira seribu orang laki-laki dan perempuan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 50, 'Selanjutnya Abimelekh pergi ke Tebes; ia mengepung Tebes, lalu merebutnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 51, 'Tetapi ada sebuah menara yang kuat di tengah-tengah kota, dan semua laki-laki dan perempuan, seluruh warga kota itu, melarikan diri ke situ; mereka menutup pintu di belakangnya dan naik ke atas sotoh menara itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 52, 'Lalu sampailah Abimelekh ke menara itu, menyerangnya, dan dapat menerobos sampai ke pintu menara itu untuk membakarnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 53, 'Tetapi seorang perempuan menimpakan sebuah batu kilangan kepada kepala Abimelekh dan memecahkan batu kepalanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 54, 'Dengan segera dipanggilnya bujang pembawa senjatanya dan berkata kepadanya: "Hunuslah pedangmu dan bunuhlah aku, supaya jangan orang berkata tentang aku: Seorang perempuan membunuh dia." Lalu bujangnya itu menikam dia, sehingga mati.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 55, 'Setelah dilihat oleh orang Israel, bahwa Abimelekh telah mati, pergilah mereka, masing-masing ke tempat kediamannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 56, 'Demikianlah Allah membalaskan kejahatan yang dilakukan oleh Abimelekh kepada ayahnya, yaitu pembunuhan atas ketujuh puluh saudaranya;', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 9, 57, 'juga segala kejahatan orang-orang Sikhem ditimpakan kembali oleh Allah kepada kepala mereka sendiri. Demikianlah kutuk Yotam bin Yerubaal mengenai mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 1, 'Sesudah Abimelekh, bangkitlah Tola bin Pua bin Dodo, seorang Isakhar, untuk menyelamatkan orang Israel. Ia diam di Samir, di pegunungan Efraim', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 2, 'dan ia memerintah sebagai hakim atas orang Israel dua puluh tiga tahun lamanya; kemudian matilah ia, lalu dikuburkan di Samir.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 3, 'Sesudah dia, bangkitlah Yair, orang Gilead, yang memerintah sebagai hakim atas orang Israel dua puluh dua tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 4, 'Ia mempunyai tiga puluh anak laki-laki, yang mengendarai tiga puluh ekor keledai jantan, dan mereka mempunyai tiga puluh kota, yang sampai sekarang disebutkan orang Hawot-Yair, di tanah Gilead.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 5, 'Lalu matilah Yair dan dikuburkan di Kamon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 6, 'Orang Israel itu melakukan pula apa yang jahat di mata TUHAN; mereka beribadah kepada para Baal dan para Asytoret, kepada para allah orang Aram, para allah orang Sidon, para allah orang Moab, para allah bani Amon dan para allah orang Filistin, tetapi TUHAN ditinggalkan mereka dan kepada Dia mereka tidak beribadah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 7, 'Lalu bangkitlah murka TUHAN terhadap orang Israel, dan Ia menyerahkan mereka ke dalam tangan orang Filistin dan bani Amon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 8, 'Dalam tahun itu juga orang Israel ditindas dan diinjak mereka; delapan belas tahun lamanya mereka memperlakukan demikian semua orang Israel yang di seberang sungai Yordan di tanah orang Amori yang di Gilead.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 9, 'Dan bani Amonpun menyeberangi sungai Yordan untuk berperang melawan suku Yehuda, suku Benyamin dan keturunan Efraim, sehingga orang Israel sangat terdesak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 10, 'Lalu berserulah orang Israel kepada TUHAN, katanya: "Kami telah berbuat dosa terhadap Engkau, sebab kami telah meninggalkan Allah kami lalu beribadah kepada para Baal."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 11, 'Tetapi firman TUHAN kepada orang Israel: "Bukankah Aku yang telah menyelamatkan kamu dari tangan orang Mesir, orang Amori, bani Amon, orang Filistin,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 12, 'orang Sidon, suku Amalek dan suku Maon yang menindas kamu, ketika kamu berseru kepada-Ku?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 13, 'Tetapi kamu telah meninggalkan Aku dan beribadah kepada allah lain; sebab itu Aku tidak akan menyelamatkan kamu lagi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 14, 'Pergi sajalah berseru kepada para allah yang telah kamu pilih itu; biar merekalah yang menyelamatkan kamu, pada waktu kamu terdesak."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 15, 'Kata orang Israel kepada TUHAN: "Kami telah berbuat dosa. Lakukanlah kepada kami segala yang baik di mata-Mu. Hanya tolonglah kiranya kami sekarang ini!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 16, 'Dan mereka menjauhkan para allah asing dari tengah-tengah mereka, lalu mereka beribadah kepada TUHAN. Maka TUHAN tidak dapat lagi menahan hati-Nya melihat kesukaran mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 17, 'Kemudian bani Amon dikerahkan dan berkemah di Gilead, sedang orang Israel berkumpul dan berkemah di Mizpa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 10, 18, 'Maka para pemimpin bangsa di Gilead berkata seorang kepada yang lain: "Siapakah orang yang berani memulai peperangan melawan bani Amon itu? Dialah yang harus menjadi kepala atas seluruh penduduk Gilead."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 1, 'Adapun Yefta, orang Gilead itu, adalah seorang pahlawan yang gagah perkasa, tetapi ia anak seorang perempuan sundal; ayah Yefta ialah Gilead.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 2, 'Juga isteri Gilead melahirkan anak-anak lelaki baginya. Setelah besar anak-anak isterinya ini, maka mereka mengusir Yefta, katanya kepadanya: "Engkau tidak mendapat milik pusaka dalam keluarga kami, sebab engkau anak dari perempuan lain."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 3, 'Maka larilah Yefta dari saudara-saudaranya itu dan diam di tanah Tob; di sana berkumpullah kepadanya petualang-petualang yang pergi merampok bersama-sama dengan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 4, 'Beberapa waktu kemudian bani Amon berperang melawan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 5, 'Dan ketika bani Amon itu berperang melawan orang Israel, pergilah para tua-tua Gilead menjemput Yefta dari tanah Tob.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 6, 'Kata mereka kepada Yefta: "Mari, jadilah panglima kami dan biarlah kita berperang melawan bani Amon."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 7, 'Tetapi kata Yefta kepada para tua-tua Gilead itu: "Bukankah kamu sendiri membenci aku dan mengusir aku dari keluargaku? Mengapa kamu datang sekarang kepadaku, pada waktu kamu terdesak?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 8, 'Kemudian berkatalah para tua-tua Gilead kepada Yefta: "Memang, kami datang kembali sekarang kepadamu, ikutilah kami dan berperanglah melawan bani Amon, maka engkau akan menjadi kepala atas kami, atas seluruh penduduk Gilead."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 9, 'Kata Yefta kepada para tua-tua Gilead: "Jadi, jika kamu membawa aku kembali untuk berperang melawan bani Amon, dan TUHAN menyerahkan mereka kepadaku, maka akulah yang akan menjadi kepala atas kamu?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 10, 'Lalu kata para tua-tua Gilead kepada Yefta: "Demi TUHAN yang mendengarkannya sebagai saksi antara kita: Kami akan berbuat seperti katamu itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 11, 'Maka Yefta ikut dengan para tua-tua Gilead, lalu bangsa itu mengangkat dia menjadi kepala dan panglima mereka. Tetapi Yefta membawa seluruh perkaranya itu ke hadapan TUHAN, di Mizpa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 12, 'Kemudian Yefta mengirim utusan kepada raja bani Amon dengan pesan: "Apakah urusanmu dengan aku, sehingga engkau mendatangi aku untuk memerangi negeriku?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 13, 'Jawab raja bani Amon kepada utusan Yefta: "Orang Israel, ketika berjalan keluar dari Mesir, telah merampas tanahku, dari sungai Arnon sampai ke sungai Yabok dan sampai ke sungai Yordan. Maka sekarang, kembalikanlah semuanya itu dengan jalan damai."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 14, 'Lalu Yefta mengirim pula utusan kepada raja bani Amon', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 15, 'dengan pesan: "Beginilah kata Yefta: orang Israel tidak merampas tanah orang Moab atau tanah bani Amon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 16, 'Sebab ketika berjalan keluar dari Mesir, orang Israel melalui padang gurun sampai ke Laut Teberau dan tiba di Kadesh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 17, 'Ketika itu orang Israel mengirim utusan kepada raja negeri Edom dengan permintaan: Izinkanlah kiranya kami berjalan melalui negerimu ini. Tetapi raja negeri Edom tidak mau mendengar. Mereka mengirim juga utusan kepada raja negeri Moab, tetapi raja ini menolak. Maka orang Israel tinggal di Kadesh.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 18, 'Kemudian mereka berjalan melalui padang gurun, menempuh jalan keliling tanah Edom dan tanah Moab, lalu sampai ke sebelah timur tanah Moab, maka berkemahlah mereka di seberang sungai Arnon, dengan tidak masuk daerah Moab, sebab sungai Arnon itulah batas daerah Moab.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 19, 'Lalu orang Israel mengirim utusan kepada Sihon, raja orang Amori, raja di Hesybon, dan orang Israel meminta kepadanya: Izinkanlah kiranya kami berjalan melalui negerimu ini sampai ke tempat yang kami tuju.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 20, 'Tetapi Sihon tidak percaya kepada orang Israel yang hendak berjalan melalui daerahnya itu, maka dikumpulkannyalah seluruh rakyatnya. Ia berkemah di Yahas, lalu berperang melawan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 21, 'Tetapi TUHAN, Allah Israel, menyerahkan Sihon dengan seluruh rakyatnya ke dalam tangan orang Israel, dan mereka dikalahkan, sehingga orang Israel menduduki seluruh negeri kepunyaan orang Amori, penduduk negeri itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 22, 'Demikianlah dimiliki orang Israel seluruh daerah orang Amori itu, dari sungai Arnon sampai ke sungai Yabok dan dari padang gurun sampai ke sungai Yordan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 23, 'Maka sekarang TUHAN, Allah Israel, telah merebut milik orang Amori, bagi Israel, umat-Nya. Apakah engkau hendak memiliki pula tanah mereka itu?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 24, 'Bukankah engkau akan memiliki apa yang diberi oleh Kamos, allahmu? Demikianlah kami memiliki segala yang direbut bagi kami oleh TUHAN, Allah kami.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 25, 'Lagipula, apakah engkau lebih baik dari Balak bin Zipor, raja Moab? Pernahkah ia menuntut hak kepada orang Israel atau pernahkah ia berperang melawan mereka?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 26, 'Ketika orang Israel diam di Hesybon dengan segala anak kotanya, di Aroer dengan segala anak kotanya, dan di segala kota sepanjang kedua tepi sungai Arnon selama tiga ratus tahun, mengapa pada waktu itu engkau tidak melepaskan kota-kota itu?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 27, 'Jadi aku tidak bersalah terhadap engkau, tetapi engkau berbuat jahat terhadap aku dengan berperang melawan aku. TUHAN, Hakim itu, Dialah yang menjadi hakim pada hari ini antara orang Israel dan bani Amon."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 28, 'Tetapi raja bani Amon tidak mendengarkan perkataan yang disampaikan kepadanya oleh utusan-utusan Yefta.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 29, 'Lalu Roh TUHAN menghinggapi Yefta; ia berjalan melalui daerah Gilead dan daerah Manasye, kemudian melalui Mizpa di Gilead, dan dari Mizpa di Gilead ia berjalan terus ke daerah bani Amon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 30, 'Lalu bernazarlah Yefta kepada TUHAN, katanya: "Jika Engkau sungguh-sungguh menyerahkan bani Amon itu ke dalam tanganku,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 31, 'maka apa yang keluar dari pintu rumahku untuk menemui aku, pada waktu aku kembali dengan selamat dari bani Amon, itu akan menjadi kepunyaan TUHAN, dan aku akan mempersembahkannya sebagai korban bakaran."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 32, 'Kemudian Yefta berjalan terus untuk berperang melawan bani Amon, dan TUHAN menyerahkan mereka ke dalam tangannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 33, 'Ia menimbulkan kekalahan yang amat besar di antara mereka, mulai dari Aroer sampai dekat Minit?dua puluh kota banyaknya?dan sampai ke Abel-Keramim, sehingga bani Amon itu ditundukkan di depan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 34, 'Ketika Yefta pulang ke Mizpa ke rumahnya, tampaklah anaknya perempuan keluar menyongsong dia dengan memukul rebana serta menari-nari. Dialah anaknya yang tunggal; selain dari dia tidak ada anaknya laki-laki atau perempuan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 35, 'Demi dilihatnya dia, dikoyakkannyalah bajunya, sambil berkata: "Ah, anakku, engkau membuat hatiku hancur luluh dan engkaulah yang mencelakakan aku; aku telah membuka mulutku bernazar kepada TUHAN, dan tidak dapat aku mundur."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 36, 'Tetapi jawabnya kepadanya: "Bapa, jika engkau telah membuka mulutmu bernazar kepada TUHAN, maka perbuatlah kepadaku sesuai dengan nazar yang kauucapkan itu, karena TUHAN telah mengadakan bagimu pembalasan terhadap musuhmu, yakni bani Amon itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 37, 'Lagi katanya kepada ayahnya: "Hanya izinkanlah aku melakukan hal ini: berilah keluasan kepadaku dua bulan lamanya, supaya aku pergi mengembara ke pegunungan dan menangisi kegadisanku bersama-sama dengan teman-temanku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 38, 'Jawab Yefta: "Pergilah," dan ia membiarkan dia pergi dua bulan lamanya. Maka pergilah gadis itu bersama-sama dengan teman-temannya menangisi kegadisannya di pegunungan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 39, 'Setelah lewat kedua bulan itu, kembalilah ia kepada ayahnya, dan ayahnya melakukan kepadanya apa yang telah dinazarkannya itu; jadi gadis itu tidak pernah kenal laki-laki. Dan telah menjadi adat di Israel,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 11, 40, 'bahwa dari tahun ke tahun anak-anak perempuan orang Israel selama empat hari setahun meratapi anak perempuan Yefta, orang Gilead itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 1, 'Dikerahkanlah orang Efraim, lalu mereka bergerak ke Zafon. Dan mereka berkata kepada Yefta: "Mengapa engkau bergerak untuk memerangi bani Amon dengan tidak memanggil kami untuk maju bersama-sama dengan engkau? Sebab itu kami akan membakar rumahmu bersama-sama kamu!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 2, 'Tetapi jawab Yefta kepada mereka: "Aku dan rakyatku telah terlibat dalam peperangan yang hebat dengan bani Amon; lalu aku memanggil kamu, tetapi kamu tidak datang menyelamatkan aku dari tangan mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 3, 'Ketika kulihat, bahwa tidak ada yang datang menyelamatkan aku, maka aku mempertaruhkan nyawaku dan aku pergi melawan bani Amon itu, dan TUHAN menyerahkan mereka ke dalam tanganku. Mengapa pada hari ini kamu mendatangi aku untuk berperang melawan aku?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 4, 'Kemudian Yefta mengumpulkan semua orang Gilead, lalu mereka berperang melawan suku Efraim. Dan orang-orang Gilead mengalahkan suku Efraim itu. Sebab orang-orang itu mengatakan: "Kamulah orang-orang yang telah lari dari suku Efraim!" ?kaum Gilead itu ada di tengah-tengah suku Efraim dan suku Manasye?.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 5, 'Untuk menghadapi suku Efraim itu, maka orang Gilead menduduki tempat-tempat penyeberangan sungai Yordan. Apabila dari suku Efraim ada yang lari dan berkata: "Biarkanlah aku menyeberang," maka orang Gilead berkata kepadanya: "Orang Efraimkah engkau?" Dan jika ia menjawab: "Bukan,"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 6, 'maka mereka berkata kepadanya: "Coba katakan dahulu: syibolet." Jika ia berkata: sibolet, jadi tidak dapat mengucapkannya dengan tepat, maka mereka menangkap dia dan menyembelihnya dekat tempat-tempat penyeberangan sungai Yordan itu. Pada waktu itu tewaslah dari suku Efraim empat puluh dua ribu orang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 7, 'Yefta memerintah sebagai hakim atas orang Israel enam tahun lamanya. Kemudian matilah Yefta, orang Gilead itu, lalu dikuburkan di sebuah kota di daerah Gilead.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 8, 'Sesudah dia, maka Ebzan dari Betlehem memerintah sebagai hakim atas orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 9, 'Ia mempunyai tiga puluh anak laki-laki. Tiga puluh anaknya perempuan dikawinkannya ke luar kaumnya dan tiga puluh anak perempuan diambilnya dari luar kaumnya untuk anak-anaknya lelaki itu. Ia memerintah atas orang Israel tujuh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 10, 'Kemudian matilah Ebzan, lalu dikuburkan di Betlehem.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 11, 'Sesudah dia, maka Elon orang Zebulon memerintah sebagai hakim atas orang Israel. Ia memerintah atas orang Israel sepuluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 12, 'Kemudian matilah Elon, orang Zebulon itu, lalu dikuburkan di Ayalon, di tanah Zebulon.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 13, 'Sesudah dia, maka Abdon bin Hilel, orang Piraton, memerintah sebagai hakim atas orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 14, 'Ia mempunyai empat puluh anak laki-laki dan tiga puluh cucu laki-laki, yang mengendarai tujuh puluh ekor keledai jantan. Ia memerintah atas orang Israel delapan tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 12, 15, 'Kemudian matilah Abdon bin Hilel, orang Piraton itu, lalu dikuburkan di Piraton, di tanah Efraim, di pegunungan orang Amalek.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 1, 'Orang Israel melakukan pula apa yang jahat di mata TUHAN; sebab itu TUHAN menyerahkan mereka ke dalam tangan orang Filistin empat puluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 2, 'Pada waktu itu ada seorang dari Zora, dari keturunan orang Dan, namanya Manoah; isterinya mandul, tidak beranak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 3, 'Dan Malaikat TUHAN menampakkan diri kepada perempuan itu dan berfirman kepadanya, demikian: "Memang engkau mandul, tidak beranak, tetapi engkau akan mengandung dan melahirkan seorang anak laki-laki.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 4, 'Oleh sebab itu, peliharalah dirimu, jangan minum anggur atau minuman yang memabukkan dan jangan makan sesuatu yang haram.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 5, 'Sebab engkau akan mengandung dan melahirkan seorang anak laki-laki; kepalanya takkan kena pisau cukur, sebab sejak dari kandungan ibunya anak itu akan menjadi seorang nazir Allah dan dengan dia akan mulai penyelamatan orang Israel dari tangan orang Filistin."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 6, 'Kemudian perempuan itu datang kepada suaminya dan berkata: "Telah datang kepadaku seorang abdi Allah, yang rupanya sebagai rupa malaikat Allah, amat menakutkan. Tidak kutanyakan dari mana datangnya, dan tidak juga diberitahukannya namanya kepadaku.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 7, 'Tetapi ia berkata kepadaku: Engkau akan mengandung dan melahirkan seorang anak laki-laki; oleh sebab itu janganlah minum anggur atau minuman yang memabukkan dan janganlah makan sesuatu yang haram, sebab sejak dari kandungan ibunya sampai pada hari matinya, anak itu akan menjadi seorang nazir Allah."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 8, 'Lalu Manoah memohon kepada TUHAN, katanya: "Ya Tuhan, berilah kiranya abdi Allah, yang Kauutus itu, datang pula kepada kami dan mengajar kami, apa yang harus kami perbuat kepada anak yang akan lahir itu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 9, 'Maka Allah mendengarkan permohonan Manoah, sehingga Malaikat Allah datang pula kepada perempuan itu, ketika ia duduk di padang dan ketika Manoah, suaminya itu, tidak ada bersama-sama dengan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 10, 'Kemudian perempuan itu segera berlari memberitahukan kepada suaminya, katanya kepadanya: "Orang yang datang kepadaku baru-baru ini menampakkan diri pula kepadaku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 11, 'Lalu bangunlah Manoah dan mengikuti isterinya. Setelah sampai kepada orang itu, berkatalah ia kepadanya: "Engkaukah orang yang telah berbicara kepada perempuan ini?" Jawabnya: "Benar!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 12, 'Lalu kata Manoah: "Dan apabila terjadi yang Kaukatakan itu, bagaimanakah nanti cara hidup anak itu dan tingkah lakunya?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 13, 'Jawab Malaikat TUHAN itu kepada Manoah: "Perempuan itu harus memelihara diri terhadap semua yang Kukatakan kepadanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 14, 'Janganlah ia makan sesuatu yang berasal dari pohon anggur; anggur atau minuman yang memabukkan tidak boleh diminumnya dan sesuatu yang haram tidak boleh dimakannya. Ia harus berpegang pada segala yang Kuperintahkan kepadanya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 15, 'Kata Manoah kepada Malaikat TUHAN itu: "Perkenankanlah kami menahan Engkau di sini, supaya kami mengolah anak kambing bagi-Mu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 16, 'Tetapi jawab Malaikat TUHAN itu kepada Manoah: "Sekalipun engkau menahan Aku di sini, hidanganmu itu tidak akan Kumakan. Tetapi jika engkau hendak mengolahnya menjadi korban bakaran, persembahkanlah itu kepada TUHAN." Sebab Manoah tidak mengetahui, bahwa Dia itu Malaikat TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 17, 'Kemudian berkatalah Manoah kepada Malaikat TUHAN itu: "Siapakah nama-Mu, sebab apabila terjadi yang Kaukatakan itu, maka kami hendak memuliakan Engkau."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 18, 'Tetapi jawab malaikat TUHAN itu kepadanya: "Mengapa engkau juga menanyakan nama-Ku? Bukankah nama itu ajaib?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 19, 'Sesudah itu Manoah mengambil seekor anak kambing dan korban sajian, lalu mempersembahkannya kepada TUHAN di atas batu. Lalu diperbuat-Nya keajaiban, sementara Manoah dan isterinya memandanginya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 20, 'Sedang nyala api itu naik ke langit dari mezbah, maka naiklah Malaikat TUHAN dalam nyala api mezbah itu. Ketika Manoah dan isterinya melihat hal ini, sujudlah mereka dengan mukanya sampai ke tanah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 21, 'Sejak itu Malaikat TUHAN tidak lagi menampakkan diri kepada Manoah dan isterinya. Maka tahulah Manoah, bahwa Dia itu Malaikat TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 22, 'Berkatalah Manoah kepada isterinya: "Kita pasti mati, sebab kita telah melihat Allah."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 23, 'Tetapi jawab isterinya kepadanya: "Seandainya TUHAN hendak membunuh kita, maka tidaklah Ia menerima korban bakaran dan korban sajian dari tangan kita dan tidaklah Ia memperlihatkan semuanya itu kepada kita dan tidaklah Ia memperdengarkan hal-hal yang demikian kepada kita pada waktu sekarang ini."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 24, 'Lalu perempuan itu melahirkan seorang anak laki-laki dan memberi nama Simson kepadanya. Anak itu menjadi besar dan TUHAN memberkati dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 13, 25, 'Mulailah hatinya digerakkan oleh Roh TUHAN di Mahane-Dan yang terletak di antara Zora dan Esytaol.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 1, 'Simson pergi ke Timna dan di situ ia melihat seorang gadis Filistin.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 2, 'Ia pulang dan memberitahukan kepada ayahnya dan ibunya: "Di Timna aku melihat seorang gadis Filistin. Tolong, ambillah dia menjadi isteriku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 3, 'Tetapi ayahnya dan ibunya berkata kepadanya: "Tidak adakah di antara anak-anak perempuan sanak saudaramu atau di antara seluruh bangsa kita seorang perempuan, sehingga engkau pergi mengambil isteri dari orang Filistin, orang-orang yang tidak bersunat itu?" Tetapi jawab Simson kepada ayahnya: "Ambillah dia bagiku, sebab dia kusukai."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 4, 'Tetapi ayahnya dan ibunya tidak tahu bahwa hal itu dari pada TUHAN asalnya: sebab memang Simson harus mencari gara-gara terhadap orang Filistin. Karena pada masa itu orang Filistin menguasai orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 5, 'Lalu pergilah Simson beserta ayahnya dan ibunya ke Timna. Ketika mereka sampai ke kebun-kebun anggur di Timna, maka seekor singa muda mendatangi Simson dengan mengaum.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 6, 'Pada waktu itu berkuasalah Roh TUHAN atas dia, sehingga singa itu dicabiknya seperti orang mencabik anak kambing?tanpa apa-apa di tangannya. Tetapi tidak diceriterakannya kepada ayahnya atau ibunya apa yang dilakukannya itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 7, 'Maka pergilah ia ke sana, lalu bercakap-cakap dengan perempuan itu, sebab Simson suka kepadanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 8, 'Setelah beberapa waktu kembalilah ia ke sana untuk kawin dengan perempuan itu; dan ketika ia menyimpang dari jalan untuk melihat bangkai singa itu, tampaklah ada kawanan lebah pada kerangka singa itu dan juga madu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 9, 'Dikeruknya madu itu ke dalam tangannya dan sambil memakannya ia berjalan terus, kemudian pergilah ia kepada ayahnya dan ibunya, dan memberikannya juga kepada mereka, lalu mereka memakannya. Tetapi tidak diceriterakannya kepada mereka, bahwa madu itu dikeruknya dari kerangka singa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 10, 'Setelah ayahnya pergi kepada perempuan itu, Simson mengadakan perjamuan di sana, sebab demikianlah biasanya dilakukan orang-orang muda.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 11, 'Ketika mereka melihat dia, dipilihlah tiga puluh orang kawan untuk menemani dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 12, 'Kata Simson kepada mereka: "Aku mau mengatakan suatu teka-teki kepada kamu. Jika kamu dapat memberi jawabnya yang tepat kepadaku dalam tujuh hari selama perjamuan ini berlangsung dan menebaknya, maka aku akan memberikan kepadamu tiga puluh pakaian lenan dan tiga puluh pakaian kebesaran.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 13, 'Tetapi jika kamu tidak dapat memberi jawabnya kepadaku, maka kamulah yang harus memberikan tiga puluh pakaian dalam dan tiga puluh pakaian kebesaran kepadaku." Kata mereka kepadanya: "Katakanlah teka-tekimu itu, supaya kami dengar."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 14, 'Lalu katanya kepada mereka: "Dari yang makan keluar makanan, dari yang kuat keluar manisan." Ada tiga hari lamanya mereka tidak dapat memberi jawab teka-teki itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 15, 'Pada hari ketujuh berkatalah mereka kepada isteri Simson: "Bujuklah suamimu, supaya diberitahukannya kepada kami jawab teka-teki itu; kalau tidak, kami akan membakar engkau beserta seisi rumah ayahmu. Apakah engkau mengundang kami untuk membuat kami menjadi miskin? Tidak, bukan?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 16, 'Lalu menangislah isteri Simson itu sambil memeluk Simson, katanya: "Engkau benci saja kepadaku, dan tidak cinta kepadaku; suatu teka-teki kaukatakan kepada orang-orang sebangsaku, tetapi jawabnya tidak kauberitahukan kepadaku." Sahutnya kepadanya: "Sedangkan kepada ayahku dan ibuku tidak kuberitahukan, masakan kepada engkau akan kuberitahukan?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 17, 'Tetapi isterinya itu menangis di sampingnya selama ketujuh hari mereka mengadakan perjamuan itu. Pada hari yang ketujuh diberitahukannyala kepadanya, karena ia merengek-rengek kepadanya, kemudian perempuan itu memberitahukan jawab teka-teki itu kepada orang-orang sebangsanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 18, 'Lalu pada hari yang ketujuh itu, sebelum matahari terbenam, berkatalah orang-orang kota itu kepadanya: "Apakah yang lebih manis dari pada madu? Apakah yang lebih kuat dari pada singa?" Sahutnya kepada mereka: "Kalau kamu tidak membajak dengan lembu betinaku, pasti kamu tidak menebak teka-tekiku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 19, 'Maka berkuasalah Roh TUHAN atas dia, lalu pergilah ia ke Askelon dan dibunuhnya tiga puluh orang di sana, diambilnya pakaian mereka dan diberikannya pakaian-pakaian kebesaran itu kepada orang-orang yang dapat memberi jawab teka-teki itu. Tetapi amarahnya masih juga bernyala-nyala, lalu pulanglah ia ke rumah ayahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 14, 20, 'Maka diberikanlah isteri Simson itu kepada kawannya, bekas pengiringnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 1, 'Beberapa waktu kemudian, dalam musim menuai gandum, pergilah Simson mengunjungi isterinya, dengan membawa seekor anak kambing, serta berkata: "Aku mau ke kamar mendapatkan isteriku." Tetapi ayah perempuan itu tidak membiarkan dia masuk.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 2, 'Kata ayah perempuan itu: "Aku telah menyangka, bahwa engkau benci sama sekali kepadanya, sebab itu aku memberikannya kepada kawanmu. Bukankah adiknya lebih cantik dari padanya? Baiklah kauambil itu bagimu sebagai gantinya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 3, 'Lalu kata Simson kepadanya: "Sekali ini aku tidak bersalah terhadap orang Filistin, apabila aku mendatangkan celaka kepada mereka."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 4, 'Maka pergilah Simson, ditangkapnya tiga ratus anjing hutan, diambilnya obor, diikatnya ekor dengan ekor dan ditaruhnya sebuah obor di antara tiap-tiap dua ekor.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 5, 'Kemudian dinyalakannyalah obor itu dan dilepaskannya anjing-anjing hutan itu ke gandum yang belum dituai kepunyaan orang Filistin, sehingga terbakarlah tumpukan-tumpukan gandum dan gandum yang belum dituai dan kebun-kebun pohon zaitun.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 6, 'Berkatalah orang Filistin: "Siapakah yang melakukan ini?" Orang menjawab: "Simson, menantu orang Timna itu, sebab orang itu telah mengambil isteri Simson dan memberikannya kepada kawannya." Kemudian pergilah orang Filistin ke sana dan membakar perempuan itu beserta ayahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 7, 'Lalu berkatalah Simson kepada mereka: "Jika kamu berbuat demikian, sesungguhnya aku takkan berhenti sebelum aku membalaskannya kepada kamu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 8, 'Dan dengan pukulan yang hebat ia meremukkan tulang-tulang mereka. Lalu pergilah ia dan tinggal dalam gua di bukit batu Etam.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 9, 'Lalu majulah orang Filistin dan berkemah di daerah Yehuda serta memencar ke Lehi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 10, 'Berkatalah orang-orang Yehuda: "Mengapa kamu maju menyerang kami?" Lalu jawab mereka: "Kami maju untuk mengikat Simson dan memperlakukan dia seperti dia memperlakukan kami."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 11, 'Kemudian turunlah tiga ribu orang dari suku Yehuda ke gua di gunung batu Etam dan berkata kepada Simson: "Tidakkah kauketahui, bahwa orang Filistin berkuasa atas kita? Apakah juga yang telah kauperbuat terhadap kami?" Tetapi jawabnya kepada mereka: "Seperti mereka memperlakukan aku, demikianlah aku memperlakukan mereka."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 12, 'Kata mereka kepadanya: "Kami datang ke sini untuk mengikat dan menyerahkan engkau ke dalam tangan orang Filistin." Tetapi jawab Simson kepada mereka: "Bersumpahlah kepadaku, bahwa kamu sendiri tidak akan menyerang aku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 13, 'Lalu kata mereka kepadanya: "Tidak, kami hanya mau mengikat engkau dan menyerahkan engkau ke dalam tangan mereka, tetapi membunuh engkau kami tidak mau." Maka mereka mengikat dia dengan dua tali baru dan membawa dia dari bukit batu itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 14, 'Setelah ia sampai ke Lehi dan orang-orang Filistin mendatangi dia dengan bersorak-sorak, maka berkuasalah Roh TUHAN atas dia dan tali-tali pada tangannya menjadi seperti batang rami yang telah habis dimakan api dan segala pengikatnya hancur tanggal dari tangannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 15, 'Kemudian ia menemui sebuah tulang rahang keledai yang masih baru, diulurkannya tangannya, dipungutnya dan dipukulnya mati seribu orang dengan tulang itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 16, 'Berkatalah Simson: "Dengan rahang keledai bangsa keledai itu kuhajar, dengan rahang keledai seribu orang kupukul."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 17, 'Setelah berkata demikian, dilemparnya tulang rahang itu dari tangannya. Kemudian dinamailah tempat itu Ramat Lehi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 18, 'Ketika ia sangat haus, berserulah ia kepada TUHAN: "Oleh tangan hamba-Mu ini telah Kauberikan kemenangan yang besar itu, masakan sekarang aku akan mati kehausan dan jatuh ke dalam tangan orang-orang yang tidak bersunat itu!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 19, 'Kemudian Allah membelah liang batu yang di Lehi itu, dan keluarlah air dari situ. Ia minum, lalu menjadi kuat dan segar kembali. Sebab itu dinamailah mata air itu Mata Air Penyeru, yang sampai sekarang masih ada di Lehi.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 15, 20, 'Ia memerintah sebagai hakim atas orang Israel dalam zaman orang Filistin, dua puluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 1, 'Pada suatu kali, ketika Simson pergi ke Gaza, dilihatnya di sana seorang perempuan sundal, lalu menghampiri dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 2, 'Ketika diberitahukan kepada orang-orang Gaza: "Simson telah datang ke sini," maka mereka mengepung tempat itu dan siap menghadang dia semalam-malaman itu di pintu gerbang kota, tetapi semalam-malaman itu mereka tidak berbuat apa-apa, karena pikirnya: "Nanti pada waktu fajar kita akan membunuh dia."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 3, 'Tetapi Simson tidur di situ sampai tengah malam. Pada waktu tengah malam bangunlah ia, dipegangnya kedua daun pintu gerbang kota itu dan kedua tiang pintu, dicabutnyalah semuanya beserta palangnya, diletakkannya di atas kedua bahunya, lalu semuanya itu diangkatnya ke puncak gunung yang berhadapan dengan Hebron.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 4, 'Sesudah itu Simson jatuh cinta kepada seorang perempuan dari lembah Sorek yang namanya Delila.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 5, 'Lalu datanglah raja-raja kota orang Filistin kepada perempuan itu sambil berkata: "Cobalah bujuk dia untuk mengetahui karena apakah kekuatannya demikian besar, dan dengan apakah kami dapat mengalahkan dia dan mengikat dia untuk menundukkannya. Maka kami masing-masing akan memberikan seribu seratus uang perak kepadamu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 6, 'Lalu berkatalah Delila kepada Simson: "Ceritakanlah kiranya kepadaku, karena apakah kekuatanmu demikian besar, dan dengan apakah engkau harus diikat untuk ditundukkan?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 7, 'Jawab Simson kepadanya: "Jika aku diikat dengan tujuh tali busur yang baru, yang belum kering, maka aku akan menjadi lemah dan menjadi seperti orang lain manapun juga."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 8, 'Lalu raja-raja kota orang Filistin membawa tujuh tali busur yang baru yang belum kering kepada perempuan itu dan ia mengikat Simson dengan tali-tali itu,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 9, 'sedang di kamarnya ada orang bersiap-siap. Kemudian berserulah perempuan itu kepadanya: "Orang-orang Filistin menyergap engkau, Simson!" Tetapi ia memutuskan tali-tali busur itu seperti tali rami yang terbakar putus, apabila kena api. Dan tidaklah ketahuan di mana duduk kekuatannya itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 10, 'Kemudian berkatalah Delila kepada Simson: "Sesungguhnya engkau telah mempermain-mainkan dan membohongi aku. Sekarang ceritakanlah kiranya kepadaku dengan apa engkau dapat diikat."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 11, 'Jawabnya kepadanya: "Jika aku diikat erat-erat dengan tali baru, yang belum terpakai untuk pekerjaan apapun, maka aku akan menjadi lemah dan menjadi seperti orang lain manapun juga."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 12, 'Kemudian Delila mengambil tali baru, diikatnyalah dia dengan tali-tali itu dan berseru kepadanya: "Orang-orang Filistin menyergap engkau, Simson!" ?di kamar ada orang bersiap-siap?tetapi tali-tali itu diputuskannya tanggal dari tangannya seperti benang saja.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 13, 'Berkatalah Delila kepada Simson: "Sampai sekarang engkau telah mempermain-mainkan dan membohongi aku. Ceritakanlah kepadaku dengan apakah engkau dapat diikat." Jawabnya kepadanya: "Kalau engkau menenun ketujuh rambut jalinku bersama-sama dengan lungsin lalu mengokohkannya dengan patok, maka aku akan menjadi lemah dan menjadi seperti orang lain manapun juga."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 14, 'Kemudian perempuan itu mengokohkan lagi tenunan itu dengan patok, lalu berserulah ia kepadanya: "Orang-orang Filistin menyergap engkau, Simson." Tetapi ketika ia terjaga dari tidurnya, disentaknya lepas patok tenunan dan lungsin itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 15, 'Berkatalah perempuan itu kepadanya: "Bagaimana mungkin engkau berkata: Aku cinta kepadamu, padahal hatimu tidak tertuju kepadaku? Sekarang telah tiga kali engkau mempermain-mainkan aku dan tidak mau menceritakan kepadaku, karena apakah kekuatanmu demikian besar."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 16, 'Lalu setelah perempuan itu berhari-hari merengek-rengek kepadanya dan terus mendesak-desak dia, ia tidak dapat lagi menahan hati, sehingga ia mau mati rasanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 17, 'Maka diceritakannyalah kepadanya segala isi hatinya, katanya: "Kepalaku tidak pernah kena pisau cukur, sebab sejak dari kandungan ibuku aku ini seorang nazir Allah. Jika kepalaku dicukur, maka kekuatanku akan lenyap dari padaku, dan aku menjadi lemah dan sama seperti orang-orang lain."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 18, 'Ketika dilihat Delila, bahwa segala isi hatinya telah diceritakannya kepadanya, disuruhnyalah memanggil raja-raja kota orang Filistin, katanya: "Sekali ini lagi datanglah ke mari, sebab ia telah menceritakan segala isi hatinya kepadaku." Lalu datanglah raja-raja kota orang Filistin itu kepadanya sambil membawa uang itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 19, 'Sesudah itu dibujuknya Simson tidur di pangkuannya, lalu dipanggilnya seorang dan disuruhnya mencukur ketujuh rambut jalinnya, sehingga mulailah Simson ditundukkan oleh perempuan itu, sebab kekuatannya telah lenyap dari padanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 20, 'Lalu berserulah perempuan itu: "Orang Filistin menyergap engkau, Simson!" Maka terjagalah ia dari tidurnya serta katanya: "Seperti yang sudah-sudah, aku akan bebas dan akan meronta lepas." Tetapi tidaklah diketahuinya, bahwa TUHAN telah meninggalkan dia.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 21, 'Orang Filistin itu menangkap dia, mencungkil kedua matanya dan membawanya ke Gaza. Di situ ia dibelenggu dengan dua rantai tembaga dan pekerjaannya di penjara ialah menggiling.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 22, 'Tetapi rambutnya mulai tumbuh pula sesudah dicukur.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 23, 'Sesudah itu berkumpullah raja-raja kota orang Filistin untuk mengadakan perayaan korban sembelihan yang besar kepada Dagon, allah mereka, dan untuk bersukaria; kata mereka: "Telah diserahkan oleh allah kita ke dalam tangan kita Simson, musuh kita."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 24, 'Dan ketika orang banyak melihat Simson, mereka memuji allah mereka, sambil berseru: "Telah diserahkan oleh allah kita ke dalam tangan kita musuh kita, perusak tanah kita, dan yang membunuh banyak teman kita."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 25, 'Ketika hati mereka riang gembira, berkatalah mereka: "Panggillah Simson untuk melawak bagi kita." Simson dipanggil dari penjara, lalu ia melawak di depan mereka, kemudian mereka menyuruh dia berdiri di antara tiang-tiang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 26, 'Berkatalah Simson kepada anak yang menuntun dia: "Lepaskan aku dan biarkanlah aku meraba-raba tiang-tiang penyangga rumah ini, supaya aku dapat bersandar padanya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 27, 'Adapun gedung itu penuh dengan laki-laki dan perempuan; segala raja kota orang Filistin ada di sana, dan di atas sotoh ada kira-kira tiga ribu orang laki-laki dan perempuan, yang menonton lawak Simson itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 28, 'Berserulah Simson kepada TUHAN, katanya: "Ya Tuhan ALLAH, ingatlah kiranya kepadaku dan buatlah aku kuat, sekali ini saja, ya Allah, supaya dengan satu pembalasan juga kubalaskan kedua mataku itu kepada orang Filistin."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 29, 'Kemudian Simson merangkul kedua tiang yang paling tengah, penyangga rumah itu, lalu bertopang kepada tiang yang satu dengan tangan kanannya dan kepada tiang yang lain dengan tangan kirinya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 30, 'Berkatalah Simson: "Biarlah kiranya aku mati bersama-sama orang Filistin ini." Lalu membungkuklah ia sekuat-kuatnya, maka rubuhlah rumah itu menimpa raja-raja kota itu dan seluruh orang banyak yang ada di dalamnya. Yang mati dibunuhnya pada waktu matinya itu lebih banyak dari pada yang dibunuhnya pada waktu hidupnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 16, 31, 'Sesudah itu datanglah ke sana saudara-saudaranya dan seluruh keluarganya, mereka mengangkat dia dan membawanya dari sana, lalu menguburkannya di antara Zora dan Esytaol di dalam kubur Manoah, ayahnya. Dia memerintah sebagai hakim atas orang Israel dua puluh tahun lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 1, 'Ada seorang dari pegunungan Efraim, Mikha namanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 2, 'Berkatalah ia kepada ibunya: "Uang perak yang seribu seratus itu, yang diambil orang dari padamu dan yang karena itu kauucapkan kutuk?aku sendiri mendengar ucapanmu itu?memang uang itu ada padaku, akulah yang mengambilnya." Lalu kata ibunya: "Diberkatilah kiranya anakku oleh TUHAN."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 3, 'Sesudah itu dikembalikannyalah uang perak yang seribu seratus itu kepada ibunya. Tetapi ibunya berkata: "Aku mau menguduskan uang itu bagi TUHAN, aku menyerahkannya untuk anakku, supaya dibuat patung pahatan dan patung tuangan dari pada uang itu. Maka sekarang, uang itu kukembalikan kepadamu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 4, 'Tetapi orang itu mengembalikan uang itu kepada ibunya, lalu perempuan itu mengambil dua ratus uang perak dan memberikannya kepada tukang perak, yang membuat patung pahatan dan patung tuangan dari pada uang itu; lalu patung itu ditaruh di rumah Mikha.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 5, 'Mikha ini mempunyai kuil. Dibuatnyalah efod dan terafim, ditahbiskannya salah seorang anaknya laki-laki, yang menjadi imamnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 6, 'Pada zaman itu tidak ada raja di antara orang Israel; setiap orang berbuat apa yang benar menurut pandangannya sendiri.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 7, 'Maka ada seorang muda dari Betlehem-Yehuda, dari kaum Yehuda; ia seorang Lewi dan tinggal di sana sebagai pendatang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 8, 'Lalu orang itu keluar dari kota Betlehem-Yehuda untuk menetap sebagai pendatang di mana saja ia mendapat tempat; dan dalam perjalanannya itu sampailah ia ke pegunungan Efraim di rumah Mikha.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 9, 'Bertanyalah Mikha kepadanya: "Engkau dari mana?" Jawabnya kepadanya: "Aku orang Lewi dari Betlehem-Yehuda, dan aku pergi untuk menetap sebagai pendatang di mana saja aku mendapat tempat."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 10, 'Lalu kata Mikha kepadanya: "Tinggallah padaku dan jadilah bapak dan imam bagiku; maka setiap tahun aku akan memberikan kepadamu sepuluh uang perak, sepasang pakaian serta makananmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 11, 'Orang Lewi itu setuju untuk tinggal padanya. Maka orang muda itu menjadi seperti salah seorang anaknya sendiri.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 12, 'Mikha mentahbiskan orang Lewi itu; orang muda itu menjadi imamnya dan diam di rumah Mikha.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 17, 13, 'Lalu kata Mikha: "Sekarang tahulah aku, bahwa TUHAN akan berbuat baik kepadaku, karena ada seorang Lewi menjadi imamku."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 1, 'Pada zaman itu tidak ada raja di antara orang Israel dan pada zaman itu suku Dan sedang mencari milik pusaka untuk menetap, sebab sampai hari itu mereka belum juga mendapat bagian milik pusaka di tengah-tengah suku-suku Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 2, 'Sebab itu bani Dan menyuruh dari kaumnya lima orang dari seluruh jumlah mereka, semuanya orang-orang yang gagah perkasa, yang berasal dari Zora dan Esytaol, untuk mengintai negeri itu dan menyelidikinya, serta berkata kepada mereka: "Pergilah menyelidiki negeri itu." Ketika orang-orang itu sampai ke pegunungan Efraim di rumah Mikha, bermalamlah mereka di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 3, 'Ketika mereka ada dekat rumah Mikha itu, dikenal merekalah logat orang muda suku Lewi itu, lalu singgahlah mereka ke sana dan berkata kepadanya: "Siapakah yang membawa engkau ke mari? Apakah pekerjaanmu dan urusanmu di sini?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 4, 'Katanya kepada mereka: "Begini begitulah dilakukan Mikha kepadaku; ia menggaji aku dan aku menjadi imamnya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 5, 'Kata mereka kepadanya: "Tanyakanlah kiranya kepada Allah, supaya kami ketahui apakah perjalanan yang kami tempuh ini akan berhasil."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 6, 'Kata imam itu kepada mereka: "Pergilah dengan selamat! Perjalanan yang kamu tempuh itu dipandang baik oleh TUHAN."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 7, 'Sesudah itu pergilah kelima orang itu, lalu sampailah mereka ke Lais. Dilihat merekalah, bahwa rakyat yang diam di sana hidup dengan tenteram, menurut adat orang Sidon, aman dan tenteram. Orang-orang itu tidak kekurangan apapun yang ada di muka bumi, malah kaya harta. Mereka tinggal jauh dari orang Sidon dan tidak bergaul dengan siapapun juga.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 8, 'Setelah mereka kembali kepada saudara-saudara sesukunya di Zora dan Esytaol, berkatalah saudara-saudara sesukunya kepada mereka: "Apakah yang kamu dapati di sana?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 9, 'Jawab mereka: "Bersiaplah, marilah kita maju menyerang mereka, sebab kami telah melihat negeri itu, dan memang sangat baik. Masakan kamu tinggal diam! Janganlah bermalas-malas untuk pergi memasuki dan menduduki negeri itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 10, 'Apabila kamu memasukinya kamu mendapati rakyat yang hidup dengan tenteram, dan negeri itu luas ke sebelah kiri dan ke sebelah kanan. Sesungguhnya, Allah telah menyerahkannya ke dalam tanganmu; itulah tempat yang tidak kekurangan apapun yang ada di muka bumi."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 11, 'Lalu berangkatlah dari sana, dari Zora dan Esytaol, enam ratus orang dari kaum suku Dan, diperlengkapi dengan senjata.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 12, 'Mereka maju, lalu berkemah di Kiryat-Yearim di Yehuda. Itulah sebabnya tempat itu disebut Mahane-Dan sampai sekarang; letaknya di sebelah barat Kiryat-Yearim.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 13, 'Dari sana mereka bergerak terus ke pegunungan Efraim dan sampai di rumah Mikha.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 14, 'Lalu berbicaralah kelima orang yang telah pergi mengintai daerah Lais itu, katanya kepada saudara-saudara sesukunya: "Tahukah kamu, bahwa dalam rumah-rumah ini ada efod, terafim, patung pahatan dan patung tuangan? Oleh sebab itu, insafilah apa yang akan kamu perbuat!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 15, 'Kemudian mereka menuju ke tempat itu, lalu sampai di rumah orang muda suku Lewi itu, di rumah Mikha, dan menanyakan apakah ia selamat.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 16, 'Sementara keenam ratus orang dari bani Dan yang diperlengkapi dengan senjata itu tinggal berdiri di pintu gerbang,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 17, 'maka kelima orang yang telah pergi mengintai negeri itu berjalan terus, masuk ke dalam lalu mengambil patung pahatan, efod, terafim dan patung tuangan itu. Adapun imam itu berdiri di pintu gerbang bersama-sama dengan keenam ratus orang yang diperlengkapi dengan senjata itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 18, 'Tetapi, setelah yang lain-lain itu masuk ke dalam rumah Mikha dan mengambil patung pahatan, efod, terafim dan patung tuangan itu, berkatalah imam itu kepada mereka: "Berbuat apakah kamu ini?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 19, 'Tetapi jawab mereka kepadanya: "Diamlah, tutup mulut, ikutlah kami dan jadilah bapak dan imam kami. Apakah yang lebih baik bagimu: menjadi imam untuk seisi rumah satu orang atau menjadi imam untuk suatu suku dan kaum di antara orang Israel?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 20, 'Maka gembiralah hati imam itu, diambilnyalah efod, terafim dan patung pahatan itu, lalu masuk ke tengah-tengah orang banyak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 21, 'Kemudian berbaliklah mereka dan pergi, dengan anak-anak, ternak dan barang-barang yang berharga ditempatkan di depan mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 22, 'Ketika mereka telah jauh dari rumah Mikha, dikerahkanlah orang-orang dari rumah-rumah yang di dekat rumah Mikha dan orang-orang itu mengejar bani Dan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 23, 'Mereka memanggil-manggil bani Dan, maka berbaliklah orang-orang itu dan berkata kepada Mikha: "Mau apa engkau dengan mengerahkan orang?" Lalu jawabnya:', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 24, '"Allahku yang kubuat serta imam juga kamu ambil, lalu kamu pergi. Apakah lagi yang masih tinggal padaku? Bagaimana perkataanmu itu kepadaku: Mau apa engkau?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 25, 'Berkatalah bani Dan kepadanya: "Janganlah suaramu kedengaran lagi kepada kami, nanti ada orang yang menyerang engkau karena sakit hati dan dengan demikian engkau serta seisi rumahmu kehilangan nyawa."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 26, 'Lalu bani Dan melanjutkan perjalanannya, dan Mikha, setelah dilihatnya mereka itu lebih kuat dari padanya, berpalinglah ia pulang ke rumahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 27, 'Lalu bani Dan, dengan membawa barang-barang yang dibuat Mikha, juga imamnya, mendatangi Lais, yakni rakyat yang hidup dengan aman dan tenteram. Mereka memukul orang-orang itu dengan mata pedang dan kotanya dibakar.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 28, 'Tidak ada orang yang datang menolong, sebab kota itu jauh dari Sidon dan orang-orang kota itu tidak bergaul dengan siapapun juga. Letak kota itu di lembah Bet-Rehob. Kemudian bani Dan membangun kota itu kembali dan diam di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 29, 'Mereka menamai kota itu Dan, menurut nama bapa leluhur mereka, yakni Dan, yang lahir bagi Israel, tetapi nama kota itu dahulu adalah Lais.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 30, 'Bani Dan menegakkan bagi mereka sendiri patung pahatan itu, lalu Yonatan bin Gersom bin Musa bersama-sama dengan anak-anaknya menjadi imam bagi suku Dan, sampai penduduk negeri itu diangkut sebagai orang buangan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 18, 31, 'Demikianlah mereka menempatkan bagi mereka sendiri patung pahatan yang telah dibuat Mikha itu, dan patung itu ada di sana selama rumah Allah ada di Silo.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 1, 'Terjadilah pada zaman itu, ketika tidak ada raja di Israel, bahwa di balik pegunungan Efraim ada seorang Lewi tinggal sebagai pendatang. Ia mengambil seorang gundik dari Betlehem-Yehuda.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 2, 'Tetapi gundiknya itu berlaku serong terhadap dia dan pergi dari padanya ke rumah ayahnya di Betlehem-Yehuda, lalu tinggal di sana empat bulan lamanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 3, 'Berkemaslah suaminya itu, lalu pergi menyusul perempuan itu untuk membujuk dia dan membawanya kembali; bersama-sama dia bujangnya dan sepasang keledai. Ketika perempuan muda itu membawa dia masuk ke rumah ayahnya, dan ketika ayah itu melihat dia, maka bersukacitalah ia mendapatkannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 4, 'Mertuanya, ayah perempuan muda itu, tidak membiarkan dia pergi, sehingga ia tinggal tiga hari lamanya pada ayah itu; mereka makan, minum dan bermalam di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 5, 'Tetapi pada hari yang keempat, ketika mereka bangun pagi-pagi dan ketika orang Lewi itu berkemas untuk pergi, berkatalah ayah perempuan muda itu kepada menantunya: "Segarkanlah dirimu dahulu dengan sekerat roti, kemudian bolehlah kamu pergi."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 6, 'Jadi duduklah mereka, lalu makan dan minumlah keduanya bersama-sama. Kata ayah perempuan muda itu kepada laki-laki itu: "Baiklah putuskan untuk tinggal bermalam dan biarlah hatimu gembira."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 7, 'Tetapi ketika orang itu bangun untuk pergi juga, mertuanya itu mendesaknya, sehingga ia tinggal pula di sana bermalam.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 8, 'Pada hari yang kelima, ketika ia bangun pagi-pagi untuk pergi, berkatalah ayah perempuan muda itu: "Mari, segarkanlah dirimu dahulu, dan tinggallah sebentar lagi, sampai matahari surut." Lalu makanlah mereka keduanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 9, 'Ketika orang itu bangun untuk pergi, bersama dengan gundiknya dan bujangnya, berkatalah mertuanya, ayah perempuan muda itu, kepadanya: "Lihatlah, matahari telah mulai turun menjelang petang; baiklah tinggal bermalam, lihat, matahari hampir terbenam, tinggallah di sini bermalam dan biarlah hatimu gembira; maka besok kamu dapat bangun pagi-pagi untuk berjalan dan pulang ke rumahmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 10, 'Tetapi orang itu tidak mau tinggal bermalam; ia berkemas, lalu pergi. Demikian sampailah ia di daerah yang berhadapan dengan Yebus?itulah Yerusalem?;bersama-sama dengan dia ada sepasang keledai yang berpelana dan gundiknya juga.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 11, 'Ketika mereka dekat ke Yebus dan ketika matahari telah sangat rendah, berkatalah bujang itu kepada tuannya: "Marilah kita singgah di kota orang Yebus ini dan bermalam di situ."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 12, 'Tetapi tuannya menjawabnya: "Kita tidak akan singgah di kota asing yang bukan kepunyaan orang Israel, tetapi kita akan berjalan terus sampai ke Gibea."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 13, 'Lagi katanya kepada bujangnya: "Marilah kita berjalan sampai ke salah satu tempat yang di sana dan bermalam di Gibea atau di Rama."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 14, 'Lalu berjalanlah mereka melanjutkan perjalanannya, dan matahari terbenam, ketika mereka dekat Gibea kepunyaan suku Benyamin.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 15, 'Sebab itu singgahlah mereka di Gibea, lalu masuk untuk bermalam di situ, dan setelah sampai, duduklah mereka di tanah lapang kota. Tetapi tidak ada seorangpun yang mengajak mereka ke rumah untuk bermalam.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 16, 'Tetapi datanglah pada malam itu seorang tua, yang pulang dari pekerjaannya di ladang. Orang itu berasal dari pegunungan Efraim dan tinggal di Gibea sebagai pendatang, tetapi penduduk tempat itu adalah orang Benyamin.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 17, 'Ketika ia mengangkat mukanya dan melihat orang yang dalam perjalanan itu di tanah lapang kota, berkatalah orang tua itu: "Ke manakah engkau pergi dan dari manakah engkau datang?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 18, 'Jawabnya kepadanya: "Kami sedang dalam perjalanan dari Betlehem-Yehuda ke balik pegunungan Efraim. Dari sanalah aku berasal; aku tadinya pergi ke Betlehem-Yehuda dan sekarang sedang berjalan pulang ke rumah. Tetapi tidak ada orang yang mengajak aku ke rumahnya,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 19, 'walaupun ada padaku jerami dan makanan untuk keledai kami, pula roti dan anggur untuk aku sendiri, untuk hambamu perempuan ini dan untuk bujang yang bersama-sama dengan hambamu ini; kami tidak kekurangan sesuatu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 20, 'Lalu berkatalah orang tua itu: "Jangan kuatir! Segala yang engkau perlukan biarlah aku yang menanggung, tetapi janganlah engkau bermalam di tanah lapang kota ini."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 21, 'Sesudah itu dibawanyalah dia masuk ke rumahnya, lalu keledai-keledai diberinya makan; maka merekapun membasuh kaki, makan dan minum.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 22, 'Tetapi sementara mereka menggembirakan hatinya, datanglah orang-orang kota itu, orang-orang dursila, mengepung rumah itu. Mereka menggedor-gedor pintu sambil berkata kepada orang tua, pemilik rumah itu: "Bawalah ke luar orang yang datang ke rumahmu itu, supaya kami pakai dia."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 23, 'Lalu keluarlah pemilik rumah itu menemui mereka dan berkata kepada mereka: "Tidak, saudara-saudaraku, janganlah kiranya berbuat jahat; karena orang ini telah masuk ke rumahku, janganlah kamu berbuat noda.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 24, 'Tetapi ada anakku perempuan, yang masih perawan, dan juga gundik orang itu, baiklah kubawa keduanya ke luar; perkosalah mereka dan perbuatlah dengan mereka apa yang kamu pandang baik, tetapi terhadap orang ini janganlah kamu berbuat noda."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 25, 'Tetapi orang-orang itu tidak mau mendengarkan perkataannya. Lalu orang Lewi itu menangkap gundiknya dan membawanya kepada mereka ke luar, kemudian mereka bersetubuh dengan perempuan itu dan semalam-malaman itu mereka mempermainkannya, sampai pagi. Barulah pada waktu fajar menyingsing mereka melepaskan perempuan itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 26, 'Menjelang pagi perempuan itu datang kembali, tetapi ia jatuh rebah di depan pintu rumah orang itu, tempat tuannya bermalam, dan ia tergeletak di sana sampai fajar.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 27, 'Pada waktu tuannya bangun pagi-pagi, dibukanya pintu rumah dan pergi ke luar untuk melanjutkan perjalanannya, tetapi tampaklah perempuan itu, gundiknya, tergeletak di depan pintu rumah dengan tangannya pada ambang pintu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 28, 'Berkatalah ia kepada perempuan itu: "Bangunlah, marilah kita pergi." Tetapi tidak ada jawabnya. Lalu diangkatnyalah mayat itu ke atas keledai, berkemaslah ia, kemudian pergi ke tempat kediamannya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 29, 'Sesampai di rumah, diambilnyalah pisau, dipegangnyalah mayat gundiknya, dipotong-potongnya menurut tulang-tulangnya menjadi dua belas potongan, lalu dikirimnya ke seluruh daerah orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 19, 30, 'Dan setiap orang yang melihatnya, berkata: "Hal yang demikian belum pernah terjadi dan belum pernah terlihat, sejak orang Israel berangkat keluar dari tanah Mesir sampai sekarang. Perhatikanlah itu, pertimbangkanlah, lalu berbicaralah!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 1, 'Lalu majulah semua orang Israel; dari Dan sampai Bersyeba dan juga dari tanah Gilead berkumpullah umat itu secara serentak menghadap TUHAN di Mizpa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 2, 'Maka berdirilah para pemuka dari seluruh bangsa itu, dari segala suku orang Israel, memimpin jemaah umat Allah yang jumlahnya empat ratus ribu orang berjalan kaki, yang bersenjatakan pedang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 3, 'Kedengaranlah kepada bani Benyamin, bahwa orang Israel telah maju ke Mizpa. Berkatalah orang Israel: "Ceritakan bagaimana kejahatan itu terjadi."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 4, 'Lalu orang Lewi, suami perempuan yang terbunuh itu, menjawab: "Aku sampai dengan gundikku di Gibea kepunyaan suku Benyamin untuk bermalam di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 5, 'Lalu warga-warga kota Gibea itu mendatangi aku dan mengepung rumah itu pada malam hari untuk menyerang aku. Mereka bermaksud membunuh aku, tetapi gundikku diperkosa mereka, sehingga mati.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 6, 'Maka kuambillah mayat gundikku, kupotong-potong dia dan kukirimkan ke seluruh daerah milik pusaka orang Israel, sebab orang-orang itu telah berbuat mesum dan berbuat noda di antara orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 7, 'Sekarang kamu sekalian, orang Israel, telah ada di sini. Berikanlah di sini pertimbanganmu dan nasihatmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 8, 'Kemudian bangunlah seluruh bangsa itu dengan serentak, sambil berkata: "Seorangpun dari pada kita takkan pergi ke kemahnya, seorangpun dari pada kita takkan pulang ke rumahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 9, 'Inilah yang akan kita lakukan kepada Gibea; memeranginya, dengan membuang undi!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 10, 'Kita akan memilih dari seluruh suku Israel sepuluh orang dari tiap-tiap seratus, seratus orang dari tiap-tiap seribu, seribu orang dari tiap-tiap sepuluh ribu, untuk mengambil bekal bagi laskar ini, supaya sesudah mereka datang, dilakukan kepada Gibea-Benyamin setimpal dengan segala perbuatan noda yang telah diperbuat mereka di antara orang Israel."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 11, 'Demikianlah orang Israel berkumpul melawan kota itu, semuanya bersekutu dengan serentak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 12, 'Kemudian suku-suku Israel mengirim orang kepada seluruh suku Benyamin dengan pesan: "Apa macam kejahatan yang terjadi di antara kamu itu!', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 13, 'Maka sekarang, serahkanlah orang-orang itu, yakni orang-orang dursila yang di Gibea itu, supaya kami menghukum mati mereka dan dengan demikian menghapuskan yang jahat itu dari antara orang Israel." Tetapi bani Benyamin tidak mau mendengarkan perkataan saudara-saudaranya, orang Israel itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 14, 'Sebaliknya, bani Benyamin dari kota-kota lain berkumpul di Gibea untuk maju berperang melawan orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 15, 'Pada hari itu dihitunglah jumlah bani Benyamin dari kota-kota lain itu: dua puluh enam ribu orang yang bersenjatakan pedang, belum termasuk penduduk Gibea, yang terhitung tujuh ratus orang pilihan banyaknya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 16, 'Dari segala laskar ini ada tujuh ratus orang pilihan yang kidal, dan setiap orang dari mereka dapat mengumban dengan tidak pernah meleset sampai sehelai rambutpun.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 17, 'Juga orang-orang Israel dihitung jumlahnya; dengan tidak termasuk suku Benyamin ada empat ratus ribu orang yang bersenjatakan pedang; semuanya itu prajurit.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 18, 'Lalu orang Israel berangkat dan maju ke Betel. Di sana mereka bertanya kepada Allah: "Siapakah dari kami yang lebih dahulu maju berperang melawan bani Benyamin?" Jawab TUHAN: "Suku Yehudalah lebih dahulu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 19, 'Lalu orang-orang Israel bangun pagi-pagi dan berkemah mengepung Gibea.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 20, 'Kemudian majulah orang-orang Israel berperang melawan suku Benyamin; orang-orang Israel mengatur barisan perangnya melawan mereka dekat Gibea.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 21, 'Juga bani Benyamin maju menyerang dari Gibea dan menggugurkan ke bumi dua puluh dua ribu orang dari antara orang Israel pada hari itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 22, 'Tetapi laskar orang Israel mengumpulkan segenap kekuatannya, lalu mengatur pula barisan perangnya di tempat mereka mengatur barisannya semula.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 23, 'Kemudian pergilah orang-orang Israel, lalu menangis di hadapan TUHAN sampai petang, sesudah itu mereka bertanya kepada TUHAN: "Akan pergi pulakah kami berperang melawan bani Benyamin, saudara kami itu?" Jawab TUHAN: "Majulah melawan mereka."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 24, 'Tetapi ketika orang-orang Israel pada hari kedua sampai di dekat bani Benyamin,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 25, 'maka pada hari kedua itu majulah suku Benyamin dari Gibea menyerbu mereka, dan digugurkannya pula ke bumi delapan belas ribu orang di antara orang-orang Israel; semuanya orang-orang yang bersenjatakan pedang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 26, 'Kemudian pergilah semua orang Israel, yakni seluruh bangsa itu, lalu sampai di Betel; di sana mereka tinggal menangis di hadapan TUHAN, berpuasa sampai senja pada hari itu dan mempersembahkan korban bakaran dan korban keselamatan di hadapan TUHAN.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 27, 'Dan orang-orang Israel bertanya kepada TUHAN?pada waktu itu ada di sana tabut perjanjian Allah,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 28, 'dan Pinehas bin Eleazar bin Harun menjadi imam Allah pada waktu itu?kata mereka: "Haruskah kami maju sekali lagi untuk berperang melawan bani Benyamin, saudara kami itu, atau haruskah kami hentikan itu?" Jawab TUHAN: "Majulah, sebab besok Aku akan menyerahkan mereka ke dalam tanganmu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 29, 'Lalu orang Israel menempatkan penghadang-penghadang sekeliling Gibea.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 30, 'Pada hari ketiga majulah orang-orang Israel melawan bani Benyamin dan mengatur barisannya melawan Gibea seperti yang sudah-sudah.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 31, 'Maka majulah bani Benyamin menyerbu laskar itu; mereka terpancing dari kota, dan seperti yang sudah-sudah, mereka mulai menyerang laskar itu pada kedua jalan raya?yang satu menuju ke Betel, dan yang lain ke Gibea melalui padang?sehingga terbunuh beberapa orang, kira-kira tiga puluh orang di antara orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 32, 'Maka kata bani Benyamin: "Orang-orang itu telah terpukul kalah oleh kita seperti semula." Tetapi orang-orang Israel telah bermupakat lebih dahulu: "Marilah kita lari dan memancing mereka dari kota ke jalan-jalan raya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 33, 'Jadi orang Israel bangun dari tempatnya dan mengatur barisannya di Baal-Tamar, sedang orang Israel yang menghadang itu tiba-tiba keluar dari tempatnya, yakni tempat terbuka dekat Geba,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 34, 'dan sampai di depan Gibea, sebanyak sepuluh ribu orang pilihan dari seluruh Israel. Pertempuran itu dahsyat, tetapi bani Benyamin tidak tahu bahwa malapetaka datang menimpa mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 35, 'TUHAN membuat suku Benyamin terpukul kalah oleh orang Israel, dan pada hari itu orang-orang Israel memusnahkan dari antara suku Benyamin dua puluh lima ribu seratus orang, semuanya orang-orang yang bersenjatakan pedang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 36, 'Bani Benyamin melihat, bahwa mereka telah terpukul kalah. Sementara orang-orang Israel agak mundur di depan suku Benyamin?sebab mereka mempercayai penghadang-penghadang yang ditempatkan mereka untuk menyerang Gibea?', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 37, 'maka segeralah penghadang-penghadang itu menyerbu Gibea. Mereka bergerak maju dan memukul seluruh kota itu dengan mata pedang.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 38, 'Tetapi orang-orang Israel telah bermupakat dengan penghadang-penghadang itu untuk menaikkan gumpalan asap tebal dari kota itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 39, 'Ketika orang-orang Israel mundur dalam pertempuran itu, maka suku Benyamin mulai menyerang orang Israel, sehingga terbunuh kira-kira tiga puluh orang, karena pikir mereka: "Tentulah orang-orang itu terpukul kalah sama sekali oleh kita seperti dalam pertempuran yang dahulu."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 40, 'Tetapi pada waktu itu mulailah gumpalan asap naik dari kota itu seperti tiang asap. Suku Benyamin menoleh ke belakang dan tampaklah kota itu seluruhnya terbakar, apinya naik ke langit.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 41, 'Lagipula orang-orang Israel maju lagi. Maka gemetarlah orang-orang Benyamin itu, sebab mereka melihat, bahwa malapetaka datang menimpa mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 42, 'Jadi larilah mereka dari depan orang-orang Israel itu, ke arah padang gurun, tetapi pertempuran itu tidak dapat dihindari mereka, lalu orang-orang dari kota-kota menghabisi mereka di tengah-tengahnya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 43, 'Mereka mengepung suku Benyamin itu, mengejarnya dengan tak henti-hentinya dan melandanya sampai di depan Gibea, di sebelah timur.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 44, 'Dari bani Benyamin ada tewas delapan belas ribu orang, semuanya orang-orang gagah perkasa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 45, 'Yang lain berpaling lari ke padang gurun, ke bukit batu Rimon. Tetapi di jalan-jalan raya masih diadakan penyabitan susulan di antara mereka: lima ribu orang; mereka diburu sampai ke Gideom dan dipukul mati dua ribu orang dari mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 46, 'Maka yang tewas dari suku Benyamin pada hari itu seluruhnya berjumlah dua puluh lima ribu orang yang bersenjatakan pedang, semuanya orang-orang gagah perkasa.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 47, 'Tetapi enam ratus orang berpaling lari ke padang gurun, ke bukit batu Rimon, dan tinggal empat bulan lamanya di bukit batu itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 20, 48, 'Tetapi orang-orang Israel kembali kepada bani Benyamin dan memukul mereka dengan mata pedang, baik manusia baik hewan dan segala sesuatu yang terdapat di sana. Juga segala kota yang terdapat di sana mereka musnahkan dengan api.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 1, 'Orang-orang Israel telah bersumpah di Mizpa, demikian: "Seorangpun dari kita takkan memberikan anaknya perempuan kepada seorang Benyamin menjadi isterinya."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 2, 'Ketika bangsa itu datang ke Betel dan tinggal di situ di hadapan Allah sampai petang, maka merekapun menyaringkan suaranya menangis dengan sangat keras,', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 3, 'katanya: "Mengapa, ya TUHAN, Allah Israel, terjadi hal yang begini di antara orang Israel, yakni bahwa hari ini satu suku dari antara orang Israel hilang?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 4, 'Keesokan harinya pagi-pagi maka bangsa itu mendirikan mezbah di situ, lalu mempersembahkan korban bakaran dan korban keselamatan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 5, 'Pada waktu itu berkatalah orang-orang Israel: "Siapakah dari seluruh suku Israel yang tidak ikut datang dengan jemaah ini untuk menghadap TUHAN?" Sebab mereka telah bersumpah dengan sungguh-sungguh mengenai orang yang tidak datang menghadap TUHAN di Mizpa, demikian: "Pastilah ia dihukum mati."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 6, 'Orang-orang Israel merasa kasihan terhadap suku Benyamin, saudaranya itu, maka kata mereka: "Hari ini ada satu suku terputus dari orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 7, 'Apakah yang dapat kita lakukan kepada orang-orang yang tinggal itu dalam hal mencarikan isteri, karena kitalah yang bersumpah demi TUHAN untuk tidak memberikan seorangpun dari anak-anak perempuan kita kepada mereka menjadi isterinya?"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 8, 'Sebab itu berkatalah mereka: "Dari suku-suku Israel adakah satu yang tidak datang menghadap TUHAN di Mizpa?" Lalu tampaklah, bahwa dari Yabesh-Gilead tidak ada seorangpun yang datang ke perkemahan jemaah itu.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 9, 'Lalu diperiksa jumlah bangsa itu, dan tampaklah tidak hadir seorangpun dari penduduk Yabesh-Gilead.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 10, 'Maka perkumpulan itu menyuruh ke situ dua belas ribu orang dari orang-orang gagah perkasa dengan memerintahkan kepada mereka, demikian: "Pergilah, pukullah penduduk Yabesh-Gilead dengan mata pedang, juga perempuan-perempuan dan anak-anak.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 11, 'Tetapi perbuatlah begini: hanya semua laki-laki sajalah dan semua perempuan yang telah pernah tidur dengan laki-laki harus kamu tumpas."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 12, 'Mereka menjumpai di antara penduduk Yabesh-Gilead empat ratus orang anak gadis, perawan yang belum pernah tidur dengan orang laki-laki, lalu gadis-gadis itu dibawa mereka ke perkemahan di Silo, di tanah Kanaan.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 13, 'Sesudah itu segenap umat itu menyuruh orang membawa pesan kepada bani Benyamin yang ada di bukit batu Rimon, lalu memaklumkan damai kepada mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 14, 'Pada waktu itu kembalilah suku Benyamin, dan kepada mereka diberikan perempuan-perempuan yang telah dibiarkan hidup dari antara perempuan Yabesh-Gilead; tetapi belum cukup juga jumlahnya bagi mereka.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 15, 'Maka bangsa itu merasa kasihan kepada suku Benyamin, karena TUHAN telah membuat keretakan di antara suku-suku Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 16, 'Kemudian berkatalah para tua-tua umat itu: "Apakah yang dapat kita lakukan kepada yang tinggal ini dalam hal mencarikan isteri? Sebab perempuan-perempuan telah punah dari antara suku Benyamin."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 17, 'Lagi kata mereka: "Warisan orang-orang yang terluput itu haruslah tetap tinggal pada suku Benyamin, supaya jangan ada suku yang terhapus dari antara orang Israel.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 18, 'Tetapi kita ini tidak dapat memberikan isteri kepada mereka dari anak-anak perempuan kita." Sebab orang-orang Israel telah bersumpah, demikian: "Terkutuklah orang yang memberikan isteri kepada suku Benyamin!"', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 19, 'Lalu kata mereka pula: "Setiap tahun ada perayaan bagi TUHAN di Silo yang letaknya di sebelah utara Betel, di sebelah timur jalan raya yang menuju dari Betel ke Sikhem dan di sebelah selatan Lebona."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 20, 'Maka mereka berpesan kepada bani Benyamin, demikian: "Pergilah menghadang di kebun-kebun anggur.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 21, 'Perhatikanlah baik-baik; maka apabila anak-anak perempuan Silo keluar untuk menari-nari, baiklah kamu keluar dari kebun-kebun anggur itu, dan masing-masing melarikan seorang dari anak-anak perempuan Silo itu menjadi isterinya dan pergi ke tanah Benyamin.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 22, 'Apabila ayah atau saudaranya laki-laki datang untuk menuntutnya kepada kami, maka kami akan berkata kepada mereka: Serahkanlah mereka itu kepada kami dengan rela hati, sebab dalam pertempuran kita tidak dapat menangkap seorang perempuan untuk menjadi isteri mereka masing-masing. Memang kamu ini tidak memberikan anak-anak gadis itu kepada mereka; sebab seandainya demikian, kamu bersalah."', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 23, 'Jadi bani Benyamin berbuat demikian; dari gadis-gadis yang menari-nari yang dirampas itu mereka mengambil perempuan, jumlahnya sama dengan jumlah mereka, kemudian pulanglah mereka ke milik pusakanya lalu membangun kota-kotanya kembali dan diam di sana.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 24, 'Pada waktu itu pergilah orang Israel dari sana, masing-masing menurut suku dan kaumnya; mereka masing-masing berangkat dari sana ke milik pusakanya.', 'id', 'TB'),
  ('7', 'hak', 'Hakim-Hakim', 21, 25, 'Pada zaman itu tidak ada raja di antara orang Israel; setiap orang berbuat apa yang benar menurut pandangannya sendiri.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 1, 'Pada zaman para hakim memerintah ada kelaparan di tanah Israel. Lalu pergilah seorang dari Betlehem-Yehuda beserta isterinya dan kedua anaknya laki-laki ke daerah Moab untuk menetap di sana sebagai orang asing.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 2, 'Nama orang itu ialah Elimelekh, nama isterinya Naomi dan nama kedua anaknya Mahlon dan Kilyon, semuanya orang-orang Efrata dari Betlehem-Yehuda; dan setelah sampai ke daerah Moab, diamlah mereka di sana.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 3, 'Kemudian matilah Elimelekh, suami Naomi, sehingga perempuan itu tertinggal dengan kedua anaknya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 4, 'Keduanya mengambil perempuan Moab: yang pertama bernama Orpa, yang kedua bernama Rut; dan mereka diam di situ kira-kira sepuluh tahun lamanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 5, 'Lalu matilah juga keduanya, yakni Mahlon dan Kilyon, sehingga perempuan itu kehilangan kedua anaknya dan suaminya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 6, 'Kemudian berkemaslah ia dengan kedua menantunya dan ia pulang dari daerah Moab, sebab di daerah Moab ia mendengar bahwa TUHAN telah memperhatikan umat-Nya dan memberikan makanan kepada mereka.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 7, 'Maka berangkatlah ia dari tempat tinggalnya itu, bersama-sama dengan kedua menantunya. Ketika mereka sedang di jalan untuk pulang ke tanah Yehuda,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 8, 'berkatalah Naomi kepada kedua menantunya itu: "Pergilah, pulanglah masing-masing ke rumah ibunya; TUHAN kiranya menunjukkan kasih-Nya kepadamu, seperti yang kamu tunjukkan kepada orang-orang yang telah mati itu dan kepadaku;', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 9, 'kiranya atas karunia TUHAN kamu mendapat tempat perlindungan, masing-masing di rumah suaminya." Lalu diciumnyalah mereka, tetapi mereka menangis dengan suara keras', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 10, 'dan berkata kepadanya: "Tidak, kami ikut dengan engkau pulang kepada bangsamu."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 11, 'Tetapi Naomi berkata: "Pulanglah, anak-anakku, mengapakah kamu turut dengan aku? Bukankah tidak akan ada lagi anak laki-laki yang kulahirkan untuk dijadikan suamimu nanti?', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 12, 'Pulanglah, anak-anakku, pergilah, sebab sudah terlalu tua aku untuk bersuami. Seandainya pikirku: Ada harapan bagiku, dan sekalipun malam ini aku bersuami, bahkan sekalipun aku masih melahirkan anak laki-laki,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 13, 'masakan kamu menanti sampai mereka dewasa? Masakan karena itu kamu harus menahan diri dan tidak bersuami? Janganlah kiranya demikian, anak-anakku, bukankah jauh lebih pahit yang aku alami dari pada kamu, sebab tangan TUHAN teracung terhadap aku?"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 14, 'Menangis pula mereka dengan suara keras, lalu Orpa mencium mertuanya itu minta diri, tetapi Rut tetap berpaut padanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 15, 'Berkatalah Naomi: "Telah pulang iparmu kepada bangsanya dan kepada para allahnya; pulanglah mengikuti iparmu itu."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 16, 'Tetapi kata Rut: "Janganlah desak aku meninggalkan engkau dan pulang dengan tidak mengikuti engkau; sebab ke mana engkau pergi, ke situ jugalah aku pergi, dan di mana engkau bermalam, di situ jugalah aku bermalam: bangsamulah bangsaku dan Allahmulah Allahku;', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 17, 'di mana engkau mati, akupun mati di sana, dan di sanalah aku dikuburkan. Beginilah kiranya TUHAN menghukum aku, bahkan lebih lagi dari pada itu, jikalau sesuatu apapun memisahkan aku dari engkau, selain dari pada maut!"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 18, 'Ketika Naomi melihat, bahwa Rut berkeras untuk ikut bersama-sama dengan dia, berhentilah ia berkata-kata kepadanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 19, 'Dan berjalanlah keduanya sampai mereka tiba di Betlehem. Ketika mereka masuk ke Betlehem, gemparlah seluruh kota itu karena mereka, dan perempuan-perempuan berkata: "Naomikah itu?"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 20, 'Tetapi ia berkata kepada mereka: "Janganlah sebutkan aku Naomi; sebutkanlah aku Mara, sebab Yang Mahakuasa telah melakukan banyak yang pahit kepadaku.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 21, 'Dengan tangan yang penuh aku pergi, tetapi dengan tangan yang kosong TUHAN memulangkan aku. Mengapakah kamu menyebutkan aku Naomi, karena TUHAN telah naik saksi menentang aku dan Yang Mahakuasa telah mendatangkan malapetaka kepadaku."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 1, 22, 'Demikianlah Naomi pulang bersama-sama dengan Rut, perempuan Moab itu, menantunya, yang turut pulang dari daerah Moab. Dan sampailah mereka ke Betlehem pada permulaan musim menuai jelai.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 1, 'Naomi itu mempunyai seorang sanak dari pihak suaminya, seorang yang kaya raya dari kaum Elimelekh, namanya Boas.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 2, 'Maka Rut, perempuan Moab itu, berkata kepada Naomi: "Biarkanlah aku pergi ke ladang memungut bulir-bulir jelai di belakang orang yang murah hati kepadaku." Dan sahut Naomi kepadanya: "Pergilah, anakku."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 3, 'Pergilah ia, lalu sampai di ladang dan memungut jelai di belakang penyabit-penyabit; kebetulan ia berada di tanah milik Boas, yang berasal dari kaum Elimelekh.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 4, 'Lalu datanglah Boas dari Betlehem. Ia berkata kepada penyabit-penyabit itu: "TUHAN kiranya menyertai kamu." Jawab mereka kepadanya: "TUHAN kiranya memberkati tuan!"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 5, 'Lalu kata Boas kepada bujangnya yang mengawasi penyabit-penyabit itu: "Dari manakah perempuan ini?"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 6, 'Bujang yang mengawasi penyabit-penyabit itu menjawab: "Dia adalah seorang perempuan Moab, dia pulang bersama-sama dengan Naomi dari daerah Moab.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 7, 'Tadi ia berkata: Izinkanlah kiranya aku memungut dan mengumpulkan jelai dari antara berkas-berkas jelai ini di belakang penyabit-penyabit. Begitulah ia datang dan terus sibuk dari pagi sampai sekarang dan seketikapun ia tidak berhenti."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 8, 'Sesudah itu berkatalah Boas kepada Rut: "Dengarlah dahulu, anakku! Tidak usah engkau pergi memungut jelai ke ladang lain dan tidak usah juga engkau pergi dari sini, tetapi tetaplah dekat pengerja-pengerja perempuan.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 9, 'Lihat saja ke ladang yang sedang disabit orang itu. Ikutilah perempuan-perempuan itu dari belakang. Sebab aku telah memesankan kepada pengerja-pengerja lelaki jangan mengganggu engkau. Jika engkau haus, pergilah ke tempayan-tempayan dan minumlah air yang dicedok oleh pengerja-pengerja itu."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 10, 'Lalu sujudlah Rut menyembah dengan mukanya sampai ke tanah dan berkata kepadanya: "Mengapakah aku mendapat belas kasihan dari padamu, sehingga tuan memperhatikan aku, padahal aku ini seorang asing?"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 11, 'Boas menjawab: "Telah dikabarkan orang kepadaku dengan lengkap segala sesuatu yang engkau lakukan kepada mertuamu sesudah suamimu mati, dan bagaimana engkau meninggalkan ibu bapamu dan tanah kelahiranmu serta pergi kepada suatu bangsa yang dahulu tidak engkau kenal.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 12, 'TUHAN kiranya membalas perbuatanmu itu, dan kepadamu kiranya dikaruniakan upahmu sepenuhnya oleh TUHAN, Allah Israel, yang di bawah sayap-Nya engkau datang berlindung."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 13, 'Kemudian berkatalah Rut: "Memang aku mendapat belas kasihan dari padamu, ya tuanku, sebab tuan telah menghiburkan aku dan telah menenangkan hati hambamu ini, walaupun aku tidak sama seperti salah seorang hamba-hambamu perempuan."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 14, 'Ketika sudah waktu makan, berkatalah Boas kepadanya: "Datanglah ke mari, makanlah roti ini dan celupkanlah suapmu ke dalam cuka ini." Lalu duduklah ia di sisi penyabit-penyabit itu, dan Boas mengunjukkan bertih gandum kepadanya; makanlah Rut sampai kenyang, bahkan ada sisanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 15, 'Setelah ia bangun untuk memungut pula, maka Boas memerintahkan kepada pengerja-pengerjanya: "Dari antara berkas-berkas itupun ia boleh memungut, janganlah ia diganggu;', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 16, 'bahkan haruslah kamu dengan sengaja menarik sedikit-sedikit dari onggokan jelai itu untuk dia dan meninggalkannya, supaya dipungutnya; janganlah berlaku kasar terhadap dia."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 17, 'Maka ia memungut di ladang sampai petang; lalu ia mengirik yang dipungutnya itu, dan ada kira-kira seefa jelai banyaknya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 18, 'Diangkatnyalah itu, lalu masuklah ia ke kota. Ketika mertuanya melihat apa yang dipungutnya itu, dan ketika dikeluarkannya dan diberikannya kepada mertuanya sisa yang ada setelah kenyang itu,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 19, 'maka berkatalah mertuanya kepadanya: "Di mana engkau memungut dan di mana engkau bekerja hari ini? Diberkatilah kiranya orang yang telah memperhatikan engkau itu!" Lalu diceritakannyalah kepada mertuanya itu pada siapa ia bekerja, katanya: "Nama orang pada siapa aku bekerja hari ini ialah Boas."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 20, 'Sesudah itu berkatalah Naomi kepada menantunya: "Diberkatilah kiranya orang itu oleh TUHAN yang rela mengaruniakan kasih setia-Nya kepada orang-orang yang hidup dan yang mati." Lagi kata Naomi kepadanya: "Orang itu kaum kerabat kita, dialah salah seorang yang wajib menebus kita."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 21, 'Lalu kata Rut, perempuan Moab itu: "Lagipula ia berkata kepadaku: Tetaplah dekat pengerja-pengerjaku sampai mereka menyelesaikan seluruh penyabitan ladangku."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 22, 'Lalu berkatalah Naomi kepada Rut, menantunya itu: "Ya anakku, sebaiknya engkau keluar bersama-sama dengan pengerja-pengerjanya perempuan, supaya engkau jangan disusahi orang di ladang lain."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 2, 23, 'Demikianlah Rut tetap dekat pada pengerja-pengerja perempuan Boas untuk memungut, sampai musim menuai jelai dan musim menuai gandum telah berakhir. Dan selama itu ia tinggal pada mertuanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 1, 'Lalu Naomi, mertuanya itu, berkata kepadanya: "Anakku, apakah tidak ada baiknya jika aku mencari tempat perlindungan bagimu supaya engkau berbahagia?', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 2, 'Maka sekarang, bukankah Boas, yang pengerja-pengerjanya perempuan telah kautemani itu, adalah sanak kita? Dia pada malam ini menampi jelai di tempat pengirikan;', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 3, 'maka mandilah dan beruraplah, pakailah pakaian bagusmu dan pergilah ke tempat pengirikan itu. Tetapi janganlah engkau ketahuan kepada orang itu, sebelum ia selesai makan dan minum.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 4, 'Jika ia membaringkan diri tidur, haruslah engkau perhatikan baik-baik tempat ia berbaring; kemudian datanglah dekat, singkapkanlah selimut dari kakinya dan berbaringlah di sana. Maka ia akan memberitahukan kepadamu apa yang harus kaulakukan."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 5, 'Lalu kata Rut kepadanya: "Segala yang engkau katakan itu akan kulakukan."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 6, 'Sesudah itu pergilah ia ke tempat pengirikan dan dilakukannyalah tepat seperti yang diperintahkan mertuanya kepadanya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 7, 'Setelah Boas habis makan dan minum dan hatinya gembira, datanglah ia untuk membaringkan diri tidur pada ujung timbunan jelai itu. Kemudian datanglah perempuan itu dekat dengan diam-diam, disingkapkannyalah selimut dari kaki Boas dan berbaringlah ia di situ.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 8, 'Pada waktu tengah malam dengan terkejut terjagalah orang itu, lalu meraba-raba ke sekelilingnya, dan ternyata ada seorang perempuan berbaring di sebelah kakinya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 9, 'Bertanyalah ia: "Siapakah engkau ini?" Jawabnya: "Aku Rut, hambamu: kembangkanlah kiranya sayapmu melindungi hambamu ini, sebab engkaulah seorang kaum yang wajib menebus kami."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 10, 'Lalu katanya: "Diberkatilah kiranya engkau oleh TUHAN, ya anakku! Sekarang engkau menunjukkan kasihmu lebih nyata lagi dari pada yang pertama kali itu, karena engkau tidak mengejar-ngejar orang-orang muda, baik yang miskin maupun yang kaya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 11, 'Oleh sebab itu, anakku, janganlah takut; segala yang kaukatakan itu akan kulakukan kepadamu; sebab setiap orang dalam kota kami tahu, bahwa engkau seorang perempuan baik-baik.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 12, 'Maka sekarang, memang aku seorang kaum yang wajib menebus, tetapi walaupun demikian masih ada lagi seorang penebus, yang lebih dekat dari padaku.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 13, 'Tinggallah di sini malam ini; dan besok pagi, jika ia mau menebus engkau, baik, biarlah ia menebus; tetapi jika ia tidak suka menebus engkau, maka akulah yang akan menebus engkau, demi TUHAN yang hidup. Berbaring sajalah tidur sampai pagi."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 14, 'Jadi berbaringlah ia tidur di sebelah kakinya sampai pagi; lalu bangunlah ia, sebelum orang dapat kenal-mengenal, sebab kata Boas: "Janganlah diketahui orang, bahwa seorang perempuan datang ke tempat pengirikan."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 15, 'Lagi katanya: "Berikanlah selendang yang engkau pakai itu dan tadahkanlah itu." Lalu ditadahkannya selendang itu. Kemudian ditakarnyalah enam takar jelai ke dalam selendang itu. Sesudah itu pergilah Boas ke kota.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 16, 'Setelah perempuan itu sampai kepada mertuanya, berkatalah mertuanya itu: "Bagaimana, anakku?" Lalu diceritakannyalah semua yang dilakukan orang itu kepadanya', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 17, 'serta berkata: "Yang enam takar jelai ini diberikannya kepadaku, sebab katanya: Engkau tidak boleh pulang kepada mertuamu dengan tangan hampa."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 3, 18, 'Lalu kata mertuanya itu: "Duduk sajalah menanti, anakku, sampai engkau mengetahui, bagaimana kesudahan perkara itu; sebab orang itu tidak akan berhenti, sebelum diselesaikannya perkara itu pada hari ini juga."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 1, 'Boas telah pergi ke pintu gerbang dan duduk di sana. Kebetulan lewatlah penebus yang disebutkan Boas itu. Lalu berkatalah Boas: "Hai saudara, datanglah dahulu ke mari, duduklah di sini." Maka datanglah ia, lalu duduk.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 2, 'Kemudian dipilihnyalah sepuluh orang dari para tua-tua kota itu, dan berkata: "Duduklah kamu di sini." Maka duduklah mereka.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 3, 'Lalu berkatalah ia kepada penebus itu: "Tanah milik kepunyaan saudara kita Elimelekh hendak dijual oleh Naomi, yang telah pulang dari daerah Moab.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 4, 'Jadi pikirku: baik juga hal itu kusampaikan kepadamu sebagai berikut: Belilah tanah itu di depan orang-orang yang duduk di sini dan di depan para tua-tua bangsa kita. Jika engkau mau menebusnya, tebuslah; tetapi jika engkau tidak mau menebusnya, beritahukanlah kepadaku, supaya aku tahu, sebab tidak ada orang yang dapat menebusnya kecuali engkau, dan sesudah engkau: aku." Lalu berkatalah ia: "Aku akan menebusnya."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 5, 'Tetapi kata Boas: "Pada waktu engkau membeli tanah itu dari tangan Naomi, engkau memperoleh Rut juga, perempuan Moab, isteri orang yang telah mati itu, untuk menegakkan nama orang itu di atas milik pusakanya."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 6, 'Lalu berkatalah penebus itu: "Jika demikian, aku ini tidak dapat menebusnya, sebab aku akan merusakkan milik pusakaku sendiri. Aku mengharap engkau menebus apa yang seharusnya aku tebus, sebab aku tidak dapat menebusnya."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 7, 'Beginilah kebiasaan dahulu di Israel dalam hal menebus dan menukar: setiap kali orang hendak menguatkan sesuatu perkara, maka yang seorang menanggalkan kasutnya sebelah dan memberikannya kepada yang lain. Demikianlah caranya orang mensahkan perkara di Israel.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 8, 'Lalu penebus itu berkata kepada Boas: "Engkau saja yang membelinya." Dan ditanggalkannyalah kasutnya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 9, 'Kemudian berkatalah Boas kepada para tua-tua dan kepada semua orang di situ: "Kamulah pada hari ini menjadi saksi, bahwa segala milik Elimelekh dan segala milik Kilyon dan Mahlon, aku beli dari tangan Naomi;', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 10, 'juga Rut, perempuan Moab itu, isteri Mahlon, aku peroleh menjadi isteriku untuk menegakkan nama orang yang telah mati itu di atas milik pusakanya. Demikianlah nama orang itu tidak akan lenyap dari antara saudara-saudaranya dan dari antara warga kota. Kamulah pada hari ini menjadi saksi."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 11, 'Dan seluruh orang banyak yang hadir di pintu gerbang, dan para tua-tua berkata: "Kamilah menjadi saksi. TUHAN kiranya membuat perempuan yang akan masuk ke rumahmu itu sama seperti Rahel dan Lea, yang keduanya telah membangunkan umat Israel. Biarlah engkau menjadi makmur di Efrata dan biarlah namamu termasyhur di Betlehem,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 12, 'keturunanmu kiranya menjadi seperti keturunan Peres yang dilahirkan Tamar bagi Yehuda oleh karena anak-anak yang akan diberikan TUHAN kepadamu dari perempuan muda ini!"', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 13, 'Lalu Boas mengambil Rut dan perempuan itu menjadi isterinya dan dihampirinyalah dia. Maka atas karunia TUHAN perempuan itu mengandung, lalu melahirkan seorang anak laki-laki.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 14, 'Sebab itu perempuan-perempuan berkata kepada Naomi: "Terpujilah TUHAN, yang telah rela menolong engkau pada hari ini dengan seorang penebus. Termasyhurlah kiranya nama anak itu di Israel.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 15, 'Dan dialah yang akan menyegarkan jiwamu dan memelihara engkau pada waktu rambutmu telah putih; sebab menantumu yang mengasihi engkau telah melahirkannya, perempuan yang lebih berharga bagimu dari tujuh anak laki-laki."', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 16, 'Dan Naomi mengambil anak itu serta meletakkannya pada pangkuannya dan dialah yang mengasuhnya.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 17, 'Dan tetangga-tetangga perempuan memberi nama kepada anak itu, katanya: "Pada Naomi telah lahir seorang anak laki-laki"; lalu mereka menyebutkan namanya Obed. Dialah ayah Isai, ayah Daud.', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 18, 'Inilah keturunan Peres: Peres memperanakkan Hezron,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 19, 'Hezron memperanakkan Ram, Ram memperanakkan Aminadab,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 20, 'Aminadab memperanakkan Nahason, Nahason memperanakkan Salmon,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 21, 'Salmon memperanakkan Boas, Boas memperanakkan Obed,', 'id', 'TB'),
  ('8', 'rut', 'Rut', 4, 22, 'Obed memperanakkan Isai dan Isai memperanakkan Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 1, 'Ada seorang laki-laki dari Ramataim-Zofim, dari pegunungan Efraim, namanya Elkana bin Yeroham bin Elihu bin Tohu bin Zuf, seorang Efraim.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 2, 'Orang ini mempunyai dua isteri: yang seorang bernama Hana dan yang lain bernama Penina; Penina mempunyai anak, tetapi Hana tidak.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 3, 'Orang itu dari tahun ke tahun pergi meninggalkan kotanya untuk sujud menyembah dan mempersembahkan korban kepada TUHAN semesta alam di Silo. Di sana yang menjadi imam TUHAN ialah kedua anak Eli, Hofni dan Pinehas.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 4, 'Pada hari Elkana mempersembahkan korban, diberikannyalah kepada Penina, isterinya, dan kepada semua anaknya yang laki-laki dan perempuan masing-masing sebagian.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 5, 'Meskipun ia mengasihi Hana, ia memberikan kepada Hana hanya satu bagian, sebab TUHAN telah menutup kandungannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 6, 'Tetapi madunya selalu menyakiti hatinya supaya ia gusar, karena TUHAN telah menutup kandungannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 7, 'Demikianlah terjadi dari tahun ke tahun; setiap kali Hana pergi ke rumah TUHAN, Penina menyakiti hati Hana, sehingga ia menangis dan tidak mau makan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 8, 'Lalu Elkana, suaminya, berkata kepadanya: "Hana, mengapa engkau menangis dan mengapa engkau tidak mau makan? Mengapa hatimu sedih? Bukankah aku lebih berharga bagimu dari pada sepuluh anak laki-laki?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 9, 'Pada suatu kali, setelah mereka habis makan dan minum di Silo, berdirilah Hana, sedang imam Eli duduk di kursi dekat tiang pintu bait suci TUHAN,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 10, 'dan dengan hati pedih ia berdoa kepada TUHAN sambil menangis tersedu-sedu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 11, 'Kemudian bernazarlah ia, katanya: "TUHAN semesta alam, jika sungguh-sungguh Engkau memperhatikan sengsara hamba-Mu ini dan mengingat kepadaku dan tidak melupakan hamba-Mu ini, tetapi memberikan kepada hamba-Mu ini seorang anak laki-laki, maka aku akan memberikan dia kepada TUHAN untuk seumur hidupnya dan pisau cukur tidak akan menyentuh kepalanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 12, 'Ketika perempuan itu terus-menerus berdoa di hadapan TUHAN, maka Eli mengamat-amati mulut perempuan itu;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 13, 'dan karena Hana berkata-kata dalam hatinya dan hanya bibirnya saja bergerak-gerak, tetapi suaranya tidak kedengaran, maka Eli menyangka perempuan itu mabuk.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 14, 'Lalu kata Eli kepadanya: "Berapa lama lagi engkau berlaku sebagai orang mabuk? Lepaskanlah dirimu dari pada mabukmu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 15, 'Tetapi Hana menjawab: "Bukan, tuanku, aku seorang perempuan yang sangat bersusah hati; anggur ataupun minuman yang memabukkan tidak kuminum, melainkan aku mencurahkan isi hatiku di hadapan TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 16, 'Janganlah anggap hambamu ini seorang perempuan dursila; sebab karena besarnya cemas dan sakit hati aku berbicara demikian lama."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 17, 'Jawab Eli: "Pergilah dengan selamat, dan Allah Israel akan memberikan kepadamu apa yang engkau minta dari pada-Nya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 18, 'Sesudah itu berkatalah perempuan itu: "Biarlah hambamu ini mendapat belas kasihan dari padamu." Lalu keluarlah perempuan itu, ia mau makan dan mukanya tidak muram lagi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 19, 'Keesokan harinya bangunlah mereka itu pagi-pagi, lalu sujud menyembah di hadapan TUHAN; kemudian pulanglah mereka ke rumahnya di Rama. Ketika Elkana bersetubuh dengan Hana, isterinya, TUHAN ingat kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 20, 'Maka setahun kemudian mengandunglah Hana dan melahirkan seorang anak laki-laki. Ia menamai anak itu Samuel, sebab katanya: "Aku telah memintanya dari pada TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 21, 'Elkana, laki-laki itu, pergi dengan seisi rumahnya mempersembahkan korban sembelihan tahunan dan korban nazarnya kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 22, 'Tetapi Hana tidak ikut pergi, sebab katanya kepada suaminya: "Nanti apabila anak itu cerai susu, aku akan mengantarkan dia, maka ia akan menghadap ke hadirat TUHAN dan tinggal di sana seumur hidupnya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 23, 'Kemudian Elkana, suaminya itu, berkata kepadanya: "Perbuatlah apa yang kaupandang baik; tinggallah sampai engkau menyapih dia; hanya, TUHAN kiranya menepati janji-Nya." Jadi tinggallah perempuan itu dan menyusui anaknya sampai disapihnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 24, 'Setelah perempuan itu menyapih anaknya, dibawanyalah dia, dengan seekor lembu jantan yang berumur tiga tahun, satu efa tepung dan sebuyung anggur, lalu diantarkannya ke dalam rumah TUHAN di Silo. Waktu itu masih kecil betul kanak-kanak itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 25, 'Setelah mereka menyembelih lembu, mereka mengantarkan kanak-kanak itu kepada Eli;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 26, 'lalu kata perempuan itu: "Mohon bicara tuanku, demi tuanku hidup, akulah perempuan yang dahulu berdiri di sini dekat tuanku untuk berdoa kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 27, 'Untuk mendapat anak inilah aku berdoa, dan TUHAN telah memberikan kepadaku, apa yang kuminta dari pada-Nya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 1, 28, 'Maka akupun menyerahkannya kepada TUHAN; seumur hidup terserahlah ia kiranya kepada TUHAN." Lalu sujudlah mereka di sana menyembah kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 1, 'Lalu berdoalah Hana, katanya: "Hatiku bersukaria karena TUHAN, tanduk kekuatanku ditinggikan oleh TUHAN; mulutku mencemoohkan musuhku, sebab aku bersukacita karena pertolongan-Mu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 2, 'Tidak ada yang kudus seperti TUHAN, sebab tidak ada yang lain kecuali Engkau dan tidak ada gunung batu seperti Allah kita.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 3, 'Janganlah kamu selalu berkata sombong, janganlah caci maki keluar dari mulutmu. Karena TUHAN itu Allah yang mahatahu, dan oleh Dia perbuatan-perbuatan diuji.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 4, 'Busur pada pahlawan telah patah, tetapi orang-orang yang terhuyung-huyung, pinggangnya berikatkan kekuatan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 5, 'Siapa yang kenyang dahulu, sekarang menyewakan dirinya karena makanan, tetapi orang yang lapar dahulu, sekarang boleh beristirahat. Bahkan orang yang mandul melahirkan tujuh anak, tetapi orang yang banyak anaknya, menjadi layu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 6, 'TUHAN mematikan dan menghidupkan, Ia menurunkan ke dalam dunia orang mati dan mengangkat dari sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 7, 'TUHAN membuat miskin dan membuat kaya; Ia merendahkan, dan meninggikan juga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 8, 'Ia menegakkan orang yang hina dari dalam debu, dan mengangkat orang yang miskin dari lumpur, untuk mendudukkan dia bersama-sama dengan para bangsawan, dan membuat dia memiliki kursi kehormatan. Sebab TUHAN mempunyai alas bumi; dan di atasnya Ia menaruh daratan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 9, 'Langkah kaki orang-orang yang dikasihi-Nya dilindungi-Nya, tetapi orang-orang fasik akan mati binasa dalam kegelapan, sebab bukan oleh karena kekuatannya sendiri seseorang berkuasa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 10, 'Orang yang berbantah dengan TUHAN akan dihancurkan; atas mereka Ia mengguntur di langit. TUHAN mengadili bumi sampai ke ujung-ujungnya; Ia memberi kekuatan kepada raja yang diangkat-Nya dan meninggikan tanduk kekuatan orang yang diurapi-Nya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 11, 'Lalu pulanglah Elkana ke Rama tetapi anak itu menjadi pelayan TUHAN di bawah pengawasan imam Eli.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 12, 'Adapun anak-anak lelaki Eli adalah orang-orang dursila; mereka tidak mengindahkan TUHAN,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 13, 'ataupun batas hak para imam terhadap bangsa itu. Setiap kali seseorang mempersembahkan korban sembelihan, sementara daging itu dimasak, datanglah bujang imam membawa garpu bergigi tiga di tangannya', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 14, 'dan dicucukkannya ke dalam bejana atau ke dalam kuali atau ke dalam belanga atau ke dalam periuk. Segala yang ditarik dengan garpu itu ke atas, diambil imam itu untuk dirinya sendiri. Demikianlah mereka memperlakukan semua orang Israel yang datang ke sana, ke Silo.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 15, 'Bahkan sebelum lemaknya dibakar, bujang imam itu datang, lalu berkata kepada orang yang mempersembahkan korban itu: "Berikanlah daging kepada imam untuk dipanggang, sebab ia tidak mau menerima dari padamu daging yang dimasak, hanya yang mentah saja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 16, 'Apabila orang itu menjawabnya: "Bukankah lemak itu harus dibakar dahulu, kemudian barulah ambil bagimu sesuka hatimu," maka berkatalah ia kepada orang itu: "Sekarang juga harus kauberikan, kalau tidak, aku akan mengambilnya dengan kekerasan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 17, 'Dengan demikian sangat besarlah dosa kedua orang muda itu di hadapan TUHAN, sebab mereka memandang rendah korban untuk TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 18, 'Adapun Samuel menjadi pelayan di hadapan TUHAN; ia masih anak-anak, yang tubuhnya berlilitkan baju efod dari kain lenan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 19, 'Setiap tahun ibunya membuatkan dia jubah kecil dan membawa jubah itu kepadanya, apabila ia bersama-sama suaminya pergi mempersembahkan korban sembelihan tahunan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 20, 'Lalu Eli memberkati Elkana dan isterinya, katanya: "TUHAN kiranya memberikan keturunan kepadamu dari perempuan ini pengganti yang telah diserahkannya kepada TUHAN." Sesudah itu pulanglah mereka ke tempat kediamannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 21, 'Dan TUHAN mengindahkan Hana, sehingga dia mengandung dan melahirkan tiga anak laki-laki dan dua anak perempuan lagi. Sementara itu makin besarlah Samuel yang muda itu di hadapan TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 22, 'Eli telah sangat tua. Apabila didengarnya segala sesuatu yang dilakukan anak-anaknya terhadap semua orang Israel dan bahwa mereka itu tidur dengan perempuan-perempuan yang melayani di depan pintu Kemah Pertemuan,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 23, 'berkatalah ia kepada mereka: "Mengapa kamu melakukan hal-hal yang begitu, sehingga kudengar dari segenap bangsa ini tentang perbuatan-perbuatanmu yang jahat itu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 24, 'Janganlah begitu, anak-anakku. Bukan kabar baik yang kudengar itu bahwa kamu menyebabkan umat TUHAN melakukan pelanggaran.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 25, 'Jika seseorang berdosa terhadap seorang yang lain, maka Allah yang akan mengadili; tetapi jika seseorang berdosa terhadap TUHAN, siapakah yang menjadi perantara baginya?" Tetapi tidaklah didengarkan mereka perkataan ayahnya itu, sebab TUHAN hendak mematikan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 26, 'Tetapi Samuel yang muda itu, semakin besar dan semakin disukai, baik di hadapan TUHAN maupun di hadapan manusia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 27, 'Seorang abdi Allah datang kepada Eli dan berkata kepadanya: "Beginilah firman TUHAN: Bukankah dengan nyata Aku menyatakan diri-Ku kepada nenek moyangmu, ketika mereka masih di Mesir dan takluk kepada keturunan Firaun?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 28, 'Dan Aku telah memilihnya dari segala suku Israel menjadi imam bagi-Ku, supaya ia mempersembahkan korban di atas mezbah-Ku, membakar ukupan dan memakai baju efod di hadapan-Ku; kepada kaummu telah Kuserahkan segala korban api-apian orang Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 29, 'Mengapa engkau memandang dengan loba kepada korban sembelihan-Ku dan korban sajian-Ku, yang telah Kuperintahkan, dan mengapa engkau menghormati anak-anakmu lebih dari pada-Ku, sambil kamu menggemukkan dirimu dengan bagian yang terbaik dari setiap korban sajian umat-Ku Israel?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 30, 'Sebab itu?demikianlah firman TUHAN, Allah Israel?sesungguhnya Aku telah berjanji: Keluargamu dan kaummu akan hidup di hadapan-Ku selamanya, tetapi sekarang?demikianlah firman TUHAN?:Jauhlah hal itu dari pada-Ku! Sebab siapa yang menghormati Aku, akan Kuhormati, tetapi siapa yang menghina Aku, akan dipandang rendah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 31, 'Sesungguhnya akan datang waktunya, bahwa Aku akan mematahkan tangan kekuatanmu dan tangan kekuatan kaummu, sehingga tidak ada seorang kakek dalam keluargamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 32, 'Maka engkau akan memandang dengan mata bermusuhan kepada segala kebaikan yang akan Kulakukan kepada Israel dan dalam keluargamu takkan ada seorang kakek untuk selamanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 33, 'Tetapi seorang dari padamu yang tidak Kulenyapkan dari lingkungan mezbah-Ku akan membuat matamu rusak dan jiwamu merana; segala tambahan keluargamu akan mati oleh pedang lawan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 34, 'Inilah yang akan menjadi tanda bagimu, yakni apa yang akan terjadi kepada kedua anakmu itu, Hofni dan Pinehas: pada hari yang sama keduanya akan mati.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 35, 'Dan Aku akan mengangkat bagi-Ku seorang imam kepercayaan, yang berlaku sesuai dengan hati-Ku dan jiwa-Ku, dan Aku akan membangunkan baginya keturunan yang teguh setia, sehingga ia selalu hidup di hadapan orang yang Kuurapi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 2, 36, 'Kemudian siapa yang masih tinggal hidup dari keturunanmu akan datang sujud menyembah kepadanya meminta sekeping uang perak atau sepotong roti, dan akan berkata: Tempatkanlah kiranya aku dalam salah satu golongan imam itu, supaya aku dapat makan sekerat roti."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 1, 'Samuel yang muda itu menjadi pelayan TUHAN di bawah pengawasan Eli. Pada masa itu firman TUHAN jarang; penglihatan-penglihatanpun tidak sering.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 2, 'Pada suatu hari Eli, yang matanya mulai kabur dan tidak dapat melihat dengan baik, sedang berbaring di tempat tidurnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 3, 'Lampu rumah Allah belum lagi padam. Samuel telah tidur di dalam bait suci TUHAN, tempat tabut Allah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 4, 'Lalu TUHAN memanggil: "Samuel! Samuel!", dan ia menjawab: "Ya, bapa."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 5, 'Lalu berlarilah ia kepada Eli, serta katanya: "Ya, bapa, bukankah bapa memanggil aku?" Tetapi Eli berkata: "Aku tidak memanggil; tidurlah kembali." Lalu pergilah ia tidur.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 6, 'Dan TUHAN memanggil Samuel sekali lagi. Samuelpun bangunlah, lalu pergi mendapatkan Eli serta berkata: "Ya, bapa, bukankah bapa memanggil aku?" Tetapi Eli berkata: "Aku tidak memanggil, anakku; tidurlah kembali."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 7, 'Samuel belum mengenal TUHAN; firman TUHAN belum pernah dinyatakan kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 8, 'Dan TUHAN memanggil Samuel sekali lagi, untuk ketiga kalinya. Iapun bangunlah, lalu pergi mendapatkan Eli serta katanya: "Ya, bapa, bukankah bapa memanggil aku?" Lalu mengertilah Eli, bahwa Tuhanlah yang memanggil anak itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 9, 'Sebab itu berkatalah Eli kepada Samuel: "Pergilah tidur dan apabila Ia memanggil engkau, katakanlah: Berbicaralah, TUHAN, sebab hamba-Mu ini mendengar." Maka pergilah Samuel dan tidurlah ia di tempat tidurnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 10, 'Lalu datanglah TUHAN, berdiri di sana dan memanggil seperti yang sudah-sudah: "Samuel! Samuel!" Dan Samuel menjawab: "Berbicaralah, sebab hamba-Mu ini mendengar."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 11, 'Lalu berfirmanlah TUHAN kepada Samuel: "Ketahuilah, Aku akan melakukan sesuatu di Israel, sehingga setiap orang yang mendengarnya, akan bising kedua telinganya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 12, 'Pada waktu itu Aku akan menepati kepada Eli segala yang telah Kufirmankan tentang keluarganya, dari mula sampai akhir.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 13, 'Sebab telah Kuberitahukan kepadanya, bahwa Aku akan menghukum keluarganya untuk selamanya karena dosa yang telah diketahuinya, yakni bahwa anak-anaknya telah menghujat Allah, tetapi ia tidak memarahi mereka!', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 14, 'Sebab itu Aku telah bersumpah kepada keluarga Eli, bahwa dosa keluarga Eli takkan dihapuskan dengan korban sembelihan atau dengan korban sajian untuk selamanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 15, 'Samuel tidur sampai pagi; kemudian dibukanya pintu rumah TUHAN. Samuel segan memberitahukan penglihatan itu kepada Eli.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 16, 'Tetapi Eli memanggil Samuel, katanya: "Samuel, anakku." Jawab Samuel: "Ya, bapa."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 17, 'Kata Eli: "Apakah yang disampaikan-Nya kepadamu? Janganlah kausembunyikan kepadaku. Kiranya beginilah Allah menghukum engkau, bahkan lebih lagi dari pada itu, jika engkau menyembunyikan sepatah katapun kepadaku dari apa yang disampaikan-Nya kepadamu itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 18, 'Lalu Samuel memberitahukan semuanya itu kepadanya dengan tidak menyembunyikan sesuatupun. Kemudian Eli berkata: "Dia TUHAN, biarlah diperbuat-Nya apa yang dipandang-Nya baik."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 19, 'Dan Samuel makin besar dan TUHAN menyertai dia dan tidak ada satupun dari firman-Nya itu yang dibiarkan-Nya gugur.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 20, 'Maka tahulah seluruh Israel dari Dan sampai Bersyeba, bahwa kepada Samuel telah dipercayakan jabatan nabi TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 3, 21, 'Dan TUHAN selanjutnya menampakkan diri di Silo, sebab Ia menyatakan diri di Silo kepada Samuel dengan perantaraan firman-Nya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 1, 'Dan perkataan Samuel sampai ke seluruh Israel. (4-1b) Orang Israel maju berperang melawan orang Filistin dan berkemah dekat Eben-Haezer, sedang orang Filistin berkemah di Afek.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 2, 'Orang Filistin mengatur barisannya berhadapan dengan orang Israel. Ketika pertempuran menghebat, terpukullah kalah orang Israel oleh orang Filistin, yang menewaskan kira-kira empat ribu orang di medan pertempuran itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 3, 'Ketika tentara itu kembali ke perkemahan, berkatalah para tua-tua Israel: "Mengapa TUHAN membuat kita terpukul kalah oleh orang Filistin pada hari ini? Marilah kita mengambil dari Silo tabut perjanjian TUHAN, supaya Ia datang ke tengah-tengah kita dan melepaskan kita dari tangan musuh kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 4, 'Kemudian bangsa itu menyuruh orang ke Silo, lalu mereka mengangkat dari sana tabut perjanjian TUHAN semesta alam, yang bersemayam di atas para kerub; kedua anak Eli, Hofni dan Pinehas, ada di sana dekat tabut perjanjian Allah itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 5, 'Segera sesudah tabut perjanjian TUHAN sampai ke perkemahan, bersoraklah seluruh orang Israel dengan nyaring, sehingga bumi bergetar.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 6, 'Dan orang Filistin yang mendengar bunyi sorak itu berkata: "Apakah bunyi sorak yang nyaring di perkemahan orang Ibrani itu?" Ketika diketahui mereka, bahwa tabut TUHAN telah sampai ke perkemahan itu,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 7, 'ketakutanlah orang Filistin, sebab kata mereka: "Allah mereka telah datang ke perkemahan itu," dan mereka berkata: "Celakalah kita, sebab seperti itu belum pernah terjadi dahulu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 8, 'Celakalah kita! Siapakah yang menolong kita dari tangan Allah yang maha dahsyat ini? Inilah juga Allah, yang telah menghajar orang Mesir dengan berbagai-bagai tulah di padang gurun.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 9, 'Kuatkanlah hatimu dan berlakulah seperti laki-laki, hai orang Filistin, supaya kamu jangan menjadi budak orang Ibrani itu, seperti mereka dahulu menjadi budakmu. Berlakulah seperti laki-laki dan berperanglah!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 10, 'Lalu berperanglah orang Filistin, sehingga orang Israel terpukul kalah. Mereka melarikan diri masing-masing ke kemahnya. Amatlah besar kekalahan itu: dari pihak Israel gugur tiga puluh ribu orang pasukan berjalan kaki.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 11, 'Lagipula tabut Allah dirampas dan kedua anak Eli, Hofni dan Pinehas, tewas.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 12, 'Seorang dari suku Benyamin lari dari barisan pertempuran dan pada hari itu juga ia sampai ke Silo dengan pakaian terkoyak-koyak dan dengan tanah di kepalanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 13, 'Ketika ia sampai, Eli sedang duduk di kursi di tepi jalan menunggu-nunggu, sebab hatinya berdebar-debar karena tabut Allah itu. Ketika orang itu masuk ke kota dan menceritakan kabar itu, berteriaklah seluruh kota itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 14, 'Ketika Eli mendengar bunyi teriakan itu, bertanyalah ia: "Keributan apakah itu?" Lalu bersegeralah orang itu mendapatkan Eli dan memberitahukannya kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 15, 'Eli sudah sembilan puluh delapan tahun umurnya dan matanya sudah bular, sehingga ia tidak dapat melihat lagi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 16, 'Kata orang itu kepada Eli: "Aku datang dari medan pertempuran; baru hari ini aku melarikan diri dari medan pertempuran." Kata Eli: "Bagaimana keadaannya, anakku?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 17, 'Jawab pembawa kabar itu: "Orang Israel melarikan diri dari hadapan orang Filistin; kekalahan yang besar telah diderita oleh rakyat; lagipula kedua anakmu, Hofni dan Pinehas, telah tewas, dan tabut Allah sudah dirampas."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 18, 'Ketika disebutnya tabut Allah itu, jatuhlah Eli telentang dari kursi di sebelah pintu gerbang, batang lehernya patah dan ia mati. Sebab telah tua dan gemuk orangnya. Empat puluh tahun lamanya ia memerintah sebagai hakim atas orang Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 19, 'Adapun menantunya perempuan, isteri Pinehas, sudah hamil tua. Ketika didengarnya kabar itu, bahwa tabut Allah telah dirampas dan mertuanya laki-laki serta suaminya telah mati, duduklah ia berlutut, lalu bersalin, sebab ia kedatangan sakit beranak.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 20, 'Ketika ia hampir mati, berkatalah perempuan-perempuan yang berdiri di dekatnya: "Janganlah takut, sebab engkau telah melahirkan seorang anak laki-laki." Tetapi ia tidak menjawab dan tidak memperhatikannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 21, 'Ia menamai anak itu Ikabod, katanya: "Telah lenyap kemuliaan dari Israel" ?karena tabut Allah sudah dirampas dan karena mertuanya dan suaminya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 4, 22, 'Katanya: "Telah lenyap kemuliaan dari Israel, sebab tabut Allah telah dirampas."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 1, 'Sesudah orang Filistin merampas tabut Allah, maka mereka membawanya dari Eben-Haezer ke Asdod.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 2, 'Orang Filistin mengambil tabut Allah itu, dibawanya masuk ke kuil Dagon dan diletakkannya di sisi Dagon.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 3, 'Ketika orang-orang Asdod bangun pagi-pagi pada keesokan harinya, tampaklah Dagon terjatuh dengan mukanya ke tanah di hadapan tabut TUHAN; lalu mereka mengambil Dagon dan mengembalikannya ke tempatnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 4, 'Tetapi ketika keesokan harinya mereka bangun pagi-pagi, tampaklah Dagon terjatuh dengan mukanya ke tanah di hadapan tabut TUHAN, tetapi kepala Dagon dan kedua belah tangannya terpenggal dan terpelanting ke ambang pintu, hanya badan Dagon itu yang masih tinggal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 5, 'Itulah sebabnya para imam Dagon dan semua orang yang masuk ke dalam kuil Dagon tidak menginjak ambang pintu rumah Dagon yang di Asdod, sampai hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 6, 'Tangan TUHAN menekan orang-orang Asdod itu dengan berat dan Ia membingungkan mereka: Ia menghajar mereka dengan borok-borok, baik Asdod maupun daerahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 7, 'Ketika dilihat orang-orang Asdod, bahwa demikian halnya, berkatalah mereka: "Tabut Allah Israel tidak boleh tinggal pada kita, sebab tangan-Nya keras melawan kita dan melawan Dagon, allah kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 8, 'Sebab itu mereka memanggil berkumpul kepadanya semua raja kota orang Filistin dan berkata: "Apakah yang akan kita lakukan dengan tabut Allah Israel itu?" Lalu kata mereka: "Tabut Allah Israel harus dipindahkan ke Gat." Jadi mereka memindahkan tabut Allah Israel itu ke sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 9, 'Tetapi setelah mereka memindahkannya, maka tangan TUHAN mendatangkan kegemparan yang sangat besar atas kota itu; Ia menghajar orang-orang kota itu, anak-anak dan orang dewasa, sehingga timbul borok-borok pada mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 10, 'Lalu mereka mengantarkan tabut Allah itu ke Ekron. Tetapi sesampai tabut Allah itu di Ekron, berteriaklah orang Ekron itu, demikian: "Mereka memindahkan tabut Allah Israel itu kepada kita untuk mematikan kita dan bangsa kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 11, 'Sebab itu mereka memanggil berkumpul semua raja kota orang Filistin itu dan berkata: "Antarkanlah tabut Allah Israel itu; biarlah itu kembali ke tempatnya, supaya jangan dimatikannya kita dan bangsa kita." Sebab di seluruh kota itu ada kegemparan maut; tangan Allah menekan orang-orang di sana dengan sangat berat:', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 5, 12, 'orang-orang yang tidak mati, dihajar dengan borok-borok, sehingga teriakan kota itu naik ke langit.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 1, 'Setelah tujuh bulan lamanya tabut TUHAN itu ada di daerah orang Filistin,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 2, 'maka orang Filistin itu memanggil para imam dan para petenung, lalu berkata kepada mereka: "Apakah yang harus kami lakukan dengan tabut TUHAN itu? Beritahukanlah kepada kami, bagaimana kami harus mengantarkannya kembali ke tempatnya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 3, 'Lalu kata mereka: "Apabila kamu mengantarkan tabut Allah Israel itu, maka janganlah kamu mengantarkannya dengan tangan hampa, melainkan haruslah kamu membayar tebusan salah kepada-Nya; maka kamu akan menjadi sembuh dan kamu akan mengetahui, mengapa tangan-Nya tidak undur dari padamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 4, 'Sesudah itu bertanyalah mereka: "Apakah tebusan salah yang harus kami bayar kepada-Nya?" Jawab mereka: "Menurut jumlah raja-raja kota orang Filistin, lima borok emas dan lima tikus emas, sebab tulah yang sama menimpa kamu sekalian dan raja-raja kotamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 5, 'Jadi buatlah gambar borok-borokmu dan gambar tikus yang merusak tanahmu, dan sampaikanlah hormatmu kepada Allah Israel. Mungkin Ia akan mengangkat dari padamu, dari pada allahmu dan dari pada tanahmu tangan-Nya yang menekan dengan berat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 6, 'Mengapa kamu berkeras hati, sama seperti orang Mesir dan Firaun berkeras hati? Bukankah mereka membiarkan bangsa itu pergi, ketika Ia mempermain-mainkan mereka?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 7, 'Oleh sebab itu ambillah dan siapkanlah sebuah kereta baru dengan dua ekor lembu yang menyusui, yang belum pernah kena kuk, pasanglah kedua lembu itu pada kereta, tetapi bawalah anak-anaknya kembali ke rumah, supaya jangan mengikutinya lagi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 8, 'Kemudian ambillah tabut TUHAN, muatkanlah itu ke atas kereta dan letakkanlah benda-benda emas, yang harus kamu bayar kepada-Nya sebagai tebusan salah, ke dalam suatu peti di sisinya. Dan biarkanlah tabut itu pergi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 9, 'Perhatikanlah: apabila tabut itu mengambil jalan ke daerahnya, ke Bet-Semes, maka Dialah itu yang telah mendatangkan malapetaka yang hebat ini kepada kita. Dan jika tidak, maka kita mengetahui, bahwa bukanlah tangan-Nya yang telah menimpa kita; kebetulan saja hal itu terjadi kepada kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 10, 'Demikianlah diperbuat orang-orang itu. Mereka mengambil dua ekor lembu yang menyusui, dipasangnya pada kereta, tetapi anak-anaknya ditahan di rumah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 11, 'Mereka meletakkan tabut TUHAN ke atas kereta, juga peti berisi tikus-tikus emas dan gambar benjol-benjol mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 12, 'Lembu-lembu itu langsung mengikuti jalan yang ke Bet-Semes; melalui satu jalan raya, sambil menguak dengan tidak menyimpang ke kanan atau ke kiri, sedang raja-raja kota orang Filistin itu berjalan di belakangnya sampai ke daerah Bet-Semes.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 13, 'Orang-orang Bet-Semes sedang menuai gandum di lembah. Ketika mereka mengangkat muka, maka tampaklah kepada mereka tabut itu, lalu bersukacitalah mereka melihatnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 14, 'Kereta itu sampai ke ladang Yosua, orang Bet-Semes itu, dan berhenti di sana. Di sana ada batu besar. Mereka membelah kayu kereta itu dan mereka mempersembahkan lembu-lembu sebagai korban bakaran kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 15, 'Orang-orang suku Lewi menurunkan tabut TUHAN dengan peti yang ada di sebelahnya, yang di dalamnya ada benda-benda emas itu, lalu menaruhnya di atas batu besar itu, dan pada hari itu orang-orang Bet-Semes mempersembahkan korban bakaran dan korban sembelihan kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 16, 'Ketika kelima raja kota orang Filistin melihat hal itu, pulanglah mereka ke Ekron pada hari itu juga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 17, 'Inilah benjol-benjol emas yang dibayar orang Filistin kepada TUHAN sebagai tebusan salah: dari Asdod satu, dari Gaza satu, dari Askelon satu, dari Gat satu, dari Ekron satu;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 18, 'lagi tikus-tikus emas menurut jumlah segala kota orang Filistin kepunyaan kelima raja kota itu, baik kota-kota yang berkubu maupun dusun-dusun sekitarnya; dan batu besar, yang di atasnya diletakkan mereka tabut TUHAN, di ladang Yosua, orang Bet-Semes itu, adalah saksi sampai hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 19, 'Dan Ia membunuh beberapa orang Bet-Semes, karena mereka melihat ke dalam tabut TUHAN; Ia membunuh tujuh puluh orang dari rakyat itu. Rakyat itu berkabung, karena TUHAN telah menghajar mereka dengan dahsyatnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 20, 'Dan orang-orang Bet-Semes berkata: "Siapakah yang tahan berdiri di hadapan TUHAN, Allah yang kudus ini? Kepada siapakah Ia akan berangkat meninggalkan kita?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 6, 21, 'Lalu mereka mengirim utusan kepada penduduk Kiryat-Yearim dengan pesan: "Orang Filistin telah mengembalikan tabut TUHAN; datanglah dan angkutlah itu kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 1, 'Lalu orang-orang Kiryat-Yearim datang, mereka mengangkut tabut TUHAN itu dan membawanya ke dalam rumah Abinadab yang di atas bukit. Dan Eleazar, anaknya, mereka kuduskan untuk menjaga tabut TUHAN itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 2, 'Sejak saat tabut itu tinggal di Kiryat-Yearim berlalulah waktu yang cukup lama, yakni dua puluh tahun, dan seluruh kaum Israel mengeluh kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 3, 'Lalu berkatalah Samuel kepada seluruh kaum Israel demikian: "Jika kamu berbalik kepada TUHAN dengan segenap hati, maka jauhkanlah para allah asing dan para Asytoret dari tengah-tengahmu dan tujukan hatimu kepada TUHAN dan beribadahlah hanya kepada-Nya; maka Ia akan melepaskan kamu dari tangan orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 4, 'Kemudian orang-orang Israel menjauhkan para Baal dan para Asytoret dan beribadah hanya kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 5, 'Lalu berkatalah Samuel: "Kumpulkanlah segenap orang Israel ke Mizpa; maka aku akan berdoa untuk kamu kepada TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 6, 'Setelah berkumpul di Mizpa, mereka menimba air dan mencurahkannya di hadapan TUHAN. Mereka juga berpuasa pada hari itu dan berkata di sana: "Kami telah berdosa kepada TUHAN." Dan Samuel menghakimi orang Israel di Mizpa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 7, 'Ketika didengar orang Filistin, bahwa orang Israel telah berkumpul di Mizpa, majulah raja-raja kota orang Filistin mendatangi orang Israel. Serta didengar orang Israel demikian, maka ketakutanlah mereka terhadap orang Filistin.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 8, 'Lalu kata orang Israel kepada Samuel: "Janganlah berhenti berseru bagi kami kepada TUHAN, Allah kita, supaya Ia menyelamatkan kami dari tangan orang Filistin itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 9, 'Sesudah itu Samuel mengambil seekor anak domba yang menyusu, lalu mempersembahkan seluruhnya kepada TUHAN sebagai korban bakaran. Dan ketika Samuel berseru kepada TUHAN bagi orang Israel, maka TUHAN menjawab dia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 10, 'Sedang Samuel mempersembahkan korban bakaran itu, majulah orang Filistin berperang melawan orang Israel. Tetapi pada hari itu TUHAN mengguntur dengan bunyi yang hebat ke atas orang Filistin dan mengacaukan mereka, sehingga mereka terpukul kalah oleh orang Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 11, 'Keluarlah orang-orang Israel dari Mizpa, mengejar orang Filistin itu dan memukul mereka kalah sampai hilir Bet-Kar.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 12, 'Kemudian Samuel mengambil sebuah batu dan mendirikannya antara Mizpa dan Yesana; ia menamainya Eben-Haezer, katanya: "Sampai di sini TUHAN menolong kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 13, 'Demikianlah orang Filistin itu ditundukkan dan tidak lagi memasuki daerah Israel. Tangan TUHAN melawan orang Filistin seumur hidup Samuel,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 14, 'dan kota-kota yang diambil orang Filistin dari pada Israel, kembali pula kepada Israel, mulai dari Ekron sampai Gat; dan orang Israel merebut daerah sekitarnya dari tangan orang Filistin. Antara orang Israel dan orang Amori ada damai.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 15, 'Samuel memerintah sebagai hakim atas orang Israel seumur hidupnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 16, 'Dari tahun ke tahun ia berkeliling ke Betel, Gilgal dan Mizpa, dan memerintah atas orang Israel di segala tempat itu,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 7, 17, 'lalu ia kembali ke Rama, sebab di sanalah rumahnya dan di sanalah ia memerintah atas orang Israel; dan di sana ia mendirikan mezbah bagi TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 1, 'Setelah Samuel menjadi tua, diangkatnyalah anak-anaknya laki-laki menjadi hakim atas orang Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 2, 'Nama anaknya yang sulung ialah Yoel, dan nama anaknya yang kedua ialah Abia; keduanya menjadi hakim di Bersyeba.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 3, 'Tetapi anak-anaknya itu tidak hidup seperti ayahnya; mereka mengejar laba, menerima suap dan memutarbalikkan keadilan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 4, 'Sebab itu berkumpullah semua tua-tua Israel; mereka datang kepada Samuel di Rama', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 5, 'dan berkata kepadanya: "Engkau sudah tua dan anak-anakmu tidak hidup seperti engkau; maka angkatlah sekarang seorang raja atas kami untuk memerintah kami, seperti pada segala bangsa-bangsa lain."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 6, 'Waktu mereka berkata: "Berikanlah kepada kami seorang raja untuk memerintah kami," perkataan itu mengesalkan Samuel, maka berdoalah Samuel kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 7, 'TUHAN berfirman kepada Samuel: "Dengarkanlah perkataan bangsa itu dalam segala hal yang dikatakan mereka kepadamu, sebab bukan engkau yang mereka tolak, tetapi Akulah yang mereka tolak, supaya jangan Aku menjadi raja atas mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 8, 'Tepat seperti yang dilakukan mereka kepada-Ku sejak hari Aku menuntun mereka keluar dari Mesir sampai hari ini, yakni meninggalkan Daku dan beribadah kepada allah lain, demikianlah juga dilakukan mereka kepadamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 9, 'Oleh sebab itu dengarkanlah permintaan mereka, hanya peringatkanlah mereka dengan sungguh-sungguh dan beritahukanlah kepada mereka apa yang menjadi hak raja yang akan memerintah mereka."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 10, 'Dan Samuel menyampaikan segala firman TUHAN kepada bangsa itu, yang meminta seorang raja kepadanya,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 11, 'katanya: "Inilah yang menjadi hak raja yang akan memerintah kamu itu: anak-anakmu laki-laki akan diambilnya dan dipekerjakannya pada keretanya dan pada kudanya, dan mereka akan berlari di depan keretanya;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 12, 'ia akan menjadikan mereka kepala pasukan seribu dan kepala pasukan lima puluh; mereka akan membajak ladangnya dan mengerjakan penuaian baginya; senjata-senjatanya dan perkakas keretanya akan dibuat mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 13, 'Anak-anakmu perempuan akan diambilnya sebagai juru campur rempah-rempah, juru masak dan juru makanan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 14, 'Selanjutnya dari ladangmu, kebun anggurmu dan kebun zaitunmu akan diambilnya yang paling baik dan akan diberikannya kepada pegawai-pegawainya', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 15, 'dari gandummu dan hasil kebun anggurmu akan diambilnya sepersepuluh dan akan diberikannya kepada pegawai-pegawai istananya dan kepada pegawai-pegawainya yang lain.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 16, 'Budak-budakmu laki-laki dan budak-budakmu perempuan, ternakmu yang terbaik dan keledai-keledaimu akan diambilnya dan dipakainya untuk pekerjaannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 17, 'Dari kambing dombamu akan diambilnya sepersepuluh, dan kamu sendiri akan menjadi budaknya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 18, 'Pada waktu itu kamu akan berteriak karena rajamu yang kamu pilih itu, tetapi TUHAN tidak akan menjawab kamu pada waktu itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 19, 'Tetapi bangsa itu menolak mendengarkan perkataan Samuel dan mereka berkata: "Tidak, harus ada raja atas kami;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 20, 'maka kamipun akan sama seperti segala bangsa-bangsa lain; raja kami akan menghakimi kami dan memimpin kami dalam perang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 21, 'Samuel mendengar segala perkataan bangsa itu, dan menyampaikannya kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 8, 22, 'TUHAN berfirman kepada Samuel: "Dengarkanlah permintaan mereka dan angkatlah seorang raja bagi mereka." Kemudian berkatalah Samuel kepada orang-orang Israel itu: "Pergilah, masing-masing ke kotanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 1, 'Ada seorang dari daerah Benyamin, namanya Kish bin Abiel, bin Zeror, bin Bekhorat, bin Afiah, seorang suku Benyamin, seorang yang berada.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 2, 'Orang ini ada anaknya laki-laki, namanya Saul, seorang muda yang elok rupanya; tidak ada seorangpun dari antara orang Israel yang lebih elok dari padanya: dari bahu ke atas ia lebih tinggi dari pada setiap orang sebangsanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 3, 'Kish, ayah Saul itu, kehilangan keledai-keledai betinanya. Sebab itu berkatalah Kish kepada Saul, anaknya: "Ambillah salah seorang bujang, bersiaplah dan pergilah mencari keledai-keledai itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 4, 'Lalu mereka berjalan melalui pegunungan Efraim; juga mereka berjalan melalui tanah Salisa, tetapi tidak menemuinya. Kemudian mereka berjalan melalui tanah Sahalim, tetapi keledai-keledai itu tidak ada; kemudian mereka berjalan melalui tanah Benyamin, tetapi tidak menemuinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 5, 'Ketika mereka sampai ke tanah Zuf, berkatalah Saul kepada bujangnya yang bersama-sama dengan dia: "Mari, kita pulang. Nanti ayahku tidak lagi memikirkan keledai-keledai itu, tetapi kuatir mengenai kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 6, 'Tetapi orang ini berkata kepadanya: "Tunggu, di kota ini ada seorang abdi Allah, seorang yang terhormat; segala yang dikatakannya pasti terjadi. Marilah kita pergi ke sana sekarang juga, mungkin ia dapat memberitahukan kepada kita tentang perjalanan yang kita tempuh ini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 7, 'Jawab Saul kepada bujangnya itu: "Tetapi kalau kita pergi, apakah yang kita bawa kepada orang itu? Sebab roti di kantong kita telah habis, dan tidak ada pemberian untuk dibawa kepada abdi Allah itu. Apakah yang ada pada kita?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 8, 'Jawab bujang itu pula kepada Saul: "Masih ada padaku seperempat syikal perak; itu dapat aku berikan kepada abdi Allah itu, maka ia akan memberitahukan kepada kita tentang perjalanan kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 9, '?Dahulu di antara orang Israel, apabila seseorang pergi menanyakan petunjuk Allah, ia berkata begini: "Mari kita pergi kepada pelihat," sebab nabi yang sekarang ini disebutkan dahulu pelihat. ?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 10, 'Kemudian berkatalah Saul kepada bujangnya itu: "Pikiranmu itu baik. Mari kita pergi." Maka pergilah mereka ke kota, ke tempat abdi Allah itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 11, 'Ketika mereka naik jalan pendakian ke kota itu, mereka bertemu dengan gadis-gadis yang keluar hendak menimba air. Mereka bertanya kepada gadis-gadis itu: "Pelihat ada di sini?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 12, 'Jawab gadis-gadis itu kepada mereka: "Ya, ada, baru saja ia mendahului kamu, cepat-cepatlah sekarang. Ia datang ke kota hari ini, karena ada perjamuan korban untuk orang banyak di bukit pada hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 13, 'Apabila kamu masuk ke kota, kamu akan segera menjumpainya, sebelum ia naik ke bukit untuk makan. Sebab orang banyak tidak akan makan, sebelum ia datang; karena dialah yang memberkati korban, kemudian barulah para undangan makan. Pergilah sekarang, sebab kamu akan menjumpainya dengan segera."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 14, 'Maka naiklah mereka ke kota, dan ketika mereka masuk kota, Samuel yang berjalan keluar untuk naik ke bukit, berpapasan dengan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 15, 'Tetapi TUHAN telah menyatakan kepada Samuel, sehari sebelum kedatangan Saul, demikian:', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 16, '"Besok kira-kira waktu ini Aku akan menyuruh kepadamu seorang laki-laki dari tanah Benyamin; engkau akan mengurapi dia menjadi raja atas umat-Ku Israel dan ia akan menyelamatkan umat-Ku dari tangan orang Filistin. Sebab Aku telah memperhatikan sengsara umat-Ku itu, karena teriakannya telah sampai kepada-Ku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 17, 'Ketika Samuel melihat Saul, maka berfirmanlah TUHAN kepadanya: "Inilah orang yang Kusebutkan kepadamu itu; orang ini akan memegang tampuk pemerintahan atas umat-Ku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 18, 'Dalam pada itu Saul, datang mendekati Samuel di tengah pintu gerbang dan berkata: "Maaf, di mana rumah pelihat itu?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 19, 'Jawab Samuel kepada Saul, katanya: "Akulah pelihat itu. Naiklah mendahului aku ke bukit. Hari ini kamu makan bersama-sama dengan daku; besok pagi aku membiarkan engkau pergi dan aku akan memberitahukan kepadamu segala sesuatu yang ada dalam hatimu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 20, 'Adapun keledai-keledaimu, yang telah hilang tiga hari lamanya sampai sekarang, janganlah engkau kuatir, sebab telah diketemukan. Tetapi siapakah yang memiliki segala yang diingini orang Israel? Bukankah itu ada padamu dan pada seluruh kaum keluargamu?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 21, 'Tetapi jawab Saul: "Bukankah aku seorang suku Benyamin, suku yang terkecil di Israel? Dan bukankah kaumku yang paling hina dari segala kaum suku Benyamin? Mengapa bapa berkata demikian kepadaku?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 22, 'Sesudah itu Samuel mengajak Saul dan bujangnya, dibawanya ke pendopo dan diberikannya kepada mereka tempat utama di depan para undangan, yang banyaknya kira-kira tiga puluh orang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 23, 'Berkatalah Samuel kepada juru masak: "Berikanlah sekarang bagian yang kuberikan kepadamu tadi, dengan pesan: Simpanlah ini dahulu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 24, 'Lalu juru masak itu menghidangkan paha dan apa yang termasuk ke situ dan meletakkannya ke depan Saul. Dan Samuel berkata: "Lihat, yang tinggal ini diletakkan ke depanmu; makanlah, sebab telah disimpan bagimu untuk perayaan ini, ketika aku berkata: Aku telah mengundang orang banyak." Demikianlah pada hari itu Saul makan bersama-sama dengan Samuel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 25, 'Sesudah itu turunlah mereka dari bukit ke kota. Dan Samuel bercakap-cakap dengan Saul di atas sotoh.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 26, 'Mereka bangun pagi-pagi, dan ketika fajar menyingsing, Samuel memanggil Saul yang ada di atas sotoh itu, katanya: "Bangunlah, aku akan mengantarkan engkau." Lalu Saul bangun dan mereka keduanya pergi ke luar, yakni ia dan Samuel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 9, 27, 'Ketika mereka turun sampai ke ujung kota, berkatalah Samuel kepada Saul: "Katakanlah kepada bujang itu, supaya ia pergi mendahului kita, tetapi berhentilah engkau sebentar, maka aku akan memberitahukan kepadamu firman Allah."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 1, 'Lalu Samuel mengambil buli-buli berisi minyak, dituangnyalah ke atas kepala Saul, diciumnyalah dia sambil berkata: "Bukankah TUHAN telah mengurapi engkau menjadi raja atas umat-Nya Israel? Engkau akan memegang tampuk pemerintahan atas umat TUHAN, dan engkau akan menyelamatkannya dari tangan musuh-musuh di sekitarnya. Inilah tandanya bagimu, bahwa TUHAN telah mengurapi engkau menjadi raja atas milik-Nya sendiri:', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 2, 'Apabila engkau pada hari ini pergi meninggalkan aku, maka engkau akan bertemu dengan dua orang laki-laki di dekat kubur Rahel, di daerah Benyamin, di Zelzah. Mereka akan berkata kepadamu: Keledai-keledai yang engkau cari itu telah diketemukan; dan ayahmu tidak memikirkan keledai-keledai itu lagi, tetapi ia kuatir mengenai kamu, katanya: Apakah yang akan kuperbuat untuk anakku itu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 3, 'Dari sana engkau akan berjalan terus lagi dan sampai ke pohon tarbantin Tabor, maka di sana engkau akan ditemui oleh tiga orang laki-laki yang naik menghadap Allah di Betel; seorang membawa tiga ekor anak kambing, seorang membawa tiga ketul roti dan yang lain lagi sebuyung anggur.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 4, 'Mereka akan memberi salam kepadamu dan memberikan kepadamu dua ketul roti yang akan kauterima dari mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 5, 'Sesudah itu engkau akan sampai ke Gibea Allah, tempat kedudukan pasukan orang Filistin. Dan apabila engkau masuk kota, engkau akan berjumpa di sana dengan serombongan nabi, yang turun dari bukit pengorbanan dengan gambus, rebana, suling dan kecapi di depan mereka; mereka sendiri akan kepenuhan seperti nabi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 6, 'Maka Roh TUHAN akan berkuasa atasmu; engkau akan kepenuhan bersama-sama dengan mereka dan berubah menjadi manusia lain.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 7, 'Apabila tanda-tanda ini terjadi kepadamu, lakukanlah apa saja yang didapat oleh tanganmu, sebab Allah menyertai engkau.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 8, 'Engkau harus pergi ke Gilgal mendahului aku, dan camkanlah, aku akan datang kepadamu untuk mempersembahkan korban bakaran dan korban keselamatan. Engkau harus menunggu tujuh hari lamanya, sampai aku datang kepadamu dan memberitahukan kepadamu apa yang harus kaulakukan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 9, 'Sedang ia berpaling untuk pergi meninggalkan Samuel, maka Allah mengubah hatinya menjadi lain. Dan segala tanda-tanda yang tersebut itu terjadi pada hari itu juga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 10, 'Ketika mereka sampai di Gibea dari sana, maka bertemulah ia dengan serombongan nabi; Roh Allah berkuasa atasnya dan Saul turut kepenuhan seperti nabi di tengah-tengah mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 11, 'Dan semua orang yang mengenalnya dari dahulu melihat dengan heran, bahwa ia bernubuat bersama-sama dengan nabi-nabi itu; lalu berkatalah orang banyak yang satu kepada yang lain: "Apakah gerangan yang terjadi dengan anak Kish itu? Apa Saul juga termasuk golongan nabi?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 12, 'Lalu seorang dari tempat itu menjawab: "Siapakah bapa mereka?" ?Itulah sebabnya menjadi peribahasa: Apa Saul juga termasuk golongan nabi?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 13, 'Setelah habis ia kepenuhan seperti nabi, pulanglah ia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 14, 'Dan paman Saul berkata kepadanya dan bujangnya: "Dari mana kamu?" Jawabnya: "Mencari keledai-keledai itu, tetapi ketika tidak terlihat, maka kami pergi kepada Samuel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 15, 'Kemudian paman Saul itu berkata: "Coba ceritakan kepadaku apa yang dikatakan Samuel kepada kamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 16, 'Kata Saul kepada pamannya itu: "Terus saja diberitahukannya kepada kami, bahwa keledai-keledai itu telah diketemukan." Tetapi perihal menjadi raja yang telah dikatakan Samuel kepadanya, tidak diceritakan kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 17, 'Kemudian Samuel mengerahkan bangsa itu ke hadapan TUHAN di Mizpa', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 18, 'dan ia berkata kepada orang Israel itu: "Beginilah firman TUHAN, Allah Israel: Aku telah menuntun orang Israel keluar dari Mesir dan telah melepaskan kamu dari tangan orang Mesir dan dari tangan segala kerajaan yang menindas kamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 19, 'Tetapi sekarang kamu menolak Allahmu yang menyelamatkan kamu dari segala malapetaka dan kesusahanmu, dengan berkata: Tidak, angkatlah seorang raja atas kami. Maka sebab itu, berdirilah kamu di hadapan TUHAN, menurut sukumu dan menurut kaummu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 20, 'Lalu Samuel menyuruh segala suku Israel tampil ke muka, maka didapati suku Benyamin.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 21, 'Sesudah itu disuruhnyalah suku Benyamin tampil ke muka menurut kaum keluarganya, maka didapati kaum keluarga Matri. Akhirnya disuruhnyalah kaum keluarga Matri tampil ke muka seorang demi seorang, maka didapati Saul bin Kish. Tetapi ketika ia dicari, ia tidak diketemukan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 22, 'Sebab itu ditanyakan pulalah kepada TUHAN: "Apa orang itu juga datang ke mari?" TUHAN menjawab: "Sesungguhnya ia bersembunyi di antara barang-barang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 23, 'Berlarilah orang ke sana dan mengambilnya dari sana, dan ketika ia berdiri di tengah-tengah orang-orang sebangsanya, ternyata ia dari bahu ke atas lebih tinggi dari pada setiap orang sebangsanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 24, 'Dan Samuel berkata kepada seluruh bangsa itu: "Kamu lihatkah orang yang dipilih TUHAN itu? Sebab tidak ada seorangpun yang sama seperti dia di antara seluruh bangsa itu." Lalu bersoraklah seluruh bangsa itu, demikian: "Hidup raja!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 25, 'Kemudian Samuel menguraikan kepada bangsa itu tentang hak-hak kerajaan, menuliskannya pada suatu piagam dan meletakkannya di hadapan TUHAN; sesudah itu Samuel menyuruh seluruh bangsa itu pulang, masing-masing ke rumahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 26, 'Saulpun pulang ke rumahnya, ke Gibea, dan bersama-sama dengan dia ikut pergi orang-orang gagah perkasa yang hatinya telah digerakkan Allah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 10, 27, 'Tetapi orang-orang dursila berkata: "Masakan orang ini dapat menyelamatkan kita!" Mereka menghina dia dan tidak membawa persembahan kepadanya. Tetapi ia pura-pura tuli.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 1, 'Maka Nahas, orang Amon itu, bergerak maju dan berkemah mengepung Yabesh-Gilead. Lalu berkatalah semua orang Yabesh itu kepada Nahas: "Adakanlah perjanjian dengan kami, maka kami akan takluk kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 2, 'Tetapi Nahas, orang Amon itu, berkata kepada mereka: "Dengan syarat inilah aku akan mengadakan perjanjian dengan kamu, bahwa tiap mata kananmu akan kucungkil; dengan demikian aku mendatangkan malu kepada segenap orang Israel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 3, 'Para tua-tua Yabesh berkata kepadanya: "Berilah kelonggaran kepada kami tujuh hari lamanya, supaya kami mengirim utusan ke seluruh daerah Israel; dan jika tidak ada seorangpun yang menyelamatkan kami, maka kami akan keluar menyerahkan diri kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 4, 'Ketika para utusan itu sampai di Gibea-Saul, dan menyampaikan hal itu kepada bangsa itu, menangislah bangsa itu dengan suara nyaring.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 5, 'Saul baru saja datang dari padang dengan berjalan di belakang lembunya, dan ia bertanya: "Ada apa dengan orang-orang itu, sehingga mereka menangis?" Mereka menceritakan kepadanya kabar orang-orang Yabesh itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 6, 'Ketika Saul mendengar kabar itu, maka berkuasalah Roh Allah atas dia, dan menyala-nyalalah amarahnya dengan sangat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 7, 'Diambilnyalah sepasang lembu, dipotong-potongnya, lalu potongan-potongan itu dikirimkannya ke seluruh daerah Israel dengan perantaraan utusan, pesannya: "Siapa yang tidak maju mengikuti Saul dan mengikuti Samuel, lembu-lembunya akan diperlakukan juga demikian." Lalu TUHAN mendatangkan ketakutan kepada bangsa itu, sehingga majulah mereka serentak.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 8, 'Ketika Saul memeriksa barisan mereka di Bezek, maka ada tiga ratus ribu orang Israel dan tiga puluh ribu orang Yehuda.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 9, 'Kepada para utusan yang datang itu dikatakan: "Beginilah kamu katakan kepada orang-orang Yabesh-Gilead: Besok pada waktu panas teriknya matahari akan datang bagimu penyelamatan." Ketika para utusan kembali dan memberitahukan hal itu kepada orang-orang Yabesh, bersukacitalah mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 10, 'Lalu orang-orang Yabesh itu berkata kepada Nahas: "Besok kami akan keluar menyerahkan diri kepadamu; maka bolehlah kamu lakukan terhadap kami apapun yang kamu pandang baik."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 11, 'Keesokan harinya Saul membagi rakyat itu menjadi tiga pasukan. Mereka itu masuk ke tengah-tengah perkemahan musuh pada waktu kawal pagi dan memukul kalah orang-orang Amon sebelum hari panas; dan terserak-seraklah orang-orang yang lolos itu, sehingga di antara mereka tidak ada tinggal dua orang bersama-sama.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 12, 'Lalu berkatalah bangsa itu kepada Samuel: "Siapakah yang telah berkata: Masakan Saul menjadi raja atas kita? Serahkanlah orang-orang itu, supaya kami membunuhnya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 13, 'Tetapi kata Saul: "Pada hari ini seorangpun tidak boleh dibunuh, sebab pada hari ini TUHAN telah mewujudkan keselamatan kepada Israel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 14, 'Dan Samuel berkata kepada bangsa itu: "Marilah kita pergi ke Gilgal dan membaharui jabatan raja di sana."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 11, 15, 'Lalu pergilah seluruh bangsa itu ke Gilgal dan menjadikan Saul raja di sana di hadapan TUHAN di Gilgal, dan mereka mempersembahkan di sana korban keselamatan di hadapan TUHAN, dan bersukarialah di sana Saul dan semua orang Israel dengan sangat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 1, 'Berkatalah Samuel kepada seluruh orang Israel: "Telah kudengarkan segala permintaanmu yang kamu sampaikan kepadaku, dan seorang raja telah kuangkat atasmu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 2, 'Maka sekarang raja itulah yang menjadi pemimpinmu; tetapi aku ini telah menjadi tua dan beruban, dan bukankah anak-anakku laki-laki ada di antara kamu? Akulah yang menjadi pemimpinmu dari sejak mudaku sampai hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 3, 'Di sini aku berdiri. Berikanlah kesaksian menentang aku di hadapan TUHAN dan di hadapan orang yang diurapi-Nya: Lembu siapakah yang telah kuambil? Keledai siapakah yang telah kuambil? Siapakah yang telah kuperas? Siapakah yang telah kuperlakukan dengan kekerasan? Dari tangan siapakah telah kuterima sogok sehingga aku harus tutup mata? Aku akan mengembalikannya kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 4, 'Jawab mereka: "Engkau tidak memeras kami dan engkau tidak memperlakukan kami dengan kekerasan dan engkau tidak menerima apa-apa dari tangan siapapun."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 5, 'Lalu berkatalah ia kepada mereka: "TUHAN menjadi saksi kepada kamu, dan orang yang diurapi-Nyapun menjadi saksi pada hari ini, bahwa kamu tidak mendapat apa-apa dalam tanganku." Jawab mereka: "Dia menjadi saksi."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 6, 'Lalu berkatalah Samuel kepada bangsa itu: "Tuhanlah saksi, yang mengangkat Musa dan Harun dan yang menuntun nenek moyangmu keluar dari tanah Mesir.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 7, 'Maka sebab itu, berdirilah supaya aku bersama-sama dengan kamu berhakim di hadapan TUHAN mengenai segala perbuatan keselamatan TUHAN yang telah dikerjakan-Nya kepadamu dan kepada nenek moyangmu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 8, 'Ketika Yakub datang ke Mesir dan nenek moyangmu berseru-seru kepada TUHAN, maka TUHAN mengutus Musa dan Harun, yang membawa nenek moyangmu keluar dari Mesir, dan membiarkan mereka diam di tempat ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 9, 'Tetapi mereka melupakan TUHAN, Allah mereka, dan Ia menyerahkan mereka ke dalam tangan Sisera, panglima tentara di Hazor, dan ke dalam tangan orang Filistin dan raja Moab, yang berperang melawan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 10, 'Mereka berseru-seru kepada TUHAN, katanya: Kami telah berdosa, sebab kami telah meninggalkan TUHAN dan beribadah kepada para Baal dan para Asytoret; maka sekarang lepaskanlah kami dari tangan musuh kami, maka kami akan beribadah kepada-Mu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 11, 'Sesudah itu TUHAN mengutus Yerubaal, Barak, Yefta dan Samuel, dan melepaskan kamu dari tangan musuh di sekelilingmu, sehingga kamu diam dengan tenteram.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 12, 'Tetapi ketika kamu melihat, bahwa Nahas, raja bani Amon, mendatangi kamu, maka kamu berkata kepadaku: Tidak, seorang raja harus memerintah kami, padahal TUHAN, Allahmu, adalah rajamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 13, 'Maka sebab itu, lihat itu raja yang telah kamu pilih, yang kamu minta. Sesungguhnya TUHAN telah mengangkat raja atasmu,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 14, 'asal saja kamu takut akan TUHAN, beribadah kepada-Nya, mendengarkan firman-Nya dan tidak menentang titah TUHAN, dan baik kamu, maupun raja yang akan memerintah kamu itu mengikuti TUHAN, Allahmu!', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 15, 'Tetapi jika kamu tidak mendengarkan firman TUHAN dan kamu menentang titah TUHAN, maka tangan TUHAN akan melawan kamu dan melawan rajamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 16, 'Sekarang tinggallah berdiri dan lihatlah perkara yang besar yang akan dilakukan TUHAN di depan matamu ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 17, 'Bukankah sekarang musim menuai gandum? Aku akan berseru kepada TUHAN, supaya Ia memberikan guruh dan hujan. Lihatlah dan sadarlah, bahwa besar kejahatan yang telah kamu lakukan itu di mata TUHAN dengan meminta raja bagimu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 18, 'Lalu berserulah Samuel kepada TUHAN, maka TUHAN memberikan pada hari itu guruh dan hujan, sehingga sangat takutlah seluruh bangsa itu kepada TUHAN dan kepada Samuel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 19, 'Berkatalah seluruh bangsa itu kepada Samuel: "Berdoalah untuk hamba-hambamu ini kepada TUHAN, Allahmu, supaya jangan kami mati, sebab dengan meminta raja bagi kami, kami menambah dosa kami dengan kejahatan ini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 20, 'Dan berkatalah Samuel kepada bangsa itu: "Jangan takut; memang kamu telah melakukan segala kejahatan ini, tetapi janganlah berhenti mengikuti TUHAN, melainkan beribadahlah kepada TUHAN dengan segenap hatimu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 21, 'Janganlah menyimpang untuk mengejar dewa kesia-siaan yang tidak berguna dan tidak dapat menolong karena semuanya itu adalah kesia-siaan belaka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 22, 'Sebab TUHAN tidak akan membuang umat-Nya, sebab nama-Nya yang besar. Bukankah TUHAN telah berkenan untuk membuat kamu menjadi umat-Nya?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 23, 'Mengenai aku, jauhlah dari padaku untuk berdosa kepada TUHAN dengan berhenti mendoakan kamu; aku akan mengajarkan kepadamu jalan yang baik dan lurus.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 24, 'Hanya takutlah akan TUHAN dan setialah beribadah kepada-Nya dengan segenap hatimu, sebab ketahuilah, betapa besarnya hal-hal yang dilakukan-Nya di antara kamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 12, 25, 'Tetapi jika kamu terus berbuat jahat, maka kamu akan dilenyapkan, baik kamu maupun rajamu itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 1, 'Saul berumur sekian tahun ketika ia menjadi raja; dua tahun ia memerintah atas Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 2, 'Saul memilih tiga ribu orang dari antara orang Israel; dua ribu orang ada bersama-sama dengan Saul di Mikhmas dan di pegunungan Betel, sedang seribu orang ada bersama-sama dengan Yonatan di Gibea Benyamin, tetapi selebihnya dari rakyat itu disuruhnya pulang, masing-masing ke kemahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 3, 'Yonatan memukul kalah pasukan pendudukan orang Filistin yang ada di Geba; dan hal itu terdengar oleh orang Filistin. Karena itu Saul menyuruh meniup sangkakala di seluruh negeri, sebab pikirnya: "Biarlah orang Ibrani mendengarnya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 4, 'Demikianlah seluruh orang Israel mendengar kabar, bahwa Saul telah memukul kalah pasukan pendudukan orang Filistin dan dengan demikian orang Israel dibenci oleh orang Filistin. Kemudian dikerahkanlah rakyat itu untuk mengikuti Saul ke Gilgal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 5, 'Adapun orang Filistin telah berkumpul untuk berperang melawan orang Israel. Dengan tiga ribu kereta, enam ribu orang pasukan berkuda dan pasukan berjalan kaki sebanyak pasir di tepi laut mereka bergerak maju dan berkemah di Mikhmas, di sebelah timur Bet-Awen.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 6, 'Ketika dilihat orang-orang Israel, bahwa mereka terjepit?sebab rakyat memang terdesak?maka larilah rakyat bersembunyi di gua, keluk batu, bukit batu, liang batu dan perigi;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 7, 'malah ada orang Ibrani yang menyeberangi arungan sungai Yordan menuju tanah Gad dan Gilead, sedang Saul masih di Gilgal dan seluruh rakyat mengikutinya dengan gemetar.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 8, 'Ia menunggu tujuh hari lamanya sampai waktu yang ditentukan Samuel. Tetapi ketika Samuel tidak datang ke Gilgal, mulailah rakyat itu berserak-serak meninggalkan dia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 9, 'Sebab itu Saul berkata: "Bawalah kepadaku korban bakaran dan korban keselamatan itu." Lalu ia mempersembahkan korban bakaran.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 10, 'Baru saja ia habis mempersembahkan korban bakaran, maka tampaklah Samuel datang. Saul pergi menyongsongnya untuk memberi salam kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 11, 'Tetapi kata Samuel: "Apa yang telah kauperbuat?" Jawab Saul: "Karena aku melihat rakyat itu berserak-serak meninggalkan aku dan engkau tidak datang pada waktu yang telah ditentukan, padahal orang Filistin telah berkumpul di Mikhmas,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 12, 'maka pikirku: Sebentar lagi orang Filistin akan menyerang aku di Gilgal, padahal aku belum memohonkan belas kasihan TUHAN; sebab itu aku memberanikan diri, lalu mempersembahkan korban bakaran."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 13, 'Kata Samuel kepada Saul: "Perbuatanmu itu bodoh. Engkau tidak mengikuti perintah TUHAN, Allahmu, yang diperintahkan-Nya kepadamu; sebab sedianya TUHAN mengokohkan kerajaanmu atas orang Israel untuk selama-lamanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 14, 'Tetapi sekarang kerajaanmu tidak akan tetap. TUHAN telah memilih seorang yang berkenan di hati-Nya dan TUHAN telah menunjuk dia menjadi raja atas umat-Nya, karena engkau tidak mengikuti apa yang diperintahkan TUHAN kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 15, 'Kemudian berangkatlah Samuel dan pergi dari Gilgal ke Gibea Benyamin. Tetapi Saul memeriksa barisan rakyat yang ada bersama-sama dengan dia itu: kira-kira enam ratus orang banyaknya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 16, 'Saul dan Yonatan, anaknya, dan rakyat yang ada bersama-sama dengan mereka, tinggal di Geba-Benyamin, sedang orang Filistin berkemah di Mikhmas.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 17, 'Maka keluarlah orang-orang penjarah dari perkemahan orang Filistin dalam tiga gerombolan: gerombolan yang satu mengambil jalan ke Ofra, ke daerah Syual;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 18, 'gerombolan yang kedua mengambil jalan ke Bet-Horon, dan gerombolan yang satu lagi mengambil jalan ke perbatasan yang menghadap ke lembah Zeboim arah ke padang gurun.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 19, 'Seorang tukang besi tidak terdapat di seluruh negeri Israel, sebab orang Filistin berkata: "Jangan-jangan orang Ibrani membuat pedang atau tombak."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 20, 'Jadi semua orang Israel harus pergi kepada orang Filistin untuk mengasah mata bajaknya, beliungnya, kapaknya atau aritnya masing-masing?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 21, 'adapun bayarannya ialah dua pertiga syikal untuk mata bajak dan beliung, dan sepertiga syikal untuk mengasah kapak dan untuk memasang kusa?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 22, 'sehingga pada hari pertempuran itu sebilah pedang atau lembingpun tidak terdapat pada seluruh rakyat yang ada bersama Saul dan Yonatan. Tetapi Saul dan Yonatan, anaknya itu, masih mempunyainya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 13, 23, 'Dan suatu pasukan pengawal orang Filistin telah keluar ke pelintasan gunung di Mikhmas.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 1, 'Pada suatu hari Yonatan bin Saul berkata kepada bujang pembawa senjatanya: "Mari kita menyeberang ke dekat pasukan pengawal orang Filistin yang di sebelah sana." Tetapi tidak diberitahukannya hal itu kepada ayahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 2, 'Adapun Saul duduk di ujung Gibea di bawah pohon delima yang di Migron. Dan rakyat yang ada bersama-sama dengan dia itu, kira-kira enam ratus orang banyaknya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 3, 'Ahia, anak Ahitub, saudara Ikabod, anak Pinehas, anak Eli, imam TUHAN di Silo, dialah yang memakai baju efod pada waktu itu. Tetapi rakyat tidak tahu tentang perginya Yonatan itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 4, 'Di antara pelintasan-pelintasan bukit, yang dicoba Yonatan menyeberanginya ke arah pasukan pengawal orang Filistin, ada ujung bukit batu di sebelah sini dan ada ujung bukit batu di sebelah sana: yang satu bernama Bozes, yang lain bernama Sene.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 5, 'Ujung yang satu berdiri di sebelah utara di tentangan Mikhmas, yang lain di sebelah selatan di tentangan Geba.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 6, 'Berkatalah Yonatan kepada bujang pembawa senjatanya itu: "Mari kita menyeberang ke dekat pasukan pengawal orang-orang yang tidak bersunat ini. Mungkin TUHAN akan bertindak untuk kita, sebab bagi TUHAN tidak sukar untuk menolong, baik dengan banyak orang maupun dengan sedikit orang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 7, 'Lalu jawab pembawa senjatanya itu kepadanya: "Lakukanlah niat hatimu itu; sungguh, aku sepakat."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 8, 'Kata Yonatan: "Perhatikan, kita menyeberang ke dekat orang-orang itu dan memperlihatkan diri kepada mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 9, 'Apabila kata mereka kepada kita begini: Berhentilah, sampai kami datang padamu, maka kita tinggal berdiri di tempat kita dan tidak naik mendapatkan mereka,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 10, 'tetapi apabila kata mereka begini: Naiklah ke mari, maka kita akan naik, sebab kalau demikian TUHAN telah menyerahkan mereka ke dalam tangan kita. Itulah tandanya bagi kita."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 11, 'Ketika mereka keduanya memperlihatkan diri kepada pasukan pengawal orang Filistin, berkatalah orang Filistin itu: "Lihat, orang-orang Ibrani keluar dari lobang-lobang tempat mereka bersembunyi."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 12, 'Orang-orang dari pasukan pengawal itu berseru kepada Yonatan dan pembawa senjatanya, katanya: "Naiklah ke mari, maka kami akan menghajar kamu." Lalu kata Yonatan kepada pembawa senjatanya: "Naiklah mengikuti aku, sebab TUHAN telah menyerahkan mereka ke dalam tangan orang Israel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 13, 'Maka naiklah Yonatan merangkak ke atas, dengan diikuti oleh pembawa senjatanya. Orang-orang itu tewas terparang oleh Yonatan, sedang pembawa senjatanya membunuh mereka dari belakangnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 14, 'Kekalahan yang pertama ini, yang ditimbulkan Yonatan dan pembawa senjatanya itu, besarnya kira-kira dua puluh orang dalam jarak kira-kira setengah alur dari sepembajakan ladang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 15, 'Lalu timbullah kegentaran di perkemahan, di padang dan di antara seluruh rakyat. Juga pasukan pengawal dan penjarah-penjarah itu gentar, dan bumi gemetar, sehingga menjadi kegentaran yang dari Allah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 16, 'Ketika peninjau-peninjau Saul di Gibea Benyamin melihat hal itu?dan sesungguhnya, orang ramai seperti ombak berjalan ke sana ke mari?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 17, 'berkatalah Saul kepada tentara yang bersama-sama dengan dia itu: "Periksalah barisan dan lihatlah siapa yang pergi dari pada kita." Mereka memeriksa barisan, dan ternyata Yonatan dan pembawa senjatanya tidak ada.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 18, 'Lalu kata Saul kepada Ahia: "Bawalah baju efod ke mari." Karena pada waktu itu dialah yang memakai baju efod di antara orang Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 19, 'Tetapi sedang Saul berbicara kepada imam itu, maka kian lama kian bertambahlah keributan di perkemahan orang Filistin, sehingga Saul berkata pula kepada imam itu: "Biarlah!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 20, 'Kemudian berkumpullah Saul dan seluruh rakyat yang bersama-sama dengan dia itu; dan ketika mereka sampai ke tempat pertempuran, tampaklah setiap orang menikam temannya dengan pedang, suatu huru-hara yang sangat besar.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 21, 'Lagipula orang-orang Ibrani yang telah lama tinggal pada orang Filistin dan yang telah ikut maju dalam tentara mereka, mereka juga berbalik untuk bergabung dengan orang-orang Israel yang ada bersama-sama dengan Saul dan Yonatan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 22, 'Bahkan, ketika semua orang Israel yang telah bersembunyi di pegunungan Efraim, mendengar bahwa orang Filistin telah lari, orang-orang itupun bergabung dengan mereka dalam pertempuran.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 23, 'Demikianlah TUHAN menyelamatkan orang Israel pada hari itu. Pertempuran itu meluas sampai lewat Bet-Awen.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 24, 'Ketika orang-orang Israel terdesak pada hari itu, Saul menyuruh rakyat mengucapkan kutuk, katanya: "Terkutuklah orang yang memakan sesuatu sebelum matahari terbenam dan sebelum aku membalas dendam terhadap musuhku." Sebab itu tidak ada seorangpun dari rakyat yang memakan sesuatu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 25, 'Dan seluruh orang itu sampailah ke suatu hutan dan di sana ada madu di tanah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 26, 'Ketika rakyat sampai ke hutan itu, tampaklah ada di sana madu meleleh, tetapi tidak ada seorangpun yang mencedoknya ke mulutnya dengan tangan, sebab rakyat takut kepada sumpah itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 27, 'Tetapi Yonatan tidak mendengar, bahwa ayahnya telah menyuruh rakyat bersumpah. Ia mengulurkan tongkat yang ada di tangannya dan mencelupkan ujungnya ke dalam sarang madu; kemudian ia mencedoknya ke mulutnya dengan tangan, lalu matanya menjadi terang lagi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 28, 'Dan seorang dari rakyat berbicara, katanya: "Ayahmu telah menyuruh rakyat bersumpah dengan bersungguh-sungguh, katanya: Terkutuklah orang yang memakan sesuatu pada hari ini; sebab itu rakyat letih lesu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 29, 'Lalu kata Yonatan: "Ayahku mencelakakan negeri; coba lihat, bagaimana terangnya mataku, setelah aku merasai sedikit dari madu ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 30, 'Apalagi, jika sekiranya rakyat pada hari ini boleh makan dengan bebas dari jarahan musuhnya, yang telah didapatnya! Tetapi sekarang tidaklah besar kekalahan di antara orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 31, 'Dan pada hari itu mereka memukul kalah orang Filistin dari Mikhmas sampai ke Ayalon. Rakyat sudah sangat letih lesu,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 32, 'sebab itu rakyat menyambar jarahan; mereka mengambil kambing domba, lembu dan anak lembu, menyembelihnya begitu saja di atas tanah, dan memakannya dengan darahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 33, 'Lalu diberitahukanlah kepada Saul, demikian: "Lihat, rakyat berdosa terhadap TUHAN dengan memakannya dengan darahnya." Dan ia berkata: "Kamu berbuat khianat; gulingkanlah sekarang juga sebuah batu besar ke mari."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 34, 'Kata Saul pula: "Berserak-seraklah di antara rakyat dan katakan kepada mereka: Setiap orang harus membawa lembunya atau dombanya kepadaku; sembelihlah itu di sini, maka kamu boleh memakannya. Tetapi janganlah berdosa terhadap TUHAN dengan memakannya dengan darahnya." Lalu setiap orang dari seluruh rakyat membawa serta pada malam itu lembunya, dan mereka menyembelihnya di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 35, 'Saul mendirikan mezbah bagi TUHAN; inilah mezbah yang mula-mula sekali didirikannya bagi TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 36, 'Lagi kata Saul: "Marilah kita pada malam ini mengejar orang Filistin dan menjarahi mereka sampai fajar menyingsing dan janganlah kita biarkan hidup seorangpun dari mereka." Jawab mereka itu: "Perbuatlah apa yang kaupandang baik." Tetapi imam berkata: "Marilah kita dahulu tampil menghadap Allah di sini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 37, 'Saul bertanya kepada Allah: "Bolehkah aku mengejar orang Filistin itu? Akan Kauserahkankah mereka ke dalam tangan orang Israel?" Tetapi pada hari itu Ia tidak menjawab Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 38, 'Lalu kata Saul: "Datanglah ke mari, kamu segala pemuka rakyat; berusahalah mengetahui apa sebab dosa ini terjadi pada hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 39, 'Sebab demi TUHAN yang hidup, yang menyelamatkan orang Israel, sekalipun itu disebabkan oleh Yonatan, anakku, maka ia pasti akan mati." Tetapi seorangpun dari seluruh rakyat tidak ada yang menjawabnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 40, 'Kemudian berkatalah ia kepada seluruh orang Israel: "Kamu berdiri di sebelah yang satu dan aku serta anakku Yonatan akan berdiri di sebelah yang lain." Lalu jawab rakyat kepada Saul: "Perbuatlah apa yang kaupandang baik."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 41, 'Lalu berkatalah Saul: "Ya, TUHAN, Allah Israel, mengapa Engkau tidak menjawab hamba-Mu pada hari ini? Jika kesalahan itu ada padaku atau pada anakku Yonatan, ya TUHAN, Allah Israel, tunjukkanlah kiranya Urim; tetapi jika kesalahan itu ada pada umat-Mu Israel, tunjukkanlah Tumim." Lalu didapati Yonatan dan Saul, tetapi rakyat itu terluput.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 42, 'Kata Saul: "Buanglah undi antara aku dan anakku Yonatan." Lalu didapati Yonatan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 43, 'Kata Saul kepada Yonatan: "Beritahukanlah kepadaku apa yang telah kauperbuat." Lalu Yonatan memberitahukan kepadanya, katanya: "Memang, aku telah merasai sedikit madu dengan ujung tongkat yang ada di tanganku. Aku bersedia untuk mati."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 44, 'Kata Saul: "Beginilah kiranya Allah menghukum aku, bahkan lebih lagi dari pada itu. Sesungguhnya, Yonatan, engkau harus mati."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 45, 'Tetapi rakyat berkata kepada Saul: "Masakan Yonatan harus mati, dia yang telah mendapat kemenangan yang besar ini di Israel? Jauhlah yang demikian! Demi TUHAN yang hidup, sehelai rambutpun dari kepalanya takkan jatuh ke bumi! Sebab dengan pertolongan Allah juga dilakukannya hal itu pada hari ini." Demikianlah rakyat membebaskan Yonatan, sehingga ia tidak harus mati.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 46, 'Maka pulanglah Saul setelah mengejar orang Filistin, dan orang Filistin itupun kembali ke tempat kediamannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 47, 'Setelah Saul mendapat jabatan raja atas Israel, maka berperanglah ia ke segala penjuru melawan segala musuhnya: melawan Moab, bani Amon, Edom, raja-raja negeri Zoba dan orang Filistin. Dan ke manapun ia pergi, ia selalu mendapat kemenangan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 48, 'Ia melakukan perbuatan-perbuatan yang gagah perkasa, memukul kalah orang Amalek, dan melepaskan Israel dari tangan orang-orang yang merampasi mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 49, 'Anak-anak lelaki Saul ialah Yonatan, Yiswi dan Malkisua. Nama kedua anaknya yang perempuan: yang tertua bernama Merab, yang termuda bernama Mikhal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 50, 'Isteri Saul bernama Ahinoam, anak Ahimaas. Panglima tentaranya bernama Abner, anak Ner, paman Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 51, 'Kish, ayah Saul, dan Ner, ayah Abner, adalah anak-anak Abiel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 14, 52, 'Hebat peperangan melawan orang Filistin selama zaman Saul. Dan semua pahlawan dan orang gagah perkasa, yang dilihat Saul, dikumpulkannya kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 1, 'Berkatalah Samuel kepada Saul: "Aku telah diutus oleh TUHAN untuk mengurapi engkau menjadi raja atas Israel, umat-Nya; oleh sebab itu, dengarkanlah bunyi firman TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 2, 'Beginilah firman TUHAN semesta alam: Aku akan membalas apa yang dilakukan orang Amalek kepada orang Israel, karena orang Amalek menghalang-halangi mereka, ketika orang Israel pergi dari Mesir.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 3, 'Jadi pergilah sekarang, kalahkanlah orang Amalek, tumpaslah segala yang ada padanya, dan janganlah ada belas kasihan kepadanya. Bunuhlah semuanya, laki-laki maupun perempuan, kanak-kanak maupun anak-anak yang menyusu, lembu maupun domba, unta maupun keledai."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 4, 'Lalu Saul memanggil rakyat berkumpul dan memeriksa barisan mereka di Telaim: ada dua ratus ribu orang pasukan berjalan kaki dan sepuluh ribu orang Yehuda.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 5, 'Setelah Saul sampai ke kota orang Amalek, disuruhnyalah orang-orang menghadang di lembah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 6, 'Berkatalah Saul kepada orang Keni: "Berangkatlah, menjauhlah, pergilah dari tengah-tengah orang Amalek, supaya jangan kulenyapkan kamu bersama-sama dengan mereka. Bukankah kamu telah menunjukkan persahabatanmu kepada semua orang Israel, ketika mereka pergi dari Mesir?" Sesudah itu menjauhlah orang Keni dari tengah-tengah orang Amalek.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 7, 'Lalu Saul memukul kalah orang Amalek mulai dari Hawila sampai ke Syur, yang di sebelah timur Mesir.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 8, 'Agag, raja orang Amalek, ditangkapnya hidup-hidup, tetapi segenap rakyatnya ditumpasnya dengan mata pedang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 9, 'Tetapi Saul dan rakyat itu menyelamatkan Agag dan kambing domba dan lembu-lembu yang terbaik dan tambun, pula anak domba dan segala yang berharga: tidak mau mereka menumpas semuanya itu. Tetapi segala hewan yang tidak berharga dan yang buruk, itulah yang ditumpas mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 10, 'Lalu datanglah firman TUHAN kepada Samuel, demikian:', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 11, '"Aku menyesal, karena Aku telah menjadikan Saul raja, sebab ia telah berbalik dari pada Aku dan tidak melaksanakan firman-Ku." Maka sakit hatilah Samuel dan ia berseru-seru kepada TUHAN semalam-malaman.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 12, 'Lalu Samuel bangun pagi-pagi untuk bertemu dengan Saul, tetapi diberitahukan kepada Samuel, demikian: "Saul telah ke Karmel tadi dan telah didirikannya baginya suatu tanda peringatan; kemudian ia balik dan mengambil jurusan ke Gilgal."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 13, 'Ketika Samuel sampai kepada Saul, berkatalah Saul kepadanya: "Diberkatilah kiranya engkau oleh TUHAN; aku telah melaksanakan firman TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 14, 'Tetapi kata Samuel: "Kalau begitu apakah bunyi kambing domba, yang sampai ke telingaku, dan bunyi lembu-lembu yang kudengar itu?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 15, 'Jawab Saul: "Semuanya itu dibawa dari pada orang Amalek, sebab rakyat menyelamatkan kambing domba dan lembu-lembu yang terbaik dengan maksud untuk mempersembahkan korban kepada TUHAN, Allahmu; tetapi selebihnya telah kami tumpas."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 16, 'Lalu berkatalah Samuel kepada Saul: "Sudahlah! Aku akan memberitahukan kepadamu apa yang difirmankan TUHAN kepadaku tadi malam." Kata Saul kepadanya: "Katakanlah."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 17, 'Sesudah itu berkatalah Samuel: "Bukankah engkau, walaupun engkau kecil pada pemandanganmu sendiri, telah menjadi kepala atas suku-suku Israel? Dan bukankah TUHAN telah mengurapi engkau menjadi raja atas Israel?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 18, 'TUHAN telah menyuruh engkau pergi, dengan pesan: Pergilah, tumpaslah orang-orang berdosa itu, yakni orang Amalek, berperanglah melawan mereka sampai engkau membinasakan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 19, 'Mengapa engkau tidak mendengarkan suara TUHAN? Mengapa engkau mengambil jarahan dan melakukan apa yang jahat di mata TUHAN?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 20, 'Lalu kata Saul kepada Samuel: "Aku memang mendengarkan suara TUHAN dan mengikuti jalan yang telah disuruh TUHAN kepadaku dan aku membawa Agag, raja orang Amalek, tetapi orang Amalek itu sendiri telah kutumpas.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 21, 'Tetapi rakyat mengambil dari jarahan itu kambing domba dan lembu-lembu yang terbaik dari yang dikhususkan untuk ditumpas itu, untuk mempersembahkan korban kepada TUHAN, Allahmu, di Gilgal."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 22, 'Tetapi jawab Samuel: "Apakah TUHAN itu berkenan kepada korban bakaran dan korban sembelihan sama seperti kepada mendengarkan suara TUHAN? Sesungguhnya, mendengarkan lebih baik dari pada korban sembelihan, memperhatikan lebih baik dari pada lemak domba-domba jantan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 23, 'Sebab pendurhakaan adalah sama seperti dosa bertenung dan kedegilan adalah sama seperti menyembah berhala dan terafim. Karena engkau telah menolak firman TUHAN, maka Ia telah menolak engkau sebagai raja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 24, 'Berkatalah Saul kepada Samuel: "Aku telah berdosa, sebab telah kulangkahi titah TUHAN dan perkataanmu; tetapi aku takut kepada rakyat, karena itu aku mengabulkan permintaan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 25, 'Maka sekarang, ampunilah kiranya dosaku; kembalilah bersama-sama dengan aku, maka aku akan sujud menyembah kepada TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 26, 'Tetapi jawab Samuel kepada Saul: "Aku tidak akan kembali bersama-sama dengan engkau, sebab engkau telah menolak firman TUHAN; sebab itu TUHAN telah menolak engkau, sebagai raja atas Israel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 27, 'Ketika Samuel berpaling hendak pergi, maka Saul memegang punca jubah Samuel, tetapi terkoyak.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 28, 'Kemudian berkatalah Samuel kepadanya: "TUHAN telah mengoyakkan dari padamu jabatan raja atas Israel pada hari ini dan telah memberikannya kepada orang lain yang lebih baik dari padamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 29, 'Lagi Sang Mulia dari Israel tidak berdusta dan Ia tidak tahu menyesal; sebab Ia bukan manusia yang harus menyesal."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 30, 'Tetapi kata Saul: "Aku telah berdosa; tetapi tunjukkanlah juga hormatmu kepadaku sekarang di depan para tua-tua bangsaku dan di depan orang Israel. Kembalilah bersama-sama dengan aku, maka aku akan sujud menyembah kepada TUHAN, Allahmu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 31, 'Sesudah itu kembalilah Samuel mengikuti Saul. Dan Saul sujud menyembah kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 32, 'Lalu berkatalah Samuel: "Bawa ke mari Agag, raja Amalek itu." Dengan gembira Agag pergi kepadanya, sebab pikirnya: "Sesungguhnya, kepahitan maut telah lewat."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 33, 'Tetapi kata Samuel: "Seperti pedangmu membuat perempuan-perempuan kehilangan anak, demikianlah ibumu akan kehilangan anak di antara perempuan-perempuan." Sesudah itu Samuel mencincang Agag di hadapan TUHAN di Gilgal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 34, 'Kemudian Samuel pergi ke Rama, tetapi Saul pergi ke rumahnya, di Gibea-Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 15, 35, 'Sampai hari matinya Samuel tidak melihat Saul lagi, tetapi Samuel berdukacita karena Saul. Dan TUHAN menyesal, karena Ia menjadikan Saul raja atas Israel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 1, 'Berfirmanlah TUHAN kepada Samuel: "Berapa lama lagi engkau berdukacita karena Saul? Bukankah ia telah Kutolak sebagai raja atas Israel? Isilah tabung tandukmu dengan minyak dan pergilah. Aku mengutus engkau kepada Isai, orang Betlehem itu, sebab di antara anak-anaknya telah Kupilih seorang raja bagi-Ku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 2, 'Tetapi Samuel berkata: "Bagaimana mungkin aku pergi? Jika Saul mendengarnya, ia akan membunuh aku." Firman TUHAN: "Bawalah seekor lembu muda dan katakan: Aku datang untuk mempersembahkan korban kepada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 3, 'Kemudian undanglah Isai ke upacara pengorbanan itu, lalu Aku akan memberitahukan kepadamu apa yang harus kauperbuat. Urapilah bagi-Ku orang yang akan Kusebut kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 4, 'Samuel berbuat seperti yang difirmankan TUHAN dan tibalah ia di kota Betlehem. Para tua-tua di kota itu datang mendapatkannya dengan gemetar dan berkata: "Adakah kedatanganmu ini membawa selamat?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 5, 'Jawabnya: "Ya, benar! Aku datang untuk mempersembahkan korban kepada TUHAN. Kuduskanlah dirimu, dan datanglah dengan daku ke upacara pengorbanan ini." Kemudian ia menguduskan Isai dan anak-anaknya yang laki-laki dan mengundang mereka ke upacara pengorbanan itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 6, 'Ketika mereka itu masuk dan Samuel melihat Eliab, lalu pikirnya: "Sungguh, di hadapan TUHAN sekarang berdiri yang diurapi-Nya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 7, 'Tetapi berfirmanlah TUHAN kepada Samuel: "Janganlah pandang parasnya atau perawakan yang tinggi, sebab Aku telah menolaknya. Bukan yang dilihat manusia yang dilihat Allah; manusia melihat apa yang di depan mata, tetapi TUHAN melihat hati."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 8, 'Lalu Isai memanggil Abinadab dan menyuruhnya lewat di depan Samuel, tetapi Samuel berkata: "Orang inipun tidak dipilih TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 9, 'Kemudian Isai menyuruh Syama lewat, tetapi Samuel berkata: "Orang inipun tidak dipilih TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 10, 'Demikianlah Isai menyuruh ketujuh anaknya lewat di depan Samuel, tetapi Samuel berkata kepada Isai: "Semuanya ini tidak dipilih TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 11, 'Lalu Samuel berkata kepada Isai: "Inikah anakmu semuanya?" Jawabnya: "Masih tinggal yang bungsu, tetapi sedang menggembalakan kambing domba." Kata Samuel kepada Isai: "Suruhlah memanggil dia, sebab kita tidak akan duduk makan, sebelum ia datang ke mari."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 12, 'Kemudian disuruhnyalah menjemput dia. Ia kemerah-merahan, matanya indah dan parasnya elok. Lalu TUHAN berfirman: "Bangkitlah, urapilah dia, sebab inilah dia."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 13, 'Samuel mengambil tabung tanduk yang berisi minyak itu dan mengurapi Daud di tengah-tengah saudara-saudaranya. Sejak hari itu dan seterusnya berkuasalah Roh TUHAN atas Daud. Lalu berangkatlah Samuel menuju Rama.', 'id', 'TB')
